export default [{"id":23,"question":"توفي ابن أخي ابن الثانية عشرة من العمر في حادثٍ، فرأيته في المنام تكرارًا يقول لي: أنا زعلان عليكم، فما تفسير هذا يا سماحة الشيخ؟ جزاكم الله خيرًا.","title":"ماذا يفعل من رأى قريبًا له في المنام يعاتبه؟","answer":"الجواب: ثبت عن رسول الله عليه الصلاة والسلام أنه قال: الرؤيا الصَّالحة من الله، فإذا رأى أحدكم ما يُحبّ فليحمد الله، وليُخبر بها مَن يُحبّ، والحلم من الشيطان، فإذا رأى أحدُكم ما يكره فلينفث عن يساره ثلاث مراتٍ، وليتعوّذ بالله من الشيطان ومن شرِّ ما رأى ثلاث مرات، ثم لينقلب على جنبه الآخر، فإنَّها لا تضرُّه، ولا يُخبر بها أحدًا.\nهكذا يقول ﷺ، فالرؤيا المكروهة من الشيطان؛ ترى ولدك يقول: كذا أنا زعلان، أنا في النار، أنا كذا، أو أباك، أو أخاك، أو زوجك، أو أمك، كل هذا من الشيطان، تحزينٌ من الشيطان وإيذاء، فإذا رأى الإنسانُ ما يكرهه، أو أنه يُضرب، أو أنه في محل مَخُوف، أو أنه يُقتل، أو أنه يُتوعد بالقتل، أو ما أشبه ذلك من الأشياء التي يكرهها فإنَّ الدواء في هذا أن يقول عندما يستيقظ: يتفل عن يساره ثلاث مرات ويقول: \"أعوذ بالله من الشيطان الرجيم، أعوذ بالله من الشيطان ومن شرِّ ما رأيت\" ثلاث مرات يُكررها، يستعيذ بالله من الشيطان، ومن شرِّ ما رأى ثلاث مرات، ثم ينقلب على جنبه الآخر، ولا يُخبر بها أحدًا، يقول: رأيت، ورأيت، لا، يسكت ولا تضرُّه.","link":"https://binbaz.org.sa/fatwas/2803/ماذا-يفعل-من-راى-قريبا-له-في-المنام-يعاتبه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0276.mp3","categories":["الحكم على الأحاديث","الآداب والأخلاق المحمودة"]},{"id":57,"question":"هنالك أيضًا أخت أخرى تسأل وتقول: ما مدى صحة الحديث الذي يقول: من لم يهتم بأمر المسلمين فليس منهم؟","title":"درجة حديث \"من لم يهتم بأمر المسلمين..\"","answer":"الجواب: هذا الحديث رواه الطبراني وجماعة وفيه ضعف، لكن معناه صحيح، وأن الواجب على المسلمين أن يهتم بعضهم ببعض، يقول النبي ﷺ: لا يؤمن أحدكم حتى يحب لأخيه ما يحب لنفسه، ويقول عليه الصلاة والسلام: المؤمن للمؤمن كالبنيان يشد بعضه بعضًا وشبّك بين أصابعه، وقال عليه الصلاة والسلام: مثل المؤمنين في توادهم وتراحمهم وتعاطفهم كمثل الجسد إذا اشتكى منه عضو تداعى له سائر الجسد بالسهر والحمى.","link":"https://binbaz.org.sa/fatwas/2968/درجة-حديث-من-لم-يهتم-بامر-المسلمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0030.mp3","categories":["الحكم على الأحاديث","الآداب والأخلاق المحمودة"]},{"id":60,"question":"فضيلة الشيخ  حفظه الله: السلام عليكم ورحمة الله وبركاته، يوجد بعض من الشباب الصالح يعق والديه ويرفض مطالبهم بحجة أنه يوجد درس أو محاضرة يريد الذهاب إليها، ماذا عن فعلهم هذا، هل صحيح أم يعتبر عقوق للوالدين، نرجو النصيحة لهؤلاء؟","title":"حكم تأخير حاجة الوالدين لحضور العلم","answer":"الجواب: عقوق الوالدين منكر لا يجوز، وعقوقهما قطيعتهما والإساءة إليهما أو إيذاؤهما أو سبهما أو عدم الإنفاق عليهما مع الحاجة؛ كل هذا من العقوق فإذا كان لوالديه حاجة فيه بَدَّاها وقَدَّمها على ذهابه إلى حضور المحاضرة، أو الدرس؛ لأن هذا شيء جزئي لا يمنعه من طلب العلم ولا يمنعه من صحبة الأخيار، بل هو عارض؛ فينبغي له في هذه الحالة أن يقدم طاعة الوالد؛ لأن بره واجب؛ فالواجب أن يقدم طاعته في هذه المسائل الجزئية، وأن يقدم ذلك على أن يحضر المحاضرة الفلانية أو العزيمة الفلانية أو الندوة الفلانية أو ما أشبه ذلك؛ لأن البر واجب فلا يترك لمستحب.\nثم أيضًا يجب على الأولاد الحرص غاية الحرص على بر الوالدين حتى ولو كانا كافرين، فكيف وهما مسلمان؟! الله يقول في حق الوالدين الكافرين: وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا [لقمان:15] وهما كافران، فكيف بالمسلمين؟! الواجب برهما والإحسان إليهما والرفق بهما وخفض الجناح لهما وتليين الكلام معهما والسمع والطاعة لهما في المعروف، هذا هو الواجب على الولد ذكرًا كان أو أنثى صغيرًا أو كبيرًا.","link":"https://binbaz.org.sa/fatwas/2975/حكم-تاخير-حاجة-الوالدين-لحضور-العلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0035.mp3","categories":["الحكم على الأحاديث","الآداب والأخلاق المحمودة"]},{"id":83,"question":"ما صحة حديث: إنَّ الله خلق آدم على صورته أو: على صورة الرحمن؟","title":"درجة حديث \"إن الله خلق آدم على صورته\"","answer":"الجواب: الحديث صحيحٌ، ومعنى خلق آدم على صورته أي: سميعًا، بصيرًا، يتكلَّم، ذا عينٍ، وذا يدٍ، وذا قدمٍ، وليس معناه المُشابهة، فإنَّ الله لا يُشبهه شيء: وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ [الإخلاص:4]، لكن معناه: خلقه الله على صورته: سميعًا، بصيرًا، له وجهٌ، وله يدٌ، وله قدمٌ، يعلم، ويسمع، ويُبْصِر، هكذا قال أهلُ السنة: كأحمد وإسحاق وغيرهم، رحمة الله عليهم.","link":"https://binbaz.org.sa/fatwas/3076/درجة-حديث-ان-الله-خلق-ادم-على-صورته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0060.mp3","categories":["الحكم على الأحاديث","الآداب والأخلاق المحمودة"]},{"id":155,"question":"ما رأي الإسلام في الوساطات الموجودة في كل المصالح الحكومية، بما في ذلك جامعة الملك عبدالعزيز -على حدِّ قوله؟","title":"حكم الوساطة والشفاعة في مصالح الناس","answer":"الجواب: الواسطات قسمان: واسطة بالخير، وواسطة بالشر:\nأما الوساطة في الخير وتكثيره ونفع المسلمين فهذه وساطة صالحة مشروعة، قال النبيُّ ﷺ: اشفعوا تُؤجروا، ويقضي الله على لسان نبيه ما يشاء، فالذي يتوسط لدى الدكتور عبدالله في أن يقبل فلانًا في كذا، في محلٍّ يستحقه في الجامعة، أو يُعلي مرتبته في وظيفته؛ لأنه يستحقُّ ذلك، أو ما أشبه ذلك من الحقوق التي يعرف الشافعُ أنَّ المشفوع له جديرٌ بذلك، أو يقول إذا كان جديرًا بذلك؛ فلا بأس بذلك.\nأما الوساطة فيما حرَّم الله: فلا يجوز التوسط لإنسانٍ يُعطى ما حرَّم الله عليه، أو يُجعل في محلٍّ لا يليق به، أو ما أشبه ذلك، لا تصلح هذه الوساطة.\nفالحاصل أنَّ الوساطة تختلف: فإن كانت في خيرٍ فهي مشروعة، وإن كانت فيما حرَّم الله: كتوسطه به في الرشوة، وكتوسطه به في الزنا، وكتوسطه في الخمر، أو في التدخين، أو في غير هذا؛ فذلك لا يجوز، فالوسيلة على حسب الغاية، إن كانت الغايةُ طيبةً فالوساطة طيبة، وإن كانت الغايةُ رديئةً ومحرمةً فالوساطة محرمة.","link":"https://binbaz.org.sa/fatwas/3692/حكم-الوساطة-والشفاعة-في-مصالح-الناس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0148.mp3","categories":["الحكم على الأحاديث","الآداب والأخلاق المحمودة"]},{"id":162,"question":"في حقِّ مَن تجوز الغيبة؟ وهل يصحّ حديث: لا غيبةَ لفاسِقٍ؟","title":"ما الأحوال التي تجوز فيها الغِيبة؟","answer":"الجواب: الحديث ليس بصحيحٍ فيما أعلم. لكن ذكر العلماءُ ستة أشياء، تجوز فيها الغيبة: إذا أظهر الفسق. وهكذا في الاستفتاء. وهكذا في التَّظلم. وهكذا في جرح الشهود، وجرح الرواة. كل هذه أمور لا بأس فيها. وهكذا في المُناصحة؛ أن يستنصحك ويستشيرك. فهذه الأمور الستة ليس فيها غيبة: عند جرح الشهود، عند جرح الرواة، عند المُستفتي الذي يستفتيك عن كذا وكذا: تستفتيه امرأةٌ أن تأخذ من مال زوجها؛ لأنه بخيلٌ ما يُعطيها حقوقها، يستفتيك في إنسانٍ ظلمه: هل يُخاصمه؟ هل يأخذ من ماله مقابل حقِّه؟ وما أشبه ذلك.\nفالإنسان إذا أظهر الفسق لا غيبةَ له: إذا أظهر حلق اللحية، وقال إنسانٌ: هذا فلان محلوق اللحية، ما هي بغيبة، وإذا كان يُسبل ثيابه وقال بعضُ الناس فيه: إنه مُسْبِلٌ، ما هي بغيبةٍ؛ لأنه أظهرها، هو الذي أظهر المعصية، هو الذي فضح نفسه، فلا يُسمَّى: مُغتابًا -نسأل الله السلامة.","link":"https://binbaz.org.sa/fatwas/3700/ما-الاحوال-التي-تجوز-فيها-الغيبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0156.mp3","categories":["الآداب والأخلاق المحمودة","الحكم على الأحاديث"]},{"id":340,"question":"إذا كان هناك عاملٌ عمل لديَّ، وكان له مبلغ من المال عندي، ولم أجده لكي أُعطيه حقَّه، كيف أفعل فيه؟","title":"ما حكم من عنده حقٌّ لإنسانٍ فلم يجده؟","answer":"الجواب: إذا كان على الإنسان حقٌّ للغير ولم يجده ولم يعرف مكانه؛ يتصدَّق به عنه بالنية، والله يوصله إليه، وتبرأ الذمة. فإن جاء بعد حينٍ يطلبه؛ خيَّره: إن شاء قبل الصدقة ووصل له الأجر، وإن شاء أعطيته حقَّه وصار الأجرُ لك.","link":"https://binbaz.org.sa/fatwas/4428/ما-حكم-من-عنده-حق-لانسان-فلم-يجده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0393.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":685,"question":"قال الشارح: ويكره أن يخص أحد بسلام لأنه يولد الوحشة، فبعض الناس يخص طالب العلم أو الشيخ بالسلام من سائر الموجودين، فهل لهذا أصل؟","title":"حكم تخصيص شيخ أو غيره بالسلام وحده","answer":"الجواب: لا، مزيد سلام يعني، يعم الجميع وإذا خص بعضهم بعدين فلا بأس.\n(دروس شرح بلوغ المرام، كتاب الجامع)","link":"https://binbaz.org.sa/fatwas/6832/حكم-تخصيص-شيخ-او-غيره-بالسلام-وحده","audio":"https://files.zadapps.info/binbaz.org.sa/maram253 - 03 - .mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":687,"question":"حكم النصيحة؟","title":"هل النصيحة واجبة أم مستحبة؟","answer":"الجواب: واجبة فيما يجب، ومستحبة فيما يستحب، واجبة في ترك المنكرات ومستحبة في المستحبات.\n(دروس شرح بلوغ المرام، كتاب الجامع)","link":"https://binbaz.org.sa/fatwas/6834/هل-النصيحة-واجبة-ام-مستحبة","audio":"https://files.zadapps.info/binbaz.org.sa/maram255 - 03 - .mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":749,"question":"إنني أعرف شخصًا ولكن له أمّ كبيرة وأطفال وزوجة، وهو يستعمل استعمالًا فظيعًا بالمخدرات، إلا أنه لا يُروج، فهل يا سماحة الشيخ يجوز لي أن أفضح أمره؛ لأنني ناشدته وناصحته فلم يسمع؟ فهل يجوز لي ويكون هؤلاء الأطفال وأمّهم وأمّه ضحيةً لغيابه عنهم والنفقة عند مَن؟","title":"ما حكم الستر على متعاطي المخدرات؟","answer":"الجواب: إذا كان ضرره على نفسه ما يروِّجها بين الناس ولا يبيعها على الناس، إنما ضرره في نفسه، لا، استُرْ عليه وانصحه، إنما المصيبة إذا كان يروِّجها للناس ويضرّ الناس، ولو وراءه أطفال، أما إذا كان ضررها على نفسه..... ، يتعاطى في نفسه هو، فلا ترفع أمره، ولكن تُديم النَّصيحة والتَّوجيه إليه؛ لعلَّ الله يهديه بأسبابك.","link":"https://binbaz.org.sa/fatwas/20645/ما-حكم-الستر-على-متعاطي-المخدرات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0568حكم الستر على متعاطي المخدرات خاصة إذا كان يعول أمه وأولاده ليس لهم عائل غيره.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":793,"question":"هل يجوز أن يُقَبِّل الرجلُ الرجلَ عند اللِّقاء –أي: عند السلام؟ وهل وردت أحاديث في النَّهي عن ذلك؟ أرجو التوضيح، رغم أنَّ هذه العادة انتشرت بين الناس.","title":"حكم التقبيل بين الرجال عند اللقاء والسلام","answer":"الجواب: قال أنسٌ : \"كان أصحابُ النبي ﷺ إذا تلاقوا تصافحوا، وإذا قدموا من سفرٍ تعانقوا\"، فالسنة المعانقة عند القدوم من السفر وطول الغيبة، أما التَّقبيل فلا حاجةَ إليه، تكفي المصافحة، وإذا قبَّله بين عينيه أو على رأسه فالأمر أسهل؛ لأنه رُوي عن النبي أنه قبَّل جعفرًا لما قدم من الحبشة بين عينيه -جعفر بن أبي طالب- فالأمر في هذا، وقد رُوي عنه ﷺ أنَّ بعض الصحابة قبَّلوا يدَه ورِجْلَه عند قدومه من بعض الأسفار.\nلكن ترك ذلك هو الأفضل، وعدم اعتياده، وإنما تكفي المصافحة، هذا هو الأفضل، وإذا تعانقا عند القدوم من السفر فلا بأس بذلك، وإن قبَّل ما بين عينيه أو رأسه فلا بأس إن شاء الله، نعم، لكن ترك ذلك والاكتفاء بالمعانقة أوْلى.","link":"https://binbaz.org.sa/fatwas/20782/حكم-التقبيل-بين-الرجال-عند-اللقاء-والسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0613هل يجوز أن يقبل الرجل عند اللقاءوعند السلام؟ ابن باز فتاوى المحاضرات.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":795,"question":"متى يصح الستر على صاحب المُنكر؟ ومتى يصح التَّشهير بمُنكره وبه؟","title":"ما ضابط الستر أو التشهير بصاحب المُنكر؟","answer":"الجواب: ما دام مُستترًا بمعصيته فاستر عليه وانصحه ووجّهه إلى الخير،. ومتى أظهرها ولم يستحِ وجب رفع أمره إلى ولاة الأمور حتى يُقام عليه الحدُّ إذا أظهر معصيته، وهكذا إذا كررها لمن شهد بذلك وعرف ذلك أن يشهد عليه، حتى لا يستمر في الباطل، وقد قال ﷺ: مَن ستر مسلمًا ستره الله في الدنيا والآخرة، وفي اللفظ الآخر: ستره الله يوم القيامة، فإذا ستر المسلم على أخيه مرةً أو مرتين أو ثلاثًا؛ لعله يستجيب، لعله يندم، لعله يُقلع، فلا حرج في ذلك، فإن كانوا جماعةً ورأوا الشَّهادة عليه؛ فلا بأس.\nأما إذا أعلن ولم يُبال ولم يستحِ فإنه تجب الشَّهادة عليه، ويجب رفع أمره؛ حتى لا يضرَّ الناس، وحتى لا يفتنهم في فعل المنكر ظاهرًا، بل يجب البدار إلى ولاة الأمور بالشَّهادة عليه بالمحكمة حتى يُقام عليه الحدُّ.","link":"https://binbaz.org.sa/fatwas/20805/ما-ضابط-الستر-او-التشهير-بصاحب-المنكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0632متى يصح الستر على صاحب المنكر ومتى يصح التشهير بمنكره وبه؟ابن باز فتاوى المحاضرات.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":878,"question":"المشهور لدى الناس: الاستعاذة من الشيطان بعد التثاؤب، فهل لهذا أصلٌ في الشريعة؟ وجزاكم الله خير الجزاء.","title":"ما حكم الاستعاذة بعد التثاؤب؟","answer":"الجواب: الاستعاذة بالله من الشيطان بعد التَّثاؤب ما أعرف أنه جاء فيه شيءٌ، لكن لما علم الناسُ أنَّ التثاؤب من الشيطان صاروا يستعيذون من الشيطان عند وجوده؛ لأنَّ الرسول قال: التثاؤب من الشيطان، فإذا تثاءب أحدُكم فليكظم ما استطاع، وفي اللفظ الآخر: فليضع يدَه على فيه، ولا يقل: هاه، فإن الشيطان يدخل في فيه، فالسنة إذا تثاءب أن يكظم ما استطاع، وأن يضع يده على فيه.\nوأما التَّعوذ فلا أعلم له دليلًا، إلا أن يُؤخذ من قول النبيِّ ﷺ: التثاؤب من الشيطان، والله يقول جلَّ وعلا: وَإِمَّا يَنْزَغَنَّكَ مِنَ الشَّيْطَانِ نَزْغٌ فَاسْتَعِذْ بِاللَّهِ [الأعراف:200]، فلا أعلم بأسًا في هذا، إذا تعوَّذ بالله من الشيطان عند وجود أعمال الشيطان ما نعلم بأسًا في ذلك، لكن لا أعلم فيه روايةً، إنما يُؤخَذ من قول النبي ﷺ: التَّثاؤب من الشيطان.","link":"https://binbaz.org.sa/fatwas/20923/ما-حكم-الاستعاذة-بعد-التثاوب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0718ما حكم الاستعاذة بعد التثاؤب؟ ابن باز فتاوى المحاضرات.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":1054,"question":"أنا شابٌّ، وعندي أحد إخواني أُصيب بمرضٍ: جانٌّ دخل فيه، وبعد الذهاب للشيخ علي العمري تكلَّم الجانُّ الخبيثُ وقال: دخلتُ فيه عن طريق السحر، وبعد مدةٍ بحثنا عن السحر ووجدناه، وأبطلناه، وشُفي ولله الحمد، واتَّضح بعد ذلك من كلام الجانِّ أنَّ مَن وضع السحرَ له هو عمي، والآن أنا قاطعتُه ولم أزره، أرجو إفادتي، ماذا عليَّ جزاكم الله خيرًا؟","title":"حكم هَجْر قريبٍ أخبر الجنُّ بفعله السحر","answer":"الجواب:\nهذا غلطٌ منك، لا تُصدق الجانَّ الظالم في عمِّك، بل عليك أن تصله ولا تقطعه، ولا تُصدق أعداء الله من الجنِّ والإنس، فالواجب عليك صلةُ الرحم، وإكرام عمك، فهو بمنزلة الأب، وألا تُطاوع أعداء الله من الجنِّ، ولا من الإنس، ولو وجدتَ ما قال الجنيُّ فهو ليس بصدوقٍ، بل هو كذوبٌ كما قال النبيُّ ﷺ: صدقك وهو كذوبٌ، قد يكون وضعه غيرُ عمِّك، فإذا وجدتَ ما قاله الشيطانُ، وأنه وُضِعَ لك في كذا وكذا وأتلفته فلا تُصدقه بأنه وضعه عمك، أو فلان، أو فلان، وتقطع رحمك، أو تهجر أخاك بغير حقٍّ، لا، هذا لا يجوز، بل احمد الله الذي شفاك وعافاك والحمد لله، وصِلْ رحمَك، واتَّقِ ربَّك.","link":"https://binbaz.org.sa/fatwas/21076/حكم-هجر-قريب-اخبر-الجن-بفعله-السحر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0872هل يجوز أن أقاطع عمي بسبب أنه وضع السحر لأخي وعرفت ذلك عن طريق الجن؟ ابن باز.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":1117,"question":"يقول هذا السائل في ورقةٍ قدَّمها: هذه نصيحتي إلى طلاب العلم، الرجاء قراءتها ليُعلِّق عليها سماحةُ الشيخ: أنصحهم بحُسن الخلق، فقد قال الرسولُ ﷺ: أنا زعيمٌ ببيتٍ في أعلى الجنَّة لمَن حسن خلقه، ومَن تمثَّل بالخلق الحسن فإنه يوم القيامة يكون في منزلةٍ يغبطه عليها الأنبياء والشُّهداء.وسبب توجيهي هذه النَّصيحة أنَّ كثيرًا من طلبة العلم سيئ الأخلاق، ويأخذه العُجب والغُرور بعلمه، ولا يعلم أنه جاهلٌ؛ لأنه لو كان لديه علمٌ لما عمل هكذا.الرجاء قراءتها ليُعلِّق عليها سماحةُ الشيخ؛ لأنَّ الدين النَّصيحة، جزاكم الله خيرًا.","title":"ما النصيحة لمن يغترّ بعلمه ويأخذه العُجْب؟","answer":"الجواب:\nلا شكَّ أنَّ هذه نصيحة مهمة، فإنَّ الواجب على العالم وطالب العلم وعلى كل مؤمنٍ ومؤمنةٍ: العناية بحُسن الخلق، وعدم التَّكبر، وعدم سُوء الخلق، فإن حُسن الخلق له شأنٌ عظيمٌ، ولهذا قال فيه النبيُّ ﷺ: البِرُّ حُسن الخلق، هكذا روى مسلم في \"الصحيح\": البر حُسن الخلق، وقال عليه الصلاة والسلام: إنَّ أحبَّكم إليَّ وأقربَكم مني مجلسًا يوم القيامة: أحاسنُكم أخلاقًا، وقال عليه الصلاة والسلام: أنا زعيمٌ ببيتٍ في أعلى الجنة لمن حسن خلقه، فتحسين الخلق من المهمَّات.\nوهو طيب الكلام، وانبساط الوجه، كما قال عليه الصلاة والسلام: لا تحقرنَّ من المعروف شيئًا، ولو أن تلقى أخاك بوجهٍ طليقٍ، وفي لفظٍ: بوجهٍ طَلْقٍ يعني: منبسطًا، هكذا المؤمن مع إخوانه في الله، وهكذا المؤمنة مع أخواتها في الله، كلٌّ منهم ينبسط، ولا يعبس، ولا يكفهر، ولا يُسيئ الكلام، ولكن يحسن خلقه في تعليمه، ودعوته إلى الله، وفي سلامه، وإرشاده، وفي محادثاته، يكون طيب الخلق، وهذا من أسباب قبول دعوته، ومن أسباب قبول نصيحته، ومن أسباب الانتفاع بعلمه، يقول الله  لموسى وهارون لما بعثهما إلى فرعون: فَقُولَا لَهُ قَوْلًا لَيِّنًا لَعَلَّهُ يَتَذَكَّرُ أَوْ يَخْشَى [طه:44]، وقال عن نبينا ﷺ: فَبِمَا رَحْمَةٍ مِنَ اللَّهِ لِنْتَ لَهُمْ وَلَوْ كُنْتَ فَظًّا غَلِيظَ الْقَلْبِ لَانْفَضُّوا مِنْ حَوْلِكَ [آل عمران:159]، فمدحه ﷺ بأنه ليّن الجانب، ليّن العريكة، ولهذا قال: فَبِمَا رَحْمَةٍ مِنَ اللَّهِ يعني: بسبب رحمةٍ من الله لِنتَ لهم، يعني: كنتَ لين الجانب، تخفض الجناح للمؤمنين: وَلَوْ كُنْتَ فَظًّا غَلِيظَ الْقَلْبِ لَانْفَضُّوا مِنْ حَوْلِكَ يعني: لنفروا وابتعدوا.\nفالواجب على الجميع العناية بهذا الأمر، والحرص على حُسن الخلق، وعدم العجب بالعلم، أو بالنسب، أو بالمال، أو بوظيفةٍ، أو غير ذلك، يجب عليك أن تتواضع، الله يقول سبحانه: وَاخْفِضْ جَنَاحَكَ لِلْمُؤْمِنِينَ [الحجر:88]، ويقول النبي ﷺ: ما تواضع أحدٌ لله إلا رفعه، ولماذا يتكبَّر؟ ولماذا يُسيئ الخلق وهو يعرف نفسه؟ أنت مخلوقٌ من نطفةٍ ضعيفةٍ، ثم سوَّاك ربُّك وطوَّرك حتى كنتَ رجلًا سويًّا، وحتى كنت أيتها المرأة امرأة سوية من فضل الله عليك.\nفالواجب عليك أن تعرف قدر هذه النعمة، وأن تشكر المنعم، وأن تتواضع لله، وأن تبتعد عن الكبر، والخيلاء، والعنف، والشدة، رزق الله الجميع التوفيق.","link":"https://binbaz.org.sa/fatwas/21162/ما-النصيحة-لمن-يغتر-بعلمه-وياخذه-العجب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0958نصيحة في حسن الخلق؟.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":1345,"question":"ما الفرق بين الصبر والاصْطِبَار؟","title":"ما الفرق بين الصبر والاصْطِبَار؟","answer":"الجواب:\nالصبر والاصطبار التصبر يعني، كَوْنُه يجاهد نفسه على الصبر.  يعني الذي يُرزق الصبر من غير تكلُّف أزين وأزين.  وإذا ما تيسر له؛ يجاهد نفسه حتى يُكُفَّها عما لا ينبغي، فلا يجزع ولا يتكلم بما لا ينبغي، ولا يفعل ما لا ينبغي؛ ولهذا قال ﷺ: أنا بريء من الصالقة والحالقة والشاقة وقال ﷺ: ليس منا من ضرب الخدود أو شق الجيوب أو دعا بدعوى الجاهلية. وعَقَدَ النساء وعَاهَدَهُن على ألا يَنُحْن.","link":"https://binbaz.org.sa/fatwas/21436/ما-الفرق-بين-الصبر-والاصطبار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما الفرق بين الصبر والاصطبار.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":1346,"question":"هل ورد إرشاد من انتابه الغضب بالسكوت؟","title":"ما المشروع للمسلم في أحوال الغضب؟","answer":"الجواب:\nما أتذكر شيئًا، لكن على كل حال هو من أسباب العافية، كونه يسكت وينتقل من مكان إلى مكان، يغادر المجلس، والوضوء كذلك؛ لأنه جمرة من النار.\nس: أو إذا كان واقفًا يجلس؟\nج: الواقف يجلس، نعم؛ يُغَيِّر حاله.\nس: أحسن الله إليك، لماذا لم يُعْلِمه النبي ﷺ بنفسه بهذه الكلمة اللي هي أعوذ بالله من الشيطان الرجيم؟\nج: النُّوَّاب عنه يُبَلِّغون، كل السُّنة أكثرها بلاغًا.\nس: يعني هو حضر هذه الواقعة يعني ولم يفض النزاع؟\nج: قال: إني لأعلم كلمة..؛ حتى يستفيد الجميع، وهم بَلَّغُوه.","link":"https://binbaz.org.sa/fatwas/21437/ما-المشروع-للمسلم-في-احوال-الغضب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في الغضب.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":1351,"question":"بعضهم يسمي الكذب \"دبلوماسية\"، وبعضهم يسميه \"كذبة بيضاء\"، وبعضهم يمزح ويقول: أنا أمزح، يعني يُكْثِر الكذب؟","title":"ما حكم مَن يُسَمُّون الكذب بغير اسمه؟","answer":"الجواب:\nكل هذا كلام باطل، كلام السفهاء.","link":"https://binbaz.org.sa/fatwas/21443/ما-حكم-من-يسمون-الكذب-بغير-اسمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في الصدق والكذب.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":1455,"question":"كيف يكون التَّحلل من العرض؟ فبعض الأشخاص لا تقدر على التحلُّل منه.","title":"كيف يكون التَّحلل من العِرْض؟","answer":"الجواب:\nإذا ما استطعت تذكر محاسنه وأخباره الطيبة التي تعلمها عنه، فتذكر أخباره الطيبة في المجالس التي اغتبته فيها، وتدعو له، وتستغفر له.","link":"https://binbaz.org.sa/fatwas/21552/كيف-يكون-التحلل-من-العرض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/كيف يكون التَّحلل من العرض.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":1457,"question":"يقول عز وجل: وَإِذَا حُيِّيتُمْ بِتَحِيَّةٍ فَحَيُّوا بِأَحْسَنَ مِنْهَا أَوْ رُدُّوهَا [النساء:86]، فكيف إذا سلَّم عليه أحدٌ وقال: \"السلام عليكم ورحمة الله وبركاته\" فكيف أزيد؟","title":"كيف تكون زيادة الرد على السلام الكامل؟","answer":"الجواب:\nيزيد: جزاك الله خيرًا، غفر الله لك، يدعو له، ونحو هذا، هذا من مزيد الخير: بارك الله فيك، أو أحسن الله إليك، أو نحو هذا.","link":"https://binbaz.org.sa/fatwas/21554/كيف-تكون-زيادة-الرد-على-السلام-الكامل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الزيادة في السلام.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":1486,"question":"أصحاب بلدة معينة من الدويلات التي استُحدثت الآن يقول لأخيه المسلم من دولةٍ أخرى: أجنبي، ويجرحه بهذه الكلمة!","title":"حكم وصف الوافد المسلم بكلمة \"أجنبي\"","answer":"الجواب:\nلا، المسلم أخو المسلم في أي مكانٍ، سواء كان في مشرق الأرض أو مغربها، مثلما قال ﷺ: المسلم أخو المسلم، وفي عرف الناس الأجنبي: الغريب، يعني الذي يأتي من بلادٍ بعيدةٍ يُسمونه أجنبيًّا، يعني: غريبًا، وهذا عرفٌ اصطلاحي بين الناس، ما هو أجنبي بمعنى كافر، لا، معناه أنه غريب، يقول: عندنا أجانب، يعني جاءوا من بعيدٍ، ما في ذلك محذور إذا أراد أنَّه غريب.","link":"https://binbaz.org.sa/fatwas/21584/حكم-وصف-الوافد-المسلم-بكلمة-اجنبي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في الأخوة الإسلامية.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":1487,"question":"قول: من كان في حاجة أخيه كان الله في حاجته هل هو على العموم؟","title":"معنى حديث \"من كان في حاجة أخيه...\"","answer":"الجواب:\nنعم صحيح، وعدٌ من ربنا جل وعلا على لسان رسول الله ﷺ، إذا قضيتَ حاجةَ أخيك: شفعت له في منفعةٍ، ساعدته في شيءٍ، أقرضته في شيءٍ، ساعدته في دواءٍ، في أجرة الطبيب وهو عاجز؛ كل هذا لك الأجر فيه، دللته على خيرٍ، أرشدته إلى خيرٍ، منعته من شرٍّ، يُؤجَر على المتَّعدِّي والقاصر.\nس: قضاء الحاجات والمساعدة.....؟\nج: يفعل هذا وهذا، المتعدي والقاصر، القاصر بعضه واجب وبعضه مستحب، والمتعدي كذلك: بعضه واجب وبعضه مستحب.","link":"https://binbaz.org.sa/fatwas/21585/معنى-حديث-من-كان-في-حاجة-اخيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من كان في حاجة أخيه كان الله في حاجته هل هو على العموم.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":1491,"question":"بالنسبة لعيادة المريض: هل يُدعى له، أو مثلًا ينفث عليه، أو يقول: \"أسأل الله العلي العظيم رب العرش العظيم أن يشفيك\" سبع مرات باسم الشخص؟","title":"هل يوجد دعاء مشروع عند عيادة المريض؟","answer":"الجواب:\nيُدعى له، فالدعاء طيب، إذا زار أخاه دعا له، والحديث فيه ضعف، لكن يُرجى إجابته: أسأل الله العظيم ربّ العرش العظيم أن يشفيك سبع مراتٍ.","link":"https://binbaz.org.sa/fatwas/21589/هل-يوجد-دعاء-مشروع-عند-عيادة-المريض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في عيادة المريض.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":1603,"question":"الرجل إذا دعا والديه لترك بعض المعاصي ولم يستجيبا هل له أن ينزل من البيت ويتركهما؟","title":"كيف يكون البر بالوالدين العاصيين؟","answer":"الجواب:\nلا، يرفق بهما، الله قال في حقِّ الكافِرَيْن: وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا [لقمان:15]، حتى الكافِرَيْن يرفق بهما، ويعتني بهما.","link":"https://binbaz.org.sa/fatwas/21707/كيف-يكون-البر-بالوالدين-العاصيين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/وجوب الرفق بالوالدين العاصيين.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":1622,"question":"عبارة \"هذا شخصٌ كافٍّ خيرَه وشرَّه عن الناس\"؟","title":"حكم قول \"هذا شخصٌ كافٍّ خيرَه وشرَّه..\"","answer":"الجواب:\nإذا كفَّ شرَّه فهو مشكور، أما إذا كفَّ خيرَه فليس بمشكورٍ.","link":"https://binbaz.org.sa/fatwas/21727/حكم-قول-هذا-شخص-كاف-خيره-وشره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/قول هذا شخصٌ كافٍ خيرَه وشرَّه عن الناس.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":1677,"question":"الإعلام بالنسبة لمن يُحبّه على حسب النصوص للوجوب أم للاستحباب؟","title":"هل الإعلام بالحب في الله مستحب أم واجب؟","answer":"الجواب:\nالمشهور في مثل هذا أنه للاستحباب.","link":"https://binbaz.org.sa/fatwas/21783/هل-الاعلام-بالحب-في-الله-مستحب-ام-واجب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل إعلام من يحبه في الله للوجوب أم للاستحباب.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":1686,"question":"هل يُقال: فلان ملتزم، أو: فلان مستقيم؟","title":"ما حكم الوصف بـ\"مستقيم\" و\"ملتزم\"؟","answer":"الجواب:\nالأحسن أن يُقال: ظاهره الخير؛ لأنَّ الاستقامة والالتزام قد تخفى على الناس، قد يكون في باطن الأمر ليس كذلك.\nس: ما يُقال بالتفصيل؟\nج: يقال: ظاهره الخير، أو: ظاهره العدالة، فالناس ليس لهم إلا الظاهر.\nس: ما يقال: هذا سابقٌ بالخيرات، وهذا مُقتصِدٌ، وهذا ظالمٌ لنفسه؟\nج: لا، هذا صعب، ألا يضبط الأمور، لكن مَن أظهر الخير يُقال: ظاهره الخير، ونشهد له بالخير، والحمد لله، فالعمل على الظواهر.\nس: إذا كان الإنسانُ في الظاهر ملتزمًا؛ لكن هناك شواهد تدل على أنَّه غير ملتزمٍ؛ هل يُبلغون وليَّ الأمر؟\nج: هذا فيه تفصيل، إذا أظهر المعاصي يُبَلَّغ ولي الأمر، إن كان فيها حدودٌ يُبَلَّغ حتى يُقام عليه الحدّ، بعد النَّصيحة، وبعد التَّوجيه.\nس: إن قال: ملتزم أو مستقيم، نحسبه كذلك، يعني: مَن زاد: نحسبه كذلك؟\nج: كذلك، طيب.","link":"https://binbaz.org.sa/fatwas/21792/ما-حكم-الوصف-بـمستقيم-وملتزم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما يقال في الشخص المستقيم.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":1691,"question":"رجلٌ اعتاد صيامَ الاثنين والخميس، فإذا دُعِيَ يوم الاثنين يعني: وعده شخصٌ وقال له: يوم الاثنين - إن شاء الله - تتغدَّى عندي، فهل الأفضل أن يقول له: أنا اعتدتُ الصيامَ أو يفطر؟","title":"حكم مَن دُعِي لوليمة في يومٍ اعتاد صومه","answer":"الجواب:\nلا، يُجيب الدعوةَ ولا يأكل، يُجيب الدعوةَ، ويعتذر عن الطعام، وإن أفطر فلا بأس، فالنبي ﷺ قال: إذا دُعِيَ أحدُكم فليُجِبْ: فإن كان صائمًا فليدعو، وإن كان مُفْطِرًا فليطعم، إن كان صائمًا يدعو لهم ويقول: سامحوني أنا صائم، وجزاكم الله خيرًا، فيذهب إليهم، ويدعو لهم، وإن أفطر فلا بأس.\nس: مُخَيَّرٌ بين الاثنين؟\nج: نعم مُخَيَّرٌ، وإن كان جبرُهم بالفطر أفضل.\nس: يعني: يكون أميرَ نفسه؟\nج: نعم، لكن يُجيبهم، ويذهب إليهم، ثم يعتذر، أو يُفْطِر، ويأكل معهم.\nس: هل الأفضل أن يعتذر لهم؟\nج: إذا كان يَجْبُرُهم بذلك، ويرى أنَّ المصلحة في إفطاره جَبْرًا لخواطرهم أفطر، وإن لم يكن يضرُّهم، ولا يهمُّهم؛ أفطر أو ما أفطر فيعتذر، يقول: سامحوني أنا صائم، وجئتُ وأجبتُ الدَّعوة، وسامحوني في أن أرجع.","link":"https://binbaz.org.sa/fatwas/21797/حكم-من-دعي-لوليمة-في-يوم-اعتاد-صومه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من كانت له عادة صيام ودعي لوليمة يوم صيامه هل يجيب أم يعتذر.mp3","categories":["صيام التطوع","حكم الزواج وأهميته","الآداب والأخلاق المحمودة"]},{"id":1709,"question":"إذا لم يكن في البيت أحدٌ فهل ترد الملائكةُ السلام؟","title":"هل ترد الملائكةُ السلام إذا لم يكن بالبيت أحدٌ؟","answer":"الجواب:\nما بلغني شيء في هذا، إذا دخل البيت وفيه أحدٌ سلَّم، وإذا لم يكن فيه أحدٌ فلا يحتاج إلى سلامٍ.","link":"https://binbaz.org.sa/fatwas/21815/هل-ترد-الملاىكة-السلام-اذا-لم-يكن-بالبيت-احد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في السلام ورد السلام.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":1711,"question":"كان النبيُّ إذا تكلَّم كرر الكلامَ ثلاثَ مرات، فهل يُؤخَذ منه أنَّ من السنة إذا تكلَّم الإنسانُ أن يُعيد الكلام ثلاث مرات، ليس فقط في السلام؟","title":"هل مِن السُّنة تكرار الكلام ثلاث مرات؟","answer":"الجواب:\nلا، مقصوده أنه إذا خشي ألا يسمعوا كرَّر حتى يبلغهم.\nس: عندنا جملة أخيرة لم يقرأها بعد ورواه البخاري: \"وهذا محمُولٌ عَلَى مَا إِذَا كَانَ الجَمْعُ كثيرًا\".\nج: نعم، يعني: إذا خشي ألا يبلغهم، أما إذا كان يظن أو يعلم أنه بلغهم فلا حاجة للتكرار، جمعًا بين الأحاديث.","link":"https://binbaz.org.sa/fatwas/21817/هل-من-السنة-تكرار-الكلام-ثلاث-مرات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل من السنة تكرار الكلام ثلاث مرات.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":1712,"question":"حين يشير بالسلام هل يتلفظ به؟","title":"حكم الإشارة بالسلام دون كلام","answer":"الجواب:\nإذا صاروا بعيدين أو يخشى ألا يسمعوا؛ يُشير مع اللفظ.","link":"https://binbaz.org.sa/fatwas/21818/حكم-الاشارة-بالسلام-دون-كلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في السلام ورده.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":1715,"question":"هل يجوز ردّ السلام بقول: \"وعليكم\" أم أنَّ هذا خاصّ بأهل الكتاب؟","title":"حكم قول \"وعليكم\" في رد السلام للمُسْلِم","answer":"الجواب:\nوعليكم السلام.\nس: قلت في يوم الخميس أنَّ من فوائد حديث \"المسيء صلاته\": ويجوز أن يقول \"وعليكم\"؟\nج: لأنَّ الرسول قال للمُسيء: وعليك.\nس: أليس هناك زيادة أنَّه ردّ السلام؟\nج: بلى، ردَّ عليه السلام، لكن هذه الرواية وعليك تُسمَّى ردًّا، والمبتدأ مُقدَّر، يعني: \"السلام\"، فهذا يُسمَّى ردًّا، ولكن إذا كمَّل يكون أحسن.","link":"https://binbaz.org.sa/fatwas/21821/حكم-قول-وعليكم-في-رد-السلام-للمسلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم قول وعليكم في رد السلام.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":1717,"question":"إذا بدأ الكافرُ بالسلام على المسلم؟","title":"كيف يرد المسلم لو بدأ الكافر بالسلام؟","answer":"الجواب:\nيرد عليه ويقول: \"وعليكم\"، فالنبي ﷺ قال: لا تبدؤوا اليهودَ والنصارى بالسلام، وقال: إذا سلَّم عليكم أهلُ الكتاب فقولوا: وعليكم.\nس: والفضل هنا يكون للمسلم؟\nج: نعم.","link":"https://binbaz.org.sa/fatwas/21823/كيف-يرد-المسلم-لو-بدا-الكافر-بالسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/بدأ الكافر بالسلام على المسلم فكيف يرد، ولمن الفضل.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":1720,"question":"إذا كانت مجموعة فيهم المسلم وغير المسلم، كيف أُسلّم عليهم؟","title":"حكم السلام على جماعة فيهم مسلمون وغيرهم","answer":"الجواب:\nسلِّمْ على الجميع وانوِ المسلمين، فالنبي مرَّ على مجلسٍ فيه مسلمون ويهود ووثنيون، فسلَّم عليهم والنية على المسلمين.","link":"https://binbaz.org.sa/fatwas/21827/حكم-السلام-على-جماعة-فيهم-مسلمون-وغيرهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/وجد جماعة من الناس فيهم مسلمين وغير مسلمين فكيف يسلم عليهم.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":1729,"question":"الكافر إذا عطس؟","title":"حكم تشميت الكافر وصيغ الحمد والتشميت","answer":"الجواب:\nإذا عطس وحمد الله يُقال: \"يهديكم الله\"، كما كان اليهود يتعاطسون عند النبي ﷺ، فإذا حمدوا الله قال: \"يهديكم الله\".\nس: من باب الدعاء؟\nج: من باب الدعاء لهم بالهداية.\nس: قول القائل: إن لتشميت العاطس ثلاث صيغٍ: أوَّلها: إذا قال: \"الحمد لله\"، فرد عليه الشَّامت بأن يقول: \"يهديكم الله ويُصلح بالَكم\"؟\nج: \"يرحمك الله\".\nس: نعم، الثاني: إذا عطس وقال: \"الحمد لله رب العالمين\"، فإذا ردَّ عليه الشامت فإنه يقول: \"يغفر الله لنا ولكم\"؟\nج: لا، ما لها أصل، كلها يحمد الله، والمشَمِّت يقول: \"يرحمك الله\"، فيقول: \"يهديكم الله ويُصلح بالكم\".\nس: يعني: ما جاءت أحاديث تذكر مثلًا: \"الحمد لله على كل حال\"؟\nج: أنواع الحمد، فكيفما حمد الله يقول له: \"يرحمك الله\".\nس: هل ثبت عن رسول الله أنه إذا عطس أكثر من ثلاث مرات يقول له: \"شفاك الله\"؟\nج: ما جاء فيه شيء يثبت، إنما قال: هذا مزكوم، ولكن ما يمنع من تشميته إذا حمد الله..... وإذا دعا له بالشفاء فلا بأس.","link":"https://binbaz.org.sa/fatwas/21836/حكم-تشميت-الكافر-وصيغ-الحمد-والتشميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تشميت العاطس وحكم إذا عطس الكافر هل يشمت.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":1741,"question":"تقبيل الرجل على الخدّين، أو التقبيل بين الرجال على الخدّين؟","title":"حكم التقبيل بين الرجال على الخدين والأنف","answer":"الجواب:\nالأفضل بين العينين أو على الرأس، أما إذا قبَّل بنته أو أخته على خدِّها فلا بأس، يُروى عن الصديق أنه كان يُقبِّل عائشةَ على خدِّها.\nس: تقبيل الأنف؟\nج: الأنف أو الجبهة ما فيه بأس.\nس: الصديق ما قبَّل الرسول ﷺ على خدِّه؟\nج: قبَّل ابنته عائشة.","link":"https://binbaz.org.sa/fatwas/21848/حكم-التقبيل-بين-الرجال-على-الخدين-والانف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم التقبيل بين الرجال على الخدين والأنف.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":1743,"question":"تقبيل الرِّجْلَين للوالِدَين؟","title":"ما حكم تقبيل أقدام الوالدين؟","answer":"الجواب:\nيُقبِّل ما بين عينيه ويكفي، ما بين عينيه، أو أنفه، أو جبهته، كله طيب.\nس: تقبيل اليد للوالد؟\nج: إذا قبَّلها لا بأس، لكن الرأس أفضل، كما فعلت فاطمةُ مع أبيها عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/21850/ما-حكم-تقبيل-اقدام-الوالدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تقبيل الرِّجْلَين للوالِدَين.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":1745,"question":"مَن ترك المصافحة هل خالف السنة؟","title":"هل تَرْك المصافحة مخالفة للسُّنة؟","answer":"الجواب:\nعند اللقاء؟\nس: نعم.\nج: نعم، السُّنَّة المصافحة عند اللقاء، تَرَكَ الأفضل.","link":"https://binbaz.org.sa/fatwas/21852/هل-ترك-المصافحة-مخالفة-للسنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/جزاء من فعل السنة وخالفها.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":1759,"question":"نصب اليد عند قرب الفجر هذا خاصّ بالسفر أو في كلّ...؟","title":"هل النَّوْم مع نصب اليد قبل الفجر سُنة دائمة؟","answer":"الجواب:\nحتى في الحضر كان ينام ﷺ على شقه الأيمن، يستريح، فإذا كان الوقت قصيرًا وأراد أن يستريح ويستطيع أن ينام على شقِّه الأيمن فعل؛ لأنَّ هذا أقرب إلى ألا ينام، لكن ما كلٌّ يستطيع أن ينام على اليد، لكن مَن استطاع فحسنٌ إذا كان الوقت قصيرًا.\nس: الآن مشي الليل فيه خطورة فيه سيارات وخطورة في كثرة الدّواب والإبل؟\nج: على كل حال، الرسول ﷺ أخبر عن زمانه، فإذا صار الطريق فيه خطورة يترك الخطورة، فمراد النبي ﷺ الشيء الذي ما فيه خطورة، فإذا جاء في طريقٍ فيه خطورة يتجنبه.","link":"https://binbaz.org.sa/fatwas/21866/هل-النوم-مع-نصب-اليد-قبل-الفجر-سنة-داىمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/فوائد في السفر.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":1806,"question":"مدحُ الناس للمؤمن ألا يكون من عاجل بُشرى المؤمن؟","title":"ما حكم المدح؟ وما دلالته للممدوح؟","answer":"الجواب:\nبلى، هذه مسألة أخرى، إذا أُثْنِي عليه بما فيه فهذا من عاجل بُشراه، أما إذا أُثني عليه بشيءٍ ما هو فيه فهذا يغُرُّه.\nس: إذا مُدِحَ الرجلُ في وجهه؟\nج: إذا دعت الحاجةُ فالشيء القليل، وإلا ما ينبغي المدح، فالرسول ﷺ لما سمع رجلًا يمدح شخصًا قال: قطعت ظهره، ويلك! إذا أراد أحدُكم فليقل: أحسبه كذا والله حسيبه، وقال: إذا رأيتم المدَّاحين فاحثُوا في وجوههم التُّراب.\nس: الممدوح ماذا يقول للمادح؟\nج: يقول: جزاك الله خيرًا، اقصر، لا تمدح، أنا أعلم بنفسي. لكن الشيء القليل يُعفى عنه ولا بأس به، مثلما قال ﷺ لما رأى عمر: إنَّك إذا سلكتَ فجًّا سلك الشيطانُ فجًّا غير فجِّك.\nس: وإذا استطاع الإنسانُ أن يُنْكِرَ بيده على المادح؟\nج: لا، ما يحتاج يد، إلا حثو التراب.\nس: يحثو في وجهه التراب؟\nج: إذا أمن الفتنة، أما لا؛ فيكفي النصيحة؛ لأن بعض الناس ما يتحمَّل هذا.","link":"https://binbaz.org.sa/fatwas/21914/ما-حكم-المدح-وما-دلالته-للممدوح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل مدح الناس للعبد من عاجل بُشرى المؤمن.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":1807,"question":"المُداراة ما معناها، وهل هي من المدح؟","title":"ما معنى \"المداراة\" وهل تدخل في المدح؟","answer":"الجواب:\nالمداراة: يعمل بالخير، ولكن يتحرى الكلمات المناسبات والأفعال المناسبة حتى لا تقع فتنة، يفعل الخير والحق لكن ما هو بالشدة ولا بالعنف، يُداري الأمور حتى لا تقع فتنة.","link":"https://binbaz.org.sa/fatwas/21915/ما-معنى-المداراة-وهل-تدخل-في-المدح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما المقصود بالمداراة.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":1820,"question":"مصافحة المرأة الأجنبية من أجل المصلحة؟","title":"حكم مصافحة المرأة الأجنبية للمصلحة","answer":"الجواب:\nلا، ما يجوز مصافحة النساء، لكن يُكلِّمها بغير مصافحةٍ، يقول النبي ﷺ: إني لا أُصافح النساء، وتقول عائشة رضي الله عنها: \"والله ما مسَّت يدُ رسول الله يدَ امرأةٍ قط، ما كان يُبايعهن إلا بالكلام\".\nس: التسليم عليهن؟\nج: بالكلام: السلام عليكم، فالنبي ﷺ مرَّ على النساء فسلَّم عليهنَّ.","link":"https://binbaz.org.sa/fatwas/21928/حكم-مصافحة-المراة-الاجنبية-للمصلحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم مصافحة المرأة الأجنبية والتسليم عليها من أجل المصلحة.mp3","categories":["قضايا المرأة","الآداب والأخلاق المحمودة"]},{"id":1829,"question":"بعض الناس إذا جاء يشرب وكان في يده دسم يضع يده تحت الكأس؟","title":"حكم الاستعانة باليد اليُسرى في الأكل والشرب","answer":"الجواب:\nيستعين باليُسرى، ما في بأس، إذا دعت الحاجة يستعين باليُسرى، فالنبي ﷺ كان يستعين بها في التَّعرُّق بالعظم، فيأخذ السكين ويستعين باليُسرى، فإذا دعت الحاجةُ إلى الاستعانة باليُسرى فلا بأس.","link":"https://binbaz.org.sa/fatwas/21937/حكم-الاستعانة-باليد-اليسرى-في-الاكل-والشرب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/كيفية الشرب لمن كان في يده اليمنى شيء.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":1895,"question":"الدفاية تكون من جنس النار؟","title":"هل المدفأة مثل النار في وجوب إطفائها؟","answer":"الجواب:\nالأقرب أنها ما هي من جنسها؛ لأنها للتدفئة، لحاجتهم إليها.\nس: لأنَّ منها أنواعًا تكون شبه النار؟\nج: على كل حال، إذا كان فيها خطرٌ تدخل في الموضوع.","link":"https://binbaz.org.sa/fatwas/22006/هل-المدفاة-مثل-النار-في-وجوب-اطفاىها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل الدفاية من جنس النار.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":1897,"question":"كثير من البيوت يتركون الكهرباء –يعني: النور- في الليل كله، هل هذا من الإسراف؟","title":"هل يجب إطفاء ضوء الكهرباء ليلًا مثل النار؟","answer":"الجواب:\nعلى كل حال، بعضهم مِن الجهل، وبعضهم يظن أنه لا بدّ منه في الليل، فهذا يقوم، وهذا ينزل، وهذا يخرج للحمام، فلا بد من وجود النور، يرون أنه بحمد الله مأمون وما هناك خطر، والغالب أنه ليس هناك خطر، لكن الحيطة فعل السنة، فإطفاؤها أحوْط وأحسن على فعل السنة، وإلا فالغالب أنه لا يوجد خطر مثل النار التي تشتعل.\nس: الضوء مثل النار؟\nج: أسهل وأخفّ.\nس: الأفضل إطفاؤه؟\nج: ما في شك مطلقًا، الأفضل إطفاؤه.","link":"https://binbaz.org.sa/fatwas/22008/هل-يجب-اطفاء-ضوء-الكهرباء-ليلا-مثل-النار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يقاس ضوء الكهرباء على النار في وجوب الإطفاء.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":1976,"question":"دخل رجلٌ المجلس، وكان هناك رجلٌ كبير السن، فهل يبدأ في السلام باليمين أم يُسلِّم عليه مباشرةً إذا كان هو في وسط المجلس؟","title":"من أين يبدأ في السلام وكذا الضيافة","answer":"الجواب:\nيُسلِّم على الجميع، ويبدأ برئيس المجلس، كبير المجلس، فقد كان الصحابة إذا دخلوا بدأوا بالنبي ﷺ -رئيس المجلس- ثم عن يمينه، وعن شماله، فإذا كانت هناك كُلْفَة أو قد يُستنكر عليه ذلك أو يُساء به الظن فيُسلِّم على الجميع وينتهي حيث ينتهي المجلس، فإذا دخل على مجلسٍ ورأى أنَّ من الأدب أن يُسلِّم على كبيرٍ ثم على مَن حوله فعل ذلك، يفعل ما هو الأصلح.\nس: الشاي والقهوة؟\nج: كذلك، يبدأ برئيس المجلس، ثم مَن كان عن يمينه، مثلما كانوا يبدأون بالنبي ﷺ، ثم يدفعون إلى مَن عن يمينه عليه الصلاة والسلام، إلا أن يسمح مَن كان عن اليمين لليسار فلا بأس.","link":"https://binbaz.org.sa/fatwas/22092/من-اين-يبدا-في-السلام-وكذا-الضيافة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من أين يبدأ في السلام من اليمين أم برئيس المجلس وكذا الضيافة.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":1980,"question":"هل هناك نهيٌ عن النوم بعد صلاة العصر؟","title":"حكم النوم بعد صلاتي العصر والمغرب","answer":"الجواب:\nما ورد شيء، ما أعلم أنه ورد في هذا شيء، إلا من كلام بعض الشعراء، لكن لا وجهَ له، لا يُعَوَّل عليه.\nس: يعني ما فيه شيء؟\nج: لا، ما فيه شيء، فلا بأس به.\nس: النوم بعد صلاة المغرب مكروه؟\nج: نعم، مكروه.","link":"https://binbaz.org.sa/fatwas/22096/حكم-النوم-بعد-صلاتي-العصر-والمغرب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم النوم بعد صلاة العصر والمغرب.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":2013,"question":"قد تمدح رجلًا ويزيد في العمل إذا مدحته؟","title":"حكم تحقير النفس وما يفعل مَنْ مَدَحَه الناس؟","answer":"الجواب:\nالشيء القليل الذي ما يخشى من شره؛ لا بأس، مثل ما جرى للصحابة  مع النبي ﷺ.\nس: كيف يواجه الرجل مدح الناس إذا أثنوا عليه في وجهه؟\nالشيخ: يقول: الله يغفر لي ولكم، غفر الله لي ولكم، عفا الله عني وعنكم، وما أشبه ذلك.\nس: يَحُطُّ مِنْ نفسه؟\nالشيخ: يقول: الله يعفو عني وعنكم، الله يغفر لنا، نسأل الله المغفرة، نسأل الله العفو، نسأل الله أن يجعلنا وإياكم خير مما يظن الناس.\nس: كان فوق جبل عرفة، وكان يحقر نفسه، ويقول: لولا أنا لغفر لمن فوق الجبل؟\nالشيخ: لا يُعْجَب بنفسه.\nس: كان فوق جبل عرفة وهو يقول: لولا أنا لغفر لمن فوق جبل عرفة؟\nالشيخ: لا ما له لزوم هذا، هذا كذب، وأيش يدريه؟ لا بأس يقول: الله يعفو عنا وعنكم، يا أخي لا تمدح، وجزاك الله خيرًا، ونحو هذا.\nس: الثناء عليه وتشجيعه على العمل وكذا؟\nالشيخ: إذا كان قليلًا؛ لا بأس للمصلحة، ولا يخشى منه مضرة؛ لا بأس إن شاء الله، وعليه يُحمل ما جاء عن الصحابة، الشيء القليل ولا يترتب عليه شر؛ لا بأس.","link":"https://binbaz.org.sa/fatwas/22129/حكم-تحقير-النفس-وما-يفعل-من-مدحه-الناس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في مدح الرجل وتحقير النفس.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":2088,"question":"وماذا عن الشفاعة للناس، كالشَّفاعة للفقير، بأن يقول: هذا فقير، وهذا جاره، أو أخوه، أو قريبه؟","title":"حكم الشفاعة للفقراء وذوي الحاجات","answer":"الجواب:\nلا بأس بها، فإذا علم فقره وحاجته فعليه أن يشفع له فيما يسدّ حاجته.","link":"https://binbaz.org.sa/fatwas/22206/حكم-الشفاعة-للفقراء-وذوي-الحاجات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تدخل الشفاعة للناس في المسألة.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":2096,"question":"هل ينبغي أن يشبع الإنسانُ تارةً ويترك الشِّبَع تارةً؟","title":"حكم الشِّبَع والرِّيّ من الطعام والشراب","answer":"الجواب:\nالأحسن له عدم الشّبع الكُلي، ولكن إذا شبع فلا بأس، ولهذا قال ﷺ لأبي هريرة: اشرب، فشرب، ثم قال: اشرب، فشرب، ثم قال: اشرب، فشرب، ثم قال: اشرب، قال: والذي بعثك بالحق، لا أجد له مساغًا. فلا بأس بالشِّبَع، ولا بأس بالرّي، ولكن إذا تركه بعض الأحيان كان أصلح، مثلما قال ﷺ: بحسب ابن آدم لُقَيمات يُقِمْنَ صلبه، فإن كان لا محالةَ فثلثٌ لطعامه، وثلثُ لشرابه... يعني: للتَّقَوِّي على طاعة الله.","link":"https://binbaz.org.sa/fatwas/22214/حكم-الشبع-والري-من-الطعام-والشراب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل للإنسان أن يشبع تارةً ويترك الشبع تارةً.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":2121,"question":"قوله ﷺ لأبي هريرة: اقعد (في الشراب)؟","title":"ما حكم الشرب جالسًا وقائمًا؟","answer":"الجواب:\nيدل على أنَّ الشُّرب قاعدًا أفضل كما تقدم.\nس: والقيام كيف يكون خلاف الأوْلى؟\nج: جائز، ولكن القعود أفضل.\nس: رواه البخاري أم مسلم؟\nج: المؤلف عزاه للبخاري.","link":"https://binbaz.org.sa/fatwas/22239/ما-حكم-الشرب-جالسا-وقاىما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الشرب جالسا أفضل.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":2122,"question":"إذا دخل رسول الله ﷺ على أصحابه وهم جلوسٌ هل كان يُصافحهم أم يُسَلِّم عليهم ثم يجلس حيث ينتهي به المجلس؟","title":"حكم المصافحة لمن دخل على قَوْمٍ جُلُوس","answer":"الجواب:\nيجلس حيث ينتهي به المجلس عليه الصلاة والسلام.\nس: والمُصافحة؟\nج: ما بلغنا، كان الصحابةُ إذا تلاقوا تصافحوا، وإذا دخل لم يقوموا له، ويجلس حيث ينتهي به المجلس عليه الصلاة والسلام.\nس: حديث المُصافحة؟\nج: سُنة، إذا تصافحوا سُنة، لكن ما بلغنا أنهم كانوا يقومون ويُصافحونه؛ لأنه قد يُكلِّف هذا كثيرًا.","link":"https://binbaz.org.sa/fatwas/22240/حكم-المصافحة-لمن-دخل-على-قوم-جلوس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من دخل على أناس وهم جلوس هل يصافحهم.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":2134,"question":"ما الصواب في أن الإنسان لا يتحدث بقوله: \"أنا أنا\"؟","title":"ما الصواب في كيفية الاستئذان؟","answer":"الجواب:\nإذا استأذن يقول: أنا فلان بن فلان.\nس: هذا منهيٌّ عنه؟\nج: نعم، عليه أن يُصَرِّح باسمه، أما \"أنا\" فتشتبه.","link":"https://binbaz.org.sa/fatwas/22252/ما-الصواب-في-كيفية-الاستىذان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/كيفية الاستئذان.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":2155,"question":"البداءة بالسلام: هل التّحقيق فيها للوجوب أم للاستحباب؟","title":"هل البَدْءُ بالسلام للوجوب أم للاستحباب؟","answer":"الجواب:\nالله أعلم، لكن ظاهر الأحاديث أنه ينبغي للمؤمن ألا يبخل بالبداءة، فيُبادر بالسلام، هذه هي السنة للمؤمن، يقول ﷺ في الحديث الصحيح: حقّ المسلم على المسلم سِتٌّ: إذا لقيتَه فسَلِّمْ عليه..، ويقول البراء: أمرنا رسولُ الله ﷺ بسبعٍ، وذكر منها: إفشاء السلام، فعلى الإنسان أن يُبادر به، سواء قلنا بالاستحباب أو بالوجوب، أمَّا الرد فهو واجب.","link":"https://binbaz.org.sa/fatwas/22274/هل-البدء-بالسلام-للوجوب-ام-للاستحباب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل التّحقيق في البداءة بالسلام للوجوب أم للاستحباب.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":2161,"question":"هل يُشرع أن نعفو عن الكافر إذا كنا لا نرجو إسلامه؟","title":"حكم العفو عن الكافر الذي لا يُرجى إسلامه","answer":"الجواب:\nولو، فَمَنْ عَفَا وَأَصْلَحَ [الشورى:40]، قد ينفعه الله ويهديه ويرى أن هذا من أخلاق الإسلام، وقد يُؤثِّر هذا في قلبه.","link":"https://binbaz.org.sa/fatwas/22282/حكم-العفو-عن-الكافر-الذي-لا-يرجى-اسلامه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/العفو عن الكافر إذا كان لا يرجو إسلامه.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":2178,"question":"إذا كان في المجلس كبيرُ السِّنّ وعالم وحافظ فبمَن يبدأ؟","title":"هل يُبدأ باليمين ولو كان بالمجلس كبيرٌ وعالمٌ؟","answer":"الجواب:\nيبدأ بمَن عن يمينه، إذا شرب يعطي من عن يمينه، ولو كان الذي عن يمينه عامِّيًّا..... إلا أن يأذن.\nس: يبدأ بالكبير أم بالعالم؟\nج: يبدأ بمن عن يمينه.\nس: أول ما يدخل المجلس يبدأ بمَن عن يمينه مباشرةً أو يبدأ بالكبار؟\nج: لا، يبدأ برئيس المجلس، ثم رئيس المجلس يُصَرِّفه عن اليمين.","link":"https://binbaz.org.sa/fatwas/22299/هل-يبدا-باليمين-ولو-كان-بالمجلس-كبير-وعالم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/بمَن يبدأ في المجلس بكبير السن أم بالعالم الحافظ.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":2247,"question":"إذا دخل شخصٌ في الإسلام واسمه سابقًا كان أعجميًّا، هل عليه أن يُغيّره إلى اسمٍ مسلمٍ؟","title":"هل يلزمُ الأعجميَّ إذا أسلم تغييرُ اسمه؟","answer":"الجواب:\nإن لم يكن اسمه محذورًا فلا يلزم تغييره، أمَّا إن كان غير طيبٍ فيُغيّره بما هو أحسن منه، مثل: عبد الكعبة، عبد النبي، وأشباه ذلك يُغيّره.","link":"https://binbaz.org.sa/fatwas/22370/هل-يلزم-الاعجمي-اذا-اسلم-تغيير-اسمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أسلم وله اسم أعجمي فهل له أن يغيره إلى اسم مسلم.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":2249,"question":"إنسان غضب، ماذا عليه أن يفعل ليُزيل هذا الغضب؟","title":"ما المشروع فعله عند الغضب؟","answer":"الجواب:\nيقول: أعوذ بالله من الشيطان الرجيم، ويتوضأ إذا تيسر الوضوء، ويجلس إن كان قائمًا، ويسكت إن كان يتكلم؛ حتى يهدأ غضبه.","link":"https://binbaz.org.sa/fatwas/22372/ما-المشروع-فعله-عند-الغضب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/التعامل مع الغضب.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":2257,"question":"العفو من باب النَّدب أم من باب الوجوب؟","title":"هل العفو واجب أم مندوب؟","answer":"الجواب:\nلا، من باب النَّدب، وإلا فللإنسان أن يطلب حقَّه وينتقم إذا رأى المصلحة في ذلك.","link":"https://binbaz.org.sa/fatwas/22380/هل-العفو-واجب-ام-مندوب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/العفو واجب أم مندوب.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":2297,"question":"إنَّ الملائكة لتستحي من عثمان ؟","title":"معنى حياء الملائكة مِن عثمان رضي الله عنه","answer":"الجواب:\nعثمان من أرباب الحياء ، وفي حديث عمران: الحياء خيرٌ كله، لا يأتي الحياءُ إلا بخيرٍ.","link":"https://binbaz.org.sa/fatwas/22421/معنى-حياء-الملاىكة-من-عثمان-رضي-الله-عنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/استحياء الملائكة من عثمان رضي الله عنه.mp3","categories":["التاريخ والسيرة","الآداب والأخلاق المحمودة"]},{"id":2298,"question":"إذا تُوفي الشخصُ الذي كان عنده السرّ؟","title":"حكم إفشاءُ أسرار الأحياء والأموات","answer":"الجواب:\nيختلف، إن كان يزول الضَّرر بوفاته فلا بأس، وإن كان ما يزول فلا يُفشيه، مثل: قصة فاطمة لما سارّها النبيُّ ﷺ وقال لها أنَّ أجلَه قريبٌ؛ بكت، ثم سارَّها النبيُّ ﷺ وذكر أنها سيدة نساء أهل الجنة فضحكتْ، فسألتْها عائشةُ فلم تُخبرها، فلما تُوفي النبيُّ ﷺ سألتها فقالت: نعم، أمَّا الآن أُخبرك، وأما قبل فهو سرّ؛ لأنَّه بوفاة النبي ﷺ زال المحذور في الإخبار بأنَّ أجله قريبٌ، فقد وقع الموتُ.\nس: إذا اشترط ألا يُفشي السرَّ حتى لو تُوفي؟\nج: لا يُفشيه.\nس: الأسرار عامةً؟\nج: الأسرار التي يضرّ إفشاؤها، ويُخشى أنَّ صاحبها لا يرضى، سواء عن جماعٍ أو غير جماعٍ.\nس: المرأة ما لها أن تُخْبِر أمّها أو أختها؟\nج: لا تُفشي السر، لا لأمِّها ولا لأختها، حتى لأبيها.\nس: إذا كانت هذه المرأةُ مطلقةً من رجلٍ، وأراد أن يتزوَّج من أخرى، وتخشى على أُختِها أن يضرَّها؟\nج: السر لا يُفشى إلا إذا أذن فيه صاحبُه أو زالت العِلَّة.","link":"https://binbaz.org.sa/fatwas/22422/حكم-افشاء-اسرار-الاحياء-والاموات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المحافظة على الأسرار.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":2315,"question":"ما المقياس بالنسبة للتَّكرير (في الكلام)؟","title":"هل مِن السُّنة تكرير الكلام لتوضيحه؟","answer":"الجواب:\nمثلما قال ﷺ: ثلاثًا.\nس: التَّفصيل بين الكلام هل يكون من التَّفضيل؟\nج: هذا من السُّنة، فمن السُّنة للمؤمن إذا تكلَّم أن يُوضِّح، سواء كان ناصحًا، أو مُسَلِّمًا، أو مُستشيرًا، يُوضِّح حتى يكون المخاطَب على بصيرةٍ.","link":"https://binbaz.org.sa/fatwas/22439/هل-من-السنة-تكرير-الكلام-لتوضيحه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/التَّفصيل في الكلام وتوضيحه.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":2331,"question":"رجل طلب الضِّيافة من أكثر من واحدٍ من أهل بلدٍ، واعتذروا ولم يُضَيِّفوه، فهل يأثمون؟","title":"هل يأثم أهل بلدٍ لم يضيِّفوا مَن نزل بهم؟","answer":"الجواب:\nإذا نزل بهم واعتذروا كلهم؛ يأثمون.\nس: وإذا ضيَّفوه ولم يُعطوه القِرَى، هل يجوز له أن يأخذ بغير إذنهم؟\nج: جاء في الحديث أنَّه إنْ لم يأمروا له بما يجب جاز له أن يأخذ، لكن إذا كان يخشى الفتنةَ فلا، وعليه أن يُعاملَهم بالتي هي أحسن حتى لا تقع فتنةٌ.\nس: طيب، وإذا كان الطعامُ مالًا عامًّا، كأن يكون مثلًا في حائطٍ به زروع، وهم لم يُضيِّفوه، هل يأخذ من هذا الحائط؟\nج: نعم، يأخذ قِراه.","link":"https://binbaz.org.sa/fatwas/22455/هل-ياثم-اهل-بلد-لم-يضيفوا-من-نزل-بهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/طلب الضِّيافة من أهل بلدٍ ولم يُضَيِّفوه، فهل يأثمون.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":2347,"question":"مَن دخل مجلسًا وفيه كبير -إمَّا عالم أو كبير في السن- فهل يبدأ باليمين؟","title":"هل يبدأ باليمين أم بالكبير مَنْ دخل مجلسًا؟","answer":"الجواب:\nيصل إلى رئيس المجلس أولًا ويُسَلِّم عليه، ثم مَن كان عن يمينه.\nس: وإذا كان يريد أن يُقدِّم شيئًا كالقهوة؟\nج: يبدأ برئيس المجلس، ثم مَن كان عن يمينه، مثلما كانوا يبدؤون بالنبي عليه الصلاة والسلام ثم مَن كان عن يمينه.","link":"https://binbaz.org.sa/fatwas/22472/هل-يبدا-باليمين-ام-بالكبير-من-دخل-مجلسا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/دخل مجلسًا وفيه كبير فهل يبدأ باليمين.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":2348,"question":"زيادة \"الرحمن الرحيم\"؟","title":"ما لفظ التسمية المشروع للطعام وغيره؟","answer":"الجواب:\nحسن؛ لأنها تمام التَّسمية.\nس: في الدّخول والخروج، والأكل ..؟\nج: كله، ما فيها بأس، إذا أتمَّها فطيب.\nس: حديث: سَمِّ الله، وكُلْ بيمينك على الوجوب أم على الاستحباب؟\nج: نعم على الوجوب، يجب أن يأكل بيمينه.\nس: زيادة \"الرحمن الرحيم\" عند قوله: \"بسم الله\" في الأكل؟\nج: هذا هو الكمال، وإن قال: \"بسم الله\" كفى، وإذا كمَّلها: \"بسم الله الرحمن الرحيم\" كان أكمل.","link":"https://binbaz.org.sa/fatwas/22473/ما-لفظ-التسمية-المشروع-للطعام-وغيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/التسمية عند الدخول والخروج والطعام ونحوه.mp3","categories":["الآداب والأخلاق المحمودة","الأدعية والأذكار"]},{"id":2349,"question":"تسمية الواحد تُجزئ عن البقية؟","title":"هل تجزئ تسمية الواحد في طعام الجماعة؟","answer":"الجواب:\nلا، ما تُجزئ. س: كل واحد يسمي؟ ج: نعم.","link":"https://binbaz.org.sa/fatwas/22474/هل-تجزى-تسمية-الواحد-في-طعام-الجماعة","audio":"https://files.zadapps.info/binbaz.org.sa/بعض آداب الطعام.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":2351,"question":"ما التَّسمية المشروعة في البداية؟","title":"ما السنة في التسمية عند بداية الطعام؟","answer":"الجواب:\n\"بسم الله\" و\"بسم الله الرحمن الرحيم\" هذه هي التَّسمية عند أوله.\nس: البسملة والحمد واجبة أم مُستحبَّة؟\nج: كلها مُستحبَّة، كلها سنة، لكن التَّسمية متأكِّدة؛ قال النبيُّ ﷺ للغلام: سَمِّ الله، وكُلْ بيمينك.","link":"https://binbaz.org.sa/fatwas/22476/ما-السنة-في-التسمية-عند-بداية-الطعام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/التسمية المشروعة عند بداية الطعام.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":2364,"question":"حديث عائشة: كان الرسول ﷺ إذا أوى إلى فراشه جمع كفيه ثم نفث فيه؟","title":"ما صحة وكيفية النفث بالمعوذات عند النوم؟","answer":"الجواب:\nثابت في الصحيحين.\nس: يمسح ما استطاع؟\nالشيخ: كان يقرأ بيده ويمسح على رأسه ووجهه وصدره وما أقبل من جسده ثلاث مرات، عليه الصلاة والسلام، إذا اشتكى فعل ذلك أيضًا.\nس: الأذكار الأخرى تُقال مع المعوذات؟\nالشيخ: نعم كل ما تيسر وَسَبِّحْ بِحَمْدِ رَبِّكَ قَبْلَ طُلُوعِ الشَّمْسِ وَقَبْلَ غُرُوبِهَا [طه:130].","link":"https://binbaz.org.sa/fatwas/22489/ما-صحة-وكيفية-النفث-بالمعوذات-عند-النوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/كان عليه الصلاة والسلام إذا أوى إلى فراشه جمع كفيه ثم نفث.mp3","categories":["الآداب والأخلاق المحمودة","الأدعية والأذكار"]},{"id":2388,"question":"زيارة المريض عودوا المريض هل تدل على الوجوب؟","title":"هل حديث \"عُودُوا المريض\" يعني الوجوب؟","answer":"الجواب:\nهذا الأصل في الأوامر، لكن المعروف عند العلماء أنها سُنة مؤكدة، وإلا الأصل في الأوامر الوجوب.","link":"https://binbaz.org.sa/fatwas/22513/هل-حديث-عودوا-المريض-يعني-الوجوب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/عودوا المريض، هل تدل على الوجوب.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":2493,"question":"أيها الناس أفشوا السلام الأمر للوجوب؟","title":"هل الأمر للوجوب في \"أفشوا السلام\"؟","answer":"الجواب:\nالمعروف عند العلماء أنه سُنة، والقول بالوجوب قول قوي، لكن المعروف عند العلماء أنه سُنة، والرد واجب وَإِذَا حُيِّيتُمْ بِتَحِيَّةٍ فَحَيُّوا بِأَحْسَنَ مِنْهَا أَوْ رُدُّوهَا [النساء:86] فالرد واجب والبدء سنة. وهكذا إطعام الطعام وصلاة الليل والناس نيام؛ كلها سُنة. الفريضة الخمس صلوات.\nس: ترجيحكم؟\nالشيخ: الظاهر قول الأئمة أنه سُنة، أما الرد وَإِذَا حُيِّيتُمْ بِتَحِيَّةٍ فَحَيُّوا بِأَحْسَنَ مِنْهَا أَوْ رُدُّوهَا [النساء:86] الرد واجب.","link":"https://binbaz.org.sa/fatwas/22623/هل-الامر-للوجوب-في-افشوا-السلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أيها الناس أفشوا السلام هل الأمر للوجوب.mp3","categories":["شروح الحديث","الآداب والأخلاق المحمودة"]},{"id":2574,"question":"حديث الثلاثة الذين طرقوا أهلهم ليلًا مع الرسول في غزوة فوجد كل واحد منهم عند زوجته رجلًا؟","title":"حكم طَرْق الرجل أهله ليلًا دون إخبارهم","answer":"الجواب: النبي نهى عن الطُرُوق ليلًا عليه الصلاة والسلام، أمر ألا يَطْرُق الرجلُ أهلَه ليلًا إلا أن يخبرهم، فلما قدم ﷺ في آخر النهار نزل حول المدينة ثم دخلها؛ لأنها قد يأتي أهله على حالة غير مرضية، وفي الحديث الآخر: لا يَتَخوَّن أهلَه السُّنَّة للمؤمن ألا يَقْدَم ليلًا إلا إذا كان قد أخبرهم، وإلا يُصبح.\nس: هل هذا ثابت عن الثلاثة من الصحابة؟\nالشيخ: ما أدري، ما أذكره.","link":"https://binbaz.org.sa/fatwas/22707/حكم-طرق-الرجل-اهله-ليلا-دون-اخبارهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/النهي عن طرق الرجل أهله ليلًا إلا أن يخبرهم.mp3","categories":["الحكم على الأحاديث","الآداب والأخلاق المحمودة"]},{"id":2703,"question":"سائل يقول أنه يرد على المكالمات الهاتفية ويقول: السلام عليكم، ويقول له: لا تقل السلام عليكم، قل: نعم. لأنه نحن نسلم عليك؟","title":"هل خَيْرُ المتكلِّمَيْن بالهاتف مَنْ يبدأ بالسلام؟","answer":"الجواب: خَيْرُهُما الذي يبدأ بالسلام، خَيْرُ المتكلِّمَيْن الذي يبدأ بالسلام، سواء هذا أو هذا.","link":"https://binbaz.org.sa/fatwas/22841/هل-خير-المتكلمين-بالهاتف-من-يبدا-بالسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/خير المتكلمين الذي يبدأ بالسلام.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":2802,"question":"لو قضى ما عليه من دَيْن ولكن أعطاه زيادة من غير جنس الدَّيْن؟","title":"حكم قضاء الدَّيْن مع زيادة مِن غير جنسه","answer":"الجواب: ما في بأس، مُحْسِن، جزاه الله خيرًا.","link":"https://binbaz.org.sa/fatwas/22950/حكم-قضاء-الدين-مع-زيادة-من-غير-جنسه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/قضى ما عليه من دين وأعطى زيادة من غير جنس الدين.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":2806,"question":"إذا اشترى سلعة ممكن يذكر الحديث: رحم الله امرءًا سَمْحًا إذا باع.. لصاحب المحل؟","title":"معنى حديث \"رحم الله امرءًا سَمْحًا إذا باع...\"","answer":"الجواب: ويش المانع طيب؟ يقول النبي ﷺ: رحم الله امرءًا سَمْحًا إذا باع، سَمْحًا إذا اشترى، سَمْحًا إذا اقتضى إذا كنت وإياه، الحديث للجميع للبائع والمشتري.","link":"https://binbaz.org.sa/fatwas/22955/معنى-حديث-رحم-الله-امرءا-سمحا-اذا-باع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ذكر حديث رحم الله امرأ إذا باع سمحا إذا اشترى سلعة من صاحب المحل.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":2814,"question":"هل الغِبْطة مِن غير أن يتمنى زوال النعمة؟","title":"ما معنى الغِبْطة؟","answer":"الجواب: نعم، يغبطه على الخير ويحب له الخير، ولا يحب زوال النعمة عنه، بل يحب له الخير ويدعوه إلى الخير ويرغّبه في الخير..... يُغْبط ويُدْعَى له بالتوفيق، ولا يُحْسَد.","link":"https://binbaz.org.sa/fatwas/22963/ما-معنى-الغبطة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما هي الغبطة.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":2950,"question":"نَفْض الفراش..؟","title":"هل يُعيد نَفْض الفراش مَن قام لعارض؟","answer":"الجواب: كذلك، كونه يَنْفُض فراشه بطرف ثوبه إذا راح وعوّد عليه، لا يدري ماذا عَقَبَه فيه، ولِيَه بطرف ثوبه كان هذا أفضل.","link":"https://binbaz.org.sa/fatwas/23106/هل-يعيد-نفض-الفراش-من-قام-لعارض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/نفض الفراش عند النوم.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":3009,"question":"تقبيل جبهة الوالد أو شيخ في العلم أو شيخ كبير في السن أو غير ذلك، هل جائز؟ وهل ورد هناك حديث في ذلك؟","title":"حكم تقبيل جبهة الوالد والعالم والكبير","answer":"الجواب: ما في حرج، تقبيل رأس الكبير أو الوالد أو الوالدة؛ لا بأس، النبي ﷺ كان يُقبّل فاطمة إذا دخلت عليه، يقوم لها ويُقبّلها وهي تقوم له وتُقبّله، والصدّيق ﷺ لما قَدِم والنبي ﷺ قد توفي وسُجّي كشف الغطاء عن وجهه وقَبّله بين عينيه، وقال: بأبي أنت وأمي لقد طِبْتَ حيًّا وميتًا، اللهم صلِّ عليه وسلم، إذا كان مَحْرَمًا، أو رجلًا مع رجل، أو امرأة مع امرأة، أو مَحْرَمًا قَبّل أمه أو أخته، لا بأس.","link":"https://binbaz.org.sa/fatwas/23167/حكم-تقبيل-جبهة-الوالد-والعالم-والكبير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم تقبيل جبهة الوالد أو شيخ علم.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":3026,"question":"مَنْ أدخل في الغِيبة: الرَّدَّ على أهل البدع والمخالفين، هل يصح هذا؟","title":"حكم غِيبة مَنْ أظهر فسقًا أو بِدْعة","answer":"الجواب: لا، غلط، مَنْ أظهر البدع ما له غِيبة، ومَنْ أظهر الفسق ما له غِيبة، الغِيبة لمن كان كلامه مستورًا ما أظهره، عمله السيئ ما أظهره، أما إذا أبرزه ما صارت غِيبة. الغيبة: أن تذكره بشيء لم يجهر به، أما من أظهر الشر والفسق فلا غيبة له فيما أظهر، قال الله جل وعلا في كتابه العظيم لَا يُحِبُّ اللَّهُ الْجَهْرَ بِالسُّوءِ مِنَ الْقَوْلِ إِلَّا مَنْ ظُلِمَ [النساء:148]، ويقول النبي ﷺ: كل أمتى معافى إلا المجاهرين، ولما دخل عليه رجل لا خير فيه قال: بئس أخو العشيرة، وفي لفظ قال: بئس ابن العشيرة، ائذنوا له، ولما مرَّ عليه بجنازة سوء أثنوا عليها شرَّا فقال: وَجَبَتْ لها النار أثنوا عليها شرًّا بما ظهر منها ولم يُنكِر عليهم ذلك، دلَّ على أن مَنْ أظهر الشر لا غيبة له.","link":"https://binbaz.org.sa/fatwas/23185/حكم-غيبة-من-اظهر-فسقا-او-بدعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل لمن أظهر فسقا أو بدعة غيبة.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":3030,"question":"هل يشرع ترك الأولاد للزوجة والخروج لتجديد الإيمان؟","title":"حكم ترك الأهل والخروج لتجديد الإيمان","answer":"الجواب: يعمل ما هو أصلح، إذا كان الخروج ما يضرهم؛ لا بأس يسافر، وإذا كان خروجه يضرهم فالجهاد فيهم أوْلى لتعليمهم وتوجيههم وإرشادهم والخوف عليهم من الشر. أما إذا كان خروجه ما يضرهم؛ عندهم مَنْ يقوم مقامه أو والدتهم طيبة تقوم مقامه؛ لا بأس.","link":"https://binbaz.org.sa/fatwas/23190/حكم-ترك-الاهل-والخروج-لتجديد-الايمان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ترك الأولاد للزوجة والخروج لتجديد الإيمان.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":3050,"question":"بعض الناس يُعَرّف بما يَكْرَه مثل ابن عُلَيّة، يُعرّف بذلك الاسم لكن هو يَكْرَه ذلك؟","title":"حكم تعريف إنسان بما يَكْرَه","answer":"الجواب: ولَوْ ولو، إذا عُرِف، مثل ابن علية، مثل عبدالله ابن أم مكتوم صحابي، ابن أم مكتوم يعرف بأمه، وعبدالله بن أُبي ابن سلول المنافق ينسب لأمه.","link":"https://binbaz.org.sa/fatwas/23210/حكم-تعريف-انسان-بما-يكره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تعريف الناس بما يكره.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":3076,"question":"حديث النبي ﷺ الذي عطس فيه الرجل فقال له مرتين: يرحمك الله، وفي الثالثة قال: الرجل مزكوم؟","title":"حكم تشميت العاطس المزكوم بعد مرتين","answer":"الجواب: لكن إذا حَمِد الله يُشَمّت ولو قال: مزكوم.\nالسؤال: يستمر في تشميته؟\nالشيخ: إنْ حَمِد الله يُشَمّت.","link":"https://binbaz.org.sa/fatwas/23236/حكم-تشميت-العاطس-المزكوم-بعد-مرتين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من عطس وحمد الله يشمت.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":3085,"question":"التسمية عند الرفع والحمد بعد إنزال الإناء: ما ورد هذا؟","title":"حكم تكرار التسمية والحمد في الشُّرْب","answer":"الجواب: لا، السُّنة عند الأكل يُسمّي في أوله، ويَحْمَد الله في آخِرِه.\nس: في الشرب ثلاث مرات إذا رفع الإناء قال: بسم الله، وإذا أنزله قال: الحمد لله، ثم يرفع ويقول: بسم الله؟\nالشيخ: ما ورد، يُسَمّي مرة واحدة في أوله والحمد في آخره، وإذا كرر جزاه الله خيرًا، لكن السُّنة تكفي واحدة، تسمية في أوله وحَمْدُ الله في آخِرِه.","link":"https://binbaz.org.sa/fatwas/23245/حكم-تكرار-التسمية-والحمد-في-الشرب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم التسمية عند الرفع والحمد بعد إنزال الإناء.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":3087,"question":"إذا كان من على يمينه أصغر ومن على شماله أكبر؟","title":"حكم البدء بمَنْ على اليمين لو كان صغيرًا","answer":"الجواب: يستأذن أو يُعطي مَنْ على يمينه ولو كان أصغر، مثل ما أعطى النبي ﷺ ابن عباس وترك الأشياخ، إلا إذا أذن الأصغر للذي عن يمينه أن يعطي الذي عن يساره فلا بأس.\nس: في المجلس يبدأ بالكبير أو على اليمين إذا دخل بالعود أو بالشاي؟\nالشيخ: رئيس المجلس وكبير المجلس، يبدأ بالكبير، ثم مَن على يمينه.","link":"https://binbaz.org.sa/fatwas/23247/حكم-البدء-بمن-على-اليمين-لو-كان-صغيرا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/السنة البدء بمن في اليمين ولو كان صغيرا.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":3089,"question":"الشرب ثلاثًا خاصٌّ بالماء فقط؟","title":"هل الشرب ثلاثًا خاصٌّ بالماء؟","answer":"الجواب: أفضل.\nس: ما ورد أن الرسول ﷺ شرب اللبن مرة واحدة؟\nالشيخ: في اللبن والماء جميعًا.","link":"https://binbaz.org.sa/fatwas/23249/هل-الشرب-ثلاثا-خاص-بالماء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل الشرب ثلاث خاص بالماء.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":3116,"question":"المضيف هل يبدأ بالكبير أو مَنْ على يمينه؟","title":"هل يبدأ المُضِيف بالكبير أو مَنْ على يمينه؟","answer":"الجواب: يبدأ برئيس المجلس، ثم رئيس المجلس يبدأ مِنْ على يمينه.\nس: يعني شرط أن يكون الكبيرُ رئيسَ المجلس؟\nالشيخ: نعم، مثل ما كانوا يبدؤون بالنبي عليه الصلاة والسلام.\nس: صاحب المجلس أو رئيس المجلس؟\nالشيخ: رئيس المجلس، كبير المجلس.","link":"https://binbaz.org.sa/fatwas/23276/هل-يبدا-المضيف-بالكبير-او-من-على-يمينه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/بمن يبدأ المضيف بالكبير أو من على يمينه.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":3185,"question":"هل ورد شيء إذا قام شخص لشخص كبير؟ هل هذه كرامة؟","title":"هل يجوز القيام للشخص لسِنِّه أو مكانته؟","answer":"الجواب: لا باس أن يقوم إليه ويصافحه، لمّا دخل كعب بن مالك بعد ما تاب الله عليه قام طلحة بن عبيدالله يهرول حتى صافحه، ولما جاء سعد بن معاذ ليحكم في بني قريظة قال النبي ﷺ: قوموا إلى سيدكم فقاموا إليه وصافحوه وأنزلوه من حماره.","link":"https://binbaz.org.sa/fatwas/23348/هل-يجوز-القيام-للشخص-لسنه-او-مكانته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم القيام للكبير.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":3217,"question":"قول الملائكة لإبراهيم عليه السلام قَالُوا سَلَامًا قَالَ سَلَامٌ [هود:69]. هل يؤخذ من هذا أن الإنسان يقول السلام بالنكرة دون ألف ولام؟","title":"حكم إلقاء السلام بلفظ \"سلام عليكم\"","answer":"الجواب: لا، الأفضل الأحاديث الصحيحة، مثل ما قال الله وَإِذَا حُيِّيتُمْ بِتَحِيَّةٍ فَحَيُّوا بِأَحْسَنَ مِنْهَا أَوْ رُدُّوهَا [النساء:86] تقول: السلام عليكم، وعليكم السلام، بالتعريف، هذا هو الأفضل، وإن قال \"سلام عليكم\" ما في بأس.","link":"https://binbaz.org.sa/fatwas/23380/حكم-القاء-السلام-بلفظ-سلام-عليكم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يقال السلام نكرة سلام دون ألف ولام.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":3218,"question":"إذا أراد شخص أن يرد على الهاتف أو التلفون هل يبدؤه بالسلام، أو يتأكد من الصوت ثم يسلم المتصل؟","title":"هل يُبْدَأ بالسلام عند الرد على الهاتف؟","answer":"الجواب: إن كان سَلَمَ هو تَرُدّ عليه، وإذا كان ما سَلَمَ تسأل: من أنت؟ ثم تقول: السلام عليك.\nس: يعني هو الذي يبدأ بالسلام؟\nالشيخ: إن بدأ وإلا أنت تبدأ.\nس: ليس الأولى كالآخرة؟\nالشيخ: ليست الأولى بأحق من الآخِرة.\nس: ما المقصود؟\nالشيخ: يعني السلام على الأُولى ما هي بأحق من الآخِرة، عليك أن ترد السلام، بل الرد أوجب؛ لأن الله قال: وَإِذَا حُيِّيتُمْ بِتَحِيَّةٍ فَحَيُّوا بِأَحْسَنَ مِنْهَا أَوْ رُدُّوهَا [النساء:86] قال العلماء: البدء مستحب، والرد واجب.","link":"https://binbaz.org.sa/fatwas/23381/هل-يبدا-بالسلام-عند-الرد-على-الهاتف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يبدأ بالسلام عند الرد على الهاتف.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":3219,"question":"لو قال شخص \"السلام عليكم\" فرد فقال: \"سلام\" بالتنكير، يكون أقل من التحية؟","title":"ما حكم ردّ السلام بقول: \"سلام\" بالتنكير؟","answer":"الجواب: السُّنَّةُ أن يقول: وعليكم السلام؛ لأن الله قال: وَإِذَا حُيِّيتُمْ بِتَحِيَّةٍ فَحَيُّوا بِأَحْسَنَ مِنْهَا أَوْ رُدُّوهَا.. [النساء:86].","link":"https://binbaz.org.sa/fatwas/23382/ما-حكم-رد-السلام-بقول-سلام-بالتنكير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/السنة في رد السلام أن يقول وعليكم السلام..mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":3685,"question":"استئذان عمر -أحسن الله إليك- النبي ﷺ ثلاثًا، هو ضابط للاستئذان؟","title":"ما ضابط الاستئذان؟","answer":"الجواب: هذا من الاستئذان قال: من استأذن فليستأذن ثلاثًا، فإن أُذن وإلا فلينصرف عمر انصرف في الثالثة وانصرف في الأولى والثانية؛ لكن من شدة ما في نفسه يحب أن يسأل النبي ﷺ عما وقع. وفيه أيضًا من الفوائد:  محادثة الإنسان الذي قد أصابه ما يغضبه بما يفرحه؛ لأنه قال: كنا نغلب نساءنا فقدمنا على قوم تغلبهم نساؤهم، فتبسم النبي ﷺ، يعني: كل إنسان يحادث من هو غضبان أو من هو محزون أو من هو مكروب بما يشرح صدره ويعينه على سعة البال، هذا طيب.","link":"https://binbaz.org.sa/fatwas/23874/ما-ضابط-الاستىذان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الاستئذان وضابطه.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":3799,"question":"لو طعم عند ناس يقول لهم: اللهم بارك لهم فيما رزقتهم؟","title":"هل يستحب لمن طعم عند أناس الدعاء لهم؟","answer":"الجواب: إذا طعم عند ناس يدعو لهم: اللهم بارك لهم فيما رزقتهم واغفر لهم وارحمهم، أكل طعامكم الأبرار، وأفطر عندكم الصائمون، وصلت عليكم الملائكة. هذا فيما يتعلق بالناس. أما ما يتعلق به هو: الحمد لله، يحمد ربه.","link":"https://binbaz.org.sa/fatwas/23999/هل-يستحب-لمن-طعم-عند-اناس-الدعاء-لهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يدعو بالبركة إذا طعم عند أناس.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":3843,"question":"بعض المرضى إذا سُئل يقول: ما نمتُ البارحة من شدَّة الوجع؟","title":"حكم إخبار المريض بحاله عند الألم","answer":"الجواب: الظاهر: ليس من الجزع، يُخبر عن الواقع، من باب الخبر.","link":"https://binbaz.org.sa/fatwas/24050/حكم-اخبار-المريض-بحاله-عند-الالم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إخبار المريض بحاله عند الألم.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":3912,"question":"زوج الأم يسمى \"عم\"؟","title":"هل يسمى زوج الأم \"عمّاً\"؟","answer":"الجواب: على ظاهر ما قاله الحافظ، وهو المشهور عندنا، لكن ما عليه دليل، كلام الحافظ حين قال هذا الكلام كأنه قد وجده في شيء، أو عمه لأن من عادة العرب تسمى ابن العم الكبير \"عم\" لأن أبا طلحة ابن عم أنس.. المقصود أن ابن العم عند العرب يسمى عمًّا، ويسمى الكبير عمًّا، ولو كان ابن عم الكبير يسمونه عمًّا كما قال معاذ ومعوذ لعبدالرحمن بن عوف: يا عم أين أبو جهل، وعبد الرحمن بن عوف ليس من الأنصار، بل قرشي مهاجري، قالا له: يا عم؛ لأنه كبير السن وهم صغار، فعندهم قاعدة أن الصغير يقول للكبير \"يا عم\" أو \"يا والد\" إلى الآن.","link":"https://binbaz.org.sa/fatwas/24130/هل-يسمى-زوج-الام-عما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يسمى زوج الأم عمّاً.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":3960,"question":"إذا لم يعطه شيئًا وأخذ حق الضيف...؟","title":"حكم أخذ الضيف حقه ممن لم يعطه","answer":"الجواب: ما له داع، المعروف من القواعد الشرعية: ما لم يحصل فتنة، إذا كان له قوة أو يعرفون أنهم إذا طلبوا حق الضيف أعطوهم إياه أو عندهم قوة يستطيعون بها أخذ حق الضيف بدون فتنة وبدون شر أكبر.  أما إذا كان أخذ حق الضيف يترتب عليه ما هو أشر؛ معروف في القاعدة الشرعية: ترك ما يفضي إلى شر.\nس: من أخذ منه بدون علمه؟\nالشيخ: لا يضر، كما يأخذ العبد نفقته والزوجة نفقتها من دون علم، يجتهد في هذا ويتحرى الواجب ويأخذه إذا كان لا يترتب عليه شر أكبر.\nس: يأخذه من أدنى الناس أو من أميرهم؟\nالشيخ: من الذي نزل عليه، الطائفة التي نزل عليها.","link":"https://binbaz.org.sa/fatwas/24186/حكم-اخذ-الضيف-حقه-ممن-لم-يعطه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم أخذ حق الضيف.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":3995,"question":"التشميت يجب على كل من سمعه؟","title":"هل يجب التشميت على كل من سمع العاطس؟","answer":"الجواب: يقول النبي ﷺ : كان حقًا على كل من سمعه والوجوب محل نظر، سنة مؤكدة، والقول بالوجوب قول قوي.","link":"https://binbaz.org.sa/fatwas/24226/هل-يجب-التشميت-على-كل-من-سمع-العاطس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يجب التشميت على كل من سمع.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":4084,"question":"الإنفاق للقريب تكون صلة؟","title":"ما فضل الإنفاق على الأقارب؟","answer":"الجواب: صدقة وصلة، يقول ﷺ: الصدقة على المسكين صدقة، وعلى ذي الرحم اثنتان: صدقة وصلة.","link":"https://binbaz.org.sa/fatwas/24324/ما-فضل-الانفاق-على-الاقارب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الإنفاق للقريب.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":4090,"question":"الأكل على خوان، ما يكون الأكل قائمًا؟","title":"حكم تناول الطعام على الخوان (المائدة)","answer":"الجواب: ليس قائمًا، بل قاعد، أكل على خوان وليس بقائمٍ، ولكن قاعد، ولكن القائم جائز أيضًا، الشرب قائمًا والأكل قائمًا جائز، ولكن الجلوس أفضل.","link":"https://binbaz.org.sa/fatwas/24330/حكم-تناول-الطعام-على-الخوان-الماىدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الأكل على الخوان.mp3","categories":["الأطعمة والأشربة","الآداب والأخلاق المحمودة"]},{"id":4091,"question":"فحمد الله وسمَّى، هل الحمد قبل التَّسمية على الطعام أو من باب البركة؟","title":"هل يُسَنُّ الحمد قبل التسمية على الطعام؟","answer":"الجواب: الحمد مطلوبٌ دائمًا، والمشروع أن يُسمِّي الله، والحمد لله تسمية، نوع تسمية، لكن المشروع التسمية عند الأكل، والحمد عند الفراغ، فإذا جمع بينهما: سمَّى الله وحمد الله عند الأكل، وحمد الله بعد الأكل؛ فهذا خيرٌ إلى خيرٍ.","link":"https://binbaz.org.sa/fatwas/24331/هل-يسن-الحمد-قبل-التسمية-على-الطعام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل الحمد قبل التسمية على الطعام.mp3","categories":["الأطعمة والأشربة","الآداب والأخلاق المحمودة"]},{"id":4093,"question":"بالنسبة لفعل النبي ﷺ من جهة فراشه ومأكله، هل يُقال أنها من السنة لو فعلها الإنسانُ أحيانًا؟","title":"هل التأسي بتواضع النبيﷺفي معيشته سُنَّة؟","answer":"الجواب: هذا من التواضع، لا شكَّ من التواضع وكسر النفس، إذا فعل الإنسانُ بعض الأشياء التي تُنافي الرفاهية بعض الأحيان لكسر النفس وتعويدها النشاط وتعويدها الخشونة نعم... وسَّع الله عليه وَسَّعوا، مثلما قال عمر: \"إذا وسَّع الله عليكم فوسِّعوا\"، النبي ﷺ إذا صادف شيئًا يسَّره الله له، في زواجه من زينب وضع لحمًا كثيرًا، وطعامًا كثيرًا، ودعا العامَّة عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/24333/هل-التاسي-بتواضع-النبيﷺفي-معيشته-سنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تواضع النبي في مأكله وفراشه.mp3","categories":["الآداب والأخلاق المحمودة","التاريخ والسيرة"]},{"id":4192,"question":"إذا كان المريض كافراً، وهو من أهله، هل يعوده؟","title":"حكم عيادة المريض الكافر","answer":"الجواب: ولو كافرًا يعوده، النبي عاد أبا طالب وهو كافر، وكان له خادم يهودي في المدينة فمرض فعاده النبي ﷺ، وقال له: اشهد ألا إله إلا الله وأني رسول الله، وكان عنده أبوه، فقال أبوه: أطع أبا القاسم، فقال: أشهد ألا إله إلا الله وأشهد أن محمدًا رسول الله، وخرج النبي من عنده وهو يقول: الحمد لله الذي أنقذه بي من النار كان خادمًا قبل أن يؤمر بخروج الكفار من الجزيرة فعاده وهو يهودي وعاد أبا طالب وهو مشرك، ولاسيما إذا كانت العيادة يُرجى فيها الخير يدعوه إلى الله؛ لعل الله ينقذه به.","link":"https://binbaz.org.sa/fatwas/24449/حكم-عيادة-المريض-الكافر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم عيادة المريض الكافر.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":4197,"question":"س: مشروعية الوتر في كل الأشياء..؟","title":"هل تستحب مراعاة الوتر في كل الأشياء؟","answer":"الجواب: هذا هو الأقرب، إلا فيما نص الشارع على أنه شفع، ولهذا استعملها النبي ﷺ في أكل التمرات في عيد الفطر، كان يأكل التمرات وترًا قبل أن يصلي العيد، وشرع الله الطواف سبعًا، والسعي سبعًا، ورمي الجمرات سبعًا... لأشياء.  فالأصل أن الوتر مطلوب، إلا فيما نص الشارع على أنه شفع كأربعة كصلاة الظهر والعصر والعشاء، والسنن ركعتين ركعتين.","link":"https://binbaz.org.sa/fatwas/24456/هل-تستحب-مراعاة-الوتر-في-كل-الاشياء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الوتر مطلوب إلا فيما نص الشارع.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":4258,"question":"شباب يدعون من قِبَل الديانات في مطاعم فيها خمور تباع، فهل يستجيبون لهذه الدعوات مع تكرارها أم يتركونها؟","title":"هل تُجاب دعوة غير المسلم في مطعم به خمر؟","answer":"الجواب: إن كان يشرب الخمر في محلهم اللي يأكلون فيه وإن كان شرب الخمر له محل، واللي يعزمهم فيه غرف أخرى لا بأس؛ لأن الناس قد يحتاجون إلى المطاعم، فإذا كانت المطاعم فيها أقسام فيها لمن أراد الخلوة بطعامه عن النساء وعن الخمور فلا بأس.\nس: الطاولة التي هو فيها هو وصاحبه ليس بها خمر لكن الطاولة التي بجانبهم فيها خمر؟\nج: لا ينبغي هذا إلا مع الضرورة، لا يأتيها إلا مع الضرورة؛ لأن هذا مشاهدة للشر ويُتهم بالتساهل، لا ينبغي إلا في محلات سليمة، محلات ما فيها مشاهدة للخمر.","link":"https://binbaz.org.sa/fatwas/24528/هل-تجاب-دعوة-غير-المسلم-في-مطعم-به-خمر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يجاب دعوة الديانات في مطاعم فيها خمور.mp3","categories":["الأطعمة والأشربة","الآداب والأخلاق المحمودة"]},{"id":4288,"question":"الرؤيا إذا كان الواحد جُنُباً؟","title":"هل تصح الرؤيا من الجُنُب؟","answer":"الجواب: ولو جُنُب قد تكون صحيحة، وقد تكون من وساوس الشيطان، وقد تكون من حديث النفس، وقد تكون صحيحة ولو أنه جنب. ولكن السنة له أن ينام على وضوء.","link":"https://binbaz.org.sa/fatwas/24560/هل-تصح-الرويا-من-الجنب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تقع الرؤيا من الجنب.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":4303,"question":"المعانقة مع التقبيل أو بدون التقبيل؟","title":"هل تكون المعانقة مع التقبيل أو دون تقبيل؟","answer":"الجواب: المعانقة لي الرأس مع الرأس، هذه المعانقة، والتقبيل شيء، كانت فاطمة إذا دخلت على النبي ﷺ قام إليها وقبّلها وأخذ بيدها، وكانت إذا دخل عليها أبوها دخلت إليه وقبّلته وأخذ بيدها عليه الصلاة والسلام.\nس: لكن في مثل هذه الحالة الرجل إذا كان عنده علم والإنسان يقدره ويحترمه؟\nج:الأمر سهل، ولكن المصافحة أوْلى، عدم التكلف أوْلى، إلا إذا قدم من السفر كما كان يفعل الصحابة إذا كان قدوم من سفر وعانقه، المعانقة لي الرأس مع الرأس أو تقبيل ما بين عينيه لا بأس، أما الحضر فعدم التكلف أولى، المصافحة أولى.","link":"https://binbaz.org.sa/fatwas/24577/هل-تكون-المعانقة-مع-التقبيل-او-دون-تقبيل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المعانقة مع التقبيل أو بدون التقبيل.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":4743,"question":"إذا أُصيب بمصيبةٍ ولم يصبر فهل يُؤجر؟","title":"هل يُؤجر من أُصيب بمصيبةٍ ولم يصبر؟","answer":"إذا جزع لا، متوعد: ومَن سخط فله السخط، لكن لا يمنع ذلك من كونها قد تُكفر السيئات مع جزعه، ولا يحصل له الأجر الذي يُعطيه الله للصَّابرين، وأما في نفسها فهي مُكفِّرة.","link":"https://binbaz.org.sa/fatwas/25077/هل-يوجر-من-اصيب-بمصيبة-ولم-يصبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يُؤجر من أُصيب بمصيبةٍ ولم يصبر.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":4807,"question":"ما رأيكم في أن يكون الرجلُ حييًّا جدًّا، وقد يتورط في أزمات فوق طاقته، وقد يُسبب له مشاكل وهمومًا ردحًا من حياته أو كل عمره؟","title":"ما ضابط الحياء المحمود في الرجل؟","answer":"لا بدّ من حياء، لا يُخالف الشرع. حياء ما يأمر بمعروفٍ، ولا ينهى عن المنكر، ولا يقوم بالواجب: ما يكون حياءً، هذا جُبن، وخور، وعجز. لا بدّ من حياء يُوافق الشرع، معناه: يحجزه عن سيئ الأخلاق، ويُعينه على مكارم الأخلاق، هذا الحياء الشرعي، أما حياء يحجزه عن الواجبات، أو عن مخالطة الأخيار، أو عن طلب العلم، أو ما أشبه ذلك؛ فهذا ليس حياءً، هذا هو العجز والكسل.\nس: أقصد الحياء الذي يحجزه عن الخيرات -خيرات الدين- ولكن الحياء الذي قد يخجل بعض الناس فيتورط في خدمات، أو عزائم، أو زواج؟\nج: يُعلَّم، ويُنصح، إذا خِيف عليه يُنصح.","link":"https://binbaz.org.sa/fatwas/25202/ما-ضابط-الحياء-المحمود-في-الرجل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحياء وضابطه.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":4834,"question":"تشميت العاطس فرض كفاية أم فرض عين؟","title":"هل تشميت العاطس فرض كفاية أم فرض عين؟","answer":"ظاهر النصوص فرض عين، ظاهر النصوص وجوبه على المؤمن إذا سمعه، والمعروف عند العلماء أنه سنة مؤكدة؛ لكن ظاهر الأوامر الوجوب؛ لأن الرسول ﷺ أمر بذلك.","link":"https://binbaz.org.sa/fatwas/25257/هل-تشميت-العاطس-فرض-كفاية-ام-فرض-عين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما حكم تشميت العاطس.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":4968,"question":"هل الملائكة ترد السلام إذا ما رد الشخصُ السلام؟","title":"هل ترد الملائكة السلام إذا ما رد الإنسان؟","answer":"الجواب: هذا فيه حديث، تسلم على مَنْ قصدهم، أما إذا كانوا في بيت وسمعوا يَرُدُّوا.","link":"https://binbaz.org.sa/fatwas/27668/هل-ترد-الملاىكة-السلام-اذا-ما-رد-الانسان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل ترد الملائكة السلام إذا ما رد الشخص السلام؟.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":5005,"question":"قيادة السّيارات تدخل في الرِّفق؟","title":"هل تدخل قيادة السّيارات في الرِّفق؟","answer":"الجواب: نعم، في السيارات، والإبل، والخيل، والحمير، والبغال، حتى مشيه بنفسه، والعطاء مع أهله، ومع عياله، ومع جيرانه.\nس: بعض الناس تكون صفةً دائمةً فيه، فإذا قيل له: ارفق، أو: ترفّق أو كذا...؟\nج: لا بد من تعاطي العلاج، فيُجاهد نفسه حتى يُعالج أخلاقه الرَّديئة بأخلاقٍ طيبةٍ.","link":"https://binbaz.org.sa/fatwas/28785/هل-تدخل-قيادة-السيارات-في-الرفق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تدخل قيادة السيارات في الرفق؟.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":5047,"question":"إذا لم ترد المرأةُ على الرجل الأجنبي السلام خشية الفتنة فهل تأثم؟","title":"حكم عدم رد المرأة السلام خشية الفتنة","answer":"الجواب: تقول: \"وعليكم السلام\" والحمد لله، ما فيه فتنة.\nس: وإذا لم ترد؟\nج: تأثم.","link":"https://binbaz.org.sa/fatwas/29284/حكم-عدم-رد-المراة-السلام خشية-الفتنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم عدم رد المرأة السلام خشية الفتنة.mp3","categories":["قضايا المرأة","الآداب والأخلاق المحمودة"]},{"id":5050,"question":"هل زيارة أهل الخير هم العلماء والدُّعاة؟","title":"هل المراد بزيارة أهل الخير: العلماء والدُّعاة؟","answer":"الجواب: نعم، وأهل الصلاح، فهذا عام.","link":"https://binbaz.org.sa/fatwas/29291/هل-المراد-بزيارة-اهل-الخير-العلماء-والدعاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل المراد بزيارة أهل الخير العلماء والدعاة؟.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":5052,"question":"إذا كنتُ أُحبه في الله هل من السُّنة أن أذهب إليه في بيته وأطرق بابه وأُبلغه هذا الشيء؟","title":"هل يُسنُّ إخبارُ من يُحَبُّ في الله في بيته؟","answer":"الجواب: في بيته، أو في الطريق، أو في المسجد، ولا يلزم أن يكون في البيت، إذا بلغته يكون حسنًا، تقول: إني أحبك في الله.","link":"https://binbaz.org.sa/fatwas/29292/هل-يسن-اخبار-من-يحب في-الله-في-بيته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يسن إخبار من يحب في الله في بيته؟.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":5470,"question":"ما هي شروط المحبة في الله، وما هي ضوابطها، وماذا يجب على الأخ إذا كان يحب أخاه؟","title":"ما واجبات وضوابط المحبة في الله؟","answer":"الجواب: التحاب في الله على ظاهره، إذا كان يحبه لأجل عمله الصالح، هذه شروطها، محبته لله لأجل عمله الصالح وتقواه لله، ما هو من أجل الدنيا أو القرابة أو المجاورة، يحبه لله لأعماله الطيبة واستقامته على دين الله.[1]","link":"https://binbaz.org.sa/fatwas/31341/ما-واجبات-وضوابط-المحبة-في-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/reyath_alsalhin 006.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":5527,"question":"ما حكم مَن سأل بالله لأمرٍ ولم يجَب؟ وما حكم مَن سُئل بالله ولم يفعل؟","title":"هل تجب الإجابة على مَن سُئل بالله؟","answer":"الجواب: النبي ﷺ قال: مَن سأل بالله فأعطوه إلا إذا كان ما له حقّ فيما سأل، ولو قال: أسألك بالله أن تعطيني من الزكاة وهو ليس من أهل الزكاة، ما يُعطى، لكن إذا سأل شيئًا له فيه شبهة: سأل من بيت المال، أو سأل أن يُعطى لأنه فقير، يُعطى ما تيسر: مَن سأل بالله فأعطوه، ولكن لا ينبغي أن يسأل بالله، لا يُشدّ على الناس؛ ولهذا قال الملكُ الذي جاء إلى الأبرص والأعمى والأقرع: (أسألك بالذي أعطاك كذا وكذا)، سأله بالله. المقصود أنه إذا كان في شيءٍ مهم وسأل بالله؛ يُعطى إذا كان لحقٍّ، أما إذا لم يكن له حقّ ما يُعطى ولو سأل بالله، فلو قال: أسألكم بالله أن تُعطوني من الزكاة، وليس من أهلها؛ لم يُعط من الزكاة؛ لأنه ليس من أهلها، أو قال: أسألكم بالله أن تُعطوني أموالكم والذي عندكم كله ولا تجعلون لكم شيئًا، ما يُعطى.[1]","link":"https://binbaz.org.sa/fatwas/31460/هل-تجب-الاجابة-على-من-سىل-بالله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/kashf alshubuhat 042.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":5686,"question":"ما حد قطيعة الرحم؟ أعني ما هي المدة التي إذا مرت دون زيارتهم كانت قطيعة رحم؟","title":"كيف تكون صلة الرحم؟ وما هو حد القطيعة؟","answer":"الجواب: ما في حد محدود، صلة الرحم بالكلام الطيب، ومواساة الفقير منهم، ورد السلام عليهم، وبداءتهم بالسلام، وإعانتهم على الخير، كل هذا من صلة الرحم. وقطيعة الرحم ما لها حد محدود، جفاؤهم الذي يعد خلاف المعتاد نوع من القطيعة، جفاؤهم من غير موجب شرعي، وعدم الإنفاق على فقيرهم، والإحسان إليه، وعدم الشفاعة لمظلومهم حتى ينصر في مظلمته، ونحو ذلك، قد يعد من القطيعة.  فالقطيعة أمر عرفي، والصلة أمر عرفي، فما هو معروف بين المسلمين الصلة، والإحسان، والاتصال، والسلام، وبذل المعروف يعد صلة، وما كان بين المسلمين يعد جفاء، ويعد قطيعة، فكذلك. وليس الواصل بالمكافئ؛ لأن بعض الناس إذا ما وصله أقاربه فهو لا يصلهم يقول: لا يصلونني، ولا يجوني، ما أنا بواصلهم فهذا غلط، النبي -عليه الصلاة والسلام- يقول: ليس الواصل بالمكافئ، وإنما الواصل الذي إذا قطعت رحمه وصلها هذا الواصل.  وكذلك يقول ﷺ لما قال له رجل: يا رسول الله، إن لي قرابة أصلهم، ويقطعونني، وأحلم عليهم، ويجهلون عليّ، وأحسن إليهم، ويسيئون إليّ، قال: لئن كنت كما قلت لكأنما تسفهم المل، ولا يزال معك من الله عليهم ظهير ما دمت على ذلك فالله -جل وعلا- يعينه عليهم ما دام على حاله الطيبة، ويكون بهذا هو الواصل وهم القاطعون. أما إن وصلوك وصلتهم، وإن قطعوك قطعتهم لا، هذا ليس بصلة، حتى الأجنبي إذا وصلك تصله، الأجنبي الذي ما هو بقريب إذا وصلك وأحسن إليك، عليك المقابلة، والمكافأة، لكن الرحم، والقرابة لها حق وزيادة على هذا تصلهم، وإن قطعوا، وتحسن إليهم، ترد عليهم السلام، تبدأهم بالسلام، تدعوهم للوليمة تجيب دعوتهم.  ولو قطعوك لأجل وحشة بينك وبينهم، أو شحناء، أو خصومات لا تقطعهم أنت، لكن لك أن تهجرهم ثلاثة أيام عند الوحشة، والنزاع، والخصومات لأجل حظ الدنيا، لك أن تهجرهم ثلاثة أيام فقط، لا يزيد على ذلك؛ لأن النبي ﷺ قال: لا هجرة فوق ثلاث.  فالواجب أنه يصله بعد الثلاث، ويعود على حاله الأولى بعد الثلاث، ولا يهجر فوق ثلاث، وخيرهما الذي يبدأ بالسلام، خير المتهاجرين الذي يبدأ بالسلام.","link":"https://binbaz.org.sa/fatwas/994/كيف-تكون-صلة-الرحم-وما-هو-حد-القطيعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_23.mp3","categories":["اللقطة واللقيط","الآداب والأخلاق المحمودة"]},{"id":5732,"question":"العمال الذين يصلون إلى هنا يكون مرتبهم ضعيفًا، ومعيشتهم سدًا للرمق، ولهم ذرية ضعاف، فهل تحل الزكاة عليهم؟","title":"هل تحل الزكاة على الوافدين لضعف رواتبهم؟","answer":"الجواب: إذا عرفوا بالحاجة، وأن مرتباتهم لا تسد حاجاتهم، وكانوا مسلمين عرفوا بذلك، لا بأس أن يعطوا شيئًا من الزكاة لسد الحاجة، إذا عرفوا بأنهم مسلمون، وإذا عرفوا بالصدق، وأنهم محتاجون فقراء؛ لأن كثيرًا من الناس يدعي الفقر وهو كاذب وراتبه يكفيه.  فإذا عرف بالحاجة بالصدق بأن شهد له من يرضى بأنه فقير، وأن هذا المرتب قليل ضئيل، لا يسد حاجته؛ فلا بأس أن يعطى، وإلا فلا يعطى، ويلتمس الناس المعروفون بالحاجة والإسلام.","link":"https://binbaz.org.sa/fatwas/1061/هل-تحل-الزكاة-على-الوافدين-لضعف-رواتبهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_77.mp3","categories":["إخراج الزكاة وأهلها","الآداب والأخلاق المحمودة"]},{"id":5733,"question":"هل يجوز استلام العائدات السنوية المسماة المناخ إذا كنت موظفًا، وأستلم راتبًا شهريًا؟ وهل يستحقها أيضًا أولادي؟","title":"حكم استلام التبرع السنوي المسمى بالمناخ","answer":"الجواب:  هذا تبرع من الدولة لا بأس به، تبرع من الدولة لكل الرعية، باديًا وحاضرًا، فإذا أخذها فلا بأس، وإذا مات فهي لورثته إلا إذا منعتها الحكومة، وقطعتها فهي إليها، وإلا فهذه المناخ للعموم، والذي يموت تكون للورثة بعده.","link":"https://binbaz.org.sa/fatwas/1049/حكم-استلام-التبرع-السنوي-المسمى-بالمناخ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_66.mp3","categories":["الهبة والعطية","الآداب والأخلاق المحمودة"]},{"id":5736,"question":"العمال الذين يصلون إلى هنا يكون مرتبهم ضعيفًا، ومعيشتهم سدًا للرمق، ولهم ذرية ضعاف، فهل تحل الزكاة عليهم؟","title":"هل تحل الزكاة على الوافدين لضعف رواتبهم؟","answer":"الجواب: إذا عرفوا بالحاجة، وأن مرتباتهم لا تسد حاجاتهم، وكانوا مسلمين عرفوا بذلك، لا بأس أن يعطوا شيئًا من الزكاة لسد الحاجة، إذا عرفوا بأنهم مسلمون، وإذا عرفوا بالصدق، وأنهم محتاجون فقراء؛ لأن كثيرًا من الناس يدعي الفقر وهو كاذب وراتبه يكفيه.  فإذا عرف بالحاجة بالصدق بأن شهد له من يرضى بأنه فقير، وأن هذا المرتب قليل ضئيل، لا يسد حاجته؛ فلا بأس أن يعطى، وإلا فلا يعطى، ويلتمس الناس المعروفون بالحاجة والإسلام.","link":"https://binbaz.org.sa/fatwas/1061/هل-تحل-الزكاة-على-الوافدين-لضعف-رواتبهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_77.mp3","categories":["إخراج الزكاة وأهلها","الآداب والأخلاق المحمودة"]},{"id":5747,"question":"عثرت على رأسين من الغنم ضائعة، وقد سألت عن صاحبها في عدة أماكن، وفي سوق الغنم، ولم أجد لها صاحب، فأرجو إفتائي بما أصنع بها؟","title":"ما يفعل من وجد ضالة الغنم؟","answer":"الجواب: إذا وجد الإنسان رؤوسًا من الغنم، أو غير الغنم كالبقر، وغيرها مما يخشى عليه الذهاب والضياع يعرفه سنة كاملة، فإن عُرف فالحمد لله، وإن لم يُعرف أحل له ... ... النبي -عليه الصلاة والسلام- قال: من آوى ضالًا فهو ضال فعليه أن يعرفها ... أما البقر والإبل فهذه تحمي نفسها، فلا حاجة إلى أن يتولاها ويقبضها، بل يتركها في الصحراء حتى يجدها أهلها، وإذا كانت في الأسواق سوف يجدها أهلها.  أما الغنم فينبغي له أن يعرفها سنة كاملة، وهكذا من كان من جنس الغنم من الحيوانات الصغيرة التي يخشى عليها الموت .. أو نحو ذلك فإنه يعرفها أيضًا. فالحاصل: أنه يعرفها سنة كاملة، فإن عرفت وإلا فهي له، والأجرة على الصحيح تكون عليه، الأجرة ينادي عليها، ويعرفها في الناس تكون عليه من هذا المال الذي وجده، وإن تركه ولم يأخذه فلا بأس.","link":"https://binbaz.org.sa/fatwas/1066/ما-يفعل-من-وجد-ضالة-الغنم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_80.mp3","categories":["اللقطة واللقيط","الآداب والأخلاق المحمودة"]},{"id":5748,"question":"هل يجوز استلام العائدات السنوية المسماة المناخ إذا كنت موظفًا، وأستلم راتبًا شهريًا؟ وهل يستحقها أيضًا أولادي؟","title":"حكم استلام التبرع السنوي المسمى بالمناخ","answer":"الجواب:  هذا تبرع من الدولة لا بأس به، تبرع من الدولة لكل الرعية، باديًا وحاضرًا، فإذا أخذها فلا بأس، وإذا مات فهي لورثته إلا إذا منعتها الحكومة، وقطعتها فهي إليها، وإلا فهذه المناخ للعموم، والذي يموت تكون للورثة بعده.","link":"https://binbaz.org.sa/fatwas/1049/حكم-استلام-التبرع-السنوي-المسمى-بالمناخ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_66.mp3","categories":["الهبة والعطية","الآداب والأخلاق المحمودة"]},{"id":5785,"question":"تقولون في قصة عبدالرحمن بن عوف: أنه عندما قال له أخوه: انظر إلى إحدى زوجاتي؛ فهل النظر بالنسبة للخاطب في المرأة حلال؟","title":"هل نظر الخاطب لمخطوبته جائز؟","answer":"الجواب:  نعم، النبي ﷺ أمر الخاطب أن ينظر، قال: إذا خطب أحدكم امرأة فإن استطاع أن ينظر إلى ما يدعوه إلى نكاحها فليفعل، فإن ذلك أقرب إلى أن يؤدم بينكما فالنظر إلى المخطوبة لا بأس به، من غير خلوة.  وجاءه رجل ذكر له أن زواج امرأة، أي أراد الزواج بها، أو عقد عليها، فقال: أنظرت إليها؟ قال: لا، قال: اذهب، فانظر إليها رواه مسلم في الصحيح، فهذا لا بأس به، بل هذا من أسباب الأدم بينهما، يعني: الجمع بينهما، واستقامة النكاح بينهما إذا تيسر ذلك، إذا سمح له أهله بذلك من غير خلوة، بل مع وجود محرمها، أو أمها، ونحو ذلك ممن حضوره ينافي الخلوة.  وقد ذكر جابر بن عبدالله الأنصاري  أنه خطب امرأة، فأراد أن ينظر إليها، قال: فجعلت أتتبع النخل، وهي في النخل في مزارع الأنصار، نخلة خلف نخلة يختبي لها وراء النخل، حتى رأى منها ما أعجبه، فخطبها.  فالمقصود: أنه إذا تيسر أن يراها بالإذن، والعلم فلا بأس، وإن لم يتيسر ذلك، ورآها من غير علمها، من فرجة، أو من وراء النخل، أو من كذا، أو من كذا من الطرق التي ليس فيها محذور في الشرع، وليس فيها خلوة فلا بأس. السؤال: الأهل يأثمون إذا لم يمكنوا الخاطب من الرؤية؟ الجواب: الظاهر لا يأثموا، ولكن الأولى، والأفضل أن يمكنوه؛ لأن هذا من أسباب الإدام بينهما، والجمع بينهما، والنبي أمر به -عليه الصلاة والسلام- قال: اذهب فانظر إليها فلما أمره أن ينظر؛ دل ذلك على أنه يستحب لهم أن يمكنوه، ما دام أمر به النبي فتمكين الرجل الذي أمره النبي أن ينظر تمكينه أولى. لكن بعض الناس من عاداتهم ألا يفعلوا، ويصعب عليهم ذلك، وبعضهم يقول: أخشى أن يراها فلا تعجبه، ثم يتحدث بين الناس، ثم ينفر الناس منها بعد ذلك، لهم تأويلات في هذا.","link":"https://binbaz.org.sa/fatwas/1120/هل-نظر-الخاطب-لمخطوبته-جاىز","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_127.mp3","categories":["الخِطْبَة والاختيار ","النظر والخلوة والاختلاط","قضايا المرأة","الآداب والأخلاق المحمودة"]},{"id":5846,"question":"يقول: لا حياء في الدين، أنا شاب أريد أن أتزوج، ولكن أريد أن أعرف كيف أباشر زوجتي طبق ما فعله الرسول ﷺ؟ وما الذي أرتديه من الملابس؟ وهل أبتعد عنها إذا كانت حاملًا وشكرًا؟","title":"كيفية النكاح الشرعي","answer":"الجواب: الزواج معروف، يتزوج، يعني يخطب المرأة، يسأل عن دينها، وعن حالها، وإذا عرف أنها صالحة له مسلمة، أو رآها يتزوج الزواج الشرعي، يقوم وليها يعقد له عند بعض طلبة العلم الذين يعرفون؛ حتى يبينون له ما ينبغي، ويقول: زوجتك، والزوج يقول: قبلت بحضرة شاهدين عدلين، أربعة: الولي، والزوج، وشاهدان، ويقول الولي: زوجتك، ويقول: قبلت على مال بينهما معروف على حسب ما تيسر.  وإذا دخل عليها ذكر بعض أهل العلم أنه يصلي ركعتين أفضل، فإذا صلى ركعتين؛ حسن، يدعو الله -جل وعلا- أن يوفق بينهما، وإذا لمسها يسأل الله خيرها، وخير ما جبلت عليه، ويتعوذ بالله من شرها، وشر ما جبلت عليه، ثم إذا شاء الاتصال بها اتصل بها.  وإذا كانت حبلى، فالنكاح باطل، إذا كان دخل عليها، وهي حبلى؛ فهذا نكاح باطل، أما إذا حملت منه هو؛ فلا بأس أن يطأها وهي حامل، ولكن لا يطأها وهي حائض، ولا نفساء، الحائض، والنفساء لا توطأ، أما الحامل؛ فلا بأس أن يطأها وهي حامل إذا كان حملها منه، أما إذا كان دخل عليها، ووجدها حاملًا، فهذه لها عدة من غيره، وهو نكاح باطل، نعوذ بالله.","link":"https://binbaz.org.sa/fatwas/1193/كيفية-النكاح-الشرعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_189.mp3","categories":["صيام التطوع","حكم الزواج وأهميته","الآداب والأخلاق المحمودة"]},{"id":5917,"question":"المرأة لا تحب زوجها، وهو كذلك كما تقول، فهي تسأل هل يلزم الشرع الزوج أن يصرف عليها، وعلى ولديها منه بعد الطلاق ببيت مستقل، أم لا؟","title":"النفقة على الأولاد بعد طلاق أمهم","answer":"الجواب: إذا تفارقا فعليهما أن يصطلحا على مسألة الأولاد في النفقة، ينظر حالهما في المحكمة، يصطلحا مع وليها معها في النفقة المطلوبة كل شهر، والحمد لله؛ فإن تنازعا يرجعا إلى المحكمة، المحكمة تنظر، وتقدر النفقة اللازمة، لكن الأولى من ذلك الصلح، الأولى من المحكمة الصلح، يصطلحان على نفقة مناسبة ينفقها على أولاده إذا كان طلقها، وعندها أولاد، هذا هو الأولى، فإن تنازعا؛  فيرجعا إلى  المحكمة، ما يمكن غير المحكمة تنظر في هذا.","link":"https://binbaz.org.sa/fatwas/1283/النفقة-على-الاولاد-بعد-طلاق-امهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_270.mp3","categories":["النفقات","الآداب والأخلاق المحمودة"]},{"id":5935,"question":"ما حكم مؤخر الصداق؟ وهل نصف دينه بالزواج، ويتقي الله بالنصف الآخر، من أين هذا القول؟","title":"ما صحة القول بأن الزواج شطر الدين","answer":"الجواب: يروى عن النبي ﷺ في حديث في سنده نظر إذا تزوج الإنسان؛ فقد أحرز شطر دينه؛ فليتق الله في الشطر الآخر جاء هذا من طرق لا تخلو من ضعف عند أهل العلم، ولا شك أن الزواج مهم، ولكن كونه الشطر محل نظر! إنما هو مهم، الله يقول -جل وعلا-: وَأَنْكِحُوا الْأَيَامَى مِنْكُمْ وَالصَّالِحِينَ مِنْ عِبَادِكُمْ وَإِمَائِكُمْ إِنْ يَكُونُوا فُقَرَاءَ يُغْنِهِمُ اللَّهُ مِنْ فَضْلِهِ [النور:32].  ويقول : وَإِنْ خِفْتُمْ أَلَّا تُقْسِطُوا فِي الْيَتَامَى فَانْكِحُوا مَا طَابَ لَكُمْ مِنَ النِّسَاءِ مَثْنَى وَثُلَاثَ وَرُبَاعَ الآية [النساء:3] والرسول ﷺ أمر بالنكاح -كما سمعتم- وحث الشباب على ذلك، وقال: تزوجوا الودود الولود؛ فإني مكاثر بكم الأمم يوم القيامة فالرسول ﷺ حث على هذا، ورغب فيه كما أمر به الله  لكن كونه شطر الدين هذا محل نظر؛ لضعف الحديث. ولكن ينبغي للمؤمن أن يحرص عليه، وهو شعبة من الدين، وفرض من الفرائض، ومن أسباب العفة، وغض البصر، ومن أسباب الاستقامة، ومن أسباب صلاح المجتمع، ومن أسباب كثرة النسل، وكثرة الأمة، وكثرة من يعبد الله  فينبغي الجد في ذلك، ولكن ينبغي له أن يختار المرأة الصالحة. وإن تيسر أنه ينظر للمرأة قبل الزواج؛ فهو أحسن، النبي ﷺ أمر الخاطب أن ينظر أخبر ﷺ إذا خطب أحدكم امرأة، فإن استطاع أن ينظر إلى ما يدعوه إلى نكاحها؛ فليفعل. وسأله رجل قال: يا رسول الله، إني خطبت فلانة، فقال: أنظرت إليها؟ قال: لا، قال: اذهب فانظر إليها فإذا تيسر النظر إليها؛ فهو أولى، وينبغي لأهلها أن يسمحوا بذلك، تنظره، وينظرها، لا بأس. لكن في محل ما فيه خلوة، ينظر إليها، وتنظر إليه مع حضور والدها، أو أمها، أو أخيها، يعني ليس في خلوة في مكان ما فيه خلوة، لا يخلو بها؛ لأن الخلوة من أسباب وقوع الفاحشة. وكذلك ما نبه عليه الشيخ صالح ما قد يقع من بعض الناس، أنا ما سمعته من المسلمين، لكن موجود في الخارج، وهو أن يسافر معها، ولم يعقد عليها؛ حتى ينظر إليها، وتنظر إليه، فهذا من البلاء العظيم، والمنكر الفظيع، نعوذ بالله، إنما مجرد نظر ينظر إليها، وتنظر إليه فقط، أما أن يخلو بها، ويسافر معها، وتسافر معه؛ فهذا منكر كبير، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/1286/ما-صحة-القول-بان-الزواج-شطر-الدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_273.mp3","categories":["صيام التطوع","حكم الزواج وأهميته","الآداب والأخلاق المحمودة"]},{"id":5936,"question":"لدي زوجة تؤدي الفروض الدينية كاملة، ولكنها تعاتب في بعض الأعمال حتى يحصل الزعل، ولا تقوم ببعض الأعمال إلا بزعل، وذلك أنها متعودة على الكسل، فهل يجوز لي طلاقها؟","title":"حكم تطليق الزوجة بسبب كسلها","answer":"الجواب: ينبغي لك الصبر، إن كانت طيبة، ودينة، وإن كان فيها بعض الكسل ينبغي لك الصبر، أنت عندك بعض الكسل، ما أحد سالم، ينبغي لك أن تكون طيبًا، وأن تعاونها على أمور البيت، عاونها، النبي كان يعاون أهله -عليه الصلاة والسلام- وهو أفضل الخلق، كان يساعد أهله في البيت على حاجات البيت. فأنت ساعدها، لا تجيب خادم، ساعدها حتى تسلم من الخادم، ساعدها على أمور البيت التي تعجز عنها، قد يكون معها أطفال قد أتعبنها، ساعدها على أمور البيت، شجعها على العمل بكلام طيب، ما هو يا خبيثة، يا فاجرة، يا كذا، يا كذا، يا بنت فلان، يا أم فلان، قومي كذا، عافاك الله، الله يرضى عليك، كذا كلام طيب.","link":"https://binbaz.org.sa/fatwas/1287/حكم-تطليق-الزوجة-بسبب-كسلها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_274.mp3","categories":["الطلاق","الأيمان والنذور","الآداب والأخلاق المحمودة"]},{"id":5940,"question":"لو مر واحد على امرأة ما يعرفها، يرد عليها السلام؟","title":"هل يجوز السلام على النساء؟","answer":"الجواب: لا بأس مر النبي ﷺ على نساء، وسلم عليهن، مر على جماعة من النساء، وسلم عليهن، عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/1313/هل-يجوز-السلام-على-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_282.mp3","categories":["الحقوق الزوجية","قضايا المرأة","الآداب والأخلاق المحمودة"]},{"id":5951,"question":"لو مر واحد على امرأة ما يعرفها، يرد عليها السلام؟","title":"هل يجوز السلام على النساء؟","answer":"الجواب: لا بأس مر النبي ﷺ على نساء، وسلم عليهن، مر على جماعة من النساء، وسلم عليهن، عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/1313/هل-يجوز-السلام-على-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_282.mp3","categories":["الحقوق الزوجية","قضايا المرأة","الآداب والأخلاق المحمودة"]},{"id":5967,"question":"كنت في مجلس مع زملائي، وحلفت بالله لئن جاء أخي أن أذبح شاة، وجاء أخي، وأنا في ذلك الوقت معسر، ولا أملك قيمة الشاة، فماذا أفعل؟","title":"حكم من عجز عن الوفاء بالنذر","answer":"الجواب: إذا تيسر تذبح الشاة، إذا تيسرت الشاة تذبحها؛ وفاء لنذرك، تذبحها على نية للفقراء، تعطيها للفقراء، على نية تأكلونها أنت، وأهل بيتك، تأكلها أنت، وأهل بيتك، إذا كان ما عندك نية؛ تعطيها الفقراء، لا تأكلها.","link":"https://binbaz.org.sa/fatwas/1338/حكم-من-عجز-عن-الوفاء-بالنذر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_305.mp3","categories":["الطلاق","الأيمان والنذور","الآداب والأخلاق المحمودة"]},{"id":5984,"question":"والدي يأمرني ألا أصل خالي؛ لأن معه سوء تفاهم لأجل غرض دنيوي، ويقول: إذا أنت تزور خالك أخرجتك من بيتي، وإلا أهجرك كما هجرته، فماذا أعمل؟","title":"حكم طاعة الوالد إذا أمر ولده ألا يزور أحد أقاربه","answer":"الجواب: إذا أمرك والدك بهجر خالك، أو عمك، أو نحوهم بغير حق إلا أنه سوء تفاهم بين والدك، وبين خالك، أو أخيه، أو نحو ذلك من أجل الدنيا، والخصومات؛ فليس لك أن تطيع والدك؛ لأن هذه معصية إنما الطاعة في المعروف لا طاعة لمخلوق في معصية الخالق.  وعلى والدك أيضًا أن يتقي الله، وأن لا يهجره أكثر من ثلاث النبي ﷺ نهى عن الهجر فوق ثلاث في أمور الدنيا لا يحل لمسلم أن يهجر أخاه فوق ثلاث يلتقيان، فيعرض هذا، ويعرض هذا، وخيرهما الذي يبدأ بالسلام وقال: لا هجرة فوق ثلاث.  المقصود: أن التهاجر من أجل الشحناء، والعداوة، والخصومات لا يجوز أبدًا، لكن يباح ثلاثة أيام، يباح التهاجر في الخصومة ثلاثة أيام، فأقل، الإنسان إذا كان بينك، وبينه خصومة، وساء خلقه عليه، وحصل شيء في النفس؛ فلا بأس أن يهجره ثلاثة أيام؛ رحمة من الله؛ لأن النفوس لها نصيبها من مراعاتها، والتلطف بها، والرفق بها، فالهجر ثلاثة أيام تكفي في تخفيف الحدة، وإزالة الشدة، فإذا مضت الثلاثة فخيرهما الذي يبدأ بالسلام.  وأنت أيها الولد إذا أبى عليك أبوك؛ فلك أن تصل خالك، وعمك، ولو من طريق السر، تصل، تحسن إليهم، وتزورهم، ولو من طريق السر؛ حتى لا تشتد الحال بينك، وبين أبيك، ولا تطعه في المعصية، ولكن تعامله بالتي هي أحسن، وتجتهد بأن تكون صلتك، وبرك لخالك، وعمك، ونحو ذلك بالطريقة التي لا يطلع عليها، إذا كنت تخشى أن يقع شر أكثر.  وأما إذا كنت تستطيع أن تهدئ الوضع، وتنصح والدك، وأن تقول له: هذا لا يجوز، وأن عليك أن ترفق بأخيك، أو بخالك، المقصود أنك تنصحه؛ لعله يهتدي؛ حتى يصالح خالك، أو عمك، وحتى تزول هذه الوحشة بينهما. أما إذا كان الهجر للدين؛ لأن الشخص يتظاهر بالمعاصي، والبدع، فهو يُهجر حتى يتوب، ولو سنة، أو سنتين، لو  أكثر يهجر يتوب، وقد هجر النبي ﷺ ثلاثة تخلفوا عن الغزو بغير عذر، هجرهم النبي خمسين ليلة حتى تاب الله عليهم، فتابوا، وأظهر توبتهم، وبين للناس أن الله تاب عليهم، فكلمهم الناس بعد ذلك.  فالحاصل: أن الهجر إذا كان لله من أجل المعاصي الظاهرة، أو البدع، فهذا ليس له حد إلا التوبة، إذا رجعوا من معاصيهم الظاهرة، وبدعهم، فإن المسلمين يسلمون عليهم، وأما إذا أصروا على البدع، والمعاصي؛ فإنه يشرع هجرهم؛ لعلهم يتوبون؛ لعلهم يرجعون، وإذا كان هجرهم قد يضر المسلمين، ويسبب مشاكل أكثر؛ فلا يهجروا، بل ينصحون، ويوجهون إذا كان هجرهم يضر المجتمع، أو يفضي إلى فساد، أو إلى منكر أكبر، فهجرهم هنا محل اجتهاد، ومحل نظر.","link":"https://binbaz.org.sa/fatwas/1363/حكم-طاعة-الوالد-اذا-امر-ولده-الا-يزور-احد-اقاربه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_321.mp3","categories":["إخراج الزكاة وأهلها","الآداب والأخلاق المحمودة"]},{"id":5993,"question":"رأت والدتي في المنام أنها وجميع الأسرة في بيت، وجاء إليهم والدي المتوفي -يرحمه الله- وتقول: فرحت به، وقلت له: لا تذهب عنا، وفي فكرها أنه عايش في مكان ثان، وتقول: إنها لمسته، وقال لها: لا تلمسيني إني نجس؟","title":"ماذا يقول من يرى رؤيا لا تسره؟","answer":"الجواب: هذه الرؤيا، وأشباهها من الشياطين، يقول النبي ﷺ: الرؤيا الصالحة من الله، والحلم من الشيطان، فإذا رأى أحدكم ما يكره؛ فلينفث عن يساره ثلاث مرات، وليتعوذ بالله من الشيطان الرجيم، ومما رأى ثلاث مرات، ثم لينقلب على جنبه الآخر؛ فإنها لا تضره، ولا يخبر بها أحدًا الذي يرى أنه يقتل، أو أنه نجس، أو صب عليه البول، أو أحدًا يهدده بالقتل، أو يضربه، أو أنه مكشوف العورة، أو ما أشبه ذلك، كل هذا من الشياطين، فإذا استيقظ؛ فليتفل عن يساره ثلاث مرات، وليقل: أعوذ بالله من الشيطان، ومن شر ما رأيت، ثلاث مرات، ثم ينقلب على جنبه الآخر، ولا يخبر بها أحدًا، ولا تضره، إن شاء الله. السؤال: ما يقول الله أكبر كبيرًا، والحمد لله كثيرًا، وسبحانه الله، وبحمده بكرة، وأصيلًا؟ الجواب: ما سمعنا هذا، الذي قاله النبي ﷺ قال: فليتعوذ بالله، وليتفل عن يساره، ثلاث مرات، وليتعوذ بالله من الشيطان، ومن شر ما رأى، ثلاث مرات، ثم ينقلب على جنبه الآخر وإذا أحب أن يسبح بعد ذلك؛ فيكون فيه خير. السنة إذا استيقظ أن يقول: لا إله إلا الله وحده لا شريك له، له الملك، وله الحمد، وهو على كل شيء قدير، سبحان الله، والحمد لله، ولا إله إلا الله، والله أكبر، ولا حول ولا قوة إلا بالله، الحمد لله الذي أحياني بعد ما أماتني، وإليه النشور، يستحب هذا عند الاستيقاظ من النوم مطلقًا في آخر الليل، وفي أثناء الليل، ولو ما رأى رؤيا إذا تعار من النوم يقول هذا يستحب له هذا.","link":"https://binbaz.org.sa/fatwas/1391/ماذا-يقول-من-يرى-رويا-لا-تسره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_347.mp3","categories":["إخراج الزكاة وأهلها","الآداب والأخلاق المحمودة"]},{"id":6103,"question":"نرى الناس في الأعياد يتعانقون، ولو لم يكن بعضهم قادمًا من سفر، وقد يكون الوقت الذي يفصل بينهم قصير، وقت الصلاة، ثم يتعانقون بعد صلاة العيد، نرجو بيان الحقيقة؟","title":"حكم المعانقة في الأعياد","answer":"الجواب: ما نعلم في التعانق أصلًا إلا عادة جرى عليها الناس، إنما المسنون الدعاء بالقبول إذا قابل أخاه، ودعا له بالقبول؛ فهذا من فعل السلف، أما المعانقة لأجل هذا الخصوص لا أعلم لها أصلًا، إنما هي عادة للناس. فالأفضل المصافحة، ويكتفى بها عند اللقاء، يصافح أخاه، ويقول له: هنأك الله بهذا العيد، بارك الله لك في هذا العيد، أو تقبل الله منا ومنك، وما أشبه ذلك، لا بأس به.","link":"https://binbaz.org.sa/fatwas/1533/حكم-المعانقة-في-الاعياد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_463.mp3","categories":["إخراج الزكاة وأهلها","الآداب والأخلاق المحمودة"]},{"id":6120,"question":"حلمت في المنام ورأيت أني أشرب الدخان أنا، وأخي، ونحن لم نشرب الدخان، وثلاث ليال حصلت تلك الرؤيا، وتكررت، أفيدوني، جزاكم الله؟","title":"بيان أن الرؤى المكروهة من الشيطان","answer":"الجواب: إذا رأى الإنسان ما يكره فهو من الشيطان، فرؤيا أنه يشرب الدخان، أو أنه يشرب الخمر، أو أنه يزني، أو أنه يطأ أمه، أو أنه يطأ أخته، أو أنه يلوط، أو ما أشبه ذلك، يرى هذه المرائي المكروهة، فهي من الشيطان، قال النبي ﷺ: الرؤيا الصالحة من الله، والحلم من الشيطان، فإذا رأى أحدكم ما يكره؛ فلينفث عن يساره ثلاث مرات، وليتعوذ بالله من الشيطان، ومن شر ما رأى، ثلاث مرات، ثم لينقلب على جنبه الآخر؛ فإنها لا تضره. النصيحة لك يا أخي، وأشباهك ممن يرى ما يكره: أنه إذا استيقظ ينفث عن يساره ثلاث مرات، ويتعوذ بالله من الشيطان، ومن شر ما رأى ثلاث مرات، ثم ينتقل إلى جنبه الآخر، فإنها لا تضره، ولا يخبّر بها أحدًا، هذه السنة، وفق الله الجميع.","link":"https://binbaz.org.sa/fatwas/1524/بيان-ان-الروى-المكروهة-من-الشيطان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_454.mp3","categories":["إخراج الزكاة وأهلها","الآداب والأخلاق المحمودة"]},{"id":6130,"question":"نرى الناس في الأعياد يتعانقون، ولو لم يكن بعضهم قادمًا من سفر، وقد يكون الوقت الذي يفصل بينهم قصير، وقت الصلاة، ثم يتعانقون بعد صلاة العيد، نرجو بيان الحقيقة؟","title":"حكم المعانقة في الأعياد","answer":"الجواب: ما نعلم في التعانق أصلًا إلا عادة جرى عليها الناس، إنما المسنون الدعاء بالقبول إذا قابل أخاه، ودعا له بالقبول؛ فهذا من فعل السلف، أما المعانقة لأجل هذا الخصوص لا أعلم لها أصلًا، إنما هي عادة للناس. فالأفضل المصافحة، ويكتفى بها عند اللقاء، يصافح أخاه، ويقول له: هنأك الله بهذا العيد، بارك الله لك في هذا العيد، أو تقبل الله منا ومنك، وما أشبه ذلك، لا بأس به.","link":"https://binbaz.org.sa/fatwas/1533/حكم-المعانقة-في-الاعياد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_463.mp3","categories":["إخراج الزكاة وأهلها","الآداب والأخلاق المحمودة"]},{"id":6212,"question":"أنا شاب أرغب في بعض الطاعات، كصيام النفل يومي الخميس والإثنين، والذهاب إلى مكة لأداء العمرة، وغير ذلك، إلا أن والدي يمنعني، فما موقفي منه؟","title":"حكم طاعة الوالد في ترك النوافل","answer":"الجواب: عليك أن تستأذن والدك، وأن تستسمحه في ذلك؛ لأن برهم واجب، وهذه نوافل، فلا تقدم النوافل على الواجب، بر أبيك واجب، وقد يكون صومك في النهار يعطل عليه مصالح، ويسبب عليه مشاكل، فينبغي لك أن تجتهد في إرضاء والدك، واستسماحه؛ حتى يسمح لك بصوم الإثنين والخميس، وحتى يسمح لك بالذهاب إلى العمرة غير الواجبة، أما العمرة الواجبة، والحج الواجب؛ فالواجب أن يسمح لك، وإذا أبى لك أن تحج الحج الواجب، إذا كنت قادرًا، وتعتمر العمرة الواجبة إن كانت قادرًا ولو لم يسمح، لكن هذا في النوافل، العمرة النافلة، والحج النافلة، ونحو ذلك. السؤال: حتى لو كان أمر الوالد لولده بحلق لحيته مثلًا؟ الجواب: هذه معصية، لا يجوز له طاعته في حلق اللحية، ولا في جر الثياب، ولا في  ترك الصلاة في جماعة، المعصية ما يجوز، إنما الطاعة في المعروف، لا طاعة للمخلوق في معصية الخالق، أما النوافل لا يجتهد مع والده حتى يكون فيه سماح؛ حتى لا يكون بينه وبين والده شر، وعقوق.","link":"https://binbaz.org.sa/fatwas/1702/حكم-طاعة-الوالد-في-ترك-النوافل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_560.mp3","categories":["إخراج الزكاة وأهلها","الآداب والأخلاق المحمودة"]},{"id":6222,"question":"أنا شاب أرغب في بعض الطاعات، كصيام النفل يومي الخميس والإثنين، والذهاب إلى مكة لأداء العمرة، وغير ذلك، إلا أن والدي يمنعني، فما موقفي منه؟","title":"حكم طاعة الوالد في ترك النوافل","answer":"الجواب: عليك أن تستأذن والدك، وأن تستسمحه في ذلك؛ لأن برهم واجب، وهذه نوافل، فلا تقدم النوافل على الواجب، بر أبيك واجب، وقد يكون صومك في النهار يعطل عليه مصالح، ويسبب عليه مشاكل، فينبغي لك أن تجتهد في إرضاء والدك، واستسماحه؛ حتى يسمح لك بصوم الإثنين والخميس، وحتى يسمح لك بالذهاب إلى العمرة غير الواجبة، أما العمرة الواجبة، والحج الواجب؛ فالواجب أن يسمح لك، وإذا أبى لك أن تحج الحج الواجب، إذا كنت قادرًا، وتعتمر العمرة الواجبة إن كانت قادرًا ولو لم يسمح، لكن هذا في النوافل، العمرة النافلة، والحج النافلة، ونحو ذلك. السؤال: حتى لو كان أمر الوالد لولده بحلق لحيته مثلًا؟ الجواب: هذه معصية، لا يجوز له طاعته في حلق اللحية، ولا في جر الثياب، ولا في  ترك الصلاة في جماعة، المعصية ما يجوز، إنما الطاعة في المعروف، لا طاعة للمخلوق في معصية الخالق، أما النوافل لا يجتهد مع والده حتى يكون فيه سماح؛ حتى لا يكون بينه وبين والده شر، وعقوق.","link":"https://binbaz.org.sa/fatwas/1702/حكم-طاعة-الوالد-في-ترك-النوافل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_560.mp3","categories":["إخراج الزكاة وأهلها","الآداب والأخلاق المحمودة"]},{"id":6225,"question":"آخر يقول: أنا متزوج ولي امرأتان، وقد لاقيت من المرأة السابقة عدة مشاكل عائلية، قد حاولتُ بشتى الوسائل إصلاح كل الأشياء التي كنت أعاني منها، ولكن دون جدوى، وقد رزقت منها بأربعة أطفال، وعندما يئست من كل شيء اضطررت إلى أن أتزوج بأخرى، وقمت بتأثيث شقة بكل ما تحتاج من أثاث للزوجة الأولى، وأسكنتها فيها، وأصرف عليها بكل ما تحتاجه هي وأطفالها، إلا أنني لم أدخل عليها في شقتها، ولا أنام معها للأسباب المشار إليها سابقًا؟","title":"الرفق بالنساء والصبر عليهن","answer":"الجواب: هذه المرأة ينبغي أن تعطف عليها، وترحمها لسبقها، ولكونها أم أولادك، والنساء مثل ما قال الرسول ﷺ خلقن من ضلع، وإن أعوج شيء في الضلع أعلاه، فإن ذهبت تقيمه كسرته، وإن تركته؛ لم يزل أعوج فلا بدّ من الصبر، ولا بدّ من العفو عن بعض الأشياء، ولا بدّ من الاستمرار في العلاج، فاستمر، ولا تيأس، استمر في العلاج، ولعلها -بهذا الهجر لها- لعلها ترجع إلى صوابها، ولعلها تحس بخطئها، وتعرف أغلاطها، فراجعها، يعني ارجع إليها، ونم معها، واعدل بينها وبين ضرتها بالقسم، والنفقة، والوجه، ونحو ذلك، واستعن بالله، فلعلها تستقيم، فإن لم تستقم؛ فحينئذ أنت مخير إن شئت طلقتها، وإن شئت أبقيتها معك إذا كانت ترضى بذلك، تبقى معك على الإنفاق عليها، وتكون محرمًا لك لو دخلت عليها، ولا بأس عليك. لكن ليس لك أن تهجرها هذا الهجران إلا إذا رضيت بذلك، أما إذا قالت: لا، طلقني، أو اعدل بيني، وبين ضرتي؛ فأنت مخير، إما أن تعدل، وإما أن تطلق، أما إذا رضيت، وقالت: لا بأس أرضى، لا تطلقني، أرضى أجلس عند عيالي على حسب نفقتك، ولا تطلقني، ولا بأس أن لا تقسم لي، أنا راضية؛ فلا بأس. وقد كانت سودة بنت زمعة أم المؤمنين -رضي الله عنها- أراد النبي أن يطلقها، فقالت: يا رسول الله لا تطلقني، وأبقني في نسائك، وأنا أجعل يومي لعائشة، فاتفق معها ﷺ على ذلك، وجعلت يومها لعائشة، وبقيت على حساب نسائه، ولم يطلقها، ولم يقسم لها.  فإذا رضيت هذه الزوجة القديمة بأن تبقى معك على غير قسم لها مع ضرتها، ولا تطلب طلاقها؛ فلا حرج عليك، تنفق عليها، وعلى أولادها، ولا حاجة إلى القسم، ولا مانع أن تدخل عليها في النهار، أو بعض الأحيان كيف حالكم، كيف أنتم؟ ربما جعل الله في هذا الدخول سببًا للخير، والمحبة، والوئام بعد ذلك، تدخل عليها، تزورهم، كيف أنتم؟ كل يوم، كل يوم، بعد يوم، بعد يومين، بعد ثلاث، تزورها؛ لأنها محرمك، ما دام ما طلقتها زوجتك تدخل عليها، وترعى أحوالهم، وترى أولادك، تجلس عندهم بعض الوقت، تسأل عن أحوالهم، تأتي إليهم بحاجاتهم، والنوم مع تلك، والقسم لها وحدها؛ لا بأس. فإذا قالت الأولى: لا، أنا ما أرضى بهذا أبدًا، بل إما أن تقسم لي حقي، وإما أن تطلقني؛ لزمك أحد الأمرين، إما القسمة، وإما الطلاق، أما إذا سمحت، وقالت: لا تطلقني، ولا بأس؛ فلا بأس.","link":"https://binbaz.org.sa/fatwas/1725/الرفق-بالنساء-والصبر-عليهن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_573.mp3","categories":["الحقوق الزوجية","الآداب والأخلاق المحمودة","قضايا المرأة"]},{"id":6231,"question":"........؟","title":"الفرق بين القيام للقادم والقيام إلى القادم","answer":"الجواب:  قال النبي: قوموا إلى سيدكم قال للصحابة: قوموا إلى سيدكم فقاموا إليه، وقابلوه، وسلموا عليه، فالقيام إلى الشخص غير القيام للشخص، المكروه، والمنكر أن تقوم له وهو جالس من غير مصافحة، ولا كلام، بل  تقوم له هكذا، إعظامًا، هذا مكروه،... من باب التعظيم أيضًا، لا يجوز؛ لأنه من فعل الأعاجم.  أما القيام إليه لمقابلته، ومصافحته، والأخذ بيده، أو إجلاسه في مكانك، أو في مكان آخر؛ فهذا مشروع، وقد فعله النبي -عليه الصلاة والسلام - وفعله الصحابة، فعله النبي مع بنته إذا دخلت، وقام إليها، وأخذ بيدها، وإذا دخل عليها؛ قامت إليه، عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/1749/الفرق-بين-القيام-للقادم-والقيام-الى-القادم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_588.mp3","categories":["إخراج الزكاة وأهلها","الآداب والأخلاق المحمودة"]},{"id":6237,"question":"إذا سافرت إلى أحد البلاد المسلمة لغرض معلوم من دراسة، وغيرها، فعندما أسكن في أي مكان تأتيني المرأة تعرض نفسها عليّ، وتتعرى أمامي، وتفتني؛ وذلك لأنها تعلم أن هذه الدولة لا تقيم الحدود، فما هو موقفي، وهل عليّ إثم؟","title":"كيفية التخلص من فتنة المرأة التي تعرض نفسها للزنا","answer":"الجواب: عليك أن تحذر، وعليك أن تدفعها، وتنكر عليها وتحاربها في ذلك وتغلق الباب دونها، وعليك أن تتقي الله -جل وعلا- هذا ابتلاء، وامتحان، فعليك أن تتقي الله، وأن تتكلم عليها، وأن تخبرها أن هذا لا يجوز، وأني مسلم لا يحل لي هذا الأمر، الزنا محرم في شريعة الله، وتحارب ذلك، وتخرجها من المحل، وتغلق الباب دونها، أو تخرج عنها بالكلية، وتبتعد، نسأل الله العافية.  ثم هذه من فوائد السفر إلى الخارج، هذا من فوائده -نعوذ بالله- يجب الحذر من السفر إلى الخارج، ولا يجوز الابتعاث إلى الخارج؛ لأنه شر عظيم في الدين، والأخلاق جميعًا، فيجب على المؤمن أن يحذر سفر الخارج، ولو للتعلم، يتعلم في بلاده، ويكفي، النبي -عليه الصلاة والسلام- يقول: أنا بريء من كل مسلم يقيم بين المشركين ففيه الخطر العظيم، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/1734/كيفية-التخلص-من-فتنة-المراة-التي-تعرض-نفسها-للزنا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_577.mp3","categories":["إخراج الزكاة وأهلها","الآداب والأخلاق المحمودة"]},{"id":6244,"question":"إذا حضرت أنا وزوجتي، وأخي، وزوجته في مجلس واحد فهل هذا جائز؟","title":"حكم اجتماع الأخوين مع زوجتيهما في مجلس واحد","answer":"الجواب: لا بأس أن تجتمع العائلة في مجلس واحد، لكن مع الحجاب، والتستر، والبعد عما حرم الله، والمرأة زوجة أخيك عندكم، أو زوجة خالك، أو زوجة عمك، أو ما أشبه ذلك عندكم في المجلس، أو في البيت، فهذا لا محذور فيه، هذا من عهد النبي إلى يومنا هذا، الناس يتزاورون، ويزور بعضهم بعضًا، ويلتقي بعضهم بعضًا، ويزور الأجنبي بلاد أصدقائه، وبيت أصدقائه، ولو كان غير أخ، ويكون نساؤه مع نسائهم، وربما اجتمعوا جميعًا، لكن مع الحجاب، والستر، والبعد عن الكلمات الخبيثة النابية، هذا كله لا حرج فيه. السؤال: وإذا لم يكن هناك حجاب؟ الجواب: ما يجوز يجب عليها أن تستر، وإلا تبتعد، لا تجلس معهم، وإذا كانت لا بدّ من جلوسها فيقم هو الذي ليس محرمًا لها، أو يغض بصره، ويعرض عنها؛ حتى يكون امتثل أمر الله.","link":"https://binbaz.org.sa/fatwas/1736/حكم-اجتماع-الاخوين-مع-زوجتيهما-في-مجلس-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_579.mp3","categories":["الخِطْبَة والاختيار ","النظر والخلوة والاختلاط","قضايا المرأة","الآداب والأخلاق المحمودة"]},{"id":6248,"question":"إذا سافرت إلى أحد البلاد المسلمة لغرض معلوم من دراسة، وغيرها، فعندما أسكن في أي مكان تأتيني المرأة تعرض نفسها عليّ، وتتعرى أمامي، وتفتني؛ وذلك لأنها تعلم أن هذه الدولة لا تقيم الحدود، فما هو موقفي، وهل عليّ إثم؟","title":"كيفية التخلص من فتنة المرأة التي تعرض نفسها للزنا","answer":"الجواب: عليك أن تحذر، وعليك أن تدفعها، وتنكر عليها وتحاربها في ذلك وتغلق الباب دونها، وعليك أن تتقي الله -جل وعلا- هذا ابتلاء، وامتحان، فعليك أن تتقي الله، وأن تتكلم عليها، وأن تخبرها أن هذا لا يجوز، وأني مسلم لا يحل لي هذا الأمر، الزنا محرم في شريعة الله، وتحارب ذلك، وتخرجها من المحل، وتغلق الباب دونها، أو تخرج عنها بالكلية، وتبتعد، نسأل الله العافية.  ثم هذه من فوائد السفر إلى الخارج، هذا من فوائده -نعوذ بالله- يجب الحذر من السفر إلى الخارج، ولا يجوز الابتعاث إلى الخارج؛ لأنه شر عظيم في الدين، والأخلاق جميعًا، فيجب على المؤمن أن يحذر سفر الخارج، ولو للتعلم، يتعلم في بلاده، ويكفي، النبي -عليه الصلاة والسلام- يقول: أنا بريء من كل مسلم يقيم بين المشركين ففيه الخطر العظيم، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/1734/كيفية-التخلص-من-فتنة-المراة-التي-تعرض-نفسها-للزنا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_577.mp3","categories":["إخراج الزكاة وأهلها","الآداب والأخلاق المحمودة"]},{"id":6252,"question":"وآت ذا القربى حقه أليس ذلك الزكاة، أو هي نفقة خاصة دون الزكاة؟","title":"عموم قوله: (وَآتِ ذَا الْقُرْبَى حَقَّهُ) في الزكاة والصلة وغيرهما","answer":"الجواب: \nهذا عام، إيتاء ذي القربى حقه، صلة الرحم حق، إذا كان فقيرًا؛ يعطى حقه صلة الرحم، وإذا كان عاجزًا؛ أعطاه من الزكاة، فكل هذا له حق في الزكاة، وله حق في مال قريبه إذا كان فقيرًا، فالآية تعم هذا، وهذا، تعم حق الزكاة، وتعم حق الصلة، فإذا تيسر أنه يعطيه حق الصلة، ويغنيه بذلك وهو يقدر؛ كفاه عن الزكاة، وإذا كان لا يستطيع أن يكفيه؛ أعطاه من الزكاة، أو كمل له من الزكاة.","link":"https://binbaz.org.sa/fatwas/1781/عموم-قوله-وات-ذا-القربى-حقه-في-الزكاة-والصلة-وغيرهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_620.mp3","categories":["صدقة التطوع","الآداب والأخلاق المحمودة"]},{"id":6261,"question":"وآت ذا القربى حقه أليس ذلك الزكاة، أو هي نفقة خاصة دون الزكاة؟","title":"عموم قوله: (وَآتِ ذَا الْقُرْبَى حَقَّهُ) في الزكاة والصلة وغيرهما","answer":"الجواب: \nهذا عام، إيتاء ذي القربى حقه، صلة الرحم حق، إذا كان فقيرًا؛ يعطى حقه صلة الرحم، وإذا كان عاجزًا؛ أعطاه من الزكاة، فكل هذا له حق في الزكاة، وله حق في مال قريبه إذا كان فقيرًا، فالآية تعم هذا، وهذا، تعم حق الزكاة، وتعم حق الصلة، فإذا تيسر أنه يعطيه حق الصلة، ويغنيه بذلك وهو يقدر؛ كفاه عن الزكاة، وإذا كان لا يستطيع أن يكفيه؛ أعطاه من الزكاة، أو كمل له من الزكاة.","link":"https://binbaz.org.sa/fatwas/1781/عموم-قوله-وات-ذا-القربى-حقه-في-الزكاة-والصلة-وغيرهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_620.mp3","categories":["صدقة التطوع","الآداب والأخلاق المحمودة"]},{"id":6276,"question":"يوجد لدي بهيمة ضالة، عنزة لها أكثر من خمسة عشر يومًا، قد بحثت عن صاحبها، ولم أجده، أرجو الحكم في التصرف فيها؟","title":"كيفية التصرف مع ضالة الغنم","answer":"الجواب:  عرفها دائمًا، عرفها حتى تتم السنة، عرفها سنة كاملة في مجامع الناس، في الشهر مرتين، ثلاثًا، أربعًا، من له الضالة؟ من له العنز الضالة؟ من له العنز الضالة؟ وإذا كملت السنة، ولم يأت إليها أحد؛ فهي لك، وإذا كنت يشق عليك علفها؛ بعها، واحفظ ثمنها، واحفظ صفاتها عندك، فإذا جاء ربها، وعرفها؛ فأعطه الثمن، وإن لم يأت أحد مع التعريف؛ فهي لك، لكن لا تسكت، عرفها سنة كاملة في مجامع الناس، في كل شهر ثلاث مرات أربع مرات، أكثر، من له الضالة؟ من له الضالة؟ .. السؤال: حديث الرسول: هي لك أو لأخيك أو للذئب؟ الجواب: الرسول -عليه الصلاة والسلام- قال: من آوى ضالة؛ فهو ضال من لم يعرفها، رواه مسلم، وقوله: هي لك، أو لأخيك، أو للذئب يعني لا تدعها، خذها، ولكن لا يأخذها حتى يعرفها.  السؤال: ولو تركها يا شيخ؟ الجواب: إذا تركها ما عليه شيء.","link":"https://binbaz.org.sa/fatwas/1784/كيفية-التصرف-مع-ضالة-الغنم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_623.mp3","categories":["اللقطة واللقيط","الآداب والأخلاق المحمودة"]},{"id":6334,"question":"وأحد الإخوة يسأل: لقد اشتركت في مسابقة القرآن الكريم في شهر رمضان المبارك، والذي كان يقدم من إذاعة القرآن الكريم، وقد فزت بجائزة قدرها عشرة آلاف ريال، وأنا لم أسمع النتيجة بنفسي، ولكن أذاعوها، وإنما كتبوا بعض الأحباب، وقد استلمت الجائزة إلا أن قلبي لم يرتح لذلك، مالم أعطهم بشارة على ما يقول المثل؛ لأن الفضل لله، ثم لهم، فهل لو أعطيتهم شيئًا من هذا يوافق سنة رسول الله؟","title":"حكم الهبة لمن بشرك بخير","answer":"الجواب: ما نعلم فيه شيئًا، لا بأس، كعب بن مالك لما بشره بعض الصحابة بتوبة الله عليه، أعطاه ثوبين، ثوبين كانا عليه، فإذا أعطى المبشر بخير ينفعه، أعطاه دراهم، أو ملابس؛ لا بأس.","link":"https://binbaz.org.sa/fatwas/1932/حكم-الهبة-لمن-بشرك-بخير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_717.mp3","categories":["الهبة والعطية","الآداب والأخلاق المحمودة"]},{"id":6342,"question":"وأحد الإخوة يسأل: لقد اشتركت في مسابقة القرآن الكريم في شهر رمضان المبارك، والذي كان يقدم من إذاعة القرآن الكريم، وقد فزت بجائزة قدرها عشرة آلاف ريال، وأنا لم أسمع النتيجة بنفسي، ولكن أذاعوها، وإنما كتبوا بعض الأحباب، وقد استلمت الجائزة إلا أن قلبي لم يرتح لذلك، مالم أعطهم بشارة على ما يقول المثل؛ لأن الفضل لله، ثم لهم، فهل لو أعطيتهم شيئًا من هذا يوافق سنة رسول الله؟","title":"حكم الهبة لمن بشرك بخير","answer":"الجواب: ما نعلم فيه شيئًا، لا بأس، كعب بن مالك لما بشره بعض الصحابة بتوبة الله عليه، أعطاه ثوبين، ثوبين كانا عليه، فإذا أعطى المبشر بخير ينفعه، أعطاه دراهم، أو ملابس؛ لا بأس.","link":"https://binbaz.org.sa/fatwas/1932/حكم-الهبة-لمن-بشرك-بخير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_717.mp3","categories":["الهبة والعطية","الآداب والأخلاق المحمودة"]},{"id":6350,"question":"وأحد الإخوة يقول: لو ميزت أحد أبنائي بمال أكتبه له؛ لأنني لم أتح له الفرصة التي أتحتها لإخوته، أو لأنه لم يتزوج مثلهم، أو لأنه مريض، أو كفيف البصر، فهل أستطيع أعطي له شيئًا من مالي؟","title":"حكم تخصيص أحد الأبناء بشيء من المال","answer":"الجواب: النبي ﷺ يقول: اتقوا الله، واعدلوا بين أولادكم، أفلا يسرك أن يكونوا في البر سواء؟ قال: بلى، قال: فلا إذًا، وقال : إني لا أشهد على جور.  فالمقصود: أن الواجب على الإنسان، سواء ذكر، أو أنثى، الأب، أو الأم عليهم أن يعدلوا بين أولادهم، وليس لهم أن يجوروا، فلا يعطي الابن، ويدع البنت، ولا يعطي بعض الأولاد، ويدع الباقين، ولا يعطي بعض البنات، ويدع الباقين، بل عليه أن يعدل بينهم جميعاً، ولو كان أحدهم ليس من الحذق مثل الآخر، لو كان واحد حاذق، وواحد ليس بحاذق، وواحد عنده أموال، وواحد ما عنده أموال يسوي بينهم، ويعدل بينهم. لكن النفقة لا بأس بها إذا كان واحد فقير، ما عنده أسباب وواحد مغنيه الله؛ ينفق على الفقير حتى يغنيه الله؛ لأن هذا من وجوب النفقة، ومن البر. فالفقير، والكفيف، والمريض الذي ما عنده أسباب، ووالده يقدر على الإنفاق، ينفق عليه، وليس هذا من الجور، والأولاد الذين أغناهم الله، وعندهم أموال ليسوا بحاجة إلى النفقة، وإذا زوجهم يزوج الجميع، إلا إذا كان بعض المتزوجين قد أغناهم الله؛ فيزوج نفسه مما أعطاه الله، والعاجز يزوجه والده مما أعطاه الله، إذا كان عاجزًا مثل النفقة.  أما أن يخص واحدًا لأجل كذا، أو لأجل كذا، وإلا كلهم سواء في المال لا، لا يخص هذا؛ لأنه كفيف، أو يخص هذا لأنه أبر، أو يخص هذا لأن عنده مثلاً أولاد كثير، أو ما أشبه ذلك، إلا إذا كان فقيراً.  المقصود: لا يخص أحدًا دون أحد إلا لأمر شرعي مثل: النفقة على الفقير العاجز، ولا يستطيع العمل، أو لأنه أراد أن يسوي بينهم في العطية، فأعطى هذا، ثم أعطى الباقين، لا لأجل التخصيص، بل ليعيطهم مثله، أو ما أشبه ذلك مما فيه التسوية.  السؤال: يا شيخ بالنسبة للتسوية بين الذكر، والأنثى؟ الجواب:  على حسب الميراث، هذا أرجح القولين.","link":"https://binbaz.org.sa/fatwas/1933/حكم-تخصيص-احد-الابناء-بشيء-من-المال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_718.mp3","categories":["الهبة والعطية","الآداب والأخلاق المحمودة"]},{"id":6371,"question":"وأحد الإخوة يسأل: لقد اشتركت في مسابقة القرآن الكريم في شهر رمضان المبارك، والذي كان يقدم من إذاعة القرآن الكريم، وقد فزت بجائزة قدرها عشرة آلاف ريال، وأنا لم أسمع النتيجة بنفسي، ولكن أذاعوها، وإنما كتبوا بعض الأحباب، وقد استلمت الجائزة إلا أن قلبي لم يرتح لذلك، مالم أعطهم بشارة على ما يقول المثل؛ لأن الفضل لله، ثم لهم، فهل لو أعطيتهم شيئًا من هذا يوافق سنة رسول الله؟","title":"حكم الهبة لمن بشرك بخير","answer":"الجواب: ما نعلم فيه شيئًا، لا بأس، كعب بن مالك لما بشره بعض الصحابة بتوبة الله عليه، أعطاه ثوبين، ثوبين كانا عليه، فإذا أعطى المبشر بخير ينفعه، أعطاه دراهم، أو ملابس؛ لا بأس.","link":"https://binbaz.org.sa/fatwas/1932/حكم-الهبة-لمن-بشرك-بخير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_717.mp3","categories":["الهبة والعطية","الآداب والأخلاق المحمودة"]},{"id":6400,"question":"أحد الإخوة بعث أسئلة من مصر، ولكنها أسئلة كثيرة عن الحد، ونختار منها هذه الأسئلة؛ لعلها الأهم كما ذكر ذلك: الناس يفرقون بين ما يحل بعقد الزواج، ويسمونه كتب الكتاب، وبين ما يحل في ليلة البناء، فهل هذا الفرق له أصل في الشرع؟ وهل إذا جامع العاقد زوجته في بيت أبيها أيكون آثمًا؟ وهل يجب استئذان الولي عند البناء بها، مع العلم بأن العقد الشرعي قد تم؟","title":"حكم الدخول على المرأة بعد العقد واستئذان الولي","answer":"الجواب: هذه أسئلة فيها بعض الغموض، والجواب: ما دام العقد الشرعي، تم عقد الزواج الشرعي، تم الإيجاب والقبول من الولي الشرعي، والقبول من الزوج، وحضور الشاهدين العدلين؛ فإن الزوجة تكون حلاً له إذا استوفت الشروط، ولا فرق بين كونه يجامعها في بيت مستقل، أو في بيت أهلها إذا جعلوا له محلًا في بيتهم هو وزوجته، لا حرج عليه أن ينام معها، وأن يجامعها، وكذلك لا حاجة لاستئذان الولي في الدخول بها إذا كان الأمر قد حصل؛ هيؤوا له المكان معها، وطابت نفوسهم بذلك.  أما ما يقع في ليلة البناء فهذا لا نعرف مراده به، إن كان المراد إذا بنى بها، يعني دخل عليها كما يسمى في اللغة العربية وفي العهد الأول، وقد بنى عليها، إذا دخل عليها، وعقد عليها، إذا أجرى العقد، فرضا العقد يحلها، والبناء عليها هو الدخول بها.  وقد يجري العقد، ولكن يمنع من الدخول لأسباب، فإذا كان العقد قد تم، ولكن أهلها لم يرضوا بالدخول؛ فلا يدخل عليها، بل يصبر، حتى يسمحوا له بالدخول عليها؛ لأنه إذا دخل عليها من دون علمهم، أو قهرًا عليهم؛ قد يفضي هذا إلى شر عظيم، وفتنة، وقد تتهم البنت بأنها اتصل بها غير زوجها؛ لأن الدخول هو إعلان النكاح، فإذا دخل عليها سرًا، أو بصفة غير معلومة، غير مألوفة؛ قد يقع ضرر بينه، وبين أهلها، وقد تتهم البنت إذا حملت بأن هذا ليس من زوجها؛ لأنهم لم يعلموا دخوله بها. فالذي ينبغي أن الزوج لا يعجل حتى تتم الأمور بالطرق المألوفة المعروفة، وحتى يدخل عليها الدخول المعروف الذي ليس فيه ريبة ولا شبهة. السؤال: لو جامعها يعني وقع مثل هذا الأمر، هل يكون آثمًا في ذلك؟ الجواب: إذا كان يترتب عليه شر؛ يأثم؛  لأن معناه ألجأهم إلى شر، أو ألجأها إلى شر، فيخشى عليها أن تتهم بالشر، وأن يظن بها أنها زنت؛ لأنهم لا يعرفون أنه دخل بها، ولا يعلمون ذلك، ما جرت المراسيم المعروفة، فهذا خطر، أما فيما بينها، وبين الله؛ فهي حل له، فينبغي أن تؤتى البيوت من أبوابها، ولا تؤتى من غير أبوابها؛ حتى لا يقع بينه، وبين أهلها مشاكل.","link":"https://binbaz.org.sa/fatwas/1965/حكم-الدخول-على-المراة-بعد-العقد-واستىذان-الولي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_752.mp3","categories":["الحقوق الزوجية","الآداب والأخلاق المحمودة"]},{"id":6472,"question":"موضوع الأخلاق موضوع يهم كل مسلم، فما هي الوسائل التي تعين على كسب هذه الأخلاق؟ وكذلك الصبر على القيام بها إذا كانت موجودة لدى المسلم، أفيدونا جزاكم الله خيرًا؟","title":"الوسائل المعينة على اكتساب الأخلاق الحميدة","answer":"الجواب: أعظم الأسباب: دعاء الله، والضراعة إليه أن يوفق لها، كما قال النبي ﷺ: اللهم اهدني لأحسن الأخلاق، لا يهدني لأحسنها إلا أنت، واصرف عني سيئها، لا يصرف عني سيئها إلا أنت يسأل ربه أن يعينه على مكارم الأخلاق، ومحاسن الأعمال، هذا أول الأسباب، وأعظمها. السبب الثاني: طلب العلم، والتبصر، معرفة الأخلاق الكريمة، ومعرفة الأخلاق السيئة الذميمة، حتى يعتاد الأخلاق الكريمة، وحتى يبتعد عن الأخلاق الذميمة. السبب الثالث: المحافظة على الأخيار، وصحبة الأخيار، والبعد عن الأشرار، فهذا من أعظم الأسباب للتخلق بالأخلاق الكريمة، والبعد عن الأخلاق الذميمة. السبب الرابع: العناية، وجهاد النفس، لا بد من جهاد، وصبر، لا بد أن يجاهد نفسه على الخلق الكريم، ويحذر بكل قوته، وبكل نشاطه، وبكل ما أعطاه الله من قوة الخلق الذميم، هكذا المؤمن، وهذا السبب الرابع يحتاج إلى صبر، ومصابرة .. النفس ما تحصل الأمور ... ولا بالشيء السهل، لا بد من صبر، ولا بد من جهاد لهذه النفس؛ حتى تعتاد الأخلاق الكريمة، وحتى تستقيم عليها، وحتى تبتعد عن الأخلاق الذميمة.","link":"https://binbaz.org.sa/fatwas/2217/الوساىل-المعينة-على-اكتساب-الاخلاق-الحميدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_836.mp3","categories":["إخراج الزكاة وأهلها","الآداب والأخلاق المحمودة"]},{"id":6504,"question":"ابتلينا في بلادنا بالمدارس المختلطة بين البنين والبنات، فتيان وفتيات، وأنا شاب متدين والحمد لله، وعينت مدرسًا بإحدى هذه المدارس المختلطة، حيث لا يوجد مدرس للبنين فقط في بلدنا، ولكن توجد مدرسة بعيدة عن بلدي، تحتاج لمجهود شاق طوال اليوم، ومصاريف كثيرة، وراتبي صغير وقليل، فهل أبقى في المدرسة المختلطة، أم أطلب النقل إلى المدرسة الأخرى، ولو دفعت مالًا للقائمين؟","title":"حكم التدريس في المدارس المختلطة","answer":"الجواب: انظر ما هو أصلح لقلبك، إذا كان تخشى على نفسك؛ فانتقل عنها، وإذا كنت ترى أن وجودك فيه صلاح للمدرسة، وحثهم على طاعة الله، وتحث البنات على الستر، وتغض بصرك، وتعمل ما ينفع الأمة تفعل.  اعمل ما هو الأصلح إن كنت تخشى على نفسك من وجود البنات، فاتق الله، واحذر، وانتقل عن هذه المدرسة، إلى مدارس أخرى، أو إلى عمل آخر، وإن كنت ترى أن وجودك في المدرسة فيه مصلحة للمسلمين، ونفع للمسلمين، وتستطيع أن تغض بصرك، وأن تأمرهن بالحجاب، والتستر، وتجتهد مع إخوانك الباقين في هذا الأمر، فأنت على ثغر عظيم من ثغور الإسلام، فاتق الله في ذلك، واعمل ما تستطيع من الخير، وإلا فانتقل.","link":"https://binbaz.org.sa/fatwas/2261/حكم-التدريس-في-المدارس-المختلطة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_884.mp3","categories":["الخِطْبَة والاختيار ","النظر والخلوة والاختلاط","قضايا المرأة","الآداب والأخلاق المحمودة"]},{"id":6507,"question":"هل يجوز مراسلة الخطيب لخطيبته قبل أن يعقد عليها؟ وهل الخطبة مشروعة؟","title":"حكم مراسلة الخاطب لخطيبته قبل العقد","answer":"الجواب: لا بأس كأن يراسلها بشيء ينفعها، هدية، أو غير ذلك، لا بأس إذا كان تم الخطبة بينهما، أو أراد أن يرغبهما في ذلك؛ أرسل إلى أهلها، وإليها بهدايا يرجوهم أن يوافقوا على الزواج؛ لا بأس بذلك، المهم أن يكون ذلك عن طريق شرعية، لا عن طريق خلوة، ولا عن طريق مقابلة خبيثة، ولكن عن طريق التودد إلى أهلها، وإليها بالهدايا حتى يستجيب لرغبته؛ لا بأس بذلك.","link":"https://binbaz.org.sa/fatwas/2268/حكم-مراسلة-الخاطب-لخطيبته-قبل-العقد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_891.mp3","categories":["الخِطْبَة والاختيار ","النظر والخلوة والاختلاط","قضايا المرأة","الآداب والأخلاق المحمودة"]},{"id":6526,"question":"ابتلينا في بلادنا بالمدارس المختلطة بين البنين والبنات، فتيان وفتيات، وأنا شاب متدين والحمد لله، وعينت مدرسًا بإحدى هذه المدارس المختلطة، حيث لا يوجد مدرس للبنين فقط في بلدنا، ولكن توجد مدرسة بعيدة عن بلدي، تحتاج لمجهود شاق طوال اليوم، ومصاريف كثيرة، وراتبي صغير وقليل، فهل أبقى في المدرسة المختلطة، أم أطلب النقل إلى المدرسة الأخرى، ولو دفعت مالًا للقائمين؟","title":"حكم التدريس في المدارس المختلطة","answer":"الجواب: انظر ما هو أصلح لقلبك، إذا كان تخشى على نفسك؛ فانتقل عنها، وإذا كنت ترى أن وجودك فيه صلاح للمدرسة، وحثهم على طاعة الله، وتحث البنات على الستر، وتغض بصرك، وتعمل ما ينفع الأمة تفعل.  اعمل ما هو الأصلح إن كنت تخشى على نفسك من وجود البنات، فاتق الله، واحذر، وانتقل عن هذه المدرسة، إلى مدارس أخرى، أو إلى عمل آخر، وإن كنت ترى أن وجودك في المدرسة فيه مصلحة للمسلمين، ونفع للمسلمين، وتستطيع أن تغض بصرك، وأن تأمرهن بالحجاب، والتستر، وتجتهد مع إخوانك الباقين في هذا الأمر، فأنت على ثغر عظيم من ثغور الإسلام، فاتق الله في ذلك، واعمل ما تستطيع من الخير، وإلا فانتقل.","link":"https://binbaz.org.sa/fatwas/2261/حكم-التدريس-في-المدارس-المختلطة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_884.mp3","categories":["الخِطْبَة والاختيار ","النظر والخلوة والاختلاط","قضايا المرأة","الآداب والأخلاق المحمودة"]},{"id":6545,"question":"إذا ثبتت سرقة في حق مسلم، فهل يحل لي أن يرد إلي مالي على ألا أبلغ القاضي ليقيم عليه حد السرقة، علمًا بأن المبلغ المسروق حوالي مائة ألف ريال؟","title":"المسامحة في الحدود قبل أن تبلغ السلطان","answer":"الجواب: لا بأس إذا تراضيت أنت وإياه، وأعطاك مالك، وسترت عليه، لا بأس، ولكن إذا كان شره كثيرًا، أو علمت أنه يتعاطى هذا مع الناس، فهذا ينبغي أن يرفع عنه، ويعتدى عليه حتى يكفى شره الناس.  أما إذا كانت مرة واحدة بينك وبينه، أو مرتين، ليس من أهل الشر المعروف؛ فلا بأس بالستر عليه، والمصالحة معه، لأن الرسول ﷺ لما سرق رداء صفوان بن أمية أتى به النبي ﷺ وقال له: إن هذا سرق ردائي، فأمر النبي بقطع يده. فقال يا رسول الله قد عفوت عنه، ردائي هو له. فقال: هلا كان هذا قبل أن تأتني به، إذا بلغت الحدود السلطان؛ فلعن الشافع والمشفع.  المقصود: أنها قبل أن تبلغ السلطان لا بأس أن تعفو عن الذي سرق منك، وتنصحه، وتحذره من العود، أما إذا بلغت السلطان، ورفعت إلى المحكمة، رفعت إلى الأمير، لا ما يعفى عنه، لا بد من إقامة الحدود بعد بلوغها السلطان.","link":"https://binbaz.org.sa/fatwas/2384/المسامحة-في-الحدود-قبل-ان-تبلغ-السلطان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_917.mp3","categories":["الجنايات والحدود","الآداب والأخلاق المحمودة"]},{"id":6547,"question":"إذا ثبتت سرقة في حق مسلم، فهل يحل لي أن يرد إلي مالي على ألا أبلغ القاضي ليقيم عليه حد السرقة، علمًا بأن المبلغ المسروق حوالي مائة ألف ريال؟","title":"المسامحة في الحدود قبل أن تبلغ السلطان","answer":"الجواب: لا بأس إذا تراضيت أنت وإياه، وأعطاك مالك، وسترت عليه، لا بأس، ولكن إذا كان شره كثيرًا، أو علمت أنه يتعاطى هذا مع الناس، فهذا ينبغي أن يرفع عنه، ويعتدى عليه حتى يكفى شره الناس.  أما إذا كانت مرة واحدة بينك وبينه، أو مرتين، ليس من أهل الشر المعروف؛ فلا بأس بالستر عليه، والمصالحة معه، لأن الرسول ﷺ لما سرق رداء صفوان بن أمية أتى به النبي ﷺ وقال له: إن هذا سرق ردائي، فأمر النبي بقطع يده. فقال يا رسول الله قد عفوت عنه، ردائي هو له. فقال: هلا كان هذا قبل أن تأتني به، إذا بلغت الحدود السلطان؛ فلعن الشافع والمشفع.  المقصود: أنها قبل أن تبلغ السلطان لا بأس أن تعفو عن الذي سرق منك، وتنصحه، وتحذره من العود، أما إذا بلغت السلطان، ورفعت إلى المحكمة، رفعت إلى الأمير، لا ما يعفى عنه، لا بد من إقامة الحدود بعد بلوغها السلطان.","link":"https://binbaz.org.sa/fatwas/2384/المسامحة-في-الحدود-قبل-ان-تبلغ-السلطان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_917.mp3","categories":["الجنايات والحدود","الآداب والأخلاق المحمودة"]},{"id":6552,"question":"رجل يريد أن يتنازل لزوجته عن بيته إكرامًا لها، وتطييبًا لخاطرها، ومكافأة لإخلاصها معه طول حياته، وتحملها المشاق معه، فما حكم ذلك؟","title":"حكم تنازل الزوج عن بيته لزوجته","answer":"الجواب: لا بأس إذا تنازل عن بيته لها، عطية لها صحيحة بسبب إكرامها له، وخدمتها له، وعملها الطيب، فلا بأس أن يتنازل لها عن بيته إذا كان صحيحًا، لا مريضًا، أما إذا كان مريضًا ليس له أن يتنازل لها؛ لأنها وارثة، وليس لها شيء، وليس له أن يوصي بها وصية، الوارث لا وصية له، لكن إذا كان صحيحًا، وأراد أن يعيطها بيته، وهو صحيح سليم -لا مريض- ولا يوصي وصية، بل يعطيها عطية ناجزة؛ لأنها امرأة صالحة، خدمته، وقامت بحقه، وأحسنت عشرته، فهذا من مكارم الأخلاق، ومن محاسن الأعمال، ولا بأس به. السؤال: لو قصد ذلك أنه ليس له أبناء ذكور يمكن حتى إخوته لا يرثونه مثلًا؟ الشيخ: سواء كان له أبناء، أو ما له أبناء، ما دام صحيحًا سليمًا، غير مريض، له أن يعطي زوجته، ويعطي غيرها. السؤال: تعد هذه وصية؟ الشيخ: لا ما هي بوصية، هذه ناجزة إذا كان وصية لا، إذا كان أوصى لها ما يجوز الوصية، لا وصية لوارث لكن إذا كان أعطاها إياه عطية ناجزة، وهو حي، وسليم صحيح.","link":"https://binbaz.org.sa/fatwas/2407/حكم-تنازل-الزوج-عن-بيته-لزوجته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_934.mp3","categories":["الهبة والعطية","الآداب والأخلاق المحمودة"]},{"id":6562,"question":"اقترضت من شخص مبلغًا من المال، ثم توفي قبل أن أقوم بتسديد هذا المبلغ، ولم أجد له ورثة، فكيف أتصرف في هذا المال؟","title":"حكم المال الذي توفي صاحبه وليس له ورثة","answer":"الجواب: إذا كان عليك دين لإنسان، وقد توفي، ولا تعلم له ورثه؛ تتصدق به عنه، تعطيه بعض الفقراء بالنية عن صاحبه، فينفعه ذلك في الدنيا والآخرة، ينفعه في موته، وينفعك أيضًا في براءة الذمة، هذا إذا كنت لا تعرف له ورثة، ولكن لا تعجل حتى تسأل عنه أهل المعرفة بذلك؛ لعلك تجد ورثة له.  فإذا مضت مدة طويلة، ولم تعرف له وارثًا، فتصدق به عنه، أو أعطه بيت المال، والصدقة عنه أحسن في هذا الباب، تصدق عنه للفقراء المعروفين بالنية عن صاحبه، والله يبرئ ذمتك، وينفع به الميت.","link":"https://binbaz.org.sa/fatwas/2396/حكم-المال-الذي-توفي-صاحبه-وليس-له-ورثة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_925.mp3","categories":["السلف والقرض","الآداب والأخلاق المحمودة"]},{"id":6563,"question":"رجل أعطى مالًا لآخر، دون أن يشترط أن يرد المال مع زيادة، ولكن المدين من تلقاء نفسه رد المبلغ، ومعه ألف ريال زيادة، بنفس راضية، فهل هذا يعتبر ربًا؟","title":"حكم قضاء الدين بزيادة دون اشتراط ذلك","answer":"الجواب: إذا رد المبلغ بدون شرط، ولا تواطؤ على الزيادة؛ فلا بأس، النبي ﷺ يقول: إن خيار الناس أحسنهم قضاء الرسول ﷺ كان يعطي خيرًا مما أخذ -عليه الصلاة والسلام- ويقول: إن خيار الناس أحسنهم قضاء فإذا اقترض مائة، ورد مائة وخمسين، أو مائتين من باب المعروف، ومن باب المكافأة؛ فلا بأس، أو اقترض خمسين صاعًا من البر؛ فرد مائة، أو أقل، أو أكثر؛ فلا بأس، النبي ﷺ جاء أنه اقترض ثلاثين، ورد ستينًا، واقترض أربعين، ورد ثمانين. السؤال: أربعون ماذا؟ الشيخ: صاعًا، أو أربعين وسقًا.","link":"https://binbaz.org.sa/fatwas/2409/حكم-قضاء-الدين-بزيادة-دون-اشتراط-ذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_936.mp3","categories":["السلف والقرض","الآداب والأخلاق المحمودة"]},{"id":6571,"question":"هل قرض البنك العقاري يعتبر دينًا؟ وكيف إذا كانت روح الميت معلقة في دينه، فكيف الحل فيمن توفي وعليه دين للبنك؟","title":"حكم من توفي وعليه دين للبنك العقاري","answer":"الجواب: يعتبر دينًا، القروض التي للبنك العقاري ديون مثل بقية الديون، وإذا مات المستدين؛ قام الورثة مقامه، فإن التزموا في الآجال، والأقساط؛ فلا بأس، ولا يضره ذلك؛ لأنه لم يتحتم عليه التسديد الآن، لا يضر الميت، وهكذا الديون الأخرى التي في ذمته مؤجلة لا تضره إذا التزم الورثة بالحق، وتبقى على آجالها للبنك، وغير البنك. أما إذا لم يلتزموا فإنها توفى بسرعة، توفى من التركة بالعجلة، ولا تؤجل، أما إذا كانت الورثة، وقالوا: نحن نقوم مقامه، ورضي البنك، أو رهنوه، أو ضمينًا، فإن الديون تبقى على آجالها، وليس لأهلها حق في تعجيلها، إلا برضى من هي عليه، والميت لا يضره ذلك؛ لأن النفس المعلقة بالدين الذي هو حال الذي يلزم تسديده، أما الدين المؤجل؛ فلا يلزمه تسديده إلا في وقته.","link":"https://binbaz.org.sa/fatwas/2426/حكم-من-توفي-وعليه-دين-للبنك-العقاري","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_953.mp3","categories":["السلف والقرض","الآداب والأخلاق المحمودة"]},{"id":6582,"question":"رجل يريد أن يتنازل لزوجته عن بيته إكرامًا لها، وتطييبًا لخاطرها، ومكافأة لإخلاصها معه طول حياته، وتحملها المشاق معه، فما حكم ذلك؟","title":"حكم تنازل الزوج عن بيته لزوجته","answer":"الجواب: لا بأس إذا تنازل عن بيته لها، عطية لها صحيحة بسبب إكرامها له، وخدمتها له، وعملها الطيب، فلا بأس أن يتنازل لها عن بيته إذا كان صحيحًا، لا مريضًا، أما إذا كان مريضًا ليس له أن يتنازل لها؛ لأنها وارثة، وليس لها شيء، وليس له أن يوصي بها وصية، الوارث لا وصية له، لكن إذا كان صحيحًا، وأراد أن يعيطها بيته، وهو صحيح سليم -لا مريض- ولا يوصي وصية، بل يعطيها عطية ناجزة؛ لأنها امرأة صالحة، خدمته، وقامت بحقه، وأحسنت عشرته، فهذا من مكارم الأخلاق، ومن محاسن الأعمال، ولا بأس به. السؤال: لو قصد ذلك أنه ليس له أبناء ذكور يمكن حتى إخوته لا يرثونه مثلًا؟ الشيخ: سواء كان له أبناء، أو ما له أبناء، ما دام صحيحًا سليمًا، غير مريض، له أن يعطي زوجته، ويعطي غيرها. السؤال: تعد هذه وصية؟ الشيخ: لا ما هي بوصية، هذه ناجزة إذا كان وصية لا، إذا كان أوصى لها ما يجوز الوصية، لا وصية لوارث لكن إذا كان أعطاها إياه عطية ناجزة، وهو حي، وسليم صحيح.","link":"https://binbaz.org.sa/fatwas/2407/حكم-تنازل-الزوج-عن-بيته-لزوجته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_934.mp3","categories":["الهبة والعطية","الآداب والأخلاق المحمودة"]},{"id":6603,"question":"قرأت في صحيح مسلم شرح النووي: أن الرجل لا يجوز له النظر إلى فرج امرأته مع التبرج في ذلك على حسب مذهب النووي، فقرأت في آداب الزفاف: أنه يجوز النظر لكل من الزوجين، أفتونا أثابكم الله؟","title":"حكم نظر كل من الزوجين إلى فرج الآخر","answer":"الجواب: النظر إلى زوجته جائز، مطلقًا، فرجها، وغير فرجها، وهو كذلك يجوز النظر إليها، قد أباح الله له جماعها، والجماع أشد من النظر، فالذي يقول: ما يجوز النظر هذا غلط، سواء النووي، أو غير النووي، والذي يقول: إنه جائز هو المصيب.  المقصود: أن نظر الرجل إلى زوجته، ونظرها إليه، إلى بدنه كله، عورته، وغير عورته، كل هذا جائز، والحمد لله، الله أباح لكل منهما النظر إلى الآخر، كان النبي يغتسل مع زوجاته -عليه الصلاة والسلام- والمغتسل تكشف العورة، ويجامعها، وترى عورته، ويرى عورتها، هذا القول: بأنه لا يجوز قول غلط، لا وجه له. السؤال: يغتسل مكشوف العورة؟ الجواب: مكشوف العورة.. مكشوف العورة نعم، ما عليه لا سراويل، ولا إزار يكفي.. والمغتسل يكشف عورته، إذا كان ما عنده أحد في حمام خاص؛ يكشف عورته، الحمد لله اغتسل النبي عريانًا، ًواغتسل موسى عريانًا، واغتسل أيوب عرياناً. السؤال: في الحديث تقول عائشة: (أنه لم ير مني، ولم أر منه)؟ الجواب: لا ما هو صحيح، هذا من كلام العامة، ما له أصل، هذا قول عائشة \"لم ير مني، ولم أر منه\" هذا غلط، ما له أصل، غير صحيح.","link":"https://binbaz.org.sa/fatwas/2450/حكم-نظر-كل-من-الزوجين-الى-فرج-الاخر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_977.mp3","categories":["الحقوق الزوجية","الآداب والأخلاق المحمودة"]},{"id":6608,"question":"قرأت في صحيح مسلم شرح النووي: أن الرجل لا يجوز له النظر إلى فرج امرأته مع التبرج في ذلك على حسب مذهب النووي، فقرأت في آداب الزفاف: أنه يجوز النظر لكل من الزوجين، أفتونا أثابكم الله؟","title":"حكم نظر كل من الزوجين إلى فرج الآخر","answer":"الجواب: النظر إلى زوجته جائز، مطلقًا، فرجها، وغير فرجها، وهو كذلك يجوز النظر إليها، قد أباح الله له جماعها، والجماع أشد من النظر، فالذي يقول: ما يجوز النظر هذا غلط، سواء النووي، أو غير النووي، والذي يقول: إنه جائز هو المصيب.  المقصود: أن نظر الرجل إلى زوجته، ونظرها إليه، إلى بدنه كله، عورته، وغير عورته، كل هذا جائز، والحمد لله، الله أباح لكل منهما النظر إلى الآخر، كان النبي يغتسل مع زوجاته -عليه الصلاة والسلام- والمغتسل تكشف العورة، ويجامعها، وترى عورته، ويرى عورتها، هذا القول: بأنه لا يجوز قول غلط، لا وجه له. السؤال: يغتسل مكشوف العورة؟ الجواب: مكشوف العورة.. مكشوف العورة نعم، ما عليه لا سراويل، ولا إزار يكفي.. والمغتسل يكشف عورته، إذا كان ما عنده أحد في حمام خاص؛ يكشف عورته، الحمد لله اغتسل النبي عريانًا، ًواغتسل موسى عريانًا، واغتسل أيوب عرياناً. السؤال: في الحديث تقول عائشة: (أنه لم ير مني، ولم أر منه)؟ الجواب: لا ما هو صحيح، هذا من كلام العامة، ما له أصل، هذا قول عائشة \"لم ير مني، ولم أر منه\" هذا غلط، ما له أصل، غير صحيح.","link":"https://binbaz.org.sa/fatwas/2450/حكم-نظر-كل-من-الزوجين-الى-فرج-الاخر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_977.mp3","categories":["الحقوق الزوجية","الآداب والأخلاق المحمودة"]},{"id":6680,"question":"في رجل إذا نام يحتلم بنفسه أنه يطير في الهواء، فإذا أصبح يصبح متشائمًا، وخائفًا أنه يصيبه مصيبة من مصائب الدنيا؟","title":"ماذا يفعل من يرى رؤى مكروهة؟","answer":"الجواب: لا، لا، إذا رأى مثل هذا، وأصبح، النبي ﷺ علمنا ما نقوله، يقول النبي ﷺ: الرؤيا الصالحة من الله، والحلم من الشيطان، فإذا رأى أحدكم ما يكره؛ فلينفث عن يساره ثلاث مرات، وليتعوذ بالله من الشيطان، من شر ما رأى ثلاث مرات، ثم ينقلب على جنبه الآخر؛ فإنها لا تضره، ولا يخبر بها أحدًا هذا دواء المرائي المكروهة. إذا رأى مرائي مكروهة تسيئ إليه، وتحزنه، إذا استيقظ يتفل عن يساره ثلاث مرات، ويقول: أعوذ بالله من الشيطان، ومن شر ما رأى، ثلاث مرات، ثم ينتقل على جنبه الآخر؛ فإنها لا تضره، ولا يخبر بها أحدًا، هذه السنة، أما إن رأى ما يحب؛ فإنه يحمد الله، ويخبر به من شاء.","link":"https://binbaz.org.sa/fatwas/2564/ماذا-يفعل-من-يرى-روى-مكروهة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1059.mp3","categories":["إخراج الزكاة وأهلها","الآداب والأخلاق المحمودة"]},{"id":6722,"question":"رأيت فيما يرى النائم، قد شفت والدي المتوفي في الرؤيا أنه قادم علينا من جهة الشمال، ومتوجه إلى الجنوب، ونحن عند ركن المسجد -مسجد القرية- وأن أطرافه كلها محترقة .. من الثوب، ووجهه محترق، وأن عليه أثر الحريق بلد في جسمه، وتوجه إلى الجنوب، ولم يدخل معنا المسجد، نرجو الإجابة؟","title":"ما يفعله الإنسان إذا رأى رؤيا مكروهة","answer":"الجواب:  مثل هذه الرؤيا لا تخبر بها أيها السائل، يقول النبي ﷺ: الرؤيا الصالحة من الله، والحلم من الشيطان، فإذا رأى أحدكم ما يكره؛ فلينفث عن يساره ثلاث مرات، وليتعوذ بالله من الشيطان، ومن شر ما رأى ثلاث مرات، ثم لينقلب على جنبه الآخر، ولا يخبر بها أحدًا، فإنها لا تضره هذا هو الشرع.  إذا رأيت أن أباك محترق، أو أنك محترق، أو أمك، أو بنتك، أو ما أشبه ذلك، فلا ينبغي لك أن تخبر الناس بذلك، بل ينبغي لك إذا استيقظت أن تنفث عن يسارك، تتفل عن يسارك ثلاث مرات، وتقول: أعوذ بالله من الشيطان، ومن شر ما رأيت، ثلاث مرات، ثم تنقلب على جنبك الآخر، فإنها لا تضرك -إن شاء الله- ولا تخبر بها أحدًا، هكذا قال المصطفى عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/2595/ما-يفعله-الانسان-اذا-راى-رويا-مكروهة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1091.mp3","categories":["إخراج الزكاة وأهلها","الآداب والأخلاق المحمودة"]},{"id":6735,"question":"لي ولد ربيته على تلاوة القرآن الكريم حتى من العمر ثماني عشرة سنة، ولما كبر لم أقدر على أدبه، وهرب مني، ولا عاد أمتلك لي عليه شيء، فما الحل؟","title":"الواجب فعله على الوالدين تجاه أولادهم","answer":"الجواب: الذي عليك فعلته، إذا فعلت هذا في الصغر، وجاهدته، وربيته؛ فأنت قد فعلت خيرًا كثيرًا، وإذا هرب منك بعد الكبر، وضيع، قلت له فالإثم عليه، ما هو عليك أنت، الإثم عليه، أما ما دام في الصغر؛ فعليك أن تقوم بالواجب، وتعلمه.  ومن أهم ذلك أن تعلمه فاتحة الكتاب؛ الحمد، فإنها أعظم سورة، وأفضل سورة في كتاب الله القرآن، الفاتحة أم القرآن، هي أعظم سورة، وأفضل سورة، فتعليم الطفل لها، والطفلة حتى يعتاد قراءتها فيها خير عظيم، وفيها فوائد جمة، وهي أم القرآن، وأعظم سورة في القرآن.  وهكذا تعليمهن القصار من القرآن، والمعوذتين، وقل هو الله أحد، وتبت، وقل يا أيها الكافرون، والسور القصيرة، إذا تعلمها الأولاد فيها الخير الكثير حتى يعشن عليها، ويتمرن على قراءتها، ثم يستفيد من المعاني، يوجههم والدهم، أو أمهم -إن كان عندها علم- من المعاني العظيمة في هذه السور القصيرة، فيحصل لهم بذلك علم عظيم، وفائدة كبيرة تنفعهم عند الكبر، كما يعين أولادهم بهذا على ما توجه المدرسة، وتقول له المدرسة هذا تعاون بين آباء الأطفال، وأمهات الأطفال، وبين المدرسة. المقصود: أن الوالد، والأم عليهم أن يعلماه، ما دام الولد بحضانتهما، وتحت قدرتهما، وتصرفهما، فإذا كبر، وخرج منها، واستقل بنفسه، فالإثم عليه، لا عليهما.","link":"https://binbaz.org.sa/fatwas/2612/الواجب-فعله-على-الوالدين-تجاه-اولادهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1108.mp3","categories":["تربية الأولاد","الآداب والأخلاق المحمودة"]},{"id":6739,"question":"زوجتي لا تأمر أولادها بالصلاة، ولا تزجرهم عن فعل المنكرات، رغم محاولتي لها بالعدول عن هذا الموقف، علمًا أنني ضربتها مرات عديدة، وهجرتها بعض الأحيان أكثر من أربعة أشهر متواصلة، ولكن دون جدوى، فماذا أفعل والحالة كذلك؟","title":"الحث على توجيه الأولاد والزوجة إلى الخير ونصيحتهم وأمرهم بذلك","answer":"الجواب: عليك أن تجتهد أنت بنفسك، وتأمرهم، وتنهاهم، وتنصح الأم، وتستمر في نصيحتها، وتوجيهها إلى الخير، وإذا نصحت أنت، واتقيت الله، واجتهدت، وبذلت الوسع؛ سوف تعان -إن شاء الله- توفق، والله يقول: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا [الطلاق:2]، وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4].  فعليك أن تتقي الله، وأنت المسؤول، وهيبتك أعظم، فعليك أن تتقي الله في ذلك، وأن تجتهد في أمرهم بالصلاة، وتوجيههم إلى الخير ذكورًا وإناثًا، وأن تنصح أمهم دائمًا، وأن تطلب منها أن تعينك على الخير، وألا تكون عونًا على الشر، ومع الجهاد المستمر، والنصيحة المستمرة والقيام بالواجب المستمر، يهديهم الله -إن شاء الله- وتكفى شر أمهم.","link":"https://binbaz.org.sa/fatwas/2608/الحث-على-توجيه-الاولاد-والزوجة-الى-الخير-ونصيحتهم-وامرهم-بذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1104.mp3","categories":["تربية الأولاد","الآداب والأخلاق المحمودة"]},{"id":6758,"question":"هناك أمر شائع بين الناس عن الخضيري، والقبيلي، وأن القبيلي لا يتزوج من الخضيرية، والخضيري لا يتزوج من القبيلية، فهل هناك حديث يمحو هذا الذي أصبح الناس يشكون منه، أو مشغولون به وعلى بناتهم؟","title":"حكم التزاوج بين الخضيري والقبيلي","answer":"الجواب: هذا شيء لا أصل له، وليس من شروط النكاح، ولكن له أصل من جهة أن الناس أنواع، وأبيات، وقبائل، وأصناف، فكل قبيلة ترغب في أن يكون من قبيلتها إذا تيسر ذلك، وربما صاحوا بمن يزوج بنته من غير قبيلتهم، وربما أنكروا عليه، وربما تساهلوا في ذلك، وإلا فالأمر في هذا سواء، يقول -جل وعلا-: يَا أَيُّهَا النَّاسُ إِنَّا خَلَقْنَاكُمْ مِنْ ذَكَرٍ وَأُنْثَى [الحجرات:13] يعني من آدم وحواء وَجَعَلْنَاكُمْ شُعُوبًا وَقَبَائِلَ لِتَعَارَفُوا [الحجرات:13] ما قال لتفاخروا، قال لتعارفوا إِنَّ أَكْرَمَكُمْ عِنْدَ اللَّهِ أَتْقَاكُمْ [الحجرات:13] فإذا تيسرت التقوى فهذا هو الأساس العظيم، فاظفر بذات الدين تربت يداك. المقصود: أن الناس في هذا سواسية، فالعربي، والمولى، والأعجمي لا بأس بتزاوجهم فيما بينهم، ويزوج بعضهم بعضًا، فينكح العربي الأعجمية، والمولى العتيقة، ولا بأس بذلك، ولا حرج في ذلك إِنَّ أَكْرَمَكُمْ عِنْدَ اللَّهِ أَتْقَاكُمْ [الحجرات:13]، وقد زوج النبي ﷺ أسامة بن زيد، وهو مولى عتيق، وأبوه عتيق وهو زيد، زوجهما جميعًا من قريش، وزوج زيدًا زينب، وهي أسدية، وأمها من بني هاشم، وزوج أسامة فاطمة بنت قيس، وهي قرشية، وهذا يدل على أن الأمر في هذا واسع، وكذلك زوج عبدالرحمن بن عوف بلالًا -وهو حبشي، وهي زهرية، قرشية.  المقصود: أن هذه الأمور فيها سعة بحمد الله، وليس فيها ما يوجب الامتناع، ولكن الجهل، والتكبر من بعض الناس، والأنفة القبلية من بعض الناس، وخوف بعض الناس من بعض الناس قد يحمل على أشياء من هذا النمط. فإذا تمكن العلم من الناس، وتمكن الدين من الناس؛ زالت هذه الأمور، واستقر الأمر الشرعي، ولكن بسبب الجهل تقع أمور كثيرة من هذا، وأكثر، وأن خضيري، وقبيلي ما له أصل، وأصله الأصل القديم أن يقال: قبلي، ومولى، أو أعجمي، أما خضيري هذه شيء جديد، حدث من جديد، لا نعلم متى حدث، وإنما المعروف قبلي، هذا من قبائل العرب، عجمي من الأعجام، مولى يعني عتيق، فهؤلاء الناس من حزب هذه الأصول المعروفة، ولا بأس أن يتزوج من هؤلاء، لا بأس أن ينكح العربي الأعجمية، والأعجمي العربية، والعربي المولاة، والمولاة العربي، كل هذا لا بأس به في الإسلام، ولا حرج فيه إِنَّ أَكْرَمَكُمْ عِنْدَ اللَّهِ أَتْقَاكُمْ [الحجرات:13].","link":"https://binbaz.org.sa/fatwas/2634/حكم-التزاوج-بين-الخضيري-والقبيلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1130.mp3","categories":["الآداب والأخلاق المحمودة","شروط وأركان الزواج"]},{"id":6801,"question":"رجل قذف شخصًا آخر بالفاحشة، وأصر المقذوف على أنه يشكوه إلى القاضي، ولكن هناك من دعوا المقذوف ألا يشكوه، ما الحكم في هذا؟","title":"حكم من قذف بالفاحشة وعفا عمن قذفه ولم يخاصمه","answer":"الجواب: القذف من حق الإنسان، ليس من حق الله في هذا، من حقوق الإنسان، كما لو ضربه أو قتل ولده، وما أشبه ذلك، إن شكاه، وطلب حقه؛ فلا بأس، وإن عفا؛ فله أجر العفو أَنْ تَعْفُوا أَقْرَبُ لِلتَّقْوَى [البقرة:237] هذا هو الصواب في حد القذف. فإذا قذف بفاحشة، أو شتمه، أو ما أشبه ذلك، فإن طلب الحق؛ وجب أخذ الحق له إذا ثبت متعدي عليه، وإن عفا؛ فلا حرج في ذلك، بخلاف إذا كان الحق لله، فإنه إذا بلغ السلطان؛ فلا يقال صاحبه، بل يقام عليه الحد، أما حق المخلوق مال له سرقه منه، فعفا عن المال، أو ظلمه، أو قذفه، أو سبه وعفا، لا بأس.","link":"https://binbaz.org.sa/fatwas/2703/حكم-من-قذف-بالفاحشة-وعفا-عمن-قذفه-ولم-يخاصمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1202.mp3","categories":["الجنايات والحدود","الآداب والأخلاق المحمودة"]},{"id":6819,"question":"رجل قذف شخصًا آخر بالفاحشة، وأصر المقذوف على أنه يشكوه إلى القاضي، ولكن هناك من دعوا المقذوف ألا يشكوه، ما الحكم في هذا؟","title":"حكم من قذف بالفاحشة وعفا عمن قذفه ولم يخاصمه","answer":"الجواب: القذف من حق الإنسان، ليس من حق الله في هذا، من حقوق الإنسان، كما لو ضربه أو قتل ولده، وما أشبه ذلك، إن شكاه، وطلب حقه؛ فلا بأس، وإن عفا؛ فله أجر العفو أَنْ تَعْفُوا أَقْرَبُ لِلتَّقْوَى [البقرة:237] هذا هو الصواب في حد القذف. فإذا قذف بفاحشة، أو شتمه، أو ما أشبه ذلك، فإن طلب الحق؛ وجب أخذ الحق له إذا ثبت متعدي عليه، وإن عفا؛ فلا حرج في ذلك، بخلاف إذا كان الحق لله، فإنه إذا بلغ السلطان؛ فلا يقال صاحبه، بل يقام عليه الحد، أما حق المخلوق مال له سرقه منه، فعفا عن المال، أو ظلمه، أو قذفه، أو سبه وعفا، لا بأس.","link":"https://binbaz.org.sa/fatwas/2703/حكم-من-قذف-بالفاحشة-وعفا-عمن-قذفه-ولم-يخاصمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1202.mp3","categories":["الجنايات والحدود","الآداب والأخلاق المحمودة"]},{"id":6909,"question":"شاب هداه الله والحمد لله، ولكنه يعاني من مضايقة والديه له، بأن يمنعانه من الخروج مع الشباب الصالح، ويعاني في المنزل من الملاهي، والغناء، وهو يتضايق من ذلك كثيرًا، فبماذا تصلونه جزاكم الله خيرًا؟","title":"طاعة الوالدين تكون في المعروف","answer":"الجواب:  إنما الطاعة في المعروف إذا كان والداه منحرفين، ويأمرانه بالانحراف؛ فليس له طاعتهما، إنما الطاعة في المعروف لا طاعة لمخلوق في معصية الخالق فلا بأس أن يصحب الأخيار، ويخرج في بيت وحده مع أهله؛ لسوء الحال في بيت والديه من المعاصي، ومع ذلك يصلهما، ويحسن إليهما بالكلام الطيب، والفعل الطيب، ويزورهما، ويقدم المعونة لهما، والصلة لهما ما لم يطرداه، ويأبيا قبول صلته.","link":"https://binbaz.org.sa/fatwas/2846/طاعة-الوالدين-تكون-في-المعروف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1294.mp3","categories":["إخراج الزكاة وأهلها","الآداب والأخلاق المحمودة"]},{"id":6916,"question":"هل يدخل في صلة الأرحام أقارب زوجتي، ووالديها، وإخوتها، وأخواتها، وأزواج أخواتها؟","title":"أقارب الزوجة ليسوا من الأرحام","answer":"الجواب: أقارب الزوجة ليسوا بأرحام، ولكنهم أصهار، وإنما أرحام لها، هم أرحام لزوجتك، وأما أنت فليسوا أرحامًا لك، أبوها، وإخوانها، وأخواتها، وأخوالها، وخالاتها، وأعمامها، وعماتها، وسائر قراباتها هم أقارب لها، وأرحام لها هي، عليها أن تصلهم حسب طاقتها، وأما أنت فليسوا أرحامًا لك ولكنهم أصهار لك، لكن إذا أحسنت إليهم بالكلام الطيب، والفعل الطيب؛ هذا طيب، ولكن ليسوا من الأرحام الذين قطيعتهم قطيعة رحم، وإنما الإحسان إليهم من باب مكارم الأخلاق.","link":"https://binbaz.org.sa/fatwas/2840/اقارب-الزوجة-ليسوا-من-الارحام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1288.mp3","categories":["إخراج الزكاة وأهلها","الآداب والأخلاق المحمودة"]},{"id":6922,"question":"أنا والحمد لله كثير الاستغفار، والدعاء لوالدي في الصلاة، وغيرها، ولكن بعض الأحيان أمزح معهما بكلام لا سخط فيه، وأحاول بهذا إسعادهما، ولأكمل السعادة، وكسب رضاهما عني، وهما -والحمد لله- راضيان عني، فهل المزاح معهما يجوز، أم لا يجوز؟ وما حكم إذا ناديت أبي يا فلان، دون أن أقول: أبي، وأمي كذلك؟","title":"حكم المزاح مع الوالدين","answer":"الجواب: المزاح بالحق إذا كان قليلُا ما يضر، إذا كان مزاحًا، يعني يسرهما، ويوسع خاطرهما بحق ليس بكذب، ولا إيذاء؛ لا بأس به، لكن الممازح لا يقول إلا حقًا، ولا يكثر حتى لا يفضي إلى شر.  والسنة أن يدعوه بأحب أسمائه إليه، كأبي فلان، أو يا والدي، يا أبت، أو يا أبا فلان إذا كان يحب ذلك، يا أبا عبدالله، يا أبا عبدالرحمن، يا أبا إبراهيم.","link":"https://binbaz.org.sa/fatwas/2851/حكم-المزاح-مع-الوالدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1299.mp3","categories":["إخراج الزكاة وأهلها","الآداب والأخلاق المحمودة"]},{"id":6953,"question":"هل يحق للرجل أن يتزوج بأخرى بدون أي أسباب تدعو إلى ذلك؟","title":"حكم الزواج بامرأة ثانية بدون داعٍ","answer":"الجواب: نعم قال الله -جل وعلا-: فَانْكِحُوا مَا طَابَ لَكُمْ [النساء:3] طاب يعني ما شئتم، وما استحسنتم، فله أن يتزوج، ولو بأكثر؛ لأن هذا ينفعه بكل حال، لأن كبح الشهوة، والقيام بما يعين على كبح الغريزة الجنسية، وكثرة الأولاد، هذا مطلوب، وقد يتزوج لطلب الأولاد، وقد يتزوج لمزيد البعد عن أسباب الفتنة.","link":"https://binbaz.org.sa/fatwas/2883/حكم-الزواج-بامراة-ثانية-بدون-داع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1331.mp3","categories":["الآداب والأخلاق المحمودة","تعدد الزوجات"]},{"id":6965,"question":"أفيدكم بأن فيه بعض من قبائل البادية، وغيرهم من الناس يتفقون على جمع بعض من المال خاصة للحوادث، ويكون هذا المبلغ لدى إنسان، وعندما يكون على أحد أفراد هذا الفخذ التابع للقبيلة، أو دية؛ يتقدم إلى الذي لديه النقود، ويعطيه المبلغ، وبعدما يسدد الدية المطلوبة؛ يقوم بتسديد .. حتى يرد المبلغ الأول إلى أمين الجمعية الخاصة بالفخذ، علمًا أن الأغلبية من هذا الفخذ بحاجة ماسة عندما تقع هذه الحوادث، ويكون في يوم محرج، وبعضهم غير محتاج إليها، لذا نأمل أن توضحوا لنا هذه الطريقة، هل هي جائزة، أم تتنافى مع الدين؟","title":"حكم جمع مال وتخصيصه للحوادث بين أفراد القبيلة","answer":"الجواب:\n\nلا حرج في ذلك، إذا اجتمعت القبيلة، أو بعض القبيلة على مساعدة معينة يجمعونها عند شخص منهم للحوادث، طابت بها نفوسهم؛ فلا بأس بذلك؛ إذا طابت بها نفوسهم، من أجل حوادث تحصل عليهم من قتل، أو غير قتل، من جراحات، أو فقر، أو من كارثة من سيل، أو حريق، أو ما أشبه ذلك، فلا حرج.\n\nهذا من باب التعاون على الخير، ومن باب الإحسان، وجبر المصاب، وسد حاجة الضعيف؛ فلا بأس بهذا -إن طابت بها نفوسهم- تجمع، وليس عليها زكاة، ويعطاها المحتاج على قدر ما أصابه، وليس لهم الرجوع فيها إذا بذلوها، ليس لهم الرجوع فيها؛ لأنهم أخرجوها لله، فتصرف في الجهات التي عينوها، وكلما قل ما بيد الأمين؛ طلب منهم، وأخبرهم أن يعطوه شيئًا آخر؛ ليعدوا ذلك للكوارث، والحوادث التي تصيبهم. \n\nالسؤال: وليس فيها زكاة؟\n\nالجواب: وليس فيها زكاة.\n\nالسؤال: وتخرج من مال الزكاة؟\n\nالجواب: لا ما هو -على كل حال- ينبغي أن تكون من غير الزكاة؛ لأن الزكاة لها مصارف مخصوصة، فإذا جعلها من الزكاة؛ لابد تعين كونها لا يعطاها إلا من هو من أهل الزكاة.\n\nالسؤال: بعضهم يا شيخ يجمع أكثر من ثلاثمائة، أربعمائة ..\n\nالجواب: ولو مليون، لكن ليس من الزكاة، الزكاة تخرج في الحال لأهلها.","link":"https://binbaz.org.sa/fatwas/2929/حكم-جمع-مال-وتخصيصه-للحوادث-بين-افراد-القبيلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1377.mp3","categories":["إخراج الزكاة وأهلها","الآداب والأخلاق المحمودة"]},{"id":6980,"question":"هل الدين يمنع إجابة الدعاء، وإن كان في نفس صاحبه أن يقضيه؟ وإذا مات صاحب الدين وهو يريد أن يقضيه هل يقضيه الله عنه؟ وهل يحاسب عليه يوم القيامة إذا قضاه الله عنه؟ وهل تعلق روح المدين حتى يقضي ما عليه من الدين؟","title":"الدين لا يمنع الدعاء لمن كانت نيته الوفاء","answer":"الجواب: يقول النبي ﷺ: من أخذ أموال الناس يريد أداءها أدى الله عنه فإذا أخذها وهو يريد الأداء، واجتهد، ولكن لم يتيسر له ذلك؛ قضاه الله عنه  وما ضره بقاؤه عليه، وفي الحديث: نفس المؤمن معلقة بدينه حتى يقضى عنه.  فإذا مات وقد نوى قضاءها، واجتهد في قضائها؛ فالله يقضيها عنه، ولا تعلق نفسه، لكن عليه بالاجتهاد والصدق، بالنيات الصادقة يكون معها العمل الصادق، فإذا كان نوى أن يقضيه؛ فعليه بالجد، والنشاط، والأخذ بالأسباب؛ حتى يقضي هذا الدين الذي  تحمله، أما أن يأخذ الدين ويقول: أنا أريد القضاء، وهو يلعب، ولا يبالي، ما هو صادق في نيته. والدين لا يمنع الدعاء، ولكن إذا كان بالنية -نية الوفاء- فهو على خير، أما إذا كان ظالمًا يريد أكل أموال الناس؛ فهذا خطر، قد يمنع دعاؤه، وقد تمنع إجابة أعماله، وقد يصيبه أضرار عظيمة بسبب أعماله القبيحة، قد يعاقب بعقوبات عاجلة، أو آجلة، لكن متى نوى قضاء الدين، واجتهد في الأسباب التي يقضى بها الدين؛ فهو على خير.","link":"https://binbaz.org.sa/fatwas/2894/الدين-لا-يمنع-الدعاء-لمن-كانت-نيته-الوفاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1342.mp3","categories":["السلف والقرض","الآداب والأخلاق المحمودة"]},{"id":6984,"question":"أفيدكم بأن فيه بعض من قبائل البادية، وغيرهم من الناس يتفقون على جمع بعض من المال خاصة للحوادث، ويكون هذا المبلغ لدى إنسان، وعندما يكون على أحد أفراد هذا الفخذ التابع للقبيلة، أو دية؛ يتقدم إلى الذي لديه النقود، ويعطيه المبلغ، وبعدما يسدد الدية المطلوبة؛ يقوم بتسديد .. حتى يرد المبلغ الأول إلى أمين الجمعية الخاصة بالفخذ، علمًا أن الأغلبية من هذا الفخذ بحاجة ماسة عندما تقع هذه الحوادث، ويكون في يوم محرج، وبعضهم غير محتاج إليها، لذا نأمل أن توضحوا لنا هذه الطريقة، هل هي جائزة، أم تتنافى مع الدين؟","title":"حكم جمع مال وتخصيصه للحوادث بين أفراد القبيلة","answer":"الجواب:\n\nلا حرج في ذلك، إذا اجتمعت القبيلة، أو بعض القبيلة على مساعدة معينة يجمعونها عند شخص منهم للحوادث، طابت بها نفوسهم؛ فلا بأس بذلك؛ إذا طابت بها نفوسهم، من أجل حوادث تحصل عليهم من قتل، أو غير قتل، من جراحات، أو فقر، أو من كارثة من سيل، أو حريق، أو ما أشبه ذلك، فلا حرج.\n\nهذا من باب التعاون على الخير، ومن باب الإحسان، وجبر المصاب، وسد حاجة الضعيف؛ فلا بأس بهذا -إن طابت بها نفوسهم- تجمع، وليس عليها زكاة، ويعطاها المحتاج على قدر ما أصابه، وليس لهم الرجوع فيها إذا بذلوها، ليس لهم الرجوع فيها؛ لأنهم أخرجوها لله، فتصرف في الجهات التي عينوها، وكلما قل ما بيد الأمين؛ طلب منهم، وأخبرهم أن يعطوه شيئًا آخر؛ ليعدوا ذلك للكوارث، والحوادث التي تصيبهم. \n\nالسؤال: وليس فيها زكاة؟\n\nالجواب: وليس فيها زكاة.\n\nالسؤال: وتخرج من مال الزكاة؟\n\nالجواب: لا ما هو -على كل حال- ينبغي أن تكون من غير الزكاة؛ لأن الزكاة لها مصارف مخصوصة، فإذا جعلها من الزكاة؛ لابد تعين كونها لا يعطاها إلا من هو من أهل الزكاة.\n\nالسؤال: بعضهم يا شيخ يجمع أكثر من ثلاثمائة، أربعمائة ..\n\nالجواب: ولو مليون، لكن ليس من الزكاة، الزكاة تخرج في الحال لأهلها.","link":"https://binbaz.org.sa/fatwas/2929/حكم-جمع-مال-وتخصيصه-للحوادث-بين-افراد-القبيلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1377.mp3","categories":["إخراج الزكاة وأهلها","الآداب والأخلاق المحمودة"]},{"id":7119,"question":"شابة تريد الصيام الاثنين والخميس، لكن والدتها تمنعها عن الصيام بحجة أنها في السن صغيرة، فماذا تفعل؟ هل تطيع والدتها مع قدرتها على الصوم؟","title":"حكم تقديم صيام التطوع على طاعة الوالدة","answer":"الجواب:\n\nنعم نعم، صوم النافلة مستحب، وطاعة الوالدة واجبة، والوالدة قصدها الخير، وقصدها أن ترحم حالها، ولا تشق على نفسها، لكن ينبغي لها أن تعالج الموضوع بالحكمة، والكلام الطيب، والأسلوب الحسن؛ حتى تسمح أمها بالصيام إذا كان الصوم لا يشق عليها ولا يؤثر عليها.\n\nفالمقصود: أن هذا من الوالدة من باب العطف والرحمة، فلا ينبغي للبنت أن تعصيها، ويكون بينها وبينها الشر، ولكن تعالج الموضوع بالكلام الطيب، والأسلوب الحسن مع الوالدة؛ حتى ترضى -إن شاء الله- وحتى تمكن من صوم بلا مشقة.","link":"https://binbaz.org.sa/fatwas/3152/حكم-تقديم-صيام-التطوع-على-طاعة-الوالدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1510.mp3","categories":["صيام التطوع","حكم الزواج وأهميته","الآداب والأخلاق المحمودة"]},{"id":7174,"question":"هل يجوز إذا دخل رجل إلى المجلس أن نقف للسلام عليه؟","title":"حكم وقوف الجالس للسلام على القادم","answer":"الجواب:\n\nأما إذا كان للمقابلة ومصافحته فلا بأس، أما ما يفعله الناس وقوف فقط فهذا ما ينبغي، أقل أحواله الكراهة، كان النبي يكره ذلك -عليه الصلاة والسلام- ولا يحب أن يقوموا له -عليه الصلاة والسلام- ولما قاموا على رأسه وهو يصلي جالسًا؛ أمرهم بالجلوس -عليه الصلاة والسلام- قال: كدتم أن تعظموني كما تعظم فارس والروم رؤساءها، أما إذا قام إليه يصافحه، قام للضيف يصافحه، ويجلسه في المحل المناسب؛ فهذا لا بأس به.\n\nالسؤال: طيب يعني منزلة في ناس تختلف، يعني في حكام رؤساء قضاة علماء يعني؟ \n\nالجواب: ولو، هو الملك لا يقوم، حتى الملك لا يقوم وهو بعيد .. يصافحه، يتقدم له ويصافحه، أما يقوم وهو في مكانه، لا.","link":"https://binbaz.org.sa/fatwas/3213/حكم-وقوف-الجالس-للسلام-على-القادم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1561.mp3","categories":["إخراج الزكاة وأهلها","الآداب والأخلاق المحمودة"]},{"id":7199,"question":"والدتي طلبت مني تسمية ابنتي باسم ترغبه هي، وهو اسم والدتها، وأنا أرغب أن أسميها باسم إحدى أمهات المؤمنين، أو الصحابيات، أفتونا مأجورين، هل أنفذ رغبة والدتي؟","title":"طاعة الأم في تسميتها المولود","answer":"الجواب:\n\nنعم نعم، رغبة والدتك أولى من رغبتك أنت، إذا كان الاسم الذي قالت والدتك ما فيه محظور، إذا كان اسمًا سائغًا، لا محذور فيه، هي قالت: تريدها مريم، وأنت تقول: أريدها فاطمة، أو عائشة؛ قدم الأم، كلها أسماء جائزة، وفي تقديم ما قالت أمك خير كثير، ورضاء لها، والأمر في هذا واسع والحمد لله، فلا حاجة إلى أن تعصيها.","link":"https://binbaz.org.sa/fatwas/3277/طاعة-الام-في-تسميتها-المولود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1602.mp3","categories":["إخراج الزكاة وأهلها","الآداب والأخلاق المحمودة"]},{"id":7210,"question":"أنا رجل هداني الله إلى الحق والحمد لله، ولكن أجد صعوبة في البيت، وأن أهلي يأمرونني على ترك إخواني في الله، ويقولون: هؤلاء مثل الفئة الضالة، ويمنعوني من فعل الخير، ومنعي من الصلاة التي يكون بعدها أحيانًا جلسة للقراءة في كتاب، أو نحوه، وأنهم لا يستمعون لي؛ لأني حريص، ويعاملونني معاملة الطفل، وعدم الاستماع إلى الأشرطة الدينية، ويقولون: هذه ضالة إلى آخره؟","title":"حكم منع الآباء أبناءهم من مصاحبة الأخيار","answer":"الجواب:\n\nعلى كل حال، عليك يا ولدي تعمل ما تستطع من إرضاء والديك، ومراعاة خاطرهما، وأهلك بالكلام الطيب، والأسلوب الحسن، لكن ليس عليك أن تطيعهما فيما يضرك، أو في معصية ربك مثل ما تقدم.\n\nتخرج لطلب العلم، وتخرج للصلاة في الجماعة، ولكن بالأسلوب الحسن، والكلام الطيب، وتسمع الأشرطة الطيبة، وتحثهم -تحث والديك وإخوتك وقراباتك- تحثهم على سماع الشيء الذي ينفعهم بالكلام الطيب، والأسلوب الحسن، لا بالعنف، والشدة، والتعاظم عليهم، ولكن بالكلام الطيب، والأسلوب الحسن؛ حتى تخرج من غضب والديك، وحتى يحصل لك أداء ما أوجب الله عليك.","link":"https://binbaz.org.sa/fatwas/3279/حكم-منع-الاباء-ابناءهم-من-مصاحبة-الاخيار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1604.mp3","categories":["إخراج الزكاة وأهلها","الآداب والأخلاق المحمودة"]},{"id":7221,"question":"أريد أن أخرج عن أهلي لأسكن أنا وأولادي ببيت خاص بنا، ووالدي لا يرضى بذلك، هل لو خرجت وهم لا يرضون بذلك يكون هذا عقوقًا؟","title":"حكم مفارقة الوالدين في سكن مستقل بدون رضاهم","answer":"الجواب:\n\nينبغي لك أنك تلاحظ رضاهم، وتحرص على رضاهم حتى -إن شاء الله- تخرج برضاهم، وإذا كان جلوسك معهم فيه معصية لله؛ لأنك تؤذى من إخوانك، أو من غير إخوانك؛ فلا بأس أن تخرج.\n\nلكن خروجك بالرضا، ومسامحة الوالدين، والحرص على إرضائهما؛ يكون أولى لك، وإذا كان ما هناك داع للخروج، ووالداك في حاجة إليك؛ لا تخرج.","link":"https://binbaz.org.sa/fatwas/3290/حكم-مفارقة-الوالدين-في-سكن-مستقل-بدون-رضاهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1615.mp3","categories":["إخراج الزكاة وأهلها","الآداب والأخلاق المحمودة"]},{"id":7236,"question":"كلفني أحد أئمة المساجد أن أسألكم على الكتابات المعلقة في المساجد، آيات وأحاديث، هل يجوز هذا؟","title":"حكم تعليق الآيات والأحاديث في المساجد","answer":"الجواب:\n\nكثير من أهل العلم يكره ذلك في المساجد؛ لأنها قد تشوش على المصلين، ولا سيما في قبلة المصلين، فلا ينبغي تعليق شيء من الكتابات في قبلة المصلين؛ لأن هذه قد تشوش على الناس، وقد تشغل المصلي.","link":"https://binbaz.org.sa/fatwas/3297/حكم-تعليق-الايات-والاحاديث-في-المساجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1622.mp3","categories":["المساجد ومواضع السجود","الآداب والأخلاق المحمودة"]},{"id":7258,"question":"هل الأخوات من الرضاعة رحم يجب علي وصلهن، أم لا؟","title":"الأخوات من الرضاعة لسن أرحاماً","answer":"الجواب:\n\nليسوا برحم، الأخوات من الرضاعة ليسوا من الأرحام، الأرحام هم القرابات، هكذا أبو الزوجة، وأخو الزوجة، وعم الزوجة، وأقاربها يقال لهم: أصهار، وليسوا رحمًا.\n\nالرحم هم القرابات، لكن أولئك ينبغي الإحسان إليهم، وصلتهم من باب المجاملة، ومن باب مقابلة المعروف بالمعروف، لا لأنهم أقارب، لكن أصهاره، وأقاربه من الرضاعة، إذا أحسنت إليهم، ووصلتهم؛ فهذا من مكارم الأخلاق.","link":"https://binbaz.org.sa/fatwas/3314/الاخوات-من-الرضاعة-لسن-ارحاما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1638.mp3","categories":["الرضاع","الآداب والأخلاق المحمودة"]},{"id":7263,"question":"أنا رجل كثير المزاح، وتصدر مني بعض الأحيان كلمات فيها جرح لبعض الإخوان دون قصد مني، أو بقصد، فما تنصحونني؟","title":"الاعتدال في المزاح","answer":"الجواب:\n\nننصحك أولًا بقلة المزاح، عليك بالتقليل من المزاح، والنبي ﷺ كان يمزح لكنه قليل -عليه الصلاة والسلام- مزحه قليل، وكان يمزح، ولكن لا يقول إلا حقًا -عليه الصلاة والسلام- فعليك أن تحذر الإكثار من المزاح، فإنه ربما يفضي إلى شر، وإذا مزحت فاحذر أن تقول إلا حقًا، إياك أن تجرح أخاك، أو تؤذي أخاك بكلام يضره، أو تقول فيه خلاف الصواب.\n\nالمقصود: أولًا: قلة المزاح، وهو الذي ينبغي.\n\nثانيًا: إذا مزحت لا تقل إلا حقًا، واحذر أن تقول الباطل.","link":"https://binbaz.org.sa/fatwas/3340/الاعتدال-في-المزاح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1661.mp3","categories":["إخراج الزكاة وأهلها","الآداب والأخلاق المحمودة"]},{"id":7273,"question":"أنا رجل كثير المزاح، وتصدر مني بعض الأحيان كلمات فيها جرح لبعض الإخوان دون قصد مني، أو بقصد، فما تنصحونني؟","title":"الاعتدال في المزاح","answer":"الجواب:\n\nننصحك أولًا بقلة المزاح، عليك بالتقليل من المزاح، والنبي ﷺ كان يمزح لكنه قليل -عليه الصلاة والسلام- مزحه قليل، وكان يمزح، ولكن لا يقول إلا حقًا -عليه الصلاة والسلام- فعليك أن تحذر الإكثار من المزاح، فإنه ربما يفضي إلى شر، وإذا مزحت فاحذر أن تقول إلا حقًا، إياك أن تجرح أخاك، أو تؤذي أخاك بكلام يضره، أو تقول فيه خلاف الصواب.\n\nالمقصود: أولًا: قلة المزاح، وهو الذي ينبغي.\n\nثانيًا: إذا مزحت لا تقل إلا حقًا، واحذر أن تقول الباطل.","link":"https://binbaz.org.sa/fatwas/3340/الاعتدال-في-المزاح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1661.mp3","categories":["إخراج الزكاة وأهلها","الآداب والأخلاق المحمودة"]},{"id":7284,"question":"هل تجوز غيبة الكافر؟","title":"حكم غيبة الكافر","answer":"الجواب:\n\nفيما أظهر، غيبته فيما أظهر من كفره، يقال: فلان فعل كذا، وفعل كذا نعم، بل قد تجب عند الحاجة إلى ذلك؛ حتى يقام عليه الحد الشرعي من استتابته، أو قتله، وهكذا الفاسق فيما أظهر من فسقه، ليس له غيبة فيما أظهر.","link":"https://binbaz.org.sa/fatwas/3354/حكم-غيبة-الكافر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1675.mp3","categories":["إخراج الزكاة وأهلها","الآداب والأخلاق المحمودة"]},{"id":7287,"question":"هل تغيير المسميات يقصد الأخ التورية..؟","title":"حكم التورية","answer":"الجواب:\n\nفي التأويل مندوحة عن الكذب، إذا تأول للحاجة من دون أن يجحد حقًا، أو يدعو إلى باطل، ففي التأويل، وفي التعريض مندوحة عليه أن يتحرى في كلامه الحق. \n\nوإذا كان يخشى من التصريح شيئًا يأتي بالمعاريض التي يحصل بها  المقصود من دون أن يكذب على أحد، أو يظلم أحدًا أو يتكلم بما حرم الله.","link":"https://binbaz.org.sa/fatwas/3350/حكم-التورية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1671.mp3","categories":["إخراج الزكاة وأهلها","الآداب والأخلاق المحمودة"]},{"id":7300,"question":"أنا امرأة لي زوج وخمسة أبناء، ولكن زوجي متزوج من امرأة أخرى ويوليها اهتمامه أكثر مني ومن أبنائي، ويمنعني من أشياء يسمح بها للأخرى، وهذه حياتي معه، فما رأي سماحتكم بهذا الحال؟","title":"العدل بين الزوجات","answer":"الجواب: الواجب على الزوج أن يعدل فيما يتعلق بالزوجات، وليس له الحيف، هو مسؤول عن هذا الشيء، فالواجب على الأزواج أن يعدلوا بين الزوجات، وأن يستعينوا بالله، وأن يراقبوه  في كل شيء، في القسم، وفي النفقة، وفيما يتعلق بجبر الخواطر بينهن، وعدم إشاعة الشحناء بينهما.  هكذا ينبغي للزوج يكون حكيما وأن يحرص على كل ما يهدئ الأحوال ويجبر الخواطر، ويجعل الزوجتين فأكثر في راحة وفي طمأنينة من عدله وعنايته وحسن خلقه معهما جميعا، هذا هو الواجب عليه، وعلى الزوجات -ننصح الزوجات أيضا- بالتسامح في بعض الشيء وعدم التشديد وعدم التنقيب في كل الأمور، فإن من شدد لا بد يندم، ولا بد يفضي هذا التشديد إلى تحطيم الأسرة والعشرة بينهما إلا ما شاء الله، فينبغي للنساء أيضا التسامح في بعض الأمور وألا يشددن على الزوج فيما يتعلق بالعدل إذا كانت هفوة قليلة، أو شيء قليل ينبغي فيه التسامح والتغاضي، فلا بد من عناية من الزوج ولا بد من تسامح من الزوجات عن بعض الأشياء التي قد تقع من الزوج، وقد يكون غير عامد لها، وقد يكون مضطرا إليها، والمرأة لا ... الثانية، فينبغي للمرأة أن تسامحه في بعض الشيء؛ حتى يحصل الوئام، والتعاون على الخير.","link":"https://binbaz.org.sa/fatwas/3377/العدل-بين-الزوجات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1695.mp3","categories":["الآداب والأخلاق المحمودة","تعدد الزوجات"]},{"id":7322,"question":"اشتريت قطعة أرض من صاحبها بالتقسيط على أربعة أعوام بمبلغ من المال، وبعد حوالي عام اتفقت معه على أن أسدده جميع الأقسام المتبقية دفعة واحدة، على أن يخفض من المبلغ المتفق عليه، فما رأي فضيلتكم في هذا؟ وهل تبدأ زكاتها منذ شرائها، أم بعد الإفراغ لي؟","title":"بيان الراجح في مسألة: (ضع وتعجل)","answer":"الجواب: هذه المسألة فيها خلاف بين أهل العلم، وهي مسألة ضع وتعجل، وهي معلومة عند أهل العلم، ويروى أن النبي ﷺ قال لبني النضير لما أراد أن يجلهم، واشتكوا أن لهم ديونًا عند الناس، قال: ضعوا وتعجلوا.  فالصواب أنه يجوز إذا قال المدين: أنا أعطيك حقك دفعة واحدة، ولكن نزل عني، والدين أربعة آلاف على أربعة أعوام، فقال: أنا أنجزه لك إذا وضعت عني ألفًا، فقال صاحب الدين: نعم أنا أضع عنك ألفًا، واعطني ثلاثة آلاف، وأنا أسامحك، لا حرج في ذلك، الصواب أنه جائز، وإن كان كثير من أهل العلم يرى خلاف ذلك، لكن الصحيح أنه جائز؛ لأن هذا فيه مصالح تعجيل الحق، وبراءة الذمة، هذا فيه مصلحتان: تعجيل الحق لصاحبه ولو ناقصًا بدل ما يكون في سنوات يعطيه إياه حالًا، وتخفيفه على المدين يطيح عنه قطعة من الدين.  الصواب في هذا: أنه جائز، وهي مسألة: ضعوا وتعجلوا، يكون لك عند زيد ألف ريال تحل في رمضان الآتي، وقلت له: أعطيك ثمانمائة وسامحني الآن، إذا أعطيته ثمانمائة وسامحك عن المائتين لأجل التعجيل لا بأس، وهكذا ما كان أكثر وأقل.","link":"https://binbaz.org.sa/fatwas/3396/بيان-الراجح-في-مسالة-ضع-وتعجل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1710.mp3","categories":["السلف والقرض","الآداب والأخلاق المحمودة"]},{"id":7364,"question":"دكتور إنجليزي يدين بالديانة المسيحية، قد أجرى عملية لوالدة بعض الأسر، فقاموا بشكره في بعض الصحف على نجاح العملية، فهل يجوز أن يشكر مثل ذلك الدكتور، أو أي دكتور، ولو كان مسلمًا؟","title":"حكم شكر طبيب مسيحي نجح في إجراء عملية","answer":"الجواب: الشكر لمن فعل معروفًا طيب لا يشكر الله من لا يشكر الناس الرسول ﷺ يقول: من فعل إليكم معروفًا؛ فكافئوه، فإن لم تجدوا ما تكافئوه به؛ فادعوا له المقصود: إذا شكر على نجاح العملية، وأن العملية انتهت ما يضر، سواء كان كافرًا أو مسلمًا.","link":"https://binbaz.org.sa/fatwas/3449/حكم-شكر-طبيب-مسيحي-نجح-في-اجراء-عملية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1755.mp3","categories":["إخراج الزكاة وأهلها","الآداب والأخلاق المحمودة"]},{"id":7383,"question":"أنا شاب متزوج، وزوجتي حامل، ولقد تركتها عند أهلها، ولها الآن ما يقارب السنة، وأنا لا أحبها، وأكرهها، هل علي إثم في تركها؟","title":"حكم ترك الزوجة عند أهلها وعدم تطليقها","answer":"الجواب: نعم نعم، إذا كانت تطلب الطلاق عليك إثم؛ إما أن تطلقها، وإما أن تقوم بحقها، أما إذا كانت راضية وسامحة عنك، تقول: لا تطلقني، ترجو أن الله يهديك، وأنك ترجع إليها؛ فلا بأس، أما إذا كانت تقول: لا، إما قم بالواجب وإلا طلقني؛ فعليك أن تقوم بالواجب، أو الطلاق أحد الأمرين.  أما إذا كانت عند أهلها، ومسامحة، ولا تطلب طلاقها، ولا عندها خلاف، فأنت فكر واستخر الله، وشاور أصحابك، وأقاربك، إذا كانت طيبة ومن أهل الخير والصلاح والاستقامة؛ فلا تطلقها ولو كرهتها، الله يقول: فَعَسَى أَنْ تَكْرَهُوا شَيْئًا وَيَجْعَلَ اللَّهُ فِيهِ خَيْرًا كَثِيرًا [النساء:19] ربما أنك إذا رجعت إليها تزكو في نفسك، وترى منها ما يسركن فتعجبك بعد ذلك، لا تعجل.","link":"https://binbaz.org.sa/fatwas/3464/حكم-ترك-الزوجة-عند-اهلها-وعدم-تطليقها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1768.mp3","categories":["الحقوق الزوجية","الآداب والأخلاق المحمودة"]},{"id":7407,"question":"أخذت ذهب زوجتي، وقمت ببيعه برضاها بالكامل؛ لضائقة ألمت بي منذ خمسة عشر عامًا، وكان الثمن دينًا لها عندي، والآن وبعد ارتفاع ثمن الذهب عشرة أضعاف تطالبني بالقيمة الحالية، أو إعادة وزن الذهب لها، ماذا أفعل حتى تبرأ ذمتي من هذا الدين؟","title":"كيفية القضاء لمن استدان من امرأته ذهباً","answer":"الجواب: عليك أن ترد عليها ذهبها إذا كانت أعطتك الذهب وسمحت لك أن تبيعه وتنفقه في حاجاتك، فالذهب يعتبر قرضًا عليك وزنًا بوزن، فإن كنت بعته على حسابها، ورضيت بأن يكون القرض هو الثمن؛ فعليك رد الثمن، أما إن كان القرض الذي بينك وبينها نفس الذهب أن ترد عليها مثل ذهبها، فالمسلمون على شروطهم، يقول النبي ﷺ: المسلمون على شروطهم.  فإن كنت اتفقت معها على أن ترد عليها ذهبها، فرد عليها مثل ذهبها غالٍ أو رخيص، فإن كان الذي جرى بينك وبينها أنك تبيعه الذهب على حسابها، وأن الثمن يكون لها عليك، فالمسلمون على شروطهم، من شروطها الثمن أيضًا، والأحسن لك يا أخي أن تعطيها ما يرضيها، هذا أو هذا؛ لأن النزاع بينكما قد يفضي إلى ما لا تحمد عقباه، فوصيتي لك أن تعطيها الذي يرضيها، ولو كان فيه كلفة عليك، هذا هو الأصلح لك، قد أحسنت إليك ووسعت لك، فأرضها، يقول النبي ﷺ: إن خيار الناس أحسنهم قضاء.","link":"https://binbaz.org.sa/fatwas/3482/كيفية-القضاء-لمن-استدان-من-امراته-ذهبا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1786.mp3","categories":["السلف والقرض","الآداب والأخلاق المحمودة"]},{"id":7423,"question":"أخذت ذهب زوجتي، وقمت ببيعه برضاها بالكامل؛ لضائقة ألمت بي منذ خمسة عشر عامًا، وكان الثمن دينًا لها عندي، والآن وبعد ارتفاع ثمن الذهب عشرة أضعاف تطالبني بالقيمة الحالية، أو إعادة وزن الذهب لها، ماذا أفعل حتى تبرأ ذمتي من هذا الدين؟","title":"كيفية القضاء لمن استدان من امرأته ذهباً","answer":"الجواب: عليك أن ترد عليها ذهبها إذا كانت أعطتك الذهب وسمحت لك أن تبيعه وتنفقه في حاجاتك، فالذهب يعتبر قرضًا عليك وزنًا بوزن، فإن كنت بعته على حسابها، ورضيت بأن يكون القرض هو الثمن؛ فعليك رد الثمن، أما إن كان القرض الذي بينك وبينها نفس الذهب أن ترد عليها مثل ذهبها، فالمسلمون على شروطهم، يقول النبي ﷺ: المسلمون على شروطهم.  فإن كنت اتفقت معها على أن ترد عليها ذهبها، فرد عليها مثل ذهبها غالٍ أو رخيص، فإن كان الذي جرى بينك وبينها أنك تبيعه الذهب على حسابها، وأن الثمن يكون لها عليك، فالمسلمون على شروطهم، من شروطها الثمن أيضًا، والأحسن لك يا أخي أن تعطيها ما يرضيها، هذا أو هذا؛ لأن النزاع بينكما قد يفضي إلى ما لا تحمد عقباه، فوصيتي لك أن تعطيها الذي يرضيها، ولو كان فيه كلفة عليك، هذا هو الأصلح لك، قد أحسنت إليك ووسعت لك، فأرضها، يقول النبي ﷺ: إن خيار الناس أحسنهم قضاء.","link":"https://binbaz.org.sa/fatwas/3482/كيفية-القضاء-لمن-استدان-من-امراته-ذهبا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1786.mp3","categories":["السلف والقرض","الآداب والأخلاق المحمودة"]},{"id":7568,"question":"هذه الرسالة وردت من حوطة بني تميم من المقدمة (م. هـ) تقول المقدمة (م. هـ): ما حكم السلام على المحارم بالتقبيل والمصافحة، وإذا كان ذلك جائز فمن يكون له من الأقارب، الإخوة أم الأب أم العم أم الأخوال، وهل يدخل في ذلك محارم الرضاعة، أقصد بالتقبيل بين الرجل والمرأة؟","title":"حكم السلام على المحارم بالتقبيل والمصافحة","answer":"الجواب: السلام على المحارم لا بأس به، السلام من الرجل على محارمه، من المرأة على محارمها لا بأس بالمصافحة أو بالتقبيل، كل هذا لا بأس به، والمحارم هم المبينون في قوله جل وعلا: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ أَوْ أَبْنَائِهِنَّ أَوْ أَبْنَاءِ بُعُولَتِهِنَّ أَوْ إِخْوَانِهِنَّ أَوْ بَنِي إِخْوَانِهِنَّ أَوْ بَنِي أَخَوَاتِهِنَّ أَوْ نِسَائِهِنَّ أَوْ مَا مَلَكَتْ أَيْمَانُهُنَّ [النور:31]، وملك اليمين لا بأس بإبداء الزينة لكن ليس من المحارم من كل وجه، لكنه في حكم المحارم من هذه الجهة، وكذلك الأخوال والأعمام هم أيضاً من المحارم، فهؤلاء هم المحارم، أبوها، وأجدادها، وأبو أمها، وأجدادها من جهة الأم، وأبناؤها، وأبناء بناتها، وأبناء بنيها، وإخوة المرأة، وأبناء إخوتها هم محارمها أيضاً، وأبناء أخواتها من محارمها، هكذا أخوالها، وأعمامها، كلهم محارمها، وهكذا أبو زوجها، وجد زوجها، وابن زوجها، وابن ابنه، وابن بنته، ابن بنت الزوج، وابن ابنه كلهم محارم، كلهم محارم لها. \nولا بأس أن يقبل الرجل محرمه؛ عمته، خالته، أمه، جدته، أخته، لا بأس أن يقبلها، لكن الأفضل يكون مع الرأس ولاسيما الكبيرة، أو على الأنف، أو على الخد، هذا هو الأفضل، وكره جمع من أهل العلم تقبيل الفم إلا للزوج، أن يقبلها مع فمها هذا يكون للزوج لا للمحارم، هذا هو الأولى، الأولى أن يكون للزوج لا للمحارم، المحارم على الرأس، على الأنف، على الخد، هذا هو الأولى والذي ينبغي، وسواء كان المحارم من النسب أو من الرضاع، حتى الأرضاع، أبوها من الرضاع، عمها من الرضاع، خالها من الرضاع، ابن زوجها من الرضاع، أبو زوجها من الرضاع، كالنسب؛ لقول النبي ﷺ: يحرم من الرضاع ما يحرم من النسب، هكذا قال عليه الصلاة والسلام، فالرضاع مثل النسب، وهكذا المصاهرة كما تقدم، أبو الزوج محرم من جهة المصاهرة، أبو الزوج، جد الزوج، ابن الزوج، هذا محرم من جهة المصاهرة سواء كان من النسب أو من الرضاع، والمصافحة من باب أولى. نعم.","link":"https://binbaz.org.sa/fatwas/4573/حكم-السلام-على-المحارم-بالتقبيل-والمصافحة ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_016/01603.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":7651,"question":"في الحقيقة محمد أحمد عبد العالي يثني على البرنامج ويقول أيضاً: بعد أن سألتكم هذا السؤال الكبير، والذي يحتاج إلى إجابة كبيرة، أريد أن أعرف ما حكم التحية: صباح الخير، هل هي جائزة أم لا؟","title":"حكم التحية بـ (صباح الخير أو مساء الخير)","answer":"الجواب: صباح الخير لا أعلم لها وجهاً، صباح الخير.. مساء الخير ما أعلم لها وجهاً، والذي ينبغي أن يقال: (السلام عليكم) ثم يقول: صبحكم الله بالخير، ومساكم بالخير، أو كيف أصبحت أو كيف أمسيت، أما صباح الخير ومساء الخير ما أعلم لها أصلاً ولا أعلم لها وجهاً، وإن كان قد يراد بذلك صباح الخير لكم أو صباح الخير ينزل بكم، ولكن استعمال الألفاظ الأخرى مثل كيف أصبحت؟ كيف أمسيت؟ صبحك الله بالخير، مساك الله بالخير بعد ما يقول: السلام عليكم، يبدأ بالسلام ويقول: (السلام عليكم) وإذا كمله فقال: السلام عليكم ورحمة الله وبركاته، كان أفضل، ثم إذا أحب يزيد فيقول: كيف أصبحت؟ كيف أمسيت؟ لعلك بخير، أرجو أنك بخير، أو صبحك الله بالخير، إذا كان في أول النهار، أو مساك الله بالخير إذا كان في آخر الليل، كل هذا طيب من باب العناية بأخيه والتحفي بأخيه، كله طيب. نعم.\nالمقدم: أحسنتم.","link":"https://binbaz.org.sa/fatwas/4799/حكم-التحية-بـ-صباح-الخير-او-مساء-الخير","audio":"","categories":["الآداب والأخلاق المحمودة"]},{"id":7834,"question":"يسأل أخونا في سؤاله الثالث عن درجة القرابة التي تكون فيها صلة الرحم واجبة ويحرم قطعها؟","title":"ترتيب القرابة في صلة الرحم","answer":"الجواب: القرابة بيَّنها الرسول ﷺ قال في الحديث الصحيح لما سأله الرجل، قال: يا رسول الله من أبر؟! قال: أمك. قال: ثم من؟ قال: أمك. قال: ثم من؟ قال: أمك. قال: ثم من؟ قال: أباك. ثم الأقربب فالأقرب وفي اللفظ الآخر: أختك وأخاك وأدناك فأدناك.\nفأول الأقارب وأحقهم بالصلة الآباء والأمهات والأجداد والجدات، ثم الأولاد وأولادهم من الذكور والإناث، ثم الإخوة وأولادهم ذكوراً وإناثا، ثم الأعمام والأخوال والخالات والعمات وأولادهم، ثم الأقرب فالأقرب من بني العم درجات، فأولاهم وأحقهم بالصلة الواجبة الآباء والأمهات والأجداد والجدات، هم أحق الناس، وأحقهم على الإطلاق الأم، ثم هكذا الأب في الدرجة الرابعة، وهكذا الجدة والأجداد.\nالمقصود أن الأصول والفروع هم أحق الناس بالبر والصلة، ثم يليهم الحواشي من الإخوة والأخوات والأعمام والعمات وأولادهم إلى آخره، الأقرب فالأقرب، والصلة واجبة حسب الطاقة فإذا استطاع أن يصل الأب والأم وصلهما، ولا يلزمه صلة الأولاد والإخوة إذا عجز، فإذا وصل الأولاد والآباء والأمهات ولكن عجز عن الإخوة سقط عنه ذلك، فإذا استطاع أن يصل الإخوة سقط عنه ما عجز عنه من صلة بنيهم وصلة الأعمام والعمات والأخوال وهكذا، الأقرب فالأقرب مع القدرة إذا كانوا فقراء، أما إذا كانوا أغنياء فالصلة تكون بالكلام الطيب والزيارة الحسنة والسلام، والسؤال عن الأحوال، وفعل ما ينفعهم من سائر المعروف، نعم.\nالمقدم: جزاكم الله خيرا ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/5226/ترتيب-القرابة-في-صلة-الرحم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_052/05207.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":7935,"question":"أيضاً له سؤال: يقول: إذا كان شخص مكلف بواجب في منطقة ما وقل زاده واحتاج إلى الطعام، فوجد بساتين أو بيوت متروكة وفيها فواكه وخضر أو طعام، فهل يحق له أن يأكل منها ويذهب جوعه أم لا؟ وفي الختام السلام عليكم ورحمة الله.","title":"حكم الأكل من بساتين الغير للضرورة","answer":"الجواب: لا شك إذا كان محتاجاً فإنه يأكل حاجته من غير أن يحمل شيئاً، إذا احتاج إلى أن يأكل من البستان من الفواكه التي فيه، أو البيت الخالي الذي فيه الطعام وهو محتاج جائع وليس عنده زاد يأكل حاجته ولا حرج عليه، كما جاء في الحديث: من أصاب بفيه من ذي حاجة فلا شيء عليه إذا مر بالبستان، فالمقصود أنه إذا أكل من هذه الثمار أو الفواكه أو غيرها مما يطعم ويؤكل فإنه لا حرج عليه، لكن لا يحمل إنما يأكل حاجته.","link":"https://binbaz.org.sa/fatwas/5455/حكم-الاكل-من-بساتين-الغير-للضرورة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_066/06605.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":8105,"question":"الرسالة التالية باعثتها إحدى الأخوات من مكة المكرمة تقول: أم أحمد ، أرجو عرض أسئلتي على فضيلة الشيخ عبد العزيز بن باز مع دعائي لكم بالتوفيق والسداد.أولاً: هل يجوز أن نقوم للضيف للسلام عليه، وإذا كان لا يجوز فإنك سوف تصافحه ويحتاج ذلك للانحناء قليلاً حتى تصل يدك ليده، ومن عادتنا أن نقبل يد الكبير من باب الاحترام حتى ولو لم أكن أعرفه من قبل، فهل هذا صحيح؟ وإن كانت الطريق غير صحيحة فكيف الطريق الصحيح لنسلم بها على الجالسين إذا قدمت وفي المجلس ضيوف؟","title":"حكم القيام للضيف ومصافحته","answer":"الجواب: يجوز القيام للضيف ومقابلته ومعانقته إذا كان قادم من سفر أو مصافحته، هذا كله من السنة، وقد كان النبي ﷺ إذا قدمت عليه ابنته فاطمة يقوم لها ويأخذ بيدها، وهكذا كانت تفعل إذا دخل عليها قامت إليه وأخذت بيده عليه الصلاة والسلام، ولما جاء سعد بن معاذ  الأنصاري سيد الأوس ليحكم في بني قريظة، قال النبي ﷺ للصحابة: قوموا إلى سيدكم، فقاموا إليه وسلموا عليه، هذا لا بأس به ولا حرج فيه.\nفالقيام إلى الضيف لمصافحته والترحيب به ومقابلته أمر مشروع وإنما المكروه أن يقوم الناس على رأس القاعد تعظيماً له، أو يقومون فقط قياماً من غير تقدم إليه ولا مصافحة بل مجرد تعظيم وإكرام وهم في محلاتهم يقومون فقط، هذا هو المكروه الذي لا ينبغي، وكذلك الوقوف عليه وهو جالس تعظيماً له لا يجوز، والنبي نهى عنه ﷺ، أما القيام إلى القادم لمصافحته والترحيب به، هذا أمر مشروع ولا بأس به ولا ينبغي أنه يجلس ويدع الضيف ينحني له بل يقوم يصافح الضيف ويكرم الضيف، وإذا كان معذوراً صاحب البيت؛ لأنه كبير السن أو مريض فالضيف يجلس ويصافحه أو يمد يده إليه وينحني حتى يطوله ليس هذا انحناء تعظيم، هذا انحناء لا يسمى تعظيم ولكنه انحناء حتى يصافحه، فإذا خفض رأسه وظهره حتى يصافحه؛ لأنه قاعد أو مضطجع أو جلس و ...، كل هذا لا بأس به، إنما الذي ينهى عنه أن ينحني تعظيماً كالراكع إذا دخل على الملك أو على الأمير أو على فلان أو فلان ينحني له، هذا منكر لا يجوز، أما إذا انحنى لأن المسلم عليه قصير أو جالس أو مريض مضطجع وانحنى ليصافحه فليس هذا من باب التعظيم بل هذا من باب الإكرام لأخيه وأداء السنة لأخيه من المصافحة؛ لأن السنة عند اللقاء المصافحة، ولا حرج في هذا من أجل المصافحة.","link":"https://binbaz.org.sa/fatwas/5901/حكم-القيام-للضيف-ومصافحته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_101/10108.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":8130,"question":"يقول: ما حكم بيع السيارات الفخمة الغالية الثمن والأثاث الغالي الثمن أيضاً؟","title":"حكم شراء الأثاث والسيارات الغالية الثمن","answer":"الجواب: هذا أمره واسع، إذا كان المشتري قادر، وليس قصده الإسراف ولا المفاخرة، إنما يريد الطيب الذي من باب الجمال أو من باب الزينة وهو أهل لذلك؛ لأن عنده المال وعنده القدرة، فلا نعلم فيه شيء، إذا اشترى سيارة فخمة أو فراشاً طيباً ما نعلم فيه شيء، لكن التواضع طيب، إذا تواضع لله واستعمل الشيء الوسط، يكون أفضل، يكون أفضل وأقصد، حتى يتمكن من صرف الزيادات في الصدقة، والمساعدة للفقراء، والمساهمة في المشاريع الخيرية، فالحاصل أن الاقتصاد والتوسط في الأمور أفضل، ولو اشترى شيئاً جميلاً نفيساً من السيارات أو من الفرش؛ لأنه قادر ويريد بذلك الجمال لا المفاخرة ولا المباهاة، فلا حرج في ذلك إن شاء الله. نعم.","link":"https://binbaz.org.sa/fatwas/5932/حكم-شراء-الاثاث-والسيارات-الغالية-الثمن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_088/08804.mp3","categories":["الآداب والأخلاق المحمودة","البيوع"]},{"id":8321,"question":"نعود إلى رسالة الأخت (مها . ع. ز) من بغداد الأعظمية الرصافة، أختنا سبق وأن عرضنا خمسة أسئلة من أسئلتها، ولها مجموعة من الأسئلة أيضاً، وتبدأ بهذا السؤال فتقول: في بعض الظروف تقتضي المجاملة ولا نقول الحقيقة، فهل يعتبر هذا نوع من الكذب؟","title":"حكم ما يجري بين الناس من المجاملات","answer":"الجواب: هذا فيه تفصيل: إن كانت المجاملة يترتب عليها جحد حق أو إثبات باطل لم تجز هذه المجاملة، أما إن كانت المجاملة لا يترتب عليها شيء إنما هو كلام طيب وفيه إجمال ولا يتضمن شهادة بحق لأحد، ولا اشترط حقاًَ لأحد وإنما هو مجاملة: إنسان طيب أو فلان لا بأس به أو فلان كذا أو .. وهو لا يعلم منه خلاف ذلك، هذه المجاملة لا يترتب عليها شيء.","link":"https://binbaz.org.sa/fatwas/6134/حكم-ما-يجري-بين-الناس-من-المجاملات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_110/11004.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":8358,"question":"أخونا يقول: أنا أسكن مع عائلتي في منزلٍ واحد، وأقوم بمراعاة مصالحهم بعد وفاة والدي، لكني أود السفر إلى المدينة المنورة والبقاء فيها، ولكن والدتي لا تطيق فراقي، وأنها تقول: ليس لهم إلا الله ثم أنا، مع العلم بأن لدي إخوة أربعة غيري، الأكبر مني والأصغر قد تزوجوا، وأنجبوا أولاد، إلا أنا، وأنا لا أريد السفر إلا لطاعة الله وقضاء باقي العمر في الطاعة؛ لأن بلادنا تعلمون ما نشكو منها، وإذا لم أستطع السفر فأود الخروج في بيتٍ لوحدي كي يتسنى لي تربية أولادي التربية الصحيحة؛ لأني لا أستطيع أن أعيش معهم؛ لأنهم يتتبعون مشاهدة الفيديو وغير ذلك، أرجو من سماحة الشيخ توجيهي حول هذه القضايا، جزاكم الله خيراً؟","title":"حكم البقاء في المنزل طاعة للوالدة مع الخلطة","answer":"الجواب: إذا كان عليك خطر في البقاء معهم فلا بأس أن تنتقل في بيت مستقل في المدينة أو في غيرها، وعليك أن تراعي مشاعر الوالدة وتستسمحها بالكلام الطيب والعبارة الحسنة، حتى تسمح إن شاء الله، فإن لم تسمح وأنت عليك خطر وعلى أولادك خطر من الاجتماع بإخوتك الذين يتسامحون في الفيديو وغير ذلك، فلا حرج عليك، وعلى الوالدة أن تسمح عنك، عليها أن تتقي الله وعليها أن تسمح لك، وعليها أن لا تشدد؛ لأنك تطلب السلامة لدينك، فلا حرج عليك، وأنت استعن بالله جل وعلا واعمل ما تراه أصلح لدينك وأصلح لأولادك، وأسلم لعرضك، هذا هو الواجب عليك، الله يقول: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] فالمؤمن يتقي الله ما استطاع، ويحرص على سلامة دينه، وسلامة أولاده، وعلى تربية أولاده التربية الإسلامية، وعلى الوالدة أن تعينك على ذلك، فإن هدى الله إخوتك، وتباعدوا عما حرم الله وصلحت الحال، فابق معهم والحمد لله، أما إن لم تتغير الحال، وأنت تخشى على دينك وعلى أولادك فلك أن تنتقل وإن لم ترض الوالدة، لكن عليها أن ترضى وعليها أن تسمح وعليها أن تقدر ما ذكرته من الحاجة إلى الانفراد، رزق الله الجميع التوفيق والهداية.\nالمقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/6207/حكم-البقاء-في-المنزل-طاعة-للوالدة-مع-الخلطة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_113/11315.mp3","categories":["تربية الأولاد","الآداب والأخلاق المحمودة"]},{"id":8365,"question":"أختان نعمل ببلد عربي، فكونا أن نرد شيئاً لوالدينا المسنين من تضحياتهم العظيمة في تربيتنا وتعليمنا، ونحن أكبر أولادهم، فأرسلنا لهم مبلغاً من المال كي يذهبوا لأداء فريضة الحج، ومع الأسف أن هذا التصرف أغضب أزواجنا، رغم عدم تقصيرنا نحوهم، ونحو أولادنا، ورغم أن هذا المبلغ من مالنا الخاص، والله تعالى أوصى بالوالدين كثيراً، فما رأي الدين في هذا أفيدونا أفادكم الله؟","title":"حكم مواساة الزوجة لوالديها من مالها دون رضا زوجها","answer":"الجواب: قد أحسنتما في هذا، والواجب عليكما برهما والإحسان إليهما بجميع الوسائل، أما مساعدتكما للوالدين بما يعينهما على الحج فهذا عمل صالح، وأنتما مشكورتان على ذلك، ولا يجوز لأزواجكما الاعتراض، بل الواجب عليهما أن يساعدا وأن يسرهما هذا الأمر، وأن يشكراكم على هذا العمل.\nالمقصود أن مساعدة الوالدين أو غير الوالدين من رواتبكما ومن مالكما الخاص، ليس للزوج فيه اعتراض، وقد كان النبي ﷺ يأمر النساء بالصدقات، بعد خطبة العيد عليه الصلاة والسلام، فيتصدقن، ولا يقل لهن: شاورن أزواجكن، بل يأمرهن بالصدقة ويقول: إني رأيتكن أكثر أهل النار ويأمرهن بالصدقة والاستغفار، ويأمر بلال أن يأخذ ما يتبرعن به، وقد ثبت عنه ﷺ أن ميمونة قالت: يا رسول الله! أشعرت أني أعتقت فلانة -جاريةً لها-؟ فقال عليه الصلاة والسلام: أما إنك لو أعطيتها أخوالك لكان أعظم لأجرك ولم يقل لها: لم لم تستأذنيني في ذلك؟ بل أمضى عتقها ولكنه أخبرها أنها لو كانت تصدقت بها على أخوالها وساعدت بها أخوالها لكان أعظم لأجرها، من باب صلة الرحم، فكيف بالوالدين؟! الوالدان أعظم وأكبر.\nفالمقصود أن مساعدتكما لوالديكما أمر مطلوب، وحق عليكما، وعلى الأزواج أن يشجعاكم على ذلك، وأن يوافقوا على ذلك، ولكن لا مانع من أخذ خاطر الأزواج، والعناية بما يرضي الأزواج، من دون أن تقصرا فيما يتعلق بالوالدين، وعلى الأزواج أن يتقوا الله وأن يشجعوكم على بر الوالدين، وأن لا يعترضوا على ذلك.","link":"https://binbaz.org.sa/fatwas/6214/حكم-مواساة-الزوجة-لوالديها-من-مالها-دون-رضا-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_114/11405.mp3","categories":["النفقات","الآداب والأخلاق المحمودة"]},{"id":8420,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة يقول: حمود فهد الهذال من الأفلاج، أخونا يقول: ما حكم السلام باليد كما هو مشاهد بين كثير من الناس، ولاسيما إذا كان الواحد منهم في سيارته؟","title":"ما حكم السلام بالإشارة اليد، ولاسيما إذا كان الواحد في سيارته؟","answer":"الجواب: الإشارة بالسلام لا بأس بها عند البعد، أو عند كون المسلم عليه لا يسمع، لكن مع التلفظ يسلم ويشير، قد مر النبي ﷺ على نساء فسلم عليهن وأشار بيده لإفهامهن أنه يسلم عليه الصلاة والسلام، فإذا كان المسلم عليه بعيداً، أو لا يسمع السلام؛ لمرض في سمعه؛ أو لأسباب أخرى فسلم باللفظ وأشار حتى يفهم المسلم عليه أنه يسلم عليه فلا بأس بذلك، أما الاكتفاء بالإشارة فلا، لا يكتفي بالإشارة؛ لأن هذا فيه تشبه بأعداء الله. نعم.","link":"https://binbaz.org.sa/fatwas/6304/ما-حكم-السلام-بالاشارة-اليد-ولاسيما-اذا-كان-الواحد-في-سيارته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_118/11811.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":8574,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات رمزت إلى اسمها بأربعة حروف هي: (ر. م. ص. ض) من الرياض، أختنا تقول: والدتي قالت لنا جميعاً: أنتم محرجين بأن لا تسمون على اسمي، ولكن أختي أنجبت ابنة وسمتها على اسم الوالدة، وكان ذلك عندما كانت الوالدة على قيد الحياة، وإنها قبيل وفاتها قالت: أنا أبيحكم جميعاً من كل شيء، سؤالي: هل يدخل هذا الإحراج في إباحتنا أم لابد من شيء يكون أوضح من ذلك؟ وجهونا جزاكم الله خيراً.","title":"حكم التسمية باسم الأم إذا حرجت على أبنائها ثم سمحت","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد:\nفالتسمية على اسم الوالدة لا حرج فيها، قد صرحت لكن بأنها قد عفتكن من الحرج السابق فذلك داخل فيه، التسمية داخلة في هذا العفو ولا حرج عليكن إن شاء الله في ذلك.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/6653/حكم-التسمية-باسم-الام-اذا-حرجت-على-ابناىها-ثم-سمحت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_208/20801.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":8668,"question":"يقول أيضاً رد السلام أثناء الوضوء هل ينقض الوضوء وهل هو مكروه، أفيدوني أفادكم الله؟","title":"حكم رد السلام أثناء الوضوء وأثناء البول والغائط","answer":"الجواب: ليس بمكروه ولا ينقض الوضوء، إذا سلم عليك وأنت تتوضأ الوضوء الشرعي فالمشروع لك أن ترد السلام، ولو تركت السلام ولم ترد فلا حرج عليك في إذا كنت في حال الاستنجاء إزالة النجاسة؛ لأن بعض العامة يسميها وضوء، ولكن رد السلام في هذا لا بأس به إن شاء الله، بخلاف حال البول حال قضاء الحاجة فإن الأولى عدم رد السلام حتى تنتهي ثم ترد السلام، النبي صلى الله عليه وسلم سلم عليه وهو يبول فلم يرد حتى قام وضرب الجدار وتيمم ورد السلام، وقال: إني كرهت أن أذكر الله على غير طهارة.\nفالحاصل أنه إذا كان يتوضأ الوضوء الشرعي الذي هو غسل الوجه واليدين ومسح الرأس وغسل الرجلين هذا هو الوضوء الشرعي، ويسميه بعض الناس التمسح، هذا إذا سلم عليه يرد السلام بلا إشكال، يجب عليه رد السلام، ولا ينتقض الوضوء برد السلام ولا بتركه، لكنه يجب عليه رد السلام، أما إذا كان يستنجي فالأظهر أنه يرد السلام أيضاً؛ لأن الاستنجاء ليس بولاً ولا غائطاً، لكنه فيه مس للنجاسة وإن ترك إلحاقاً لحاله بالبائل فلا بأس إن شاء الله ولا حرج، وإن رد فلا حرج، أما الذي يبول أو يتغوط فالأولى أن لا يرد السلام في هذه الحالة وأن لا يسلم عليه في هذه الحال. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6798/حكم-رد-السلام-اثناء-الوضوء-واثناء-البول-والغاىط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_214/21403.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":8727,"question":"شيخ عبدالعزيز! أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من إحدى الأخوات تقول فدوى أختنا تسأل مجموعة من الأسئلة في سؤالها الأول تقول: فتاة تكره أمها كراهية شديدة والأم لا تعرف ذلك، وهذه الفتاة عاشت بعيدة عن أمها مع والدها ولم ترها إلا في الكبر بسبب طلاق الأم لظروف عائلية مع العلم أنها تقدم لأمها الهدايا، وقد سألت بعض العلماء فقالوا: إن ميل القلب لا يحاسب عليه الرب. فما رأيكم وترجو التوجيه؛ لأنها تخشى أن يكون ذلك من العقوق، وهل للطلاق أثر على تلك الحالة التي تعيشها تلك البنت؟","title":"أسباب كراهية البنت لأمها وعلاج ذلك","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فلا ريب أن القلوب بيد الله  يصرفها كيف يشاء سبحانه وتعالى، فالمحبة في القلب والكراهة أمران بيد الله  لكن لهما أسباب، فإذا كانت الوالدة ذات عطف على البنت وعناية بشئونها كان هذا من أسباب المحبة، وإذا كانت الوالدة ليست كذلك بل عندها إعراض عن البنت وعدم اكتراث بها أو طالت غيبتها عنها كالسائلة فإن هذا قد يسبب شيئاً من الكراهة والجفوة.\nوالواجب عليك أيها البنت تقوى الله في ذلك وأن تحرصي على صلتها والإحسان إليها وبرها والكلام الطيب معها في جميع الأحوال، وأن تسألي ربك أن يشرح صدرك لمحبتها؛ لأن حق الوالدة عظيم وبرها من أهم الفرائض، فإذا لم تستطيعي ذلك فالأمر بيد الله ولا يضرك فأمور القلوب بيد الله هو الذي يصرفها كيف يشاء سبحانه وتعالى، ولهذا كان من دعاء النبي ﷺ: اللهم يا مقلب القلوب ثبت قلبي على دينك، ويا مصرف القلوب صرف قلبي على طاعتك فالقلوب بيد الله هو مقلبها سبحانه وتعالى، فأنت تضرعين إلى الله عز وجل وتسألينه أن يشرح صدرك لمحبتها والقيام بحقها وبرها كما شرع الله، وعليك أن تفعلي ما تستطيعين من البر والصلة من هدايا وغيرها من الأشياء التي تسبب أداء الواجب ويحصل بها رضا الوالدة ومحبة الوالدة لك، وأما أنت فليس عليك إلا ما تقدرين فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] .. لا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا [البقرة:286] ولا يجب عليك من المال أو الهدايا ما لا تقدرين، ولا يجب عليك شيء من جهة النفقة إذا كانت بحمد الله مستغنية إنما هذا من باب العطف ومن باب الإحسان ومن باب التودد إذا أهديتي لها شيئاً وأنت قادرة من مال طيب فهذا كله طيب، نسأل الله لك التوفيق. نعم.\nالمقدم: أختنا تعزو السبب سماحة الشيخ لأنها افترقت عن أمها بسبب الطلاق.\nالشيخ: قد يكون هذا هو السبب وقد يكون هناك أسباب أخرى لكن كم لله من بنت تبتعد عن أمها وهي تحن إليها ولو بعدت، تحن إليها وتحرص على لقائها ولكن الأمور بيد الله فقد يكون هناك أسباب أخرى من جهة كون الأم ما تكتب إليها أو ما تسأل عنها أو ما توصي عليها بالسلام أو ما أشبه ذلك من أنواع الجفاء. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6879/اسباب-كراهية-البنت-لامها-وعلاج-ذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_135/13501.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":8816,"question":"لعل من حسن الحظ -سماحة الشيخ- أن يقع أمامي الآن رسالة الأخ شوقي محمد أبو سعد ويعمل في العراق وهو من محافظة القادسية، أخونا يقول: حدثونا لو تكرمتم عما وعد الله به الصابرين في الدنيا والعاملين في الآخرة، وسبق أن سأل عما يجب على الإنسان أن يفعله تجاه هذه الدنيا وحبها ومتاعها؟","title":"فضل الصبر والصابرين","answer":"الجواب: نعم، الله سبحانه خلق الخلق ليعبدوه وحده لا شريك له، ليطيعوا أوامره وينتهوا عن نواهيه، ويكثروا من ذكره سبحانه كما قال عز وجل: وَمَا خَلَقْتُ الْجِنَّ وَالإِنسَ إِلَّا لِيَعْبُدُونِ [الذاريات:56]، وعبادته هي توحيده بدعائه وخوفه ورجائه، وبالصلاة والصوم وغير ذلك، وهي طاعة أوامره وترك نواهيه، ووعدهم على ذلك في الدنيا الخير الكثير والعاقبة الحميدة، ووعدهم في الآخرة بالجنة والكرامة فقال سبحانه وتعالى: فَاصْبِرْ إِنَّ الْعاقِبَةَ لِلْمُتَّقِينَ [هود:49]، وقال: وَبَشِّرِ الصَّابِرِينَ  ۝ الَّذِينَ إِذَا أَصَابَتْهُمْ مُصِيبَةٌ قَالُوا إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ  ۝ أُوْلَئِكَ عَلَيْهِمْ صَلَوَاتٌ مِنْ رَبِّهِمْ وَرَحْمَةٌ وَأُوْلَئِكَ هُمُ الْمُهْتَدُونَ [البقرة:155-157]، وقال سبحانه وتعالى: إِنَّمَا يُوَفَّى الصَّابِرُونَ أَجْرَهُمْ بِغَيْرِ حِسَابٍ[الزمر:10]، وقال النبي ﷺ: ما أعطي أحد عطاءً خيرًا وأوسع من الصبر، فالصابر له العاقبة الحميدة في الدنيا وله العاقبة الحميدة في الآخرة إذا صبر على تقوى الله وطاعته، وصبر على ما ابتلي به من شظف العيش، من الفقر، من المرض، من تسليط بعض الأعداء إلى غير ذلك.\nفالصبر عاقبته حميدة قال تعالى في حق المؤمنين وعدوهم قال سبحانه: وَإِنْ تَصْبِرُوا وَتَتَّقُوا لا يَضُرُّكُمْ كَيْدُهُمْ شَيْئًا إِنَّ اللَّهَ بِمَا يَعْمَلُونَ مُحِيطٌ [آل عمران:120]، فالصبر له عواقب حميدة على طاعة الله وعلى المصائب مع الإيمان والتقوى، فصاحبه في الدنيا على خير مرتاح الضمير مرتاح القلب مأجور مثاب، وفي الآخرة في دار الكرامة في دار النعيم في الجنة؛ إذا استقام على أمر الله، والتزم بتقواه سبحانه وتعالى، وجاهد نفسه لله، وصبر على ما ابتلي به من الحاجة والفقر والأعمال الشاقة إلى غير ذلك فكل هذا في سبيل الله، والله المستعان. نعم.","link":"https://binbaz.org.sa/fatwas/6971/فضل-الصبر-والصابرين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_162/16214.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":8836,"question":"الأخت (ن.ض) السبيعي من مكة المكرمة كتبت كتابة مطولة عن خلاف ناشئ بينها وبين أخيها، فأرجو من فضيلتكم أن تتوجهوا بنصيحة للأشقاء عندما يكون بينهم خلاف؟","title":"العفو والمسامحة من شيم الكرام","answer":"الجواب: نعم، المشروع للأقارب وللإخوة في الله عند وجود ما يسبب الشحناء والنزاع أن يتقوا الله، وأن يجتهدوا في حل المشكلات بينهم بالطرق الشرعية، وأن يجتهدوا في السماح والعفو عن حق كل واحد منهم على أخيه، حتى تجتمع القلوب وحتى تتم المودة، وحتى يحصل التعاون على الخير، هكذا ينبغي لكل مؤمن ولكل مؤمنة، يقول الله سبحانه: وَأَنْ تَعْفُوا أَقْرَبُ لِلتَّقْوَى [البقرة:237]، ويقول : فَمَنْ عَفَا وَأَصْلَحَ فَأَجْرُهُ عَلَى اللَّهِ [الشورى:40]، ويقول النبي ﷺ: ما زاد الله عبدًا بعفو إلا عزًا. فالتسامح والعفو عن بعض الحق من صفة الكرام، ومن أخلاق الأفاضل والكرماء والأدباء، والراغبين فيما عند الله . ولا يجوز التهاجر لقول النبي ﷺ: لا تحاسدوا، ولا تباغضوا، ولا تدابروا، ولا تناجشوا، ولا يبع بعضكم على بيع بعض، وكونوا عباد الله إخوانًا، المسلم أخو المسلم لا يظلمه ولا يحقره ولا يكذبه ولا يخذله الحديث. فالتهاجر أمر ممنوع لما يفضي إليه من الشر، ويقول ﷺ: لا هجرة فوق ثلاث وفي الحديث الآخر: لا يحل لمسلم أن يهجر أخاه فوق ثلاث يلتقيان فيعرض هذا ويعرض هذا، وخيرهما الذي يبدأ بالسلام. فالمسائل التي تقع بين الإخوة وبين الأسرة وبين الجيران يجب أن تحل بالطرق التي يرضاها الله عز وجل، فإن كانت بأسباب كلمة استسمح صاحبها -من قالها فيه- من كذبة أو سبة أو غيبة أو نحو ذلك، وإن كانت الشحناء بسبب مال في ذمة أحدهم للآخر اجتهد في أداء المال و قضاء الدين، أو سامحوه بعضه، أو تحملوه فيما بينهم، وتقاسموه وأوفوا عنه، كل هذا من شيم الكرام. وإن كان هناك شيء آخر كذلك سعوا في إزالته أو السماح عنه، أو تسديده إن كان مالًا، فالحاصل أنه ينبغي للأسر والجيران والأصحاب ألا يطيعوا الشيطان في إثارة الشحناء بينهم، وفي غرس جذورها وفي استمرارها بل يحاربوه، بل عليهم أن يحاربوه بكل ما استطاعوا من قوة حتى تعود المياه إلى مجاريها، وحتى تعود القلوب إلى حالها، وحتى تسود المودة بين الجميع، رزق الله للتوفيق والهداية.","link":"https://binbaz.org.sa/fatwas/6991/العفو-والمسامحة-من-شيم-الكرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_165/16506.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":8868,"question":"ماذا يطلق على أبو الزوجة وأم الزوجة؛ لأنه في وقتنا هذا نجد بعض الناس يطلقون على أبو الزوجة لفظ خال وعلى أم الزوجة خالة، أفيدونا أفادكم الله؟","title":"إطلاق لفظ الخال والخالة على أبي الزوجة وأمها","answer":"الجواب: لا نعلم في هذا شيئاً من السنة وإنما عرف الناس يختلف، منهم من يسمي أم الزوجة خالة، وأبا الزوجة خال، ومنهم من يسمي أم الزوجة عمة، ويسمي أبا الزوج عماً والأمر في هذا سهل؛ لأنه من باب العرف، وإذا سماها صهرتي أو سمى أبا الزوجة صهري كله سهل، فهم يسمون أصهاراً، الأقارب من جهة النكاح يسمون أصهاراً، لكن في عرف الناس لهم اصطلاحات في هذا الأمر؛ منهم من يسمي أبا الزوجة عماً أو خالاً وأم الزوجة عمة أو خالة، ولا مشاحة في هذا، إن شاء الله. نعم.","link":"https://binbaz.org.sa/fatwas/7024/اطلاق-لفظ-الخال-والخالة-على-ابي-الزوجة-وامها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_138/13807.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":8882,"question":"رسالة وصلت إلى البرنامج من جمهورية اليمن الديمقراطية الشعبية وباعثتها أخت من هناك تقول: المعذبة (أ. ع. ص) أختنا تقول: أنا مسلمة والحمد لله وأعمل كل ما يرضي الله وملتزمة بالحجاب الشرعي، ولكن والدتي سامحها الله لا تريد مني أن ألتزم بالحجاب وتريد مني أيضاً أن أشاهد السينما والفيديو وما أشبه ذلك، وتقول: إذا لم تتمتعي وتنشرحي -فيما يبدو- وتقول: إذا استمريت على هذا الحال سوف تعجزي ويبيض شعرك، أرجوكم بماذا تنصحونني وما هو رأيكم في مثل هذه الأم؟","title":"الواجب على البنت الملتزمة إذا دعتها والدتها لترك التزامها","answer":"الجواب: الواجب عليك أيها السائلة أن ترفقي بالوالدة وأن تحسني إليها، وأن تخاطبيها بالتي هي أحسن وأن ترفقي بها؛ لأن الوالدة حقها عظيم وبرها من أهم الواجبات، ولكن ليس لك طاعتها في غير المعروف، يقول النبي ﷺ: إنما الطاعة في المعروف، ويقول ﷺ: لا طاعة لمخلوق في معصية الخالق، فالأب والأم والزوج والسلطان والأمير وغيرهم لا يطاعون في معاصي الله، إنما الطاعة في المعروف في المباح، أما في المعصية فلا، فإذا أمرتك بما هو معصية لله كحضور السينماء والفيديو الذي فيه الصور الخليعة والأغاني والمنكرات فليس لك طاعتها في ذلك، ولكن تردين عليها بالكلام الطيب والأسلوب الحسن، وتخبرينها بأن هذا لا يجوز لك وأن طاعة الله مقدمة وأنه لا يجوز لك أن تطيعي المخلوق كائناً من كان في معاصي الله سبحانه وتعالى، لعلها تقنع ولعلها تترك مجادلتك وإيذاءك، والله المستعان.\nأما قولها: إنك تعجزين ويبيض شعرك، هذا كلام ساقط، كلام لا وجه له، فليس التعفف عن محارم الله والبعد عن محارم الله سبباً للتعجيز أو سبباً لبياض الشعر أوشيب الشعر، لا، أسباب هذا طول الزمان وتقدم العمر، أو ما يصيب الإنسان من الأمراض حتى يضعف جسمه، وأما طاعة الله فهي تعين الإنسان وتقويه، كما قال جل وعلا: وَأَنِ اسْتَغْفِرُوا رَبَّكُمْ ثُمَّ تُوبُوا إِلَيْهِ يُمَتِّعْكُمْ مَتَاعًا حَسَنًا إِلَى أَجَلٍ مُسَمًّى وَيُؤْتِ كُلَّ ذِي فَضْلٍ فَضْلَهُ [هود:3]، فالخير يقوي الناس على طاعة الله، اشتكت فاطمة إلى النبي ﷺ تطلبه خادمًا ليكفيها تعب الرحا وخدمة البيت، فاعتذر إليها النبي ﷺ بأن ليس عنده خادم في ذاك الوقت، وقال لها: تسبحين الله وتحمدينهه وتكبيرين عند النوم ثلاثاً وثلاثين مرة، قال: هو خير لك من خادم، قالت: فاستعملت هذا فما اشتكيت بعد ذلك تعبًا فالأعمال الصالحة والأذكار الشرعية تقوي المؤمن والمؤمنة لا تضعفهما، بل كل ما حصل من المؤمنة أو المؤمن الذكر الاستغفار والطاعة لله كان هذا أقوى لقلبه وبدنه، وأرضى لله عنه سبحانه وتعالى وأنفع له في الدنيا والآخرة.\nوأما هذا الكلام الذي تقوله الوالدة فهو مما أجراه الشيطان على لسانها فلا وجه له.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/7038/الواجب-على-البنت-الملتزمة-اذا-دعتها-والدتها-لترك-التزامها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_139/13908.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":8973,"question":"أختنا تقول: لدي بعض الجارات من غير المسلمات ومسلمات أيضًا لكن لي عليهن بعض الملاحظات، ما حكم تبادل الزيارات فيما بيننا؟","title":"حكم زيارة المسلمة لجيرانها من المسلمات وغيرهن","answer":"الجواب: تبادل الزيارات في مثل هذا إذا كان للنصح والتوجيه والتعاون على البر والتقوى طيب ومأمور به، يقول النبي ﷺ: يقول الله : وجبت محبتي للمتحابين فيّ والمتزاورين فيّ، والمتجالسين في والمتباذلين فيّ، أخرجه الإمام مالك رحمه الله بإسناد صحيح. ويقول النبي ﷺ: سبعة يظلهم الله في ظله يوم لا ظل إلا ظله -ذكر منهم-: رجلين تحابا في الله اجتمعا عليه وتفرقا عليه، مثل بالرجلين والحكم يعم الرجلين والمرأتين. فإذا كانت الزيارة لهذه الأخت المسلمة أو للنصرانية أو نحوهما لقصد الدعوة إلى الله وتعليم الخير والإرشاد إلى الخير لا لقصد الطمع في الدنيا أو التساهل بأمر الله فهذا كله طيب، فإذا زارت أختها في الله ونصحتها عن التبرج والسفور وعن التساهل بما حرم الله من سائر المعاصي، أو زارت جارة لها نصرانية أو غير نصرانية كبوذية أو نحو ذلك لتنصحها وترشدها وتعلمها فهذا شيء طيب، فإن قبلت فالحمد لله، وإن لم تقبل تركت الزيارة اللي ما فيها فائدة، ما دامت تزور للنصيحة والخير فلا بأس. أما الزيارة للتحبب أو اللعب والأحاديث الفارغة أو الأكل أو ما.. هذا ما يكون مع النصرانيات مع الكافرات؛ لأن هذا يرشد إلى التساهل وقلة غيرة؛ لأنهم أعداء لنا وبغضاء لنا فلا ينبغي أن نتخذهم بطانة ولا أصحاباً، لكن إذا كان الزيارة للدعوة إلى الله والترغيب في الخير والتحذير من الشر هذا أمر مطلوب. نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7131/حكم-زيارة-المسلمة-لجيرانها-من-المسلمات-وغيرهن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_146/14606.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":9130,"question":"السؤال الثالث والأخير في رسالة الأخ (أ. أ. ع) من العراق يقول فيه: ما حكم الأحلام في اليقظة وهل فيها إثم أفيدونا أفادكم الله؟","title":"حال الأحلام والرؤى التي تقع في النهار","answer":"الجواب: الأحلام لا تكون إلا في النوم ما تكون في اليقظة ما تسمى الرؤيا حلم إلا في النوم، فإذا رآها في اليقظة ما يسمى حلم، هذا يسمى مشاهدة ورؤية أو سماع، ولعلك تريد الأحلام في النهار يعني لا في الليل، فالحلم في الليل أو في النهار لا نعلم فيه فرقاً ومتى كان الرجل من أهل الصدق في يقظته وفي أحاديثه فالغالب أن مرائيه تصدق، وإن كان كذاباً فالغالب أن مرائيه مثل حاله في حالة اليقظة ليس عليها اعتماد، والسنة للمؤمن إذا رأى خيراً أن يحمد الله عليه ويخبر به من يحب، وإذا رأى شراً أن لا يخبر به أحداً وأن يتعوذ بالله من الشيطان ومن شر ما رأى حين استيقاظه، ينفث عن يساره ثلاث مرات ويقول: أعوذ بالله من الشيطان ومن شر ما رأيت، ثلاث مرات، ثم ينقلب على جنبه الآخر ولا يضره ولا يخبر به أحدا هكذا جاء الحديث عن رسول الله ﷺ أنه قال: من رأى منكم رؤيا يحبها فليحمد الله وليخبر بها من يحب، ومن رأى رؤيا يكرهها فهي من الشيطان فلينفث عن يساره وليتعوذ بالله من الشيطان ومن شر ما رأى، ثم لينقلب على جنبه الآخر فإنها لا تضره ولا يخبر بها أحداً، وفي لفظ آخر يقول ﷺ: الرؤيا الصالحة من الله والحلم من الشيطان، فإذا رأى أحدكم ما يكره فلينفث عن يساره ثلاث مرات، وليتعوذ بالله من الشيطان ومن شر ما رأى ثلاث مرات، ثم لينقلب على جنبه الآخر فإنها لا تضره ولا يخبر بها أحداً، والله أعلم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7292/حال-الاحلام-والروى-التي-تقع-في-النهار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_229/22905.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":9159,"question":"هذه رسالة وصلت إلى البرنامج من المستمع (ن. أ. غ) من بنجلادش ومقيم في الإمارات العربية المتحدة، يقول في رسالته وفي سؤاله الأول: ما حكم رد السلام المذاع عبر الإذاعة؟ وما كيفيته أفيدونا أفادكم الله؟","title":"حكم رد السلام المسموع عبر الإذاعات وكيفيته","answer":"الجواب: يرد عليه مثلما سلم هذا هو الأظهر، فإذا قال: السلام عليكم ورحمة الله وبركاته، يقال: وعليكم السلام ورحمة الله وبركاته، وإذا قال: السلام عليكم فقط يقال: وعليكم السلام، وإن زادوه: ورحمة الله وبركاته فهذا أفضل كما يسلم على من سلم عليك في الطريق. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7313/حكم-رد-السلام-المسموع-عبر-الاذاعات-وكيفيته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_231/23104.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":9238,"question":"هذه رسالة وردت من العراق أيضاً من السائل عبدالله عبدالغني العامري من الموصل، يقول في رسالته: أنا متزوج ووالدتي متوفية، ولي زوجة أب ظالمة علي وعلى زوجتي، ودائماً تحرض والدي علي، وتختلق المشاكل والفتن، ولا تدعنا نعيش بوئام وسلام، وأنا موظف وراتبي لا يكفيني، ومع هذا فنصف الراتب أعطيه لوالدي، وأكون مديناً كل شهر لبعض الناس ووالدي لا يعلم، وهذا كله بفعل زوجة أبي ومكرها، وأنا دائماً أدعو الله أن يفرج هذا الهم عني وأقول: لولا مخافة الله لأقتلنها شر قتلة، وللأسف هي تصلي، أريد من فضيلتكم توجيهي بم أفعل؟","title":"كيفية معاملة زوجة الأب المؤذية","answer":"الجواب: هذا من البلاء والامتحان، فالله يقول جل وعلا في كتابه العظيم: وَبَلَوْنَاهُمْ بِالْحَسَنَاتِ وَالسَّيِّئَاتِ لَعَلَّهُمْ يَرْجِعُونَ [الأعراف:168]، ويقول سبحانه: وَلَنَبْلُوَنَّكُمْ بِشَيْءٍ مِنَ الْخَوْفِ وَالْجُوعِ وَنَقْصٍ مِنَ الأَمْوَالِ وَالأَنفُسِ وَالثَّمَرَاتِ وَبَشِّرِ الصَّابِرِينَ [البقرة:155]، ويقول جل وعلا: وَنَبْلُوكُمْ بِالشَّرِّ وَالْخَيْرِ فِتْنَةً وَإِلَيْنَا تُرْجَعُونَ [الأنبياء:35]، هذه من البلايا والمحن، قد يبتلى بها الناس ولا سيما المسلم قد يبتلى بمثل هذا، فعليك أن تعاملها بالخير، وأن تصبر على هذا الأذى حتى يفرج الله، وأن تدعو الله لها بالهداية، وأن يكفيك شرها، إذا أساءت إليك فادعو الله أن يصلح حالها، وأن يهديها، وأن يكفيك شرها، وأن يعافيك من بلائها، وعاملها بالكلام الطيب واللطف، وهكذا زوجتك مرها بأن تعاملها بالخير؛ لعل الله يكفيكم شرها بسبب عملكم الطيب وإحسانكم، وهي زوجة أبيك ولها حق عليك ولأبيك حق عليك، فراعي حق والدك وأحسن إليه وإليها بالكلام الطيب والفعل الطيب منك ومن زوجتك، وأبشر بأن الله سيفرج في الحال إما بموتها وإما بهدايتها وإما بطلاق أبيك لها، أنت إذا أحسنت فأبشر بالخير، فالله يقول جل وعلا: هَلْ جَزَاءُ الإِحْسَانِ إِلَّا الإِحْسَانُ [الرحمن:60]، ويقول سبحانه: إِنَّ اللَّهَ مَعَ الَّذِينَ اتَّقَوْا وَالَّذِينَ هُمْ مُحْسِنُونَ [النحل:128].\nفربك سبحانه عليم جواد كريم يعلم حالكما ولا تخفى عليه حالكما، فأحسن إلى هذه المرأة المسيئة، وادع الله لها بالهداية، واصبر على ما حصل منها، وأوص زوجتك بالإحسان إليها والرفق بها والكلام الطيب معها حتى يفرج الله الكربة، فإن لم يتيسر رجوعها إلى الصواب ولم تكف شرها، فأخبر والدك بشأنها، واستأذن منه أن تكون في بيت وحدك حتى يعذرك، تنتقل إلى بيت وسوف يعينك الله، واصبر ولو تدينت، ولو أخذت ديناً من الناس، انتقل إلى بيت وحدك حتى تتخلص من شرها، وأخبر والدك بالحقيقة، وإن رأيت أن في إخباره مضرةً عليك فلا تخبره، واستأذنه بأنك محتاج إلى الانتقال لأسباب لا تستطيع إخباره بها وانتقل، واسأل ربك العون والتوفيق ولو تدينت من الناس بعض الدين، فقد قال المصطفى عليه الصلاة والسلام: من أخذ أموال الناس يريد أداءها أدى الله عنه، ومن أخذها يريد إتلافها أتلفه الله خرجه البخاري في الصحيح.\nفإذا اقترضت من إخوانك ما يعينك على البيت وأنت في نيتك أنك توفي فإن الله يوفي عنك سبحانه وتعالى، ويرضي عنك أباك، فاستعن بالله واستخر الله واعمل ما تراه الأصلح، نسأل الله لنا ولك التوفيق.","link":"https://binbaz.org.sa/fatwas/7400/كيفية-معاملة-زوجة-الاب-الموذية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_234/23411.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":9382,"question":"سؤال بقي لأخينا (د. م. م) يقول فيه: إذا أردت الزواج من بنت وهي ملتزمة بالحجاب ولكن ليست من منطقتي ولا أعرف هل هي جميلة أم لا، هل يصح النظر إليها إذا كان قد عزمت على الزواج منها، وكيف يكون ذلك جزاكم الله خيرًا؟","title":"حكم نظر الرجل إلى المرأة التي يريد خطبتها","answer":"الجواب: نعم، يشرع لك النظر إليها، إذا خطبت امرأة أو أردت أن تخطبها يشرع لك النظر إليها إذا تيسر ذلك، النبي ﷺ قال: إذا خطب أحدكم المرأة فإن استطاع أن ينظر منها إلى ما يدعوه إلى نكاحها فليفعل وذكر له رجل أنه خطب امرأة فقال: أنظرت إليها؟ قال: لا، قال: اذهب فانظر إليها فالمشروع لك أن تنظر إليها إن تيسر ذلك، وإلا ففي إمكانك تبعث من ثقات النساء، أو من محارمها إن كنت تعرف محارمها من يعطيك الخبر، فتبعث المرأة من أقاربك كأمك وخالتك وعمتك أو أختك تنظر إليها ثم تعطيها صفاتها، أو تسأل محارمها يعطونك صفاتها، وإذا تيسر لك النظر إليها من دون خلوة فلا بأس، تطلب من أبيها أو أمها أو أخيها أو نحو ذلك أن يسمح لك بالنظر إليها لكن من دون خلوة، فتنظر إليها بحضرة أبيها أو أمها أو أخيها أو غيرهم من الناس من دون خلوة. نعم.","link":"https://binbaz.org.sa/fatwas/7546/حكم-نظر-الرجل-الى-المراة-التي-يريد-خطبتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_187/18705.mp3","categories":["الخِطْبَة والاختيار ","النظر والخلوة والاختلاط","قضايا المرأة","الآداب والأخلاق المحمودة"]},{"id":9459,"question":"وهذه رسالة وردت إلى البرنامج من المستمع السوداني الذي يقيم في المملكة ورمز إلى اسمه بـ (ر. ع. ف) يقول في سؤاله الأول: لدي والدة كبيرة في السن، وهي ترغب في أن تزوجني من ابنة أخيها الذي مات من سنوات، وذلك لأنه كان بارًا وعطوفًا عليها، ووالدتي تصر على زواجي منها، ولكنني غير راغب فيها، أرجو إفادتي في هذا الموضوع أثابكم الله؟","title":"قبول الابن نصيحة الأم في اختيار الزوجة","answer":"الجواب: نصيحتي لك أيها الأخ أن تقبل نصيحة والدتك، وأن تتزوج بابنة أخيها ابنة خالك، ولعل في هذا الخير العظيم، فإن بر الوالدين ولاسيما الوالدة فإن حقها أكبر فيه خير عظيم وله عواقب حميدة، بشرط أن تكون هذه البنت سليمة في دينها، إذا كانت طيبة ذات عقيدة طيبة وذات صلاة واستقامة فإني أنصح لك وأؤكد عليك أن تقبل قول والدتك ومشورتها ونصحها، وسوف يجعل الله العاقبة حميدة، يقول الله جل وعلا: فَاصْبِرْ إِنَّ الْعاقِبَةَ لِلْمُتَّقِينَ [هود:49].\nفبر الوالدة وطاعتها في الخير من التقوى، والعاقبة لأهل التقوى، ولا تكره شيئًا من البنت إذا كان ذلك لا يضر في خلقها ودينها، فقد قال الله سبحانه: فَعَسَى أَنْ تَكْرَهُوا شَيْئًا وَيَجْعَلَ اللَّهُ فِيهِ خَيْرًا كَثِيرًا [النساء:19]، وقال سبحانه: كُتِبَ عَلَيْكُمُ الْقِتَالُ وَهُوَ كُرْهٌ لَكُمْ وَعَسَى أَنْ تَكْرَهُوا شَيْئًا وَهُوَ خَيْرٌ لَكُمْ وَعَسَى أَنْ تُحِبُّوا شَيْئًا وَهُوَ شَرٌّ لَكُمْ [البقرة:216].\nفإذا كان هناك نقص في خلق أو في خلق لا يضر بدينها ولا يعتبر هذا النقص في الخلق معصية فاصبر عليه، ولعل الله يجعل مكان ذلك كمالًا في نفسك ومحبة في نفسك، حتى تستقيم معها على الخير والهدى وحتى ترضي والدتك.\nأما إن كان هناك ما يمنع شرعًا من كونها لا تصلي، أو متهمة بالفواحش، فلا، لا تقبل ولا تنكحها واعتذر إلى والدتك وبين لها بينك وبينها سرًا الأسباب والأعذار التي تمنعك من زواجها.\nهذا هو الذي أنصح لك به وأسأل الله لك التوفيق فيما تأتي وتذر. نعم.","link":"https://binbaz.org.sa/fatwas/7617/قبول-الابن-نصيحة-الام-في-اختيار-الزوجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_191/19107.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":9497,"question":"وهذه رسالة وردت إلينا من هيثم من الرياض، يقول الأخ هيثم في رسالته: ورد في تفسير الجلالين في صفحة ثلاثمائة وأربعة وعشرين، روى أنس بن مالك قال: قلنا: يا رسول الله! أينحني بعضنا إلى بعض إذا التقينا؟ قال: لا. قلنا: أفيعتنق بعضنا بعضاً؟ قال: لا. قلنا: أفيصافح بعضنا بعضاً؟ قال: نعم، وقال ﷺ: من سره أن يتمثل له الناس قياماً فليتبوأ مقعده من النار وكان ﷺ لا ينحنى له ولا تقبل يده مع السلام، وورد في كتاب تربية الأولاد في الإسلام تأليف عبد الله علوان، تحت عنوان: تقبيل يد الكبير، أخرج أحمد والبخاري في الأدب الصغير وأبو داود وابن الأعرابي عن زارع وكان في وفد عبد القيس، قال: لما قدمنا المدينة جعلنا نتبادر من رواحلنا فنقبل يد النبي ﷺ ورجله وروى البخاري في الأدب المفرد عن صهيب قال: رأيت علياً يقبل يد العباس ورجليه انتهى الكلام المنقول من المرجعين المذكورين،  أي الأقوال هو الصحيح والواجب والسنة اتباعه في السلام، جزاكم الله خيراً؟","title":"المشروع عند اللقاء والسلام","answer":"الجواب: أما الحديث الأول حديث أنس أنهم قالوا: يا رسول الله! يلقى أحدنا أخاه أينحني له؟ قال: لا. قال: فيلتزمه ويقبله؟ قال: لا. قال: فيصافحه؟ قال: نعم هذا الحديث ضعيف الإسناد عند أهل العلم، ليس بصحيح، ولكن معناه من جهة الانحناء صحيح، لا يجوز أن ينحني لأحد، فالسلام لا يكون بالانحناء لا للكبير ولا للصغير، ولكن يسلم وهو منتصب بغير انحناء، ويصافح، السنة المصافحة، فإذا كان القدوم من سفر فالسنة المعانقة، قال أنس  في حديث آخر رواه الطبراني بإسناد جيد: كان أصحاب النبي ﷺ إذا تلاقوا تصافحوا، وإذا قدموا من سفر تعانقوا وهكذا قال الشعبي عن أصحاب النبي ﷺ، وهكذا جاء في أحاديث أخرى، كان الصحابة يتلاقون ويتصافحون، وكانوا يصافحون النبي عليه الصلاة والسلام، فالسنة المصافحة عند التلاقي، وإذا عانق أخاه عند طول الغيبة أو عند القدوم من السفر فلا حرج في ذلك، وقد جاء في هذا أخبار كثيرة تدل على أنه لا بأس بالمعانقة ولا بأس بتقبيل ما بين العينين والرأس عند اللقاء، عند القدوم من السفر، ومثلها طول الغيبة لا حرج في ذلك، أما الانحناء فلا يجوز الانحناء.\nوأما تقبيل اليد أو الرجل فالأفضل تركه، وقد ثبت أنه ﷺ قبله بعض أصحابه في بعض الأحيان قبل يده، بعضهم قبل قدمه، وثبت أن بعض اليهود قبلوا يده وقبلوا قدمه لكن هذا قليل، فإذا فعله المؤمن مع شيخه، أو مع الإمام الكبير، أو مع العالم، أو مع والده بعض الأحيان فلا بأس، أما اتخاذه طريقة متبعة فلا ينبغي بل يكره، وإنما ينبغي له أن يعتاد المصافحة، وإذا قبل يد العالم أو يد أبيه بعض الأحيان من غير اتخاذه عادة فلا حرج في ذلك إن شاء الله، وأما الحديث الثاني وهو قوله ﷺ: من أحب أن يتمثل له الرجال قياماً فليتبوأ مقعده من النار فهذا حديث صحيح، ولا يجوز للمؤمن أن يحب ذلك لنفسه، أن الناس يقومون له وينتصبون له تعظيماً له، لا يجوز له أن يحب ذلك، لكن إذا قام إليه أخوه وقابله وأخذ بيده وصافحه فلا بأس بذلك.\nوقد ثبت عنه ﷺ أنه قال للأنصار أو للصحابة جميعاً لما قدم سعد للحكم في بني قريظة: قوموا إلى سيدكم يعني: للسلام عليه والترحيب به، فالقيام إلى الشخص للترحيب به ومصافحته وإنزاله من دابته أو إنزاله في المجلس، كل هذا لا بأس به، وثبت أيضاً في الصحيحين أن طلحة بن عبيد الله التيمي ، أحد العشرة المشهود لهم بالجنة لما جاء كعب يوم تاب الله عليه ودخل المسجد والناس حول النبي ﷺ قام إليه طلحة يهرول، فصافحه وهنأه بتوبة الله عليه، ولم ينكر ذلك النبي عليه الصلاة والسلام، وكان النبي ﷺ يقوم إلى فاطمة إذا دخلت عليه، فيصافحها ويقبلها ويجلسها في مكانه، وكانت تقوم إليه إذا دخل عليها رضي الله عنها وتقبله وتأخذ بيده، كل هذا لا بأس به.\nأما أن يقوم الناس قياماً تعظيماً للشخص عند الدخول فقط فلا ينبغي هذا، كان النبي ﷺ يكره ذلك، وكان الصحابة لا يقومون له لما يرون من كراهته لهذا عليه الصلاة والسلام، أما أن تقوم لمقابلته ومصافحته وإجلاسه في مكانك أو في مكان آخر مناسب، أو تصافحه وتنزله من دابته أو من سيارته وتساعده في ذلك، أو للترحيب به وتكريمه كل هذا لا بأس به. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7663/المشروع-عند-اللقاء-والسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_242/24206.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":9533,"question":"السؤال الثاني يقول فيه: هل يجوز لي أن أتبرع بنقل دم لمريض أوشك على الهلاك وهو على غير دين الإسلام؟","title":"حكم التبرع بالدم لغير المسلمين للضرورة","answer":"الجواب: لا أعلم مانعاً في ذلك؛ لأن الله يقول جل وعلا في كتابه العظيم: لا يَنْهَاكُمُ اللَّهُ عَنِ الَّذِينَ لَمْ يُقَاتِلُوكُمْ فِي الدِّينِ وَلَمْ يُخْرِجُوكُمْ مِنْ دِيَارِكُمْ أَنْ تَبَرُّوهُمْ وَتُقْسِطُوا إِلَيْهِمْ [الممتحنة:8] فالله سبحانه أخبر أنه لا ينهانا عن الكفار الذين لم يقاتلونا ولم يخرجونا من ديارنا أن نبرهم ونحسن إليهم، والمضطر في حاجة شديدة إلى الإسعاف، وقد جاءت أم أسماء بنت أبي بكر الصديق رضي الله تعالى عنها وهي كافرة إلى بنتها أسماء في المدينة في وقت الهدنة بين النبي صلى الله عليه وسلم وبين أهل مكة تسألها الصدقة فاستفتت أسماء النبي ﷺ في ذلك، فأفتاها أن تصلها قال صلي أمك وهي كافرة فإذا اضطر المعاهد أو الكافر المستأمن الذي ليس بيننا وبينه حرب إذا اضطر إلى ذلك فلا بأس بالصدقة عليه من الدم كالميتة كما يأكل من الميتة يأخذ من الدم ما يحصل به إسعافه، وأنت مأجور في ذلك لأنك لا حرج عليك أن تسعف من اضطر إلى الصدقة. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7690/حكم-التبرع-بالدم-لغير-المسلمين-للضرورة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_245/24502.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":9541,"question":"هذه رسالة من المرسلة (م. ص. ع) مصرية تعمل بالمملكة تقول في رسالتها: إنني متزوجة من رجل يعرف الله ويخشاه ويصل رحمه إلا أنه لا يصل عمته؛ وسببه في ذلك هو خوفه من المشاكل لأنها لا تترك أحداً في حاله، وتحاول أن تثير المشاكل بيني وبين أهل زوجي، وفي كثير من الأحيان لا يسلم الناس منها، فزوجي لا يزورها أبداً خوفاً من ذلك، وأنا أقول له بأن عليك أن تزورها وأن تصل رحمك ولو كان في ذلك مشاكل، أفيدونا ما الحكم؟","title":"حكم ترك صلة الرحم لعذر","answer":"الجواب: الزوج ينظر في الأمر إذا كانت عمته تؤذيه وتؤذي أهله وإذا زارها حصل عليه ضرر بذلك فلا حرج عليه؛ لأنها هي القاطعة هي المؤذية فلا حرج عليه، أما إن كان يستطيع صلتها بالمال إن كانت فقيرة أو بالسلام بالهاتف أو بالمكاتبة أو يزورها بالسلام ولكن لا تأتي إلى بيته، يقول: لا تأتينا لأني أخشى من مجيئك مضرة علينا أو أنا أصلك بنفسي فلا حرج عليه، يصلها بنفسه ويحسن إليها وهذا هو الواجب؛ لقول النبي ﷺ: لا يدخل الجنة قاطع رحم، ولقوله ﷺ: ليس الواصل بالمكافي، ولكن الواصل الذي إذا قطعت رحمه وصلها.\nفالواجب عليه أن يصلها بالمال وبالكلام الطيب والزيارة والمكاتبة أو بالهاتف ويكفي هذا، وإذا منعها من بيته لأنها مفسدة بالكلام السيئ أو بالسب أو بالغيبة والنميمة فهو معذور إذا منعها من بيته. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7711/حكم-ترك-صلة-الرحم-لعذر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_246/24610.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":9544,"question":"هذه رسالة من المرسلة (م. ص. ع) مصرية تعمل بالمملكة تقول في رسالتها: إنني متزوجة من رجل يعرف الله ويخشاه ويصل رحمه إلا أنه لا يصل عمته؛ وسببه في ذلك هو خوفه من المشاكل لأنها لا تترك أحداً في حاله، وتحاول أن تثير المشاكل بيني وبين أهل زوجي، وفي كثير من الأحيان لا يسلم الناس منها، فزوجي لا يزورها أبداً خوفاً من ذلك، وأنا أقول له بأن عليك أن تزورها وأن تصل رحمك ولو كان في ذلك مشاكل، أفيدونا ما الحكم؟","title":"حكم ترك صلة الرحم لعذر","answer":"الجواب: الزوج ينظر في الأمر إذا كانت عمته تؤذيه وتؤذي أهله وإذا زارها حصل عليه ضرر بذلك فلا حرج عليه؛ لأنها هي القاطعة هي المؤذية فلا حرج عليه، أما إن كان يستطيع صلتها بالمال إن كانت فقيرة أو بالسلام بالهاتف أو بالمكاتبة أو يزورها بالسلام ولكن لا تأتي إلى بيته، يقول: لا تأتينا لأني أخشى من مجيئك مضرة علينا أو أنا أصلك بنفسي فلا حرج عليه، يصلها بنفسه ويحسن إليها وهذا هو الواجب؛ لقول النبي ﷺ: لا يدخل الجنة قاطع رحم، ولقوله ﷺ: ليس الواصل بالمكافي، ولكن الواصل الذي إذا قطعت رحمه وصلها.\nفالواجب عليه أن يصلها بالمال وبالكلام الطيب والزيارة والمكاتبة أو بالهاتف ويكفي هذا، وإذا منعها من بيته لأنها مفسدة بالكلام السيئ أو بالسب أو بالغيبة والنميمة فهو معذور إذا منعها من بيته. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7711/حكم-ترك-صلة-الرحم-لعذر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_246/24610.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":9843,"question":"تقول هذه السائلة: أنا من بين أخواتي وإخواني أقوم على خدمة والدي والسهر عليه عند مرضه، ولا أنزعج من ذلك وأرتاح وأعلم أن هذا واجب، لكن الوالد جزاه الله خيراً أحياناً يغضب من أبسط الأشياء، ففي أحد الأيام زارنا ضيف وهو زوج أختي وابن خال والدي فأزعجه والدي وأغضبه، فخرج من بيتنا مكسور الخاطر، وحلف أن لا يدخل بيتنا ما دام الوالد حي، في تلك الساعة غضبت على والدي كثيراً وسببت جدتي أم والدي؛ لأنها كانت بخيلة مثل والدي وهي قد ماتت منذ مدة طويلة، فندمت بعد ذلك وتبت إلى الله، وأنا أدعو لها بالمغفرة بعد كل صلاة، لكن أحياناً يعلو صوتي على والدي عندما يغضبني في مثل هذه الأشياء، فهل علي إثم وما هي نصيحتكم لوالدي؟","title":"وجوب تقدير الوالد واحترامه وعدم إغضابه","answer":"الجواب: أولاً: أنت مشكورة ومأجورة على خدمة والدك وهذه من حقه عليك ومن بره، فلك أجر عظيم واصبري وصابري واحتسبي الأجر؛ لأن المريض قد يغضب، قد لا يتحمل بعض الأمور، فينبغي لك أن تصبري وتحتسبي ولا تغضبيه وإن أغضبك تحملي.\nوأما ما فعلت من السب لجدتك فهذا غلط ومنكر، والتوبة بحمد الله فيها الكفاية ما دام تبت وندمت فالحمد لله، فالأموات لا يسبون والأقارب لهم حق، ولاسيما الجدات والآباء لهم حق عظيم، وبرهم من أهم المهمات، فسبك للجدة أمر منكر والحمد لله على التوبة، والرجوع إلى الله سبحانه وتعالى.\nوأما الغضب على والدك فينبغي لك أن تحذريه، ولا تغضبي عليه، ولا تسمعيه إلا الكلام الطيب، فتحملي واصبري، وأبشري بالخير، والمريض قد يغضب من أدنى سبب، فعليك أن تتحملي وأن تصبري وتحتسبي وفقك الله ويسر أمرك وشفى والدك.\nونوصي الوالد إذا كان يسمع هذا الكلام نوصيه بالصبر وسؤال الله العافية، وشكرك على أعمالك الطيبة، وأن لا يزعجك وأن لا يتكلم عليك بما يغضبك، بل ينبغي له أن يراعي جهودك وأعمالك الطيبة، ويشكرك عليها، ويلح في طلب الشفاء والعافية، يسأل ربه الشفاء والعافية. نعم.\nالمقدم: أثابكم الله","link":"https://binbaz.org.sa/fatwas/8018/وجوب-تقدير-الوالد-واحترامه-وعدم-اغضابه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_262/26208.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":9844,"question":"تقول هذه السائلة: أنا من بين أخواتي وإخواني أقوم على خدمة والدي والسهر عليه عند مرضه، ولا أنزعج من ذلك وأرتاح وأعلم أن هذا واجب، لكن الوالد جزاه الله خيراً أحياناً يغضب من أبسط الأشياء، ففي أحد الأيام زارنا ضيف وهو زوج أختي وابن خال والدي فأزعجه والدي وأغضبه، فخرج من بيتنا مكسور الخاطر، وحلف أن لا يدخل بيتنا ما دام الوالد حي، في تلك الساعة غضبت على والدي كثيراً وسببت جدتي أم والدي؛ لأنها كانت بخيلة مثل والدي وهي قد ماتت منذ مدة طويلة، فندمت بعد ذلك وتبت إلى الله، وأنا أدعو لها بالمغفرة بعد كل صلاة، لكن أحياناً يعلو صوتي على والدي عندما يغضبني في مثل هذه الأشياء، فهل علي إثم وما هي نصيحتكم لوالدي؟","title":"وجوب تقدير الوالد واحترامه وعدم إغضابه","answer":"الجواب: أولاً: أنت مشكورة ومأجورة على خدمة والدك وهذه من حقه عليك ومن بره، فلك أجر عظيم واصبري وصابري واحتسبي الأجر؛ لأن المريض قد يغضب، قد لا يتحمل بعض الأمور، فينبغي لك أن تصبري وتحتسبي ولا تغضبيه وإن أغضبك تحملي.\nوأما ما فعلت من السب لجدتك فهذا غلط ومنكر، والتوبة بحمد الله فيها الكفاية ما دام تبت وندمت فالحمد لله، فالأموات لا يسبون والأقارب لهم حق، ولاسيما الجدات والآباء لهم حق عظيم، وبرهم من أهم المهمات، فسبك للجدة أمر منكر والحمد لله على التوبة، والرجوع إلى الله سبحانه وتعالى.\nوأما الغضب على والدك فينبغي لك أن تحذريه، ولا تغضبي عليه، ولا تسمعيه إلا الكلام الطيب، فتحملي واصبري، وأبشري بالخير، والمريض قد يغضب من أدنى سبب، فعليك أن تتحملي وأن تصبري وتحتسبي وفقك الله ويسر أمرك وشفى والدك.\nونوصي الوالد إذا كان يسمع هذا الكلام نوصيه بالصبر وسؤال الله العافية، وشكرك على أعمالك الطيبة، وأن لا يزعجك وأن لا يتكلم عليك بما يغضبك، بل ينبغي له أن يراعي جهودك وأعمالك الطيبة، ويشكرك عليها، ويلح في طلب الشفاء والعافية، يسأل ربه الشفاء والعافية. نعم.\nالمقدم: أثابكم الله","link":"https://binbaz.org.sa/fatwas/8018/وجوب-تقدير-الوالد-واحترامه-وعدم-اغضابه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_262/26208.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":9850,"question":"هذه رسالة من مؤيد محمد الحسيني من الموصل في العراق، يقول الأخ مؤيد في رسالته: بماذا تنصحون الشخص الذي يمشي في طريق فيه محلات لبيع الخمور من الجهتين، هل يلزمه أن يغير طريقه وهل يأثم إذا مشى من قربها؟ أفيدونا أفادكم الله.","title":"حكم المشي في طريق يباع فيه خمر","answer":"الجواب: هذا فيه تفصيل: إن كان له طريق آخر ينبغي أن يسلك الطريق الآخر، لئلا يقع في مشكل، إلا إذا كان يستطيع إنكار هذا المنكر، وأن يدعوهم إلى الله  فليفعل؛ لأن إنكار المنكر من أهم المهمات وواجب، فإذا كان يستطيع إذا سلك الطريق أن ينكر المنكر، ويدعو إلى الله فليفعل، أما إن كان لا يستطيع فينبغي له أن يسلك طرقاً أخرى حتى لا يقع في مشاكل في هذا الطريق، وحتى لا يبتلى بمن يشير عليه بشرب الخمر أو يدعوه إلى شرب الخمر.\nالمقصود: إنه ينبغي له اجتناب هذا الطريق، إلى طريق آخر إذا تيسر ذلك، إلا أن يستطيع إنكار المنكر، فإنه ينكر المنكر ويدعو إلى الله بالحكمة والكلام الطيب، ويبين للناس أن شرب الخمر من المحرمات ومن الكبائر وفيه الوعيد الشديد، كما قال النبي ﷺ: لا يشرب الخمر حين يشربها وهو مؤمن ويقول ﷺ: لا يزني الزاني حين يزني وهو مؤمن، ولا يسرق السارق حين يسرق وهو مؤمن، ولا يشرب الخمر حين يشربها وهو مؤمن يعني: إنه يكون ناقص الإيمان ضعيف الإيمان لو كان إيمانه كاملاً لما فعل.\nفهذا يدل على ضعف إيمانه وقلة إيمانه، ولهذا أقدم على هذه المعاصي، وثبت عنه ﷺ: أنه لعن الخمر وشاربها وعاصرها ومعتصرها، وحاملها والمحمولة إليه، وبائعها ومشتريها، وآكل ثمنها فهي شر وهي أم الخبائث، وثبت عنه أيضاً عليه الصلاة والسلام أنه قال: إن على الله عهداً لمن مات وهو يشرب الخمر أن يسقيه الله من طينة الخبال، قيل: يا رسول الله! وما طينة الخبال؟ قال: عصارة أهل النار أو قال: عرق أهل النار نسأل الله العافية.\nفالخمر شرها كبير، فعليك أن تبتعد عنها وعن أهلها مهما استطعت، إلا إذا كنت منكراً عليهم، مرشداً لهم داعياً لهم إلى الخير، صابراً على أذاهم فلا بأس. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8020/حكم-المشي-في-طريق-يباع-فيه-خمر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_262/26209.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":9853,"question":"هذه رسالة من (ع. غ. ي) مقيم في مكة المكرمة، يقول في رسالته: الوالد يحضر سنوياً لأداء فريضة الحج، وأقوم بواجبي نحوه، والوالدة لا تحضر لكبر سنها كما أرسل لها المصاريف، وأقوم بواجبي نحوها، فهل يلزمني في برها أن أسافر إليها هناك وأطلب منها الرضا والعفو أم لا يلزمني؟","title":"حكم من يبر والدته لكنه لا يزورها","answer":"الجواب: لا يلزمك السفر إليها، ما دمت تبرها وتحسن إليها، وترسل إليها حاجاتها، فأنت مشكور ومأجور ولا يلزمك، لكن إذا طلبتك لمهمة من المهمات ولم ترض إلا بمجيئك فسافر إليها وانظر في أمرها وحاجتها، أما ما دامت سامحةً عنك، وليس هناك ضرورة إلى مجيئك، فلا حرج عليك، والحمد لله. نعم.\nالمقدم: بارك الله فيكم وأثابكم الله.","link":"https://binbaz.org.sa/fatwas/8027/حكم-من-يبر-والدته-لكنه-لا-يزورها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_262/26214.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":9959,"question":"وهذه رسالة وردتنا من سائلة من حلب من سوريا، رمزت لاسمها بـ (و. ع. س) الحقيقة هذه السائلة سألت عن رؤيا رأتها وليس من عادتنا في هذا البرنامج أن نتعرض للرؤى والأحلام، ولكنها ساقت بعد الرؤيا فعلاً ونفذت أمراً فأحببنا أن نعرضها حتى يتبين الحكم في هذا الفعل، تقول السائلة: بأنها تسحرت لصيام الست من شوال، وبعدما صلت الفجر وقرأت بعض القرآن الكريم أغفت في النوم، وتقول: بأنها رأت في المنام ما يلي: أنها أمسكت ورقة بيضاء، وكان أمامها رجل جالس وأمامه طاولة وأعطته الورقة البيضاء وصار الرجل يكتب في الورقة، فرأت الورقة تطير إلى الأعلى وحينئذ سمعت صوتاً يقول: نزل الوحي عدة مرات وبسرعة، فقامت ونظرت إلى السماء فرأت نوراً نازلاً من فوق إلى تحت وبجانبه نور أصغر منه، ورفعت يديها وقالت: يا رب! أولادي، يا رب! أولادي، ثم استيقظت، هذا هو حلمها التي رأت، فهي تقول -بعد هذا-: عندما أفقت في الصباح طلبت من أحد أولادي أن يحضر لي خروفاً ويذبحه، فسألني لماذا فعلت، فقلت له: اذبح الخروف ثم أحكي لك، وفعلاً أتى بالخروف وذبحه وبعدها أخبرته بالأمر، ووزعت لحم الخروف على الناس وتركت جزءاً منه للأكل، فما حكم ذبح الخروف وفقكم الله؟","title":"حكم الذبح من أجل رؤيا في المنام","answer":"الجواب: أما هذه الرؤيا فهي من الشيطان؛ لأن الشيطان يلبس على الناس، ويزعم لهم أشياء قد يجرهم بها إلى أن يدعوا أنهم يوحى إليهم أو أنهم أولياء بهذا الأمر، يعظمون ويغلى فيهم، فالوحي قد انقطع بموت النبي صلى الله عليه وسلم، لما توفي رسول الله ﷺ فهو خاتم النبيين محمد عليه الصلاة والسلام، هو خاتم الأنبياء والوحي قد انقطع، فهذا الذي قيل لها: إن الوحي نزل، هذا كله من الشيطان ليغرها ويلبس عليها دينها، فلا وحي بعد محمد ﷺ، وليس هناك وحي ينزل على الرجال ولا على النساء بعده عليه الصلاة والسلام.\nوهذه رؤيا فيها تلبيس من الشيطان وتغرير من الشيطان، فالواجب عليها عند هذا إذا استيقظت أن تنفث عن يسارها ثلاث مرات تتفل عن يسارها ثلاث مرات وتقول: أعوذ بالله من الشيطان ومن شر ما رأيت ثلاث مرات، ثم تنقلب على جنبها الآخر، فإنها لا تضرها، يقول النبي ﷺ الرؤيا الصالحة من الله، والحلم من الشيطان، فإذا رأى أحدكم ما يكره، فلينفث عن يساره ثلاث مرات وليتعوذ بالله من الشيطان ومن شر ما رأى ثلاث مرات، ثم ينقلب على جنبه الآخر فإنها لا تضره ولا يخبر بها أحداً.\nوأما الخروف فإذا كان قصدها الصدقة، فلا بأس تأكل وتتصدق، وأما هذه الرؤيا ما توجب خروفاً ولا غيره، هذه فيما يظهر لنا من الشيطان للتغرير والتلبيس، فعليها إذا استيقظت أن تنفث عن يسارها ثلاث مرات وتقول: أعوذ بالله من الشيطان ومن شر ما رأيت ثلاث مرات، ثم تنقلب عن جنبها الآخر ولا تخبر بها أحداً ولا تضرها.\nوالخروف إذا كان قصدها به التقرب إلى الله والصدقة على أهلها وعلى غير أهلها فلا بأس، لكن لا من أجل هذه الرؤيا، بل من أراد أن يتقرب بذبيحة إلى الله يذبحها ويتصدق بها على الفقراء في أي يوم في أيام العيد أيام عيد النحر ضحية، أو في غيره لقصد الصدقة يعطي الفقراء والمساكين أو دراهم يوزعها أو طعام يوزعه أو ملابس فلا بأس هذا قربة إلى الله، صدقة على الفقراء والمحاويج قربة إلى الله في أي وقت، هكذا الإهداء إلى الأقارب لصلة الرحم قربة إلى الله عز وجل. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8130/حكم-الذبح-من-اجل-رويا-في-المنام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_265/26508.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":9968,"question":"وهذه رسالة وردتنا من سائلة من حلب من سوريا، رمزت لاسمها بـ (و. ع. س) الحقيقة هذه السائلة سألت عن رؤيا رأتها وليس من عادتنا في هذا البرنامج أن نتعرض للرؤى والأحلام، ولكنها ساقت بعد الرؤيا فعلاً ونفذت أمراً فأحببنا أن نعرضها حتى يتبين الحكم في هذا الفعل، تقول السائلة: بأنها تسحرت لصيام الست من شوال، وبعدما صلت الفجر وقرأت بعض القرآن الكريم أغفت في النوم، وتقول: بأنها رأت في المنام ما يلي: أنها أمسكت ورقة بيضاء، وكان أمامها رجل جالس وأمامه طاولة وأعطته الورقة البيضاء وصار الرجل يكتب في الورقة، فرأت الورقة تطير إلى الأعلى وحينئذ سمعت صوتاً يقول: نزل الوحي عدة مرات وبسرعة، فقامت ونظرت إلى السماء فرأت نوراً نازلاً من فوق إلى تحت وبجانبه نور أصغر منه، ورفعت يديها وقالت: يا رب! أولادي، يا رب! أولادي، ثم استيقظت، هذا هو حلمها التي رأت، فهي تقول -بعد هذا-: عندما أفقت في الصباح طلبت من أحد أولادي أن يحضر لي خروفاً ويذبحه، فسألني لماذا فعلت، فقلت له: اذبح الخروف ثم أحكي لك، وفعلاً أتى بالخروف وذبحه وبعدها أخبرته بالأمر، ووزعت لحم الخروف على الناس وتركت جزءاً منه للأكل، فما حكم ذبح الخروف وفقكم الله؟","title":"حكم الذبح من أجل رؤيا في المنام","answer":"الجواب: أما هذه الرؤيا فهي من الشيطان؛ لأن الشيطان يلبس على الناس، ويزعم لهم أشياء قد يجرهم بها إلى أن يدعوا أنهم يوحى إليهم أو أنهم أولياء بهذا الأمر، يعظمون ويغلى فيهم، فالوحي قد انقطع بموت النبي صلى الله عليه وسلم، لما توفي رسول الله ﷺ فهو خاتم النبيين محمد عليه الصلاة والسلام، هو خاتم الأنبياء والوحي قد انقطع، فهذا الذي قيل لها: إن الوحي نزل، هذا كله من الشيطان ليغرها ويلبس عليها دينها، فلا وحي بعد محمد ﷺ، وليس هناك وحي ينزل على الرجال ولا على النساء بعده عليه الصلاة والسلام.\nوهذه رؤيا فيها تلبيس من الشيطان وتغرير من الشيطان، فالواجب عليها عند هذا إذا استيقظت أن تنفث عن يسارها ثلاث مرات تتفل عن يسارها ثلاث مرات وتقول: أعوذ بالله من الشيطان ومن شر ما رأيت ثلاث مرات، ثم تنقلب على جنبها الآخر، فإنها لا تضرها، يقول النبي ﷺ الرؤيا الصالحة من الله، والحلم من الشيطان، فإذا رأى أحدكم ما يكره، فلينفث عن يساره ثلاث مرات وليتعوذ بالله من الشيطان ومن شر ما رأى ثلاث مرات، ثم ينقلب على جنبه الآخر فإنها لا تضره ولا يخبر بها أحداً.\nوأما الخروف فإذا كان قصدها الصدقة، فلا بأس تأكل وتتصدق، وأما هذه الرؤيا ما توجب خروفاً ولا غيره، هذه فيما يظهر لنا من الشيطان للتغرير والتلبيس، فعليها إذا استيقظت أن تنفث عن يسارها ثلاث مرات وتقول: أعوذ بالله من الشيطان ومن شر ما رأيت ثلاث مرات، ثم تنقلب عن جنبها الآخر ولا تخبر بها أحداً ولا تضرها.\nوالخروف إذا كان قصدها به التقرب إلى الله والصدقة على أهلها وعلى غير أهلها فلا بأس، لكن لا من أجل هذه الرؤيا، بل من أراد أن يتقرب بذبيحة إلى الله يذبحها ويتصدق بها على الفقراء في أي يوم في أيام العيد أيام عيد النحر ضحية، أو في غيره لقصد الصدقة يعطي الفقراء والمساكين أو دراهم يوزعها أو طعام يوزعه أو ملابس فلا بأس هذا قربة إلى الله، صدقة على الفقراء والمحاويج قربة إلى الله في أي وقت، هكذا الإهداء إلى الأقارب لصلة الرحم قربة إلى الله عز وجل. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8130/حكم-الذبح-من-اجل-رويا-في-المنام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_265/26508.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":10003,"question":"تقول عندما تتصل امرأة بالهاتف على إحدى صديقاتها، ويجيب عليها أخو أو أبو هذه الصديقة، هل تقول هذه المرأة: السلام عليكم؟ أم تقول له: فلانة موجودة من غير تحية الإسلام أفيدونا جزاكم الله خيرًا؟","title":"حكم إلقاء المرأة السلام على الرجل الأجنبي","answer":"الجواب: السنة السلام؛ لأن المكالمة كالمقابلة، والمشروع للمؤمن عند لقاء أخيه أو أخته في الله أن يقول: السلام عليكم، أو السلام عليكم ورحمة الله، أو السلام عليكم ورحمة الله وبركاته، فإذا كلمه بالتلفون يبدأ يقول: السلام عليكم، وإن زاد ورحمة الله وبركاته كان أكمل، وذاك يرد عليه ويقول: وعليكم السلام ورحمة الله وبركاته، على ما قال له أخوه، ثم يسأل عن مراده. نعم.\nالمقدم: جزاكم الله خيرًا، هذا إن كان من المرأة للرجل ... ؟\nالشيخ: ولو بين الرجال والنساء، ولو كانت مع أجنبي؛ لأن هذا شرع الله، تقول: السلام عليكم، كان النبي ﷺ يسلم على النساء وهن أجنبيات، هي تقول له: السلام عليكم، ثم تقول: أين فلانة؟ زوجته أو أخته أو أمه، تسأل عنها عن لازمها، وإن كان تستفتي تسأل تقول: السلام عليكم، وتسأل عن حاجتها إن كانت تسأل عالمًا، تستفتي تقول: السلام عليكم أولًا ثم تسأل.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8169/حكم-القاء-المراة-السلام-على-الرجل-الاجنبي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_331/33108.mp3","categories":["الحقوق الزوجية","الآداب والأخلاق المحمودة","قضايا المرأة"]},{"id":10031,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يسأل ويقول: إذا طلبت الوالدة مني بعض الطلبات العادية ورفضت أن أجيبها في ذلك فهل أكون عاقاً؟","title":"حكم مخالفة أمر الوالدين في المعروف","answer":"الجواب: نعم، إذا طلبت الطلبات العادية التي هي تحتاجها طلبت منك أن تحضر حاجة المنزل، من طعام أو إدام أو غير ذلك ترك ذلك وعدم طاعتها في هذا من العقوق، أو طلبت منك أن تذهب إلى كذا لأجل تبلغه رسالة منها إلى أخيها إلى أبيها إلى زوجها في الدكان وعصيتها يكون هذا أيضاً من العقوق، فالسمع والطاعة للوالدة في المعروف وللوالد كذلك من البر، والعصيان لهما من العقوق ولو في الأمور العادية، كذلك لو طلبت منك أن تأتي بحاجة من البيت أو تحضر الغداء الموجود تقدمه في المحل الفلاني أو العشاء، أو تذهب للضيف بكذا أو تعطي الضيف مطلوبه من كذا، كل هذا واجب عليك أن تقوم به، طاعة للوالد والوالدة وليس لك أن تعصيهما في هذا، أما إذا أمراك بشيء منكر فلا إذا أمراك أن تدخن أو أمراك أن تأتي لهم بدخان أو خمر هذا لا يجوز لك ليس لك أن تطيعهما في المعصية إنما الطاعة في المعروف، أما إذا أمراك بشيء مباح أو شيء مطلوب فالواجب أن تسمع وتطيع مع القدرة. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8208/حكم-مخالفة-امر-الوالدين-في-المعروف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_301/30111.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":10096,"question":"هل عيادة المريض واتباع الجنائز واجب أم سنة لأنه يبدو من الأحاديث أنها صحيحة؟","title":"حكم عيادة المريض واتباع الجنائز","answer":"الجواب: الصحيح الأحاديث في هذا صحيحة ومستفيضة عن النبي ﷺ، والمعروف عند العلماء أنها سنة مؤكدة والقول بالوجوب قول قوي؛ لأن الرسول ﷺ أمر بالعيادة للمرضى فأقل شيء مرة واحدة فينبغي للمؤمن إذا عرف أخًا له مريض أن يعوده، قال الرسول ﷺ: عودوا المريض، وأطعموا الجائع، وفكوا العاني، أخرجه البخاري في الصحيح، وقال عليه الصلاة والسلام: للمسلم على المسلم ست خصال: إذا لقيته فسلم عليه، وإذا دعاك فأجبه، وإذا استنصحك فانصحه، وإذا عطس فحمد الله فشمته، وإذا مرض فعده وإذا مات فاتبعه، فعيادة المرضى من آكد العبادات. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8265/حكم-عيادة-المريض-واتباع-الجناىز","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_333/33309.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":10179,"question":"جزاكم الله خيراً! هل الرد على المسلم والإجابة على الأسئلة أثناء الوضوء جائزة؟","title":"حكم رد السلام والكلام أثناء الوضوء","answer":"الجواب: لا حرج، إذا كان في غير محل قضاء الحاجة، محل خارج عن قضاء الحاجة يُسلِّم ويُسلَّم عليه ويجيب عن الأسئلة، وهو في محل الوضوء لا في محل قضاء الحاجة. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8342/حكم-رد-السلام-والكلام-اثناء-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_308/30803.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":10248,"question":"الرسالة الثانية هي رسالة سبق وأن عرضنا بعضًا من أسئلتها في حلقة مضت وهي رسالة الأخت (ع. م. الخطيب) من الضفة الغربية بفلسطين، بعثت بهذه الرسالة وضمنتها عددًا كبيرًا من الأسئلة عرضنا بعضًا منها في حلقات مضت، وفي هذه الحلقة تعرض بعض الأسئلة، فتقول في سؤالها الأول: إذا غلب الإنسان التثاؤب في الصلاة، هل يسكت حتى يذهب التثاؤب أم يستمر في الذكر والقرآن؟","title":"آداب التثاؤب","answer":"الجواب: السنة للمؤمن إذا حصل له التثاؤب أن يكظم ما استطاع، أن يكظم فمه ما استطاع، وأن يضع يده على فيه ولا يقل: هاه ولا يفتح فاه، هكذا نهى النبي ﷺ وأمر، أمر بوضع اليد على الفم وأن يكظم ما استطاع، وقال: لا يقل: هاه؛ فإن الشيطان يدخل في فيه ولكن يكظم ما استطاع ويضع يده على فيه ولا يتكلم بشيء حتى ينتهي، لا يقرأ ولا يتكلم حتى ينتهي التثاؤب، هذا هو المشروع، إذا حصل التثاؤب يشرع له أمور عدة.\nالأمر الأول: أنه يكظم ما استطاع يعني: يضم فمه ما استطاع حسب الطاقة.\nالثاني: أنه يضع يده على فيه.\nالثالث: أنه لا يقول: هاه، بل يحفظ لسانه ولا يتكلم بشيء لا قليل ولا كثير، هكذا السنة التي جاءت عن النبي عليه الصلاة والسلام، وبذلك يعلم أنه لا يقرأ ولا يحدث أحدًا، ولا يتكلم بشيء حتى ينتهي التثاؤب؛ لأنه قد يتكلم بشيء غير مضبوط إذا كان معه التثاؤب، يغلبه التثاؤب فيكون كلامه غير مضبوط، فلا يتكلم حتى ينتهي. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8418/اداب-التثاوب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_336/33602.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":10257,"question":"سؤال أخير في نهاية الحلقة يقول: هل يجوز زيارة الأئمة والصالحين؟ وما هي الكلمات التي تقال عند زيارتهم أفيدونا جزاكم الله خيرًا؟","title":"حكم زيارة الأئمة والصالحين","answer":"الجواب: التزاور في الله سنة وقربة، يقول النبي ﷺ: يقول الله : وجبت محبتي للمتزاورين في والمتحابين في والمتجالسين في والمتباذلين في.\nفالتزاور في الله فيه خير كثير ومصالح كثيرة زاره سلم عليه وصافحه ودعا له، كل واحد يدعو للآخر، وإذا حدث لديه وآنسه بالحديث الطيب والمذاكرة فيما ينفعهم جميعًا في دينهم ودنياهم هذا من تمام الزيارة، وإذا أعانه على شيء مما يحتاج إليه في أمور دينه ودنياه ......... المحبة ...... الزيارة ولا أعلم شيئًا خاصًا يفعله الزائر سوى السلام ...... والدعاء له بالتوفيق والصلاح والهداية والاستقامة.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8430/حكم-زيارة-الاىمة-والصالحين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_336/33609.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":10303,"question":"له سؤال آخر يقول: هنالك شخص يطل علينا بين الحين والآخر، لكنه يكرر السب والشتم، فهل يجوز معه أكل الطعام وغيره؟","title":"حكم مجالسة من ديدنه السب والشتيمة","answer":"الجواب: هذا مثل ما تقدم، ينصح ويوجه إلى الخير لعله يستجيب وإلا فأبعدوه عنكم ولا يكون معكم؛ لأن مثل هذا يضر، ما دام سباباً لعاناً ينبغي إبعاده، فإذا لم تستطيعوا إبعاده فابتعد أنت عنه ما دام يعلن سبه وشتمه معكم على الطعام وفي المجالس ينبغي أن لا تحضره إلا إذا كان حضورك ينفع في ردعه عن باطله وفي إسكاته عن هذه الجرائم، أو يساعدك الإخوان عليه حتى يسكت فأنت في جهاد وعمل صالح.\nأما إذا كانوا لا يساعدونك بل يبقى يسب ويتكلم ويلعن ويفعل الأشياء القبيحة والكلام السيئ، مثل هذا المجلس ينبغي أن تهجره حتى يزول منه هذا الرجل. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8465/حكم-مجالسة-من-ديدنه-السب-والشتيمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_312/31205.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":10350,"question":"الزواج بغير موافقة الوالد؟","title":"الزواج بغير موافقة الوالد","answer":"الجواب: المشروع للمؤمن أن يتحرى موافقة الوالد لأن بره من الواجبات، وكذلك الوالدة تشاورهم .... لأن الوالد ما بداله والد والمرأة بدالها مرأة النساء كثير والولد كذلك، فإذا وجد امرأة صالحة طيبة فلا مانع من أن يستشير الوالد ويكثر عليه في ذلك ويطلب من الإخوان الطيبين أن يشيروا عليه حتى يوافق؛ لأن المرأة الصالحة ما ينبغي ردها ولا ينبغي تركها، ولا ينبغي لوالده أن يمنعه من ذلك ولا حرج في الزواج بها ولو لم يرض الوالد لقوله ﷺ: إنما الطاعة في المعروف، والزوجة الصالحة من المعروف، لكن مهما استطاع أن يرضيه أو يلتمس امرأة صالحة غيرها حتى لا تفوت الفرصة فهذا هو الأولى جمعاً بين المصلحتين، بين بره وبين تحصيل المرأة الصالحة مهما أمكن فإن لم يتيسر ذلك وخاف فوتها وهي امرأة صالحة مشهود لها بالخير فلا حرج عليه إن شاء الله في الزواج بها وإن لم يرض والده، وفي إمكان والده بعد ذلك أن يرضى والغالب أن الوالد الطيب لا يكره المرأة الصالحة، فإذا كرهها فلا بد أن هناك شيئاً أوجب الكراهة.\nفلا ينبغي للولد أن يعجل بل ينبغي له أن يتريث ويعرف الأسباب ويستعين على رضا والديه إذا كان ما هناك أسباب تمنع من زواجها يستعين عليه بأعمامه وإخوانه وجيرانه الطيبين حتى يرضى إن شاء الله، لا يعجل في الزواج بغير رضاه مهما أمكن إلا بعد الطمأنينة إلى أنه ليس هناك ما يمنع الزواج وأنه تعنت من أبيه لأن أباه رجل غير صالح لا يريد الصالحات فهذا خطأ عظيم. نعم.","link":"https://binbaz.org.sa/fatwas/8534/الزواج-بغير-موافقة-الوالد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_316/31613.mp3","categories":["الآداب والأخلاق المحمودة","شروط وأركان الزواج"]},{"id":10409,"question":"إذا ابتدأ الرجل المرأة بالسلام هل ترد عليه أم لا؟","title":"حكم إلقاء السلام على المرأة","answer":"الجواب: نعم ترد عليه، وهكذا لو بدأته يرد عليها، فإن الأحاديث عامة والآية الكريمة عامة وَإِذَا حُيِّيتُمْ بِتَحِيَّةٍ فَحَيُّوا بِأَحْسَنَ مِنْهَا أَوْ رُدُّوهَا [النساء:86]، فإذا قالت: السلام عليكم، يقول: وعليكم السلام، وإذا قال: السلام عليكن ... النساء، كان إذا مر على النساء سلم عليهن عليه الصلاة والسلام، فإذا سلم على النساء يردن يقلن: وعليكم والسلام، أو يزيدون ورحمة الله، أما إن قال: السلام عليكم ورحمة الله فإنهم يلزمهم أن يقولوا: وعليكم السلام ورحمة الله مثلما قال، لأن الله قال: أَوْ رُدُّوهَا فردها واجب والزيادة مستحبة، فإذا قال: السلام عليكم ورحمة الله وجب أن يقول المسلم عليه: وعليكم والسلام ورحمة الله، فإن كملها وبركاته صار أفضل، زاده خيراً. نعم.\nالمقدم: جزاكم الله خيراً وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8582/حكم-القاء-السلام-على-المراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_280/28012.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":10479,"question":"يقول: إن لي خالة أخت أمي ولها زوج ولها ابن يكرهونني، وأنا لا أريد أن أنقطع عن زيارتها؛ لأنها بمثابة والدتي، فهل يجوز أن أدخل منزلهم دون إذن منهم، أو أقوم بزيارتها خارج منزلها؟","title":"كيفية زيارة الخالة الممنوع من دخول البيت عليها","answer":"الجواب: يشرع لك زيارتها خارج منزلها، والمكالمة بالهاتف، والوصية بالسلام والدعاء لها بالتوفيق والهداية، والمصالحة مع زوجها بالكلام الطيب حتى يأذن لك، وليس لك دخول بيته إلا بإذنه، لكن عليك المخاطبة الطيبة، واستعمال الكلام الطيب مع الزوج، والدعاء له بالتوفيق، وطلب السماح أن تزور خالتك بالكلام الطيب، وهكذا مع الابن تجتهد في إصلاح الحال مع الابن بالكلام الطيب، والأسلوب الحسن، والاعتذار إليهم إن كنت أخطأت عليهم تعتذر إليهم حتى يسمحوا، والمؤمن هكذا يجتهد في أسباب الخير، ويبتعد عن أسباب الشر. نعم.\nالمقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8654/كيفية-زيارة-الخالة-الممنوع-من-دخول-البيت-عليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_281/28106.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":10506,"question":"ما هو حد الإسراف في المأكل والمشرب والملبس وفرش المنزل؟","title":"ضابط الإسراف في الحاجيات","answer":"الجواب: الإسراف هو الذي يزيد عن الحاجة التي جرت بها العادة، ولا يكون له مصرف من الطعام يلقى في الزبالة أو شيء إذا كان هناك مصرف للفقراء أو للطيور أو للحيوانات فليس بإسراف إذا كان فضل شيء، أما كونه يتعمد زيادة الطعام على وجه لا مصرف له هذه يسمى: إسراف وتبذير، وهكذا في غيرها من الأشياء الفرش وغيرها إذا كان ليست لها حاجة يكون إسراف، بل يعتني بالفرش التي جرت العادة بمثلها جمال وزينة وتستر، والشيء الذي لا حاجة له لا يكلف نفسه به، إذا كان إحضاره أو شراءه يعتبر تبذير، يعني لا وجه له ولا حاجة له، فينبغي أن يحفظ المال، إلا إذا اشترى المتاع اللي يحفظه لوقت الحاجة، يحفظه عنده لوقت الحاجة، فلا بأس.\nالمقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8681/ضابط-الاسراف-في-الحاجيات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_282/28214.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":10543,"question":"السائلة من الأردن استعرضنا بعضًا من أسئلتها في حلقة سابقة، وفي بداية هذه الحلقة بقي لها سؤال تقول سماحة الشيخ: من هم الرحم الذين على الفتاة المسلمة واجب أن تصلهم؟ وهل يسقط عنها هذا الواجب إذا قام به أخوها الرجل فقط، هذه السائلة أم مصطفى من الأردن؟","title":"الرحم الذين يجب صلتهم للرجل والمرأة ومراتبهم","answer":"الجواب: الرحم كل القرابات رحم، لكن أقربهم الأصول والفروع، الآباء والأمهات والأجداد والجدات والأولاد وأولادهم هؤلاء أقرب الرحم، ثم الإخوة ثم بنوهم أولاد الإخوة، ثم الأعمام وأولادهم وهكذا الأقرب فالأقرب؛ ولهذا لما سئل النبي ﷺ قال له السائل: من أبرر يا رسول الله؟ قال: أمك، قال: ثم من؟ قال: أمك، قال: ثم من؟ قال: أمك، قال: ثم من؟ قال: أباك، ثم الأقرب فالأقرب فالصلة تكون للأقرب فالأقرب، بالمال وبالكلام الطيب وبالزيارة بالأسلوب الحسن بالسؤال عن حاله كل هذا نوع من الصلة. والحمد لله، نعم.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/8718/الرحم-الذين-يجب-صلتهم-للرجل-والمراة-ومراتبهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_284/28415.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":10553,"question":"السائل يقول: ما رأيكم فيمن يسمي بأسماء من القرآن، مثل: آلاء وآية وبيان وغيرها حيث كثرت في زماننا هذا سماحة الشيخ؟!","title":"حكم من يسمي بأسماء من القرآن كـ: (آلاء، وآية..)","answer":"","link":"https://binbaz.org.sa/fatwas/8723/حكم-من-يسمي-باسماء-من-القران-كـ-الاء-واية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_285/28501.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":10716,"question":"ما حكم غيبة العاصي -يا سماحة الشيخ- هذا السائل عبد الله إبراهيم - سوريا؟","title":"حكم غيبة العاصي","answer":"الجواب: العاصي إن كان قد أعلن المعصية لا غيبة له في المعصية التي أعلنها وجاهر بها، كالمجاهرة بحلق اللحية، والمجاهرة بشرب الخمر، فإذا ذم بذلك فلا غيبة له، أما إذا كان سرًا لا يجهر بها بينه وبين أهل بيته فلا يجوز اغتيابه، بل يجب الحذر من ذلك والستر عليه. نعم.","link":"https://binbaz.org.sa/fatwas/8885/حكم-غيبة-العاصي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_286/28602.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":10755,"question":"يسأل أيضاً ويقول: عندما كنت أدرس القرآن على يد أحد المشايخ في بلدنا، وعدت ابنه وعمره خمس سنوات أن أحضر له دبابة، ثم سافرت إلى المملكة وانشغلت بالعمل وطالت المدة دون أن أفي بهذا الوعد، وكبر الطفل الموعود حتى أصبح رجلاً، فهل يجب علي الوفاء بهذا الوعد؟ وهل يكون كما وعدت كما نص عليه الوعد، أم بما يعادل قيمته من السلع التي تناسب سنه، أفيدوني جزاكم الله خيراً؟","title":"حكم من وعد طفلاً بهدية فكبر الطفل ولم يعطه","answer":"الجواب: إذا أوفيت بالوعد يكون حسناً وطيباً، وإلا فالقواعد الشرعية في مثل هذا أنه لا يلزمك؛ لأن محله وقت الطفولة، والعادة في مثل هذا التسامح بين الناس، وإذا كان ما تيسر لك وقت الطفولة فلا حرج عليك والحمد لله، لكن إن أعطيته شيئاً وكتبت له وراسلته وأعطيته شيئاً في مقابل هذا الوعد فهذا حسن، من باب مكارم الأخلاق. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8936/حكم-من-وعد-طفلا-بهدية-فكبر-الطفل-ولم-يعطه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_347/34706.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":10843,"question":"هناك استطلاعات صحفية سماحة الشيخ تقول: إن هجر الأقارب كثير في هذه الأيام، لا بد لسماحتكم من رأي حول الطريق الأمثل؛ لأن تعود الصلة بين الأقارب؛ ولأن يتزاور الناس، ويحيوا صلتهم الاجتماعية.","title":"علاج ظاهرة هجر الأقارب","answer":"الجواب:  على كل حال هذا من حق أهل العلم، وأهل النصح إذا عرفوا جماعة متهاجرين، أقارب، أو غير أقارب، أو جيرانًا نصحوهم، هكذا المؤمن ينصح إخوانه، سواء كان من أهل العلم، أو من خواص المؤمنين، أو من عامة المؤمنين ينصح من عرف أنه قد هجر أخاه، أو بينهم شحناء، ينصحهم، ويزورهم مع من تيسر من إخوانه إذا كانوا جماعة، يكونون أحسن؛ لأن الجماعة كلمتهم أنفع، فإذا اجتمع مع اثنين ثلاثة من أقاربهم، أو جيرانهم وزاروهم ونصحوهم حتى تزول الهجرة، وحتى تحل المودة بدل الشحناء هذا حق المسلم أخو المسلم، والرسول  يقول: الدين النصيحة قيل: لمن يا رسول الله؟! قال: لله ولكتابه ولرسوله ولأئمة المسلمين وعامتهم. والتهاجر لا يجوز، يقول ﷺ: لا يحل لمسلم أن يهجر أخاه فوق ثلاث، يلتقيان، فيعرض هذا ويعرض هذا، وخيرهما الذي يبدأ بالسلام وقال: لا تحاسدوا ولا تناجشوا ولا تدابروا ولا يبع بعضكم على بيع بعض، وكونوا عباد الله إخوانًا، المسلم أخو المسلم لا يظلمه، ولا يحقره، ولا يكذبه، ولا يخذله، التقوى ها هنا، وأشار إلى صدره ثلاث مرات، بحسب امرئ من الشر أن يحقر أخاه المسلم، كل المسلم على المسلم حرام دمه وماله وعرضه. والمقصود: أن التهاجر شره عظيم. فالواجب على الأقارب والجيران والأصدقاء أن يحلوا مشاكلهم، وأن يجتهدوا في إزالة أسباب الشحناء والعداوة والهجر بالطرق التي يستطيعونها، ولا يكلف الله نفسًا إلا وسعها. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9030/علاج-ظاهرة-هجر-الاقارب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_356/35611.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":10895,"question":"هذا السائل سعد محمد إبراهيم مصري الجنسية، يقول: والدي قد توفي منذ عشرين سنة، ولكن للأسف لم أكن بارًا به، فقد كنت أعامله معاملة قاسية جدًا، مع أنني محافظ على الصلوات، ومحافظ على عمل الخيرات، وأنا الآن نادم على ما فعلت، فهل لي من توبة؟ أرجو إرشادي -سماحة الشيخ- وكيف أفعل من أجل أن يغفر الله لي؟ وجزاكم الله خيرًا.","title":"كيفية توبة من لم يكن باراً بأبيه","answer":"الجواب:  عليك الترحم عليه والاستغفار له، وسؤال الله أن يسامحك، ويعفو عنك عما قصرت فيه، والصدقة عنه، والحج عنه، والعمرة، وفعل الخيرات، وأنت على خير، مع التوبة والندم، التوبة إلى الله، والندم مما حصل منك من التقصير، وسؤال الله أن يعفو عنك -جل وعلا- ومع ذلك تفعل الخيرات، تترحم عليه، تدعو له، تستغفر له، تتصدق عنه، تحج عنه، تعتمر عنه، كل هذا طيب.  المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/9072/كيفية-توبة-من-لم-يكن-بارا-بابيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_286/28609.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":10975,"question":"آخر سؤال للسائل من القصيم (أ. ص. ع) يقول: ما حكم الاستعاذة عند التثاؤب، وهل ورد دليل على ذلك؟","title":"حكم الاستعاذة عند التثاؤب","answer":"الجواب:  لا حرج فيها؛ لأنها من الشيطان، لكن لم يرد شيء يدل على استحبابها، لكن أخبر النبي ﷺ أن التثاؤب من الشيطان، فإذا تثاءب أحدكم فليكظم ما استطاع وفي اللفظ الآخر: فليضع يده على فيه فهذا يدل على أنه من الشيطان، فإذا قال: أعوذ بالله من الشيطان الرجيم فلا بأس، لكن لم يرد في هذا شيء عن النبي ﷺ إنما أمر بالكظم، يعني ضم الفم، وعدم فغره، وكذلك وضع اليد على الفم، كل هذا مستحب؛ لأن الشيطان إذا فغر فاه يضحك منه، فالسنة أن يكظم ما استطاع، وأن يضع يده على فيه هذا هو السنة، وإذا قال: أعوذ بالله من الشيطان فلا حرج، إن شاء الله. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/9153/حكم-الاستعاذة-عند-التثاوب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_286/28619.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":10985,"question":"يقول هذا السائل: هل ذكر المسلم في غيبته بمدح، أو ثناء عليه، أو ذكر لحاله، كصحته، أو عافيته، أو فقره أو غناه، هل هذا من الغيبة؟ وهل إذا ذكرناه في أنفسنا بشيء يكرهه، هل يجب منا أن نعتذر منه؟ وإذا لم نستطع ماذا علينا؟ أفيدونا سماحة الشيخ.","title":"حكم ذكر المسلم في غيبته بثناء وخير","answer":"الجواب:  أما ذكر الإنسان بما يحبه ويرضاه هذا ليس بغيبة، كونه يقال عنه: إنه طيب، وإنه محافظ على الصلوات، وإنه من الأخيار، هذا ليس بغيبة هذا ثناء، ولا حرج في ذلك، وإنما الغيبة ذكرك أخاك بما يكره كما قاله النبي ﷺ الغيبة ذكرك أخاك بما يكره هذه الغيبة، بخيل.. جبان.. بذيء اللسان.. وما أشبه ذلك مما يكره، هذه هي الغيبة. وإذا اغتاب الإنسان أخاه الواجب عليه أن يعتذر إليه، ويقول: سامحني -جزاك الله خيرًا- أنا وقعت في عرضك، فإن خاف من شر، وأن يترتب عليه شر، يستغفر له، ويدعو له، ويذكره بمحاسنه التي يعلمها عنه في المواضع التي ذمه وعابه فيها، ويكفي هذا والحمد لله. وإذا استهزأ بلسانه فهو مستهزئ إذا استهزأ بالدين فهو كافر ولو ما عنده أحد، إذا استهزأ فعليه التوبة إلى الله، والرجوع إلى الحق، ومن تاب تاب الله عليه. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/9163/حكم-ذكر-المسلم-في-غيبته-بثناء-وخير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_287/28706.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":10995,"question":"أسألكم عن التسمية بهذه الأسماء: إيمان؟الشيخ: غير إيمان، في عندكم أسماء أخرى.المقدم: حمد النيل.الشيخ: حمد النيل.المقدم: نعم.","title":"حكم التسمية بإيمان وحمد النيل","answer":"الجواب:  أما إيمان فلا نعلم فيها بأسًا، مثل نافع وصالح وعامر، أسماء غير مقصوده، المقصود: الاسم اللفظ، حمد النيل ما نعرف معناه، حمد النيل ما نعرفه، حمد النيل، ما أعرف معناه حمد النيل، هذه الكلمة محل نظر، والنيل لا يحمد إذا الشط، شط النيل، الماء إن كان قصده النهر، حمد النيل ما له حمد خاص النيل، فلا ينبغي التسمية بهذا الاسم، نعم.","link":"https://binbaz.org.sa/fatwas/9175/حكم-التسمية-بايمان-وحمد-النيل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_365/36509.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":11256,"question":"يقول: هل يجوز أخذ شيء دون علم صاحبه، علمًا بأن صاحب الشيء رامٍ به في سلة المهملات بمعنى: أنه لا يحتاج إليه؟","title":"حكم أخذ شيء بدون إذن صاحبه إذا استغنى عنه","answer":"الجواب:  إن كان أراد به الحفظ محلًا يحفظ فيه فلا يجوز إلا بإذنه، أما إذا كان في محل مثل القمامة قد انتهى منه ولا يأخذه ولا يرغب فيه، فلمن أراد أخذه الأخذ، أما إذا كان المحل تحفظ فيه الحاجات ولو كان فيه تساهل، لكنه ليس بتارك لهم، وطايبة نفسه به، بل إنما يجعله فيه لوقت ما، فلا بد من استئذانه وموافقته. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9444/حكم-اخذ-شيء-بدون-اذن-صاحبه-اذا-استغنى-عنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_374/37417.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":11389,"question":"تقول: هناك امرأة تسكن معنا في البيت، وأنا على خلاف معها، وذلك بسبب أنها تسعى إلى تشويه صورتي عند الجيران بكثرة حديثها، وقد نصحتها، وفي الأخير هجرتها؛ وذلك لما يلحقني أنا وأطفالي منها، وأنا ولله الحمد ملتزمة بأمور ديني، فبماذا تنصحونني؟ جزاكم الله خيرًا.","title":"حكم هجر من يحصل الضرر بوصاله","answer":"الجواب:  إذا كانت تفعل ضدك ما يضرك، ولم تقبل النصيحة؛ فلا بأس بهجرها لظلمها، أما إذا كنت لا تعلمين ذلك إنما ذلك أوهام وظنون؛ فلا يجوز لك الهجر، وعليك التسامح والدعاء لها بالهداية، أما إذا كنت تعلمين أنها تسبك، أو تغتابك يقينًا، وتشوه سمعتك، ولم تنتصح، ولم تقبل منك؛ فإنها تستحق أن تهجر.  المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9556/حكم-هجر-من-يحصل-الضرر-بوصاله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_379/37905.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":11464,"question":"يسأل عن ميزان العفة في الشرع؟","title":"ميزان العفة في الشرع","answer":"الجواب:  العفة ميزانها الوجوب، يجب على المؤمن أن يعف عما حرم الله عليه وجوبًا عن الزنا والخمر وجميع المعاصي، هذا ميزانها في الشرع، وجوب الكف عما حرم الله، الله -جل وعلا- أوجب على عباده أن يكفوا عن محارم الله، وأن يؤدوا فرائض الله  فعلى العبد أن يؤدي الفرائض، ويجتنب المحارم، يقول الله -جل وعلا-: وَمَا آتَاكُمُ الرَّسُولُ فَخُذُوهُ وَمَا نَهَاكُمْ عَنْهُ فَانْتَهُوا [الحشر:7]، ويقول سبحانه: وَلا تَقْرَبُوا الْفَوَاحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ [الأنعام:151]، يعني: المعاصي، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9645/ميزان-العفة-في-الشرع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_381/38119.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":11483,"question":"يسأل متى يجوز الكذب؟","title":"الأحوال التي يجوز فيها الكذب","answer":"الجواب:  النبي ﷺ رخص الكذب في أحوال ثلاث: في الحرب، على العدو على وجه ليس فيه غدر، كذب ليس فيه غدر. الثاني: في الإصلاح بين الناس، تصلح بين قبيلتين، أو بين جماعتين فيكذب على هذه وهذه كذبًا؛ لا يضر أحدًا لمصلحتهم هم، لا يضر أحدًا من الناس فلا بأس. والثالث: في حديث الرجل امرأته والمرأة زوجها، لما ثبت في الصحيح عن أم كلثوم بنت عقبة بن أبي معيط -رضي الله عنها- عن النبي ﷺ أنه قال: ليس الكذاب الذي يصلح بين الناس فيقول خيرًا، وينمي خيرًا، قالت: ولم أسمعه يرخص في شيء من الكذب إلا في ثلاث: الحرب، والإصلاح بين الناس، وحديث الرجل امرأته والمرأة زوجها في هذه الثلاث فقط. فإذا أراد أن يصلح بين شخصين، أو جماعتين، أو قبيلتين، وكذب قال لهذه: إن القبيلة الثانية تدعو لكم، وتثني عليكم، وتحب الصلح معكم، ثم أتى الأخرى وقال لها مثل ذلك لقصد الإصلاح؛ فلا بأس؛ لأن هذا لا يضر أحد، ينفعهم ولا يضرهم. وهكذا في الحرب إذا أراد الغزوة، ورى بغيرها، النبي ﷺ كان إذا أراد الغزوة، ورى بغيرها يقول للناس إنه متوجه للجنوب، وهو متوجه للشمال، حتى يهجم على العدو على غرة، إذا كان العدو قد بلغ، ودعي، وأبى، وأصر على الكفر؛ فلا بأس أن يخدعه حتى يهجم عليه على غرة، وهكذا لو كان العدو متحصنًا لم يخرج يرمي من داخل الحصون، فأحب أمير الجيش أن يخرج للعدو حتى يحكم الله بينهم وبينه، فأمر الجيش أن يرتحلوا، وأظهر أنهم منصرفون يعني: قافلون لعل العدو يخرج، فقال: نرتحل، نتوجه إلى البلد نرتحل، وهو ما هو بمرتحل لكن يريد أن يسمع العدو بالخبر حتى يخرج، حتى يكر عليه فيقاتله، فإذا قال هذا، فهذا الكذب لا بأس به؛ لأنه مصلحة الجهاد، وليس فيه غدر بالعدو، العدو يضرب يقاتل، ولكن فيه حيلة للمسلمين حتى يهجموا على عدوهم، وحتى يأخذوا حقهم منه، قد ثبت عنه ﷺ: أنه أغار على بني المصطلق، وهم غارون، فقتل مقاتلتهم، وسبى ذرياتهم؛ لأنهم نصحوا، دعوا فلم يستجيبوا، فهجم عليهم، عليه الصلاة والسلام. وهكذا المرأة مع زوجها والزوج مع امرأته يحتاجوا إلى هذا الشيء، الزوج يحتاج والزوجة تحتاج، فقد يغضب عليها، وقد تغضب عليه، فيحتاج إلى الكذب، كل واحد منهما، فيقول لها: سوف أشتري لك كذا وكذا، سوف أفعل كذا، سوف ننتقل في بيت ..... ، سوف أفعل كذا، أشياء ما تضر أحدًا بينهما، لمصلحتهما هم، لا بأس، أو تقول له: سمعًا وطاعة، أنا ما عاد أعصيك أبدًا، وهي تكذب، وأنا سوف أفعل هذا، وسوف أصنع الطعام الفلاني، وسوف أفعل كذا وكذا شيئًا بينهما لا يضر أحدًا من الناس؛ فلا بأس بذلك للصلح، وجمع الكلمة، وإزالة الشحناء، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9664/الاحوال-التي-يجوز-فيها-الكذب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_382/38210.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":11539,"question":"أخيرًا يسأل عن اتجاه السرير إلى جهة القبلة سرير النوم، هل هو واجب أم أنه من السنة؟","title":"حكم توجيه سرير النوم إلى القبلة","answer":"الجواب:  ليس بواجب، إن شاء نام إلى القبلة، وإن شاء إلى غيرها، الحمد لله الأمر واسع. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9722/حكم-توجيه-سرير-النوم-الى-القبلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_295/29505.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":11542,"question":"آخر سؤال لأختنا يقول: لي مدة طويلة لم أزر فيها أقاربي؛ لأن أبي يمنعنا أنا وإخوتي من الخروج من البيت إلا لطلب العلم، فهل علي إثم في مقاطعتهم تلك المدة؟ وكيف السبيل إلى زيارتهم إذا كان أبي يمنعنا من ذلك، وأنا لا أدري ما هو السبب؟ جزاكم الله خيرًا.","title":"حكم زيارة الأقارب وصلة الرحم والفرق بينهما","answer":"الجواب:  الزيارة ليست واجبة، صلة الرحم هي الواجبة، قطيعة الرحم محرمة، أما الزيارة ما هي بلازمة إذا منعك والدك لا بأس، تسترضيه بالطرق الطيبة. المقدم: هذه سائلة سماحة الشيخ. الشيخ: أو السائلة كذلك، فالمقصود سواء كانت سائلة، أو سائل إنما الزيارة غير واجبة، إذا حصل صلة الرحم بالمكاتبة بالهاتف بالتلفون بالمراسلة بغير الكتابة مع الأصدقاء والأحباب، تسأل عن حالهم كيف أنتم؟ عساكم طيبين؛ كفى، ولو ما زرتهم، والحمد لله، والزيارة قد يمنع منها موانع ومشاغل، قد يكون الإنسان مسافرًا مدة طويلة، ووالدك قد يكون له عذر شرعي يخاف عليك من الزيارة، من أشياء. فالحاصل أن الوالد له مقاصد -إن شاء الله- طيبة، فلا تعجلي، وإذا دعت الحاجة للزيارة، فشاوريه بالأسلوب الحسن، أو بواسطة أمك، أو إخوانك أو أعمامك حتى يرضى، وحتى تكون الزيارة على طريقة مأمونة، ليس فيها خطر؛ لأن الزيارات تختلف، إذا كانت الزيارة للأخت أو الأخ أو العم لا بأس، أما الزيارة لبني العم، أو بني الخال، لا، هذا فيه خطر؛ لأنهم ليسوا محارم. فالحاصل أن عليك الاستئذان من والدك، وعدم التعجل، والدعاء للأقارب بالتوفيق والهداية والسؤال عنهم، والوصية لهم بالسلام مع الأصدقاء والأحباب، أو بالتلفون كل ذلك طيب، يحصل به المقصود والحمد لله. وإذا كانوا فقراء، فمن الصلة صلتهم ومواساتهم، والإحسان إليهم، وإذا ظلموا من الصلة الشفاعة في رد الظلم عنهم، ونصر المظلوم، وإذا دعت الحاجة إلى قضاء دينهم؛ فمن الصلة المساعدة في قضاء الدين، إذا كان القريب قادرًا إلى غير هذا من وجوه الخير. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9725/حكم-زيارة-الاقارب-وصلة-الرحم-والفرق-بينهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_295/29509.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":11648,"question":"ما هي الغيرة، وهذا السؤال من الأخ أبو بكر من جدة؟","title":"معنى الغيرة","answer":"الجواب:  الغيرة: الغضب لله، وإنكار المنكر، كونه يغضب لله على بصيرة، ما هو بعلى تعنت، أو على جهل، لا، الغيرة على بصيرة، عند انتهاك محارم الله، يغار لله، هذا هو الواجب على المؤمن. يقول ﷺ لما ذكروا غيرة سعد بن عبادة قال: تعجبون من غيرة سعد ! وأنا أغير من سعد ، والله أغير مني ويقول ﷺ: ما أحد أغير من الله سبحانه أن يزني عبده، أو تزني أمته فالواجب الغيرة لله، لا تعصبًا، ولا رياءً، بل إذا رأى المحارم تنتهك؛ غار لله، وأنكر المنكر، يعني: غضب لله. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9818/معنى-الغيرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_389/38905.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":11771,"question":"يسأل أيضًا ويقول: هل يجوز أن نشكر أحدًا من الخلق، وهل كان رسول الله ﷺ يشكر أحدًا من الخلق؟","title":"حكم شكر الإنسان على الإحسان","answer":"الجواب: نعم السنة شكر المخلوق على إحسانه، في الحديث يقول ﷺ: من لا يشكر الناس لا يشكر الله وكان النبي ﷺ يشكر الناس على أعمالهم الطيبة، ويشجعهم -عليه الصلاة والسلام- فإذا شكرته بأن أعانك على زواج، أو أعانك على قضاء الدين، فشكرته، قلت: مشكورًا، جزاك الله خيرًا، ضاعف الله مثوبتك، هذا من مكارم الأخلاق، من مكارم الأخلاق أن تشكر من أحسن إليك. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9959/حكم-شكر-الانسان-على-الاحسان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_394/39421.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":11784,"question":"بعد هذا رسالة بعث بها أحد الإخوة المستمعين يسأل جمعًا من الأسئلة، فيقول مثلًا: معظم أقاربي القريبين جدًا لي متكبرون، أصلهم ويقطعون، وأعطيهم ويحرمون، ولا يقدرون للمعروف قدرًا، وإذا وجهنا لهم النصائح لا يقبلون النصح، ويتكبرون على الحق ويسفهونه، ولا أدري كيف العمل معهم، ومجالسهم كلها غيبة ونميمة، ولا أرتاح في الجلوس معهم، أرجو أن توجهوني حيث أخشى أن أتعرض للإثم جزاكم الله خيرًا.","title":"حكم صلة القريب العاصي","answer":"الجواب:  ننصحك ونوصيك بأن تستمر في النصيحة مشافهة، أو مكاتبة، وتشجع أيضًا من يرجى أنهم يتأثرون به، وينتفعون بنصيحته، تشجع من كان كذلك على نصيحتهم، كأعمامهم وأخوالهم أو آبائهم أو أمهاتهم، لقول الله سبحانه: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2]، ولقول الله : وَالْعَصْرِ ۝ إِنَّ الإِنسَانَ لَفِي خُسْرٍ ۝ إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ [العصر:1-3]، وقول النبي ﷺ: ليس الواصل بالمكافي، ولكن الواصل الذي إذا قطعت رحمه وصلها. فهذا هو الواصل الذي يصلهم وإن قطعوا، ويحسن إليهم وإن أساؤوا، وفي الحديث الآخر أنه جاءه -عليه الصلاة والسلام- رجل.. جاء إلى النبي ﷺ رجل فقال: يا رسول الله! إن لي قرابة أصلهم ويقطعونني، وأحسن إليهم ويسيؤون إلي، وأحلم عليهم، ويجهلون علي، فقال له النبي ﷺ: لئن كنت كما قلت لكأنما تسفهم المل يعني: الملة ولا يزال معك من الله عون عليهم ما دمت على ذلك فهذا مثلك يحسن ويسيؤون إليه، فأنت أبشر بالخير، وأحسن، واصبر، ولا يزال معك من الله عوين عليهم، ما دمت على هذه الحال. وأما مجالسهم فلا تحضرها، إذا كانت المجالس فيها المنكر، فيها الغيبة والنميمة والمنكرات الأخرى إن حضرت فأنكر، فإن قبلوا منك وإلا فقم. المقصود أنك لا تحضر مجالس الشر، لكن إن حضرت؛ فانصح، ووجه، وأمر بالمعروف وانه عن المنكر، فإن قبلوا، وإلا فقم، لا تحضر، لا تبقى، بارك الله فيك، ونفع بك. المقدم: اللهم آمين، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9964/حكم-صلة-القريب-العاصي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_395/39502.mp3","categories":["الآداب والأخلاق المحمودة","الدعوة والدعاة"]},{"id":11933,"question":"إحدى الأخوات المستمعات تقول: المرسلة (غ. د. م) تقول: هناك شجرة نأخذ دائمًا منها السواك، أراك أو غير الأراك، علمًا، بأن هذه الشجرة ليست لنا، وبدون علم صاحبها، فهل تدخل في حكم السرقة، أو اللقطة و .. أن ذلك جائز أخذها؟ وجزاكم الله خيرًا.","title":"حكم الأخذ من الشجر بدون إذن صاحبه","answer":"الجواب:  إذا كانت مملوكة في ملك إنسان مملوكة له؛ فلا تأخذوا إلا بإذنه، أما إن كانت برية في البر؛ فلا حرج، الحمد لله، لكل أحد يأخذ منها، أما إن كانت في ملك إنسان؛ فإنه يستأذن في أخذ بعض أجزائها سواكًا لا بأس إذا أذن، وإلا بدون إذن لا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10117/حكم-الاخذ-من-الشجر-بدون-اذن-صاحبه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_427/42710.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":11939,"question":"رسالة وصلت إلى البرنامج من جدة، وباعثها مستمع رمز إلى اسمه بالحروف (ف. ع. ف) أخونا كتب على ورقة من النوع الكبير جدًا، وكل ما في رسالته شكوى بمرارة من أم زوجته، وختم رسالته سماحة الشيخ بالرجاء التنبيه على أمهات الزوجات، حتى لا يتدخلن بين الزوج وزوجته؛ فيفسدون عليهم حياتهم، جزاكم الله خيرًا.","title":"دور أم الزوجة تجاه الزوجين","answer":"الجواب:  نوصي أمهات النساء، وأخوات النساء، وعمات النساء، وخالات النساء، نوصي الجميع بتقوى الله، وأن يكن ناصحات لقريباتهن، وأن يرغبنهن في السمع والطاعة لأزواجهن في المعروف، وأن يكن من أسباب الاجتماع، لا من أسباب الافتراق، وإذا كان الخطأ من الزوج؛ فلا مانع أن ينصحن الزوج، ويوصينه بتقوى الله في زوجته، وأن يعدل فيها، ولا يظلم. فالمقصود الوصية أن يكن مع المظلوم، لا مع الظالم، وأن يكن موجهات للخير للزوج وللزوجة، وألا يعن الزوج على الباطل، ولا الزوجة على الباطل، بل يجب أن يكن معينات على الخير للزوج والزوجة جميعًا، وناصحات للزوج والزوجة جميعًا، سواء كانت الناصحة أمًا، أو جدة، أو خالة، أو عمة، أو أختًا، أو غير ذلك، والله -جل وعلا- يقول في كتابه الكريم : وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2] ويقول سبحانه: وَالْعَصْرِ ۝ إِنَّ الإِنسَانَ لَفِي خُسْرٍ ۝ إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ [العصر:1-3]، ويقول النبي ﷺ: الدين النصيحة، الدين النصيحة، الدين النصيحة قيل: لمن يا رسول الله؟ قال: لله ولكتابه ولرسوله ولأئمة المسلمين وعامتهم فنوصي أمهات النساء خاصة، وقريباتهن -بصفة عامة- بتقوى الله، وأن يكن عونًا على الخير، وناصحات للجميع، وألا يكن عونًا للمرأة على زوجها في الباطل، بل يجب أن يكن عونًا في الحق، نعم، وفق الله الجميع.  المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10124/دور-ام-الزوجة-تجاه-الزوجين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_428/42803.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":11952,"question":"هل يجوز ذكر الإنسان بمحاسنه، وهل هذا يعتبر من الغيبة؟","title":"ذكر الإنسان بمحاسنه إذا كان غائبًا","answer":"الجواب:  ذكر الإنسان بمحاسنه لا حرج في ذلك، إلا إذا كان حاضرًا؛ فترك ذلك أولى، إلا الشيء القليل؛ لأن ذلك قد يفضي إلى العجب والخطأ العظيم بأن يعجب بنفسه، ولأنه قد يفضي أيضًا إلى التكبر، أو غير هذا من الخصال الذميمة، ولهذا جاء في الحديث: إذا رأيتم المداحين؛ فاحثوا وجوههم بالتراب ولما سمع النبي ﷺ رجلًا يمدح شخصًا قال: ويحك قطعت ظهره. فالمقصود: أن السنة التقليل من المدح في حضرة الرجل، وإذا دعت الحاجة إلى ذلك؛ فلا بأس بأن يكون قليلًا، أما في غيبته فلا يضر ذلك، نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10137/ذكر-الانسان-بمحاسنه-اذا-كان-غاىبا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_428/42816.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":12037,"question":"يقول: هل يجب علي إذا تبت إلى الله، وكنت قد اغتبت أناسًا كثيرين، هل يجب علي أن أبلغهم، وأستميحهم من ذلك، أو لا يجب؟","title":"حكم إعلام الشخص من اغتابهم للتحلل منهم","answer":"الجواب:  التوبة كافية، التوبة كافية، وتذكرهم بالخير الذي تعلمه منهم، تذكرهم بالخير الذي تعرفه منهم في المجالس التي ذكرتهم فيها بالسوء، لكن إذا تيسر استماحتهم على وجه لا يكون فيه خطر، ولا أذى، فهو أحوط إذا تيسر أن تقول لفلان: قد تكلمت في عرضك، فأبحني؛ هذا طيب، أنت مأمور بالتخلص من الظلم في الدم والمال والعرض، لكن الغالب أنك إذا قلت لأحد ذلك يغضب، ويتغير، وربما لم يسمح، فالتوبة من ذلك وذكرهم بالخير الذي تعرفه عنهم، في المجالس التي ذكرتهم فيها بالشر يكفي -إن شاء الله- ولكن إذا تيسر أنك تستبيحه ما دمت تعرف حاله، وأنك إذا استبحته يسمح، ولا يكون في ذلك شر؛ فهذا حسن، إذا ظننت أنه يسمح لك إن استبحته، وأنه لا يترتب عليه شر، فهذا من باب الحيطة، هذا حسن، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10222/حكم-اعلام-الشخص-من-اغتابهم-للتحلل-منهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_433/43306.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":12118,"question":"تقول: أذهب لزيارات بعض الأقارب، ولكني ألاحظ أنهم لا يرحبون بي، وأشعر بعدم رغبتهم في زيارتي، فهل أقطع زيارتهم علمًا بأنهم من الأقارب، ومن ذوي الأرحام كما قلت، جزاكم الله خيرًا؟","title":"حكم صلة الأرحام الذين يبدو منهم الجفاء","answer":"الجواب:  الأفضل أن تزوريهم، وتؤدي حق الرحم، وأبشري بالخير، يقول النبي ﷺ: ليس الواصل بالمكافئ، ولكن الواصل الذي إذا قطعت رحمه وصلها فإذا رأيت منهم الجفاء؛ فأنت كوني خيرًا منهم، صليهم بالكلام الطيب، والزيارة الطيبة، وأنت على خير، وعلى أجر، والحمد لله، نعم.","link":"https://binbaz.org.sa/fatwas/10303/حكم-صلة-الارحام-الذين-يبدو-منهم-الجفاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_438/43803.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":12133,"question":"ما حكم السلام على المرأة الأجنبية؟","title":"حكم إلقاء السلام على المرأة الأجنبية","answer":"الجواب:  لا حرج في ذلك، إذا لم يكن فيه فتنة، السلام عليكم، كيف حالك، كيف حال أولادك، كيف حال والديك، ما فيه بأس، كان النبي ﷺ يسلم على النساء، وكن يسلمن عليه، والصحابة كذلك، لا حرج في ذلك، أما إذا كان يخشى الفتنة؛ فليدع ذلك يلتمس مجالًا يبتعد عن هذا الشيء إذا كان يخشى؛ لأن كلامها يفتنه، ويتحرك له قلبه، وربما يخشى الوقوع في الفتنة. المقصود: إذا كان لا يخشى شيئًا؛ فإنه يسلم، ويرد السلام، ويسألها عن حالها، ولا بأس، أما إذا كان يخشى فتنة؛ لأنها امرأة لا تبالي بالتكشف، أو الكلام الذي قد يوقع الفتنة، أو ما أشبه ذلك، فلا. فهو أعلم بنفسه يبتعد عن الشيء الذي يخشى منه الفتنة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10318/حكم-القاء-السلام-على-المراة-الاجنبية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_439/43902.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":12146,"question":"مستمع من الرياض رمز إلى اسمه بالحروف (ع. ق. ع) يقول في رسالة مطولة بعض الشيء: سماحة الشيخ! السلام عليكم ورحمة الله وبركاته، حصلت مشاجرة بيني وبين أسرة مجاورة لي، وكنت أنا المخطي في حق هذه الأسرة، وعندما كان بعض الجيران يسألني عن سبب المشاجرة كنت أقص عليهم واقعة من نسج الخيال، وخلاف ذلك كنت أتهم ربة هذه الأسرة بأمور فاحشة، وذلك ضمن تلك الادعاءات الكاذبة، والآن يا سماحة الشيخ! أشعر بذنب عظيم جدًا نحو هذا المرأة، ونحو أسرتها، وأريد أن أذهب إليهم، وأستسمحهم جميعًا، ولكني أخشى أن يقابلوني بالإساءة، وتنشب بيننا مشاجرة أخرى، فحدثوني جزاكم الله خيرًا، ماذا أفعل كي يستريح ضميري من هذا الذنب؟ جزاكم الله خيرًا، وأحسن إليكم.","title":"واجب من أساء إلى الجيران وتاب من ذلك","answer":"الجواب:  نوصيك بالتوبة إلى الله، نوصيك أيها الأخ! بالتوبة إلى الله التوبة الصادقة، بالندم على ما مضى، والعزم ألا تعود في ذلك، وأن تذكرهم بالأشياء الطيبة التي تعرفها عنهم، تذكرهم، تمدحهم بالأخلاق الكريمة، والصفات الحميدة التي تعرفها عنهم، في المجالس التي ذكرتهم فيها بالسوء، حتى تكون هذه بهذه، لأن كونك تستسمح لهم يخشى منه الشر؛ فلا تأتهم، ولا تقل لهم شيئًا، ولكن اذكرهم بالخير الذي تعرفه عنهم، والصفات الطيبة التي تعرفها عنهم من دون كذب، لا تكذب، لكن تذكر صفاتهم الطيبة، بدلًا من الصفات التي قلتها سابقًا الرديئة، وتحسن ظنك بإخوانك، وتحذر العودة إلى هذا البلاء، التهم للناس، والكلام في أعراضهم، احذر وتب توبة صادقة، وعليك بالكلام الطيب، والأسلوب الحسن مع هؤلاء، ومع غيرهم، وأن تذكرهم بالشيء الطيب الذي تعرفه عنهم في المجالس، والاجتماعات التي ذكرتهم فيها بالسوء، حتى تكون هذه بهذه، تكون هذه الحسنة بدل تلك السيئة، وفق الله الجميع. المقدم: اللهم آمين، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10331/واجب-من-اساء-الى-الجيران-وتاب-من-ذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_440/44003.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":12150,"question":"من ألمانيا رسالة بعث بها مستمع من هناك يقول: مسلم من ألمانيا، له سؤال يقول فيه: ما هي مقومات صلة الرحم؟ ومن هم الأشخاص الذين يجب علي أن أصلهم من حيث درجة القرابة، إذ أن الكثيرين من أقاربي أشخاص لا يؤمنون، أو أنهم لا يصلون، ولا يصومون، ولا يعطون الزكاة، إلا أنهم مسلمون بالاسم، وليس بالفعل، فهل علي أن أصلهم، أم تجب صلة الرحم للأقارب المسلمين الحقيقيين؟ أجيبوني أثابكم الله.","title":"درجات صلة الرحم وحكم صلة الكفار منهم","answer":"الجواب:  صلة الرحم للمسلمين، وأقربهم الأبوان: الأم، والأب، والأجداد والجدات، ثم الأولاد ذكورهم وإناثهم وما نزلوا الأولاد وأولادهم، ثم الإخوة وأولادهم، ثم الأعمام والعمات والأخوال والخالات، ثم بنو العم وبنو العمات وبنو الخال وبنو الخالات، الأقرب فالأقرب، يقول النبي ﷺ لما سأله سائل قال: يا رسول الله! من أبر؟ قال: أمك قال: ثم من؟ قال: أمك قال: ثم من؟ قال: أمك قال: ثم من؟ قال: أباك ثم الأقرب فالأقرب خرجه مسلم في صحيحه ، وفي اللفظ الآخر قال: يا رسول الله! من أحق الناس بحسن الصحبة؟ قال: أمك قال: ثم من؟ قال: أمك قال: ثم من؟ قال: أمك قال: ثم من؟ قال: أبوك  ويقول النبي ﷺ: لا يدخل الجنة قاطع رحم والله يقول في كتابه العظيم: فَهَلْ عَسَيْتُمْ إِنْ تَوَلَّيْتُمْ أَنْ تُفْسِدُوا فِي الأَرْضِ وَتُقَطِّعُوا أَرْحَامَكُمْ   ۝  أُوْلَئِكَ الَّذِينَ لَعَنَهُمُ اللَّهُ فَأَصَمَّهُمْ وَأَعْمَى أَبْصَارَهُمْ [محمد: 22 -23] ويقول -جل وعلا-: أَنِ اشْكُرْ لِي وَلِوَالِدَيْكَ إِلَيَّ الْمَصِيرُ [لقمان:14] ، ويقول سبحانه: وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ وَبِالْوَالِدَيْنِ إِحْسَانًا [الإسراء:23] ويقول سبحانه: وَاعْبُدُوا اللَّهَ وَلا تُشْرِكُوا بِهِ شَيْئًا وَبِالْوَالِدَيْنِِ إِحْسَانًا وَبِذِي الْقُرْبَى وَالْيَتَامَى وَالْمَسَاكِينِ.. [النساء:36] الآية. فالمؤمن يصل قراباته، يجب عليه أن يصلهم حسب الطاقة، ولو بالكلام الطيب، ولو بالكلام الطيب، وبالمال، إذا كانوا فقراء يواسيهم إذا قدر، وينفق عليهم إذا قدر، يجب عليه ذلك حسب طاقته، الأقرب فالأقرب، ولو من طريق الهاتف (تلفون)، ولو من طريق المكاتبة، ولو قطعوك تصلهم، ولو قطعوك؛ لقول النبي ﷺ: ليس الواصل بالمكافي، ولكن الواصل الذي إذا قطعت رحمه وصلها رواه البخاري في الصحيح، هذا الواصل الكامل، الذي يصلهم وإن قطعوا. أما الكفار لا تجب صلتهم، لكن إذا وصلتهم حسن؛ لأن الله قد يهديهم بأسبابك، إذا كان لك أخ كافر، أو عم كافر، أو ابن عم ووصلته أحسنت إليه، هذا من أسباب هدايته، أما الأبوان فتصلهم ولو كانا كافرين، الأبوان حقهما عظيم، تحسن إليهم، وتصلهما وإن كانا كافرين، وتدعوهما إلى الخير، كما قال الله -جل وعلا-: أَنِ اشْكُرْ لِي وَلِوَالِدَيْكَ [لقمان:14]، وقال في الكافرين: وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا [لقمان:15] فالوالدان لهما حق عظيم، ولو كانا كافرين بالصلة والإحسان إليهما والرفق بهما، لعل الله أن يهديهما بأسبابك. أما غيرهم فأمرهم أسهل، إن وصلتهم فهذا حسن، من باب الدعوة إلى الله، من باب الترغيب في الخير، وإن لم تصلهم لم يجب عليك؛ لأن الكفر فرق بينك وبينهم، لم يجب عليك أن تصلهم، ولا أن تنفق عليهم، لكن إن وصلتهم، وأحسنت إليهم ترجو ما عند الله، لعل الله أن يهديهم، لا عن محبة لهم، ولكن بقصد الرحم والقرابة، ولعل الله أن يهديهم بأسباب ذلك، هذا طيب، وأنت مشكور ومأجور، مع بغضهم في الله، نعم.","link":"https://binbaz.org.sa/fatwas/10335/درجات-صلة-الرحم-وحكم-صلة-الكفار-منهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_440/44007.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":12232,"question":"تسأل إحدى الأخوات المستمعات من رماح، ورمزت إلى اسمها بالحروف (ن. م. مراد) تقول: أرجو أن تفيدوني عن الموضوع التالي: لي أم عجوز جدًا، ومريضة، تركتها في مصر، ولكن معها بالبيت إخوة كثيرون، ولي أيضًا أخوات يزرنها يوميًا، ولكن أحس أحيانًا بضميري يؤنبني لتركي لها، فما حكم الشرع في ذلك؟ أفادكم الله.","title":"حكم بقاء المرأة بعيدا عن أمها إذا وجد من يرعاها","answer":"الجواب: ما دامت -بحمد الله- عندها أخوات لك، وعندها إخوة؛ فالحمد لله، ليس عليك بأس، وأنت أيضًا مع زوجك، أو في عمل مهم. فالمقصود: أنه لا حرج عليك مطلقًا، ما دام عندها من يقوم بحالها من أخوات، أو إخوة؛ فلا بأس عليك، ولا حرج، والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10420/حكم-بقاء-المراة-بعيدا-عن-امها-اذا-وجد-من-يرعاها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_447/44708.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":12239,"question":"مستمع بعث برسالة يقول أخوكم خليل محمد: لي ثلاثة أسئلة أرجو أن يتفضل سماحة الشيخ بالإجابة عليها، سؤاله الأول يقول: لي ابنة سميتها هدى، وقد سمعت بعض الناس يقولون: إن اسم هدى لم يذكر، فما هي نصيحتكم، هل أغير اسم البنت؟","title":"حكم التسمية بـ (هدى)","answer":"الجواب:  لا أعلم في ذلك بأسًا، لا أعلم في هذا بأسًا، والحمد لله، نعم.","link":"https://binbaz.org.sa/fatwas/10427/حكم-التسمية-بـ-هدى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_448/44803.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":12241,"question":"يقول عن نفسه: إني رجل أصلي مع الجماعة في صلاة الفجر، وبعد انتهاء الصلاة أتكئ وأنام حتى طلوع الشمس، هل علي إثم في ذلك؟","title":"حكم النوم بعد صلاة الفجر حتى الشروق","answer":"الجواب:  لا حرج عليك، لكن الأفضل من هذا أن تشتغل بذكر الله، وقراءة القرآن والتسبيح، والدعاء؛ حتى تصبح، إذا تيسر لك ذلك هذا هو الأفضل، وأما النوم؛ فلا حرج فيه، لكن كونك تعمر وقتك هذا العظيم أول النهار بالذكر، والدعاء هو الأفضل، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10429/حكم-النوم-بعد-صلاة-الفجر-حتى-الشروق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_448/44805.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":12274,"question":"آخر سؤال له يقول: والدتي تدعو علي كثيرًا، علمًا بأنني -ولله الحمد- لا أعصيها، ولا أقصر في حقها، وأنا ملتزم بأوامر الله، مؤديًا لكافة الفروض المكتوبة، فهل دعوتها مستجابة؟ وماذا أعمل لكي أجعلها تعدل عن هذه الدعوات التي أجزم بأن الدافع وراءها هو عصبية الوالدة؟ أفيدوني جزاكم الله خيرًا.","title":"النصح بترك الوالدة الدعاء على ولدها","answer":"الجواب:  تدعو لها بالتوفيق والهداية، تجتهد في إرضائها، والتماس الأسباب التي ترضيها عنك، وتحفظ لسانها من سبك، والدعاء عليك، اجتهد في ذلك، واتق الله، فالأم لها حق عظيم، ومنزلة عظيمة، وبرها من أهم الواجبات، وإذا قمت بالواجب فأرجو أن لا يضرك دعاؤها؛ لأن الدعاء حينئذٍ ليس في محله، وهو خطأ منها، فعليك أن تجتهد في برها، والإحسان إليها.  وكونها تدعو عليك بدون سبب؛ إثم عليها هي، ولا يضرك -إن شاء الله- لكن عليك أنت أن تجتهد في برها، والإحسان إليها، وعدم عصيانها في المعروف، وعليك أن تجتهد في الأسلوب الذي يرضيها، إذا كان الأسلوب جائزًا شرعًا، تجتهد في الأسلوب المناسب الذي ترضى به عنك، وتدعو لها بظهر الغيب في سجودك، وفي آخر الصلاة، وفي غير ذلك، تدعو لها بالهداية والتوفيق، وأن الله يهديها حتى تحفظ لسانها عما لا ينبغي، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10474/النصح-بترك-الوالدة-الدعاء-على-ولدها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_450/45011.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":12315,"question":"هل يمكنني المبيت عند إحدى أخواتي في بيتها؟","title":"حكم مبيت الرجل عند أخته","answer":"الجواب:  نعم، لأنها محرم، إذا كانت في بيتها لكن لا في فراش واحد، كل واحد في فراش، أنت في فراش، وهي في فراش، المنهي عنه أن تجتمعا في فراش واحد، لأن الرسول ﷺ: أمر أن يفرق بينهم في المضاجع إذا بلغ الغلام، بلغ الغلمان، أو النساء العشر، فإذا نمت وحدك وهي وحدها؛ فلا حرج. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10530/حكم-مبيت-الرجل-عند-اخته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_398/39816.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":12319,"question":"هل يمكنني المبيت عند إحدى أخواتي في بيتها؟","title":"حكم مبيت الرجل عند أخته","answer":"الجواب:  نعم، لأنها محرم، إذا كانت في بيتها لكن لا في فراش واحد، كل واحد في فراش، أنت في فراش، وهي في فراش، المنهي عنه أن تجتمعا في فراش واحد، لأن الرسول ﷺ: أمر أن يفرق بينهم في المضاجع إذا بلغ الغلام، بلغ الغلمان، أو النساء العشر، فإذا نمت وحدك وهي وحدها؛ فلا حرج. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10530/حكم-مبيت-الرجل-عند-اخته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_398/39816.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":12486,"question":"بعد هذا رسالة بعث بها المستمع (محمد . ع) يقول: اعتدنا أنا وإخوتي الذين هم أكبر مني سنًا أن ننادي والدتنا باسمها، وهي راضية عن ذلك، فهل نأثم؟","title":"حكم نداء الابن أمه باسمها","answer":"الجواب: لا أعلم ما يدل على الإثم، لا أعلم شيئًا في ذلك، لكن إذا تيسر أن تدعى بالكنية أم فلان، أو يا والدتي، أو يا أماه، أو يا أمي، قد يكون هذا أحسن في الأدب، وإلا فلا حرج، لا أعلم حرجًا إذا قال: يا فلانة، يا فاطمة، يا نورة، يا حفصة، لا حرج في ذلك، لكن من الأدب الشرعي، من التلطف أن تدعى بالكنية: يا أم فلان، أو يا والدتي، أو يا أمي، ونحو ذلك، هذا أحسن في الأدب. المقدم: بارك الله فيكم، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10699/حكم-نداء-الابن-امه-باسمها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_406/40610.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":12499,"question":"بعد هذا رسالة بعث بها المستمع (محمد . ع) يقول: اعتدنا أنا وإخوتي الذين هم أكبر مني سنًا أن ننادي والدتنا باسمها، وهي راضية عن ذلك، فهل نأثم؟","title":"حكم نداء الابن أمه باسمها","answer":"الجواب: لا أعلم ما يدل على الإثم، لا أعلم شيئًا في ذلك، لكن إذا تيسر أن تدعى بالكنية أم فلان، أو يا والدتي، أو يا أماه، أو يا أمي، قد يكون هذا أحسن في الأدب، وإلا فلا حرج، لا أعلم حرجًا إذا قال: يا فلانة، يا فاطمة، يا نورة، يا حفصة، لا حرج في ذلك، لكن من الأدب الشرعي، من التلطف أن تدعى بالكنية: يا أم فلان، أو يا والدتي، أو يا أمي، ونحو ذلك، هذا أحسن في الأدب. المقدم: بارك الله فيكم، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10699/حكم-نداء-الابن-امه-باسمها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_406/40610.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":12525,"question":"ما حكم المزاح؛ لأنه كثر في هذ الوقت؟ جزاكم الله خيرًا.","title":"حكم المزاح وضوابطه","answer":"الجواب:  المزاح القليل لا بأس به، كان يمزح النبي ﷺ قليلًا، ولا يقول إلا حقًا، إذا كان المزح قليلًا بحق؛ فلا بأس، أما الكثرة من المزاح، أو بالكذب هذا لا يجوز، لكن المزح القليل إذا كان بحق لا بأس بذلك. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10735/حكم-المزاح-وضوابطه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_408/40814.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":12530,"question":"بعض الناس يكل والديه إلى الخادم أو الخادمة، وحينئذ ينساهم، أو يتناساهم، هل من كلمة..؟","title":"اكتفاء الابن بالخادم أو الخادمة في بر الوالدين","answer":"الجواب:  لا، لا يجوز هذا، الواجب العناية بالوالدين، وعدم -يعني- عدم الاعتماد على الخدم في هذا الشيء، بل يجب العناية بالوالدين، والإحسان إليهما، وبرهما، والحرص على كل ما ينفعهما، ويقيهما شر الأذى، لا من الخادم، ولا من الخادمة، يجب على الولد ذكرًا كان، أو أنثى أن يجتهد في بر والديه، والإصلاح في كل ما ينفعهم، ومع توجيه الخادمة والخادم، وتحريصهم على الشيء الطيب، لكن لا يكتفي بذلك، قد يقصر الخادم، قد ينسى، قد يكون كسولًا.  فالحاصل: أن الولد عليه أن يعتني بالوالدين، وألا يتكل على مجرد عمل الخادم.  المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10724/اكتفاء-الابن-بالخادم-او-الخادمة-في-بر-الوالدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_408/40803.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":12557,"question":"أولى رسائل هذه الحلقة رسالة مطولة جدًا، باعثها أحد الإخوة المستمعين يقول في نهايتها: محمد سعيد عبدالرحمن، بدأ رسالته كالتالي يقول: بسم الله الرحمن الرحيم، سماحة الشيخ عبدالعزيز بن عبدالله بن باز حفظه الله آمين! السلام عليكم ورحمة الله وبركاته، وبعد: أتوجه إلى سماحتكم عبر هذا البرنامج النافع المفيد بالسؤال التالي: لي قريب وهو في الوقت نفسه صديق عزيز جدًا أحب له الخير، وأخاف عليه من الشر، شاب جامعي ذو أخلاق طيبة جدًا، محافظ على الصلوات في المسجد، ويحضر المحاضرات، والندوات الدينية في كثير من الأحيان، طلق والده والدته منذ حوالي سنتين أو أكثر، وتزوج غيرها، ووالدته لها عدة أولاد ذكور، لكنها استقرت عنده هو لرحمته لها، وبره بها، وقد قال لي والده يومًا لمعرفته أنني صديق لابنه المذكور: إن كنت تحب فلانًا؛ فانصحه، فإنه عاق لي، ثم أخذ يشتكي من معاملته له، وأنه لا يحترمه، فوعدته خيرًا، وذهبت لصديقي، وذكرته ببر الوالدين، وأن بره بأمه يجب أن لا ينسيه بره بوالده، وأن لوالده عليه حقًا مهما كانت علاقته سيئة مع أمه، رغم أنني أقول: إن والده رجل محافظ على الصلوات -حسب علمي- قائم بواجبه نحو أولاده، وصالًا لرحمه، وإن كان فيه بعض القسوة على زوجته التي طلقها، ولقد دهشت جدًا حينما قال لي صديقي: إن هذه المعاملة هي التي يستحقها والده، واشتكى منه، وأنه يعامله معاملةً سيئة، ولا يحترمه، لذلك فهو يعامله بنفس معاملته، فذكرت له أن ذلك لا ينبغي، وأن الوالد وإن ضرب ولده، أو كان فاحشًا عليه بالكلام، ولو بدون سبب، ولو أمام الناس، فإن الولد يجب أن يصبر، ومن الدين والشرف والكرامة طاعة الوالد، وعدم معصيته، فما بالك بمخاصمته، ورد الكلام عليه؟! فقال لي صديقي: هذا أبي يعرف قدر نفسه جيدًا، ولو حدث، وفعل معي ما ذكرته لضربته، ولجعلته عبرةً لغيره، فلما سمعت هذه المقالة؛ علمت أن النصيحة لصاحبي من قبلي لن تجدي، وأنه إما يجهل عظم عقوق الوالدين، أو أنه عاص لله على علم وبصيرة، فلجأت إلى الله، ثم إلى سماحتكم لعله يستمع إلى سماحتكم، ويعود إلى صوابه، جزاكم الله خيرًا.","title":"وجوب طاعة الولد لوالده في المعروف مع إساءته للولد","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد.  فلقد نصحت هذا الرجل، وأحسنت في نصيحته، ولقد أخطأ فيما قال لك وأساء فيما يتعلق بوالده، والواجب عليه أن يبر والده، وأن يخاطبه بالتي هي أحسن، وأن يتذكر حق الوالد، وإن كان قد طلق أمه، فالوالد له حق عظيم، والوالدة لها حق عظيم، كلاهما له حق، ولا شك أن حق الوالدة أكبر وأعظم.  ولكن ذلك لا يمنع من أداء الواجب للوالد، فالواجب على صديقه أن يتقي الله، وأن يراقب الله، وأن يبر أباه، ويحسن إليه، وإن أساء أبوه إليه، لا يقابل الإساءة بالإساءة، ولكن يقابل الإساءة بالإحسان، والكلام الطيب، والأسلوب الحسن، والدعاء لوالده بالخير والاستقامة والهداية، هذا هو الواجب عليه، قد دلت النصوص الكثيرة من الكتاب والسنة على ذلك، يقول الله -جل وعلا- في كتابه العظيم: وَوَصَّيْنَا الإِنسَانَ بِوَالِدَيْهِ حَمَلَتْهُ إِحْسَانًا [لقمان:14] وفي الآية الأخرى: حُسْنًا [العنكبوت:8] ويقول -جل وعلا-: أَنِِ اشْكُرْ لِي وَلِوَالِدَيْكَ إِلَيَّ الْمَصِيرُ [لقمان:14] ويقول -جل وعلا-: وَاعْبُدُوا اللَّهَ وَلا تُشْرِكُوا بِهِ شَيْئًا وَبِالْوَالِدَيْنِ إِحْسَانًا [النساء:36] والآيات في هذا المعنى كثيرة، ويقول -جل وعلا-: وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ وَبِالْوَالِدَيْنِ إِحْسَانًا إِمَّا يَبْلُغَنَّ عِنْدَكَ الْكِبَرَ أَحَدُهُمَا أَوْْ كِلاهُمَا فَلا تَقُلْ لَهُمَا أُفٍّ وَلا تَنْهَرْهُمَا وَقُلْ لَهُمَا قَوْلًا كَرِيمًا ۝ وَاخْفِضْ لَهُمَا جَنَاحَ الذُّلِّ مِنَ الرَّحْمَةِ وَقُلْ رَّبِّ ارْحَمْهُمَا كَمَا رَبَّيَانِي صَغِيرًا [الإسراء:23-24]. ويقول النبي ﷺ في الحديث الصحيح: رضا الله في رضا الوالدين، وسخط الله في سخط الوالدين ويقول -عليه الصلاة والسلام- في الحديث الصحيح، في الصحيحين: ألا أنبئكم بأكبر الكبائر؟ قلنا: بلى يا رسول الله! قال: الإشراك بالله، وعقوق الوالدين وشهادة الزور فعقوق الوالدين من أكبر الكبائر، وقد قرنه النبي ﷺ بالشرك، فوجب على هذا الرجل، وعلى غيره أن يبر والده ،وأن يتقي الله في ذلك، ولو أساء إليه والده، ولكن هو يدعو لوالده بالتوفيق والهداية، ويطلب من إخوانه الطيبين من أعمام، أو غيرهم أن ينصحوا والده حتى لا يقسو عليه، وحتى يرحمه، وحتى يعطف عليه بالكلام الطيب. أما هو فالواجب عليه أن يبر والده، وألا ينسيه بره لوالدته، بره لأبيه، بل يتقي الله، ويعامل أباه بالحسنى، وقد قال الله  في الولد مع أبويه الكافرين قال: وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا [لقمان:15] وهما كافران فكيف بالمسلم؟!! فعلى صديقك هذا أن يتقي الله، وأن يتوب إلى الله من عمله السيئ، وأن يبر والده، ويحسن إليه، وأن يتلطف به، ويدعو الله له بالتوفيق والهداية، وأن يستعين على ذلك بخواص إخوانه الطيبين من أعمام أو أخوال أو أصدقاء؛ حتى ينصحوا والده ليرفق به، ويعامله بما ينبغي من اللطف، وهذا من باب التعاون على البر والتقوى، نسأل الله للجميع الهداية. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10755/وجوب-طاعة-الولد-لوالده-في-المعروف-مع-اساءته-للولد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_457/45701.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":12640,"question":"من جنوب سيناء في جمهورية مصر العربية المستمع: عبدي حسين زيدان بعث برسالة يقول فيها: أعمل بمدينة تبعد عن مسقط رأس بحوالي ثمانمائة كيلو مترًا، وقد قمت بنقل زوجتي وأولادي إلى مقر عملي، ولي أم تسكن بمسكنها الخاص، وأعطيتها مفتاح سكني بنفس القرية، لكنها رفضت، وأرسلت لها مبلغًا من المال لتنفق منه، ولكنها رفضت أيضًا علمًا بأن لي أخوين يسكنان في نفس القرية، فهل علي إثم في هذا؟ وهل رفض والدتي أية مساعدة مني يجعلني عاقًا، أنا في حيرة من أمري أرجو الإفادة أفادكم الله.","title":"نصيحة لابن يجتهد في بر والدته، وهي غير راضية عنه","answer":"الجواب:  لا حرج عليك في ذلك -إن شاء الله- فقد أحسنت، وأديت ما عليك من البر، وعلى أخويك أيضًا نصيبهما من البر، والله يقول -جل وعلا-: وَلا يَعْصِينَكَ فِي مَعْرُوفٍ [الممتحنة:12] ويقول النبي ﷺ: إنما الطاعة في المعروف وليس من المعروف أن تحجر عليك السفر لمصالحك، وما فيه نفعك، وأنت قد أديت ما يجب عليك من النفقة إذا كانت في حاجة إليها، مع أن أخويك قد يقومان باللازم. فالحاصل أن عليك أن تلاحظ حاجتها، وإذا قمت باللازم فأنت معذور والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10850/نصيحة-لابن-يجتهد-في-بر-والدته-وهي-غير-راضية-عنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_415/41514.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":12756,"question":"هل يأثم المسلم إذا نام على يده اليسرى؟","title":"حكم النوم على الجنب الأيسر","answer":"الجواب:  لا حرج في ذلك؛ لكن الأفضل أن يبدأ النوم على اليمنى، كان النبي ﷺ يبدأ باليمنى ويقول ﷺ: إذا أتى أحدكم فراشه؛ فليتوضأ، ثم ليضطجع على جنبه الأيمن هذا هو الأفضل، أن يبدأ النوم في الليل على جنبه الأيمن وهو على طهارة، هذا هو الأفضل، وإن نام على يساره؛ فلا حرج، وإذا بدأ النوم، ثم انقلب؛ فلا بأس، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10970/حكم-النوم-على-الجنب-الايسر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_419/41905.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":12835,"question":"شيخ عبدالعزيز أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من البحرين، وباعثها أحد الإخوة المستمعين، رمز لاسمه في نهايتها بالحروف (ع. ع. ع) أحد أسئلته يقول: أنا في انتظار مولود، وأريد أن أختار له اسم شهاب الدين فما رأيكم في مثل هذا الاسم؟","title":"حكم تسمية المولود بشهاب الدين","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد.  فلا أعلم بأسًا في هذه التسمية شهاب الدين؛ ولكن غيرها من الأسماء المعبدة لله أفضل، كما قال النبي ﷺ: أحب الأسماء إلى الله عبدالله، وعبدالرحمن إذا سميته بعبدالله، أو عبدالرحمن، أو عبدالكريم، أو عبدالملك، أو عبدالقادر، أو نحوها من الأسماء المعبدة لله سبحانه، فهذا أفضل وأحسن، وفق الله الجميع. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11049/حكم-تسمية-المولود-بشهاب-الدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_464/46401.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":12853,"question":"مع مطلع هذه الحلقة نعود إلى رسالة وصلت إلى البرنامج من سلطنة عمان، وباعثتها إحدى الأخوات من هناك هي (ع. ع. ج)، أختنا عرضنا جزءًا من أسئلتها في حلقة مضت، وفي هذه الحلقة بقي لها مجموعة أخرى من أسئلتها، ففي أحد ما تبقى من أسئلتها تقول: هل تجوز كلمة: (ألو) في الهاتف، إنهم يقولون: إن هذه اللفظة ليست للمسلمين، بل هي للنصارى، وجهونا ووجهوا المستمعين، جزاكم الله خيرًا؟","title":"حكم استخدام كلمة (ألو) في الهاتف","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد.  فلا أعلم حرجًا في كلمة (ألو)؛ لأن الناس اعتادوها، وتعارفوا عليها، ولا حرج في ذلك، وكثيرًا من الكلمات الأعجمية تعارف عليها الناس، وسارت بينهم؛ فلا يضر ذلك، وإذا قال: (نعم) بدل (ألو) كله طيب. المقصود، أن (ألو) لا حرج فيها، والله أعلم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11068/حكم-استخدام-كلمة-الو-في-الهاتف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_465/46501.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":12878,"question":"مستمع بعث برسالة وضمنها جمعًا من الأسئلة وهو: (ط. م. ط) من ليبيا، في أحد أسئلته يقول: من هم الأحق بصلة الرحم، لو تكرمتم، وجهونا حول هذا الموضوع؟ جزاكم الله خيرًا.","title":"الأحق بصلة الرحم","answer":"الجواب:  قد أجاب عن هذا السؤال الرسول -عليه الصلاة والسلام- فإنه سئل قال له رجل: يا رسول الله! من أحق بحسن صحابتي؟ قال: أمك قال: ثم من؟ قال: أمك قال: ثم من؟ قال: أمك قال: ثم من؟ قال: أبوك في الرابعة، فالأحق الأم ثم الأب، ثم الأقرب فالأقرب. وفي اللفظ الآخر عنه ﷺ أنه قال: لما قال له: يا رسول الله! من أبر؟ السائل قال: من أبر يا رسول الله؟! قال: أمك قال: ثم من؟ قال: أمك قال: ثم من؟ قال: أمك قال: ثم من؟ قال: أباك ثم الأقرب فالأقرب. فالأحق بهذا أمك أولًا، ثم أبوك، ثم أولادك، ثم إخوتك، ثم أولاد إخوتك، ثم أعمامك، وأخوالك، ثم أولاد إخوتك، ثم أعمامك وأخوالك، وهكذا الأقرب فالأقرب، بالمال والإحسان والكلام الطيب، والزيارة، وغير هذا من وجوه الإحسان، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11093/الاحق-بصلة-الرحم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_466/46610.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":12926,"question":"على بركة الله نبدأ هذا اللقاء برسالة وصلت من اليمن السائل (ي. ع. أ) يقول: توفي والدي -يرحمه الله- وكنت أراه -والحمد لله- مداومًا على الصلاة، محافظًا على الخير، وأريد أن أقدم له عملًا يزيد من حسناته، ويخفف من سيئاته، فبماذا يتمثل هذا العمل، جزاكم الله خيرًا هل هو بتلاوة القرآن، وإهدائها له؟ أو التصدق، أم الدعاء؟ جزاكم الله خيرًا.","title":"بر الوالدين بعد وفاتهما","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، والصلاة والسلام على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فإن بر الوالدين من أهم الواجبات، ومن أعظم الفرائض كما قال الله -جل وعلا- في كتابه العظيم: وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ وَبِالْوَالِدَيْنِ إِحْسَانًا [الإسراء:23] قال سبحانه: أَنِ اشْكُرْ لِي وَلِوَالِدَيْكَ إِلَيَّ الْمَصِيرُ [لقمان:14] فبرهما من أهم القربات وأفضلها. قد سئل النبي ﷺ فقيل: «يا رسول الله! هل بقي من بر أبوي شيء أبرهما به بعد وفاتهما؟ قال: الصلاة عليهما، والاستغفار لهما، وإنفاذ عهدهما من بعدهما، وصلة الرحم التي لا توصل إلا بهما، وإكرام صديقهما كل هذا من حقهما. فنوصيك -أيها السائل- بكثرة الدعاء، كثرة الدعاء لوالديك، لأبيك وأمك، والصدقة عنهما كذلك بالقليل والكثير، على الفقراء والمحاويج، ولاسيما فقراء الأقارب بالنية عن والدك، وعن والدتك جميعًا، وعن نفسك معهما كذلك، وإذا كان له وصية شرعية تنفذها كنصاب الثلث، أو الربع في أعمال البر، في وجوه الخير؛ في ضحايا .. في حج .. في صدقات، عليك التنفيذ. كذلك صلة الأقارب من أعمامك، وبني عمك وأجدادك، تصلهم، وتحسن إليهم بالهدية.. بالصدقة.. بالدعاء.. بالزيارة، كذلك أصدقاؤه -إذا كان له أصدقاء- تكرمهم أيضًا، وتحسن إليهم، كل هذا من حق والدك، ومن حق أمك أيضًا.  أما القراءة لهما فهي غير مشروعة، لم يرد في الشرع القراءة للأموات، تقرأ لنفسك، تقرأ وتسأل ربك أن يتقبل منك، وأن يثيبك، أما إهداء القرآن إلى غيرك لا، لم يرد في الشرع. لكن الدعاء للوالدين والصدقة عنهما، الحج عنهما، العمرة عنهما بعد وفاتهما، كل هذا طيب، إكرام أصدقائهما بالصدقة .. بالزيارة، إكرام أقاربك من أبيك وأمك من أعمام وعمات وأخوال وخالات وغيرهم، كل هذا من بر الوالدين -وفق الله الجميع- نعم.  المقدم: الله آمين.","link":"https://binbaz.org.sa/fatwas/11142/بر-الوالدين-بعد-وفاتهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_501/50101.mp3","categories":["إهداء القرب للميت","الآداب والأخلاق المحمودة"]},{"id":12947,"question":"السائل يقول: كيف تكون صلة الأرحام سماحة الشيخ؟","title":"كيفية صلة الأرحام","answer":"الجواب:  صلة الأرحام تكون بالهدية .. بالزيارة، بالكلام الطيب من طريق الهاتف كلها صلة، إذا وصلت إخوانك، أو أعمامك، أو خالاتك بالزيارة في البيت؛ تسلم عليهم، أهديت لهم هدية، ساعدتهم بالمال، كل هذه صلة للرحم، كلمتهم بالهاتف: كيف حالكم؟ إذا ما تيسر لك الزيارة تكلم بالهاتف، بالتلفون: كيف حالكم؟ كيف أولادكم؟ هل من حاجة؟ هل.. هكذا المؤمن مع أقاربه.. مع إخوته.. مع أعمامه.. مع أخواله.. مع عماته.. مع خالاته.. مع بني عمه إلى غير ذلك. قطيعة الرحم كبيرة، يقول الله -جل وعلا-: فَهَلْ عَسَيْتُمْ إِنْ تَوَلَّيْتُمْ أَنْ تُفْسِدُوا فِي الأَرْضِ وَتُقَطِّعُوا أَرْحَامَكُمْ  ۝  أُوْلَئِكَ الَّذِينَ لَعَنَهُمُ اللَّهُ فَأَصَمَّهُمْ وَأَعْمَى أَبْصَارَهُمْ [محمد:22-23] ويقول ﷺ: لا يدخل الجنة قاطع رحم وصلة الرحم فريضة، ومنقبة عظيمة، ومن أخلاق المؤمنين. يقول ﷺ: من أحب أن يبسط له في رزقه، وأن ينسأ له في أجله؛ فليصل رحمه ويقول ﷺ: ليس الواصل بالمكافي، ولكن الواصل الذي إذا قطعت رحمه وصلها إذا جفوا ما يتركهم، إذا جفوه وتركوه، لا، يصلهم هو، يزورهم، يهدي إليهم، يدعوهم إلى الوليمة، يصير خيرًا منهم، أطيب منهم، هذا الواصل الكامل الذي يصلهم وإن قطعوه، ويعطيهم وإن حرموه، هذا هو الأكمل. أما الذي يعطي من أعطوه، ويوصل من وصلوه؛ هذا مكافي فقط، لكن الواصل الكامل الذي له الأجر العظيم الذي يصلهم وإن قطعوا، يهدي إليهم وإن لم يهدوا، يواسيهم، ويحرص عليهم وإن جفوا، هكذا، قال رجل: «يا رسول الله! إن لي قرابة أصلهم ويقطعونني، وأحلم عليهم ويجهلون علي، فقال: إن كنت كما قلت لكأنما تسفهم المل، ولا يزال معك من الله ظهير عليهم ما دمت على ذلك لأنه يصلهم ويقطعونه، ويحلم عليهم ويجهلون عليه، ويحسن إليهم ويسيئون إليه، فقال له النبي ﷺ إذا صبرت؛ فأنت على خير عظيم: لئن كنت كما قلت لكأنما تسفهم المل، ولا يزال معك من الله ظيهر عليهم مادمت على ذلك نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11163/كيفية-صلة-الارحام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_502/50206.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":12955,"question":"سمعت أنه إذا وجد إنسان اسم الله في الشارع، أو في مكان قذر؛ يجب عليه أن يمسحه، أو يأخذه ويدفنه في مكان طاهر، هل ما سمعته صحيح؟","title":"ماذا يفعل من وجد ورقة فيها اسم الله أو آية؟","answer":"الجواب:  نعم صحيح، إذا وجد ورقة فيها ذكر اسم الله، أو آية من القرآن؛ يأخذها ويحرقها، أو يدفنها في مكان طيب. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11172/ماذا-يفعل-من-وجد-ورقة-فيها-اسم-الله-او-اية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_470/47003.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":12990,"question":"ننتقل إلى رسالة بعث بها مستمع يقول: هل يجوز السلام على تارك الصلاة، وإذا لم نسلم عليه ماذا يجب علينا؟","title":"إلقاء السلام على تارك الصلاة","answer":"الجواب:  تارك الصلاة يجب أن يهجر، ويرفع أمره إلى ولي الأمر إذا كان في البلد حكومة إسلامية يرفع الأمر إليها حتى يستتاب، فإن تاب، ولا قتل، تارك الصلاة لا يترك، يرفع إلى المحكمة، إلى الإمارة الشرعية، حتى يلزم بالحق، أو يستتاب، فإن تاب وإلا قتل؛ لقول الله سبحانه: فَإِنْ تَابُوا وَأَقَامُوا الصَّلاةَ وَآتَوُا الزَّكَاةَ فَخَلُّوا سَبِيلَهُمْ [التوبة:5] دل على أنهم إذا لم يتوبوا لا يخلى سبيلهم. وهكذا الزاني إذا عرف زناه؛ يقام عليه الحد، وهكذا سائر المعاصي إذا أظهرها صاحبها؛ يقام عليه حدها، أو تعزيرها، ولا يترك، إذا أعلنها، وأظهرها، نعم.","link":"https://binbaz.org.sa/fatwas/11206/القاء-السلام-على-تارك-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_504/50404.mp3","categories":["الآداب والأخلاق المحمودة","حكم الصلاة وأهميتها"]},{"id":12996,"question":"تقول في آخر أسئلتها: كيف يستطيع الإنسان ضبط لسانه عن الكلام، وهل الكلام عن الناس السيئين الذين يؤذوننا بكلامهم وأفعالهم وصنائعهم ،هل يعتبر ذلك غيبة، أفيدونا بذلك؟","title":"وجوب حفظ اللسان عن فلتاته","answer":"الجواب:  الواجب على المؤمن أن يجتهد في حفظ لسانه مما حرم الله من الغيبة والنميمة والفحش والسب ونحو ذلك، والكذب ونحو ذلك، ويجتهد في حفظ وقته بطاعة الله، وذكر الله، وقراءة القرآن، ونحو ذلك، أو السكوت حتى لا يقع في المهالك والمعاصي، يجتهد في حفظ جوارحه، ومن أهمها اللسان من كل ما يغضب الله، ويجتهد في إشغالها بطاعة الله، بما أوجب الله، وبما شرع الله من صلاة وقراءة وذكر وغير ذلك مما ينفعه، ويحذر شغل لسانه بما يضره من غيبة أو نميمة أو سب لأحد، أو غير هذا مما حرمه الله.  فعليه أن يتقي الله، وأن يجاهد نفسه في ذلك؛ حتى يستقيم على الحق، وحتى يدع ما حرم الله على بصيرة، ويسأل ربه التوفيق والإعانة، والله سبحانه هو الموفق والمعين -جل وعلا- وهو القائل  في كتابه: ادْعُونِي أَسْتَجِبْ لَكُمْ [غافر:60]، فالمؤمن يسأل ربه، ويستعين به، ويتوجه إليه بقلبه وقالبه في أن يعينه على الخير، وعلى حفظ جوارحه عما حرم الله، وأن يعينه على استعمالها في طاعة الله . المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11213/وجوب-حفظ-اللسان-عن-فلتاته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_504/50409.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":13042,"question":"السائل (أ. أ) من الرياض يقول: قبل خروجي إلى المدرسة أقبل رأس ويد والدي ووالدتي، هل في ذلك بأس بتقبيل يد الوالد، أو الوالدة؟","title":"حكم تقبيل يد الوالدين","answer":"الجواب:  لا حرج في ذلك -إن شاء الله- لكن تركه بعض الأحيان أحسن، ليس بدائم، تارة وتارة، وإلا فلا حرج في ذلك، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/11259/حكم-تقبيل-يد-الوالدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_505/50502.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":13180,"question":"السائلة التي رمزت لاسمها بـ أم عبدالرحمن عبدالله الرياض تقول في هذا  ما الحكم -سماحة الشيخ- فأحيانًا تقوم المرأة بالاتصال على صديقة لها، أو أخت لها في الله، ويقوم الرجل بالرد عليها، هل تبدأ بالسلام، أم تطلب حاجتها مباشرة؟","title":"البدء بالسلام عند المكالمة بالهاتف","answer":"الجواب:  الأفضل أن تبدأ بالسلام، تقول: السلام عليكم، ثم تطلب حاجتها، تقول: السلام عليكم بصوت معتاد، ليس فيه ترخيم، ولا شيء يطمع الرجل فيها، بل بالصوت المعتاد: السلام عليكم، ثم تسأل: أين أمك؟ أين الأخت فلانة؟ أين صاحبة البيت؟ تسأل عن مرادها، نعم.","link":"https://binbaz.org.sa/fatwas/11435/البدء-بالسلام-عند-المكالمة-بالهاتف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_511/51116.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":13344,"question":"السائلة تقول في هذا  ما حكم المزاح مع الوالدين، كمناداة الأم باسمها، أو مناداة الأب باسمه في حدود الدين، مع رضاهم عن هذا المزاح، وعدم غضبهم منه، وذلك بهدف الترفيه، والترويح عن النفس، وعن نفس الوالدين؟","title":"حكم المزاح مع الوالدين","answer":"الجواب: المزاح القليل لا بأس به، إذا كان بحق، كان النبي ﷺ يمزح قليلًا، ولكن بحق -عليه الصلاة والسلام- فالمزاح القليل مع الوالدين، أو مع الإخوة، أو مع غيرهم إذا كان بحق لا بأس؛ لكن يكره الإكثار منه، لكن يكون قليلًا. والأفضل في حق الوالدين أن تدعوه بالاسم الذي يرضاه، يا والدي، يا أماه، يا والدتي، هذا هو الأفضل، بدلًا من أن تقول: يا فلانة، يا فاطمة، يا كذا، يا محمد، يا زيد، تدعوه باسمه، الأفضل أن تقول: يا والدي، أو يا أبا فلان، أو يا أم فلان، هكذا، تدعوهم بأحب الأسماء إليهم، وبأحب الألفاظ إليهم، وإن مازحته؛ فليكن بحق، وليكن قليلًا إذا كانا يرضيان بالمزح منك. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11630/حكم-المزاح-مع-الوالدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_542/54205.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":13406,"question":"السائل يقول في سؤاله الثاني: هل يكفي أن أصل رحمي عبر الهاتف، أم لابد من الذهاب إليهم؟","title":"هل يكفي صلة الرحم عن طريق الهاتف؟","answer":"الجواب: هذا يختلف: إذا كان الذهاب ضروريًا؛ فلابد من ذلك، وإلا فالهاتف والمكاتبة تكفي، والحمد لله، السؤال عنهم من طريق الهاتف -التلفون- من طريق المكاتبة، من طريق الزيارة، كل هذا طيب، لكن إذا دعت الحاجة إلى الذهاب إليهم؛ لمواساتهم، أو لمرضهم، أو نحو ذلك، فمن صلة الرحم الذهاب إليهم إذا كان مقعدًا، ولا يتيسر صلته إلا بزيارته تزوره، أو مريضًا تزوره، فإذا تيسر صلته من دون زيارة، بالمكاتبة، مع صلته إذا كان فقيرًا، ومواساته، وإعطائه حاجته مع المكاتبة؛ فلا بأس فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]. وإذا ما تيسرت المكاتبة ولا تيسرت المكالمة الهاتفية، وتيسرت الزيارة بالنفس؛ تزوره بنفسك، وإلا فبوكيلك، ترسل له الحاجة والصلة بواسطة الوكيل. المقصود: أن الإنسان يتقي الله ما استطاع، يقول النبي ﷺ: من أحب أن يبسط له في رزقه، وأن ينسأ له في أجله؛ فليصل رحمه ويقول -عليه الصلاة والسلام-: ليس الواصل بالمكافي، ولكن الواصل الذي إذا قطعت رحمه وصلها ولما خلق الله الرحم قالت: يا رب! هذا مقام العائذ بك من القطيعة هكذا جاء عن النبي ﷺ في الحديث الصحيح، تقول الرحم لما خلقها الله: هذا مقام العائذ بك من القطيعة، فقال لها -جل وعلا-: ألا ترضين أن أصل من وصلك، وأن أقطع من قطعك؟ قالت: بلى يا رب. قال: فذلك لك. فالله -جل وعلا- يصل من وصل رحمه، ويقطع من قطع رحمه، والخطر عظيم، يقول النبي ﷺ: لا يدخل الجنة قاطع رحم. فالواجب الحذر، والقطيعة تكون بالإعراض، وعدم المبالاة، وعدم الصلة بالمال، ولا بالكلام الطيب، ولا بالبدن، هذه القطيعة، والصلة بالمال، أو بالكلام الطيب، أو بالمكاتبة، أو بالهاتف، هذا كله صلة، والمؤمن يتحرى كمال الصلة، فالفقير يحتاج إلى زيادة مع الكلام، ومع الزيارة البدنية، يحتاج إلى زيادة بالمواساة المالية لفقره، سواء من الزكاة، أو من غيرها. وهكذا الإنسان الذي يقع في كربة من صلة الرحم، السعي في فك كربته، أي كربة كانت، كربة دين، تسعى في قضاء دينه إذا كنت قادرًا، كربة السجن بحق، تسعى في إطلاقه بالطريقة التي شرعها الله، وأباحها، خائف تسعى في تأمينه بالطريقة التي تستطيعها.. إلى غير ذلك من وجوه الصلة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11697/هل-يكفي-صلة-الرحم-عن-طريق-الهاتف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_526/52604.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":13409,"question":"تقول في سؤالها الثاني: أشكو لكم حال والدي أثناء قيادته لسيارته، فإنه عندما تتعرض له سيارة من السيارات بخطأ، أو غيره يقوم بسبه، وشتمه وغير ذلك، حتى اللعان له نصيب من ذلك، فنطلب من سماحتكم توجيه نصيحة له لعله يستمع لسماحتكم.","title":"حكم لعن وشتم مخالفي أنظمة السير","answer":"الجواب:  نوصي الإخوان جميعًا بالحلم والصبر، والتحمل والرفق في سوق السيارة، وتحري أسباب السلامة، وإذا تعدى عليه أحد؛ فنوصيه بالرفق، والحلم والصبر، والتفاهم مع المتعدي، فقد يكون مغلوبًا على أمره، وليس باختياره، فنوصي الجميع بالحلم، والكلام الطيب، وحل المشاكل بالأسلوب الحسن، هذا هو الوصية للجميع؛ لأن الله  أحب من عباده ذلك. يقول النبي ﷺ: البر حسن الخلق ويقول -جل وعلا-: إِنَّ اللَّهَ مَعَ الَّذِينَ اتَّقَوْا وَالَّذِينَ هُمْ مُحْسِنُونَ [النحل:128] ويقول -جل وعلا-: وَجَزَاءُ سَيِّئَةٍ سَيِّئَةٌ مِثْلُهَا فَمَنْ عَفَا وَأَصْلَحَ فَأَجْرُهُ عَلَى اللَّهِ [الشورى:40] ويقول : وَإِنْ عَاقَبْتُمْ فَعَاقِبُوا بِمِثْلِ مَا عُوقِبْتُمْ بِهِ وَلَئِنْ صَبَرْتُمْ لَهُوَ خَيْرٌ لِلصَّابِرِينَ [النحل:126] ويقول: وَاصْبِرْ وَمَا صَبْرُكَ إِلَّا بِاللَّهِ [النحل:127]. فالمؤمن يتحرى الخير، ويتحرى الصبر، ويتعلم الجزاة بالمعروف فَمَنْ عَفَا وَأَصْلَحَ فَأَجْرُهُ عَلَى اللَّهِ [الشورى:40] يتحرى الخير، ويتحرى الصبر، ويقول ﷺ: ليس الواصل بالمكافي، ولكن الواصل الذي إذا قطعت رحمه وصلها.  فالمحسن، والمجازي على السيئة بالحسنة هذا له درجة عظيمة، وفضل كبير، فالله -جل وعلا- يحب من عباده أن يتناصحوا، وأن يتواصوا بالحق، وأن يصبروا، وأن يتعاملوا بالرفق والعفو والإحسان والجود والكرم والصلح، كما قال تعالى: وَالصُّلْحُ خَيْرٌ [النساء:128] وقال: وَأَحْسِنُوا إِنَّ اللَّهَ يُحِبُّ الْمُحْسِنِينَ [البقرة:195]. نعم. المقدم: شيخ عبدالعزيز، تساهل الكثير من الناس باللعان والشتائم، هل لكم توجيه؟  الشيخ: لا يجوز اللعن والشتم، يقول النبي ﷺ: لعن المؤمن كقتله ويقول ﷺ: ليس المؤمن بالطعان، ولا اللعان، ولا الفاحش، ولا البذي ويقول ﷺ: إن اللعانين لا يكونون شهداء، ولا شفعاء يوم القيامة ويقول ﷺ: المستبان ما قالا فعلى البادئ ما قالا فإثمه على البادئ ما لم يأت.... . فالواجب على المؤمن حفظ لسانه، والحذر من شر لسانه، ويقول ﷺ: سباب المسلم فسوق سباب: يعني مسابته، فسوق: يعني معصية خروج عن الطاعة، فالواجب الحذر من السب، والشتم، واللعن، والكلام السيء، والواجب أن يعود المؤمن لسانه الكلام الطيب، ويعود نفسه الحلم والصبر، نسأل الله للجميع الهداية. نعم. المقدم: اللهم آمين، جزاكم الله خيرًا سماحة الشيخ. الشيخ: الله المستعان. المقدم: الله المستعان.","link":"https://binbaz.org.sa/fatwas/11702/حكم-لعن-وشتم-مخالفي-انظمة-السير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_526/52606.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":13478,"question":"أخيرًا يسأل أخونا ويقول: الصفة الصحيحة للتسليم على النساء الأجنبيات ما هي؟","title":"صفة السلام على المرأة الأجنبية","answer":"الجواب: مثل السلام على غيرهم، السلام عليكم، السلام عليكم ورحمة الله وبركاته للرجال والنساء، وإن قال: عليكن بالنون فلا بأس. المقصود: هذا هو السلام الشرعي، وهن يقلن: وعليكم السلام ورحمة الله وبركاته، مثلما قال لهن، إن قال: السلام عليكم؛وجب أن يقولوا: وعليكم السلام، وإن قال: ورحمة الله؛ وجب أن يقولوا: وعليكم السلام ورحمة الله، وإن قال: السلام عليكم ورحمة الله وبركاته؛ وجب الرد بأن يقول: وعليكم السلام ورحمة الله وبركاته؛ لأن الله سبحانه يقول: وَإِذَا حُيِّيتُمْ بِتَحِيَّةٍ فَحَيُّوا بِأَحْسَنَ مِنْهَا أَوْ رُدُّوهَا [النساء:86] فالرد واجب، والزيادة مستحبة، زيادة ورحمة الله وبركاته مستحبة. فإذا قالها المسلم؛ وجب ردها من الرجال والنساء جميعًا، فإذا مر على النساء، أو دخل عليهن في البيت سلم عليهن، لكن على وجه ليس فيه فتنة، بل يكون مع التحجب، ومع الصيانة، وعدم الخلوة بالمرأة، يكون على طريقة شرعية ليس فيها فتنة، ولا تهمة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11781/صفة-السلام-على-المراة-الاجنبية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_478/47807.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":13494,"question":"هل المظلوم في الدنيا يكتب له الأجر في الآخرة، ويكتب له الجنة لصبره؟ وجهونا جزاكم الله خيرًا.","title":"هل يؤجر المظلوم إذا صبر؟","answer":"الجواب: المظلوم إذا صبر واحتسب؛ له أجر، وإذا طلب حقه؛ يعطى حقه، وإذا صبر واحتسب مثل ما قال -جل وعلا-: فَمَنْ عَفَا وَأَصْلَحَ فَأَجْرُهُ عَلَى اللَّهِ [الشورى:40] قد يعطيه الله أجره -جل وعلا- لاحتسابه، وترك الظلامة، وإن انتصر؛ فلا بأس، لكن إذا طلب ما عند الله؛ عفا وأصلح، عفا عن الظالم، يرجو ما عند الله من الثواب، فله أجره عند الله -جل وعلا- نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11799/هل-يوجر-المظلوم-اذا-صبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_518/51808.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":13556,"question":"السائل الذي أرسل بهذه الرسالة عاطف عبدالله من حائل، يقول في هذا  قال الرسول ﷺ: الحياء شعبة من الإيمان ما معنى الحياء؟ وهل هذا حديث؟","title":"ما معنى الحياء؟","answer":"الجواب: نعم، حديث صحيح، يقول النبي ﷺ في الصحيحين: الإيمان بضع وسبعون شعبة، أو قال: بضع وستون شعبة، فأفضلها: قول لا إله إلا الله، وأدناها: إماطة الأذى عن الطريق، والحياء شعبة من الإيمان والحياء خلق كريم قلبي، خلق في القلب يقتضي الانكفاف عما لا ينبغي هذا الحياء، الحياء: خلق كريم في القلب يقتضي أن ينكف صاحبه عما لا ينبغي من المعاصي، يستحي لا يفعل المعاصي، ولا يفعل الأشياء التي تنتقد عليه، يمنعه حياؤه من ذلك، فهو من الإيمان. وقد مر النبي ﷺ على رجل يعظ أخاه في الحياء، يقول له: دع عنك الحياء، فقال له ﷺ: دعه فإن الحياء من الإيمان فالحياء خلق كريم قلبي، يمنع صاحبه من الخصال الذميمة، والأخلاق المنحرفة، ويحمله على مكارم الأخلاق، ومحاسن الأعمال. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11879/ما-معنى-الحياء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_532/53211.mp3","categories":["شروح الحديث","الآداب والأخلاق المحمودة"]},{"id":13575,"question":"في سؤاله الأخير: كنت أعمل في لبنان أنا وأخي، وجاء والدي إلى لبنان، وطلب منا بعض المال، ولم نعطه، فغضب علينا، وذهب إلى سوريا، وبعد عودتنا إلى سوريا قالوا: بأن والدكم قد مات، وهو غضبان عليكم، وعلى أخيك بسبب هذا المال، فهل يقع علينا شيء؟ وما هو البر تجاه والدنا؟","title":"كيفية بر من مات وهو غضبان على أولاده","answer":"الجواب: عليكما التوبة إلى الله، والدعاء له، والصدقة عنه، وأبشروا بالخير -إن شاء الله- عليكم التوبة إلى الله من عقوقه، واجتهدوا في الإحسان إليه بالدعاء، والصدقة عنه، وأنتم على خير -إن شاء الله- نعم.","link":"https://binbaz.org.sa/fatwas/11921/كيفية-بر-من-مات-وهو-غضبان-على-اولاده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_533/53307.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":13583,"question":"في سؤاله الأخير: كنت أعمل في لبنان أنا وأخي، وجاء والدي إلى لبنان، وطلب منا بعض المال، ولم نعطه، فغضب علينا، وذهب إلى سوريا، وبعد عودتنا إلى سوريا قالوا: بأن والدكم قد مات، وهو غضبان عليكم، وعلى أخيك بسبب هذا المال، فهل يقع علينا شيء؟ وما هو البر تجاه والدنا؟","title":"كيفية بر من مات وهو غضبان على أولاده","answer":"الجواب: عليكما التوبة إلى الله، والدعاء له، والصدقة عنه، وأبشروا بالخير -إن شاء الله- عليكم التوبة إلى الله من عقوقه، واجتهدوا في الإحسان إليه بالدعاء، والصدقة عنه، وأنتم على خير -إن شاء الله- نعم.","link":"https://binbaz.org.sa/fatwas/11921/كيفية-بر-من-مات-وهو-غضبان-على-اولاده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_533/53307.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":13630,"question":"هذا سائل للبرنامج أرسل بمجموعة من الأسئلة، السائل أشرف يقول في هذا  ما حكم إكرام الضيف التارك للصلاة؟","title":"حكم إكرام الضيف التارك للصلاة","answer":"الجواب: الضيف ولو كان كافرًا إذا نزل بك؛ تضيفه، وتدعوه إلى الإسلام، مثلما نزل ضيف أهل الطائف وهم كفار، نزلوا بالنبي ﷺ في المدينة، وأنزلهم في المسجد، ودعاهم إلى الإسلام، وأكرمهم، وتابوا، وأسلموا، والحمد لله. فإذا نزل بك الضيف وهو كافر؛ فإنك تدعوه إلى الإسلام، وتكرمه .... الضيافة، وتدعوه إلى دين الله، وتدعو له بالتوفيق، هذا من فضل الإسلام، ومن حسن الإسلام، ومن أسباب الدخول في الإسلام. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11958/حكم-اكرام-الضيف-التارك-للصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_528/52810.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":13647,"question":"السائل (م. ب. ع) له مجموعة من الأسئلة يقول: قلت لصديقي: لك مبلغ كذا إن جاء فلان، هل في ذلك نذر، أم وعد، ما هو بالضبط هذه المسألة مأجورين؟","title":"هل قول لك كذا إن جاء فلان وعدًا أم نذرًا؟","answer":"الجواب: هذا وعد وليس بنذر، هذا وعد وليس بنذر، ومن صفات المؤمن الوفاء بالوعد والعهد؛ خلافًا لأهل النفاق. نعم.","link":"https://binbaz.org.sa/fatwas/11981/هل-قول-لك-كذا-ان-جاء-فلان-وعدا-ام-نذرا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_528/52818.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":13683,"question":"بعد ذلك ننتقل إلى رسالة بعث بها السائل الذي رمز لاسمه بـ (ن. ر. م) مصري ومقيم في خميس مشيط له مجموعة من الأسئلة، يبدأ هذه الرسالة بالسؤال الأول يقول: إذا دخل الشخص إلى المسجد، وقال لشخص آخر يقرأ القرآن: السلام عليكم، فهل يرد الذي يقرأ القرآن السلام، أم لا يرد؟","title":"هل يرد قارئ القرآن السلام؟","answer":"الجواب: الواجب عليه أن يرد، يقطع القراءة، ويرد السلام، أما إذا كان في الصلاة يرد بالإشارة، الإشارة بيده، أما إذا كان في قراءة فقط، ليس في الصلاة؛ فإنه يقطع القراءة، ويرد، يقول: وعليكم السلام، نعم.","link":"https://binbaz.org.sa/fatwas/12034/هل-يرد-قارى-القران-السلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_519/51912.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":13717,"question":"أحد الإخوة المستمعين بعث برسالة هو علي سعد محمد من السودان، أخونا يقول: عندما يسلم المذيع في الراديو، أو التلفزيون عند بداية البرنامج مثلًا، فهل يجب علي أن أرد السلام؟","title":"حكم رد السلام على المذيع في التلفاز أو الراديو","answer":"الجواب: ينبغي لك أن ترد السلام؛ لأنه سلم على المستمعين وأنت منهم، فتقول: وعليكم السلام ورحمة الله وبركاته، أما الوجوب محل نظر؛ لأنه فرض كفاية، لكن أنت مشروع لك أن ترد السلام؛ لأنه قد لا يرد غيرك، فأنت ترد السلام، وتأخذ الأجر، إذا قلت: وعليكم السلام ورحمة الله وبركاته؛ كتب الله لك ثلاثين حسنة، فرد السلام، ولا تقل: يسلم غيري، أنت بادر بالسلام، وهذا هو المشروع لك، وقد يجب عليك. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12088/حكم-رد-السلام-على-المذيع-في-التلفاز-او-الراديو","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_481/48108.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":13724,"question":"يقول: إذا مر رجل على قوم يأكلون، هل يسلم عليهم، لأنا سمعنا أن ذلك لا يجوز؟","title":"حكم إلقاء السلام على قوم يأكلون","answer":"الجواب: نعم يسلم عليهم، والذي قال: لا يسلم غلط، يسلم عليهم، إذا جاء لقوم وهم يأكلون، أو يقرؤون، أو يتحدثون؛ يسلم عليهم، يقول: السلام عليكم، أو السلام عليكم ورحمة الله، أو ورحمة الله وبركاته، ولا يكره ذلك، بل يشرع، وهم يردون عليه. نعم.. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12095/حكم-القاء-السلام-على-قوم-ياكلون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_481/48112.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":13725,"question":"في ثاني أسئلتها تقول سماحة الشيخ عبدالعزيز: ما حكم رد سلام المرأة على الرجال الأجانب؟","title":"حكم سلام المرأة وردها على الأجنبي","answer":"الجواب: لا بأس أن ترد السلام وأن تسلم، كان النساء يسلمن على النبي ﷺ ويرد عليهن السلام، من دون أسباب فتنة بالسلام العادي، لا فيه تكسر، ولا تغنج، تسلم سلامًا عاديًا، ويرد عليها لا بأس، كان النساء يسلمن على النبي ﷺ وعلى الصحابة، وكان النبي ﷺ يرد عليهن، لكن مع التستر، والحجاب وعدم الخلوة. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12096/حكم-سلام-المراة-وردها-على-الاجنبي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_545/54513.mp3","categories":["الحقوق الزوجية","الآداب والأخلاق المحمودة","قضايا المرأة"]},{"id":13771,"question":"يسأل أخونا عن حكم عمل بعض الناس في تقبيل أيادي الكبار في السن، مثل الأم والأب والعم والخال وأب الزوج وأم الزوج وزوجة الأب، وأحيانًا الكبار في السن من القرابة، هل هذا جائز أو لا؟","title":"حكم تقبيل أيدي كبار السن","answer":"الجواب: لا حرج فيه في الجملة لكن يكره أن يتخذ عادة دائمًا دائمًا، إذا فعله بعض الأحيان لا بأس، أما اتخاذه عادة كلما قابل أم زوجته أو كلما قابل أبا زوجته قبل فترك هذا أولى لئلا يظن أنه سنة دائمة، وإنما هو من باب الاحترام والإكرام، وقد كان النبي ﷺ إذا دخلت عليه فاطمة قام إليها وأخذ بيدها وقبلها عليه الصلاة والسلام، وهكذا إذا دخل عليها قامت إليه عليه الصلاة والسلام وقبلته وأخذت بيده، هذا لا بأس به، كما فعلته فاطمة مع النبي ﷺ وكما فعله معها عليه الصلاة والسلام، لكن جعل ذلك عادة مستمرة مع هؤلاء الأقارب والكبار تركه أولى يكون بعض الأحيان إذا رأى ذلك في بعض الأحيان، في بعض الأحيان يترك ذلك حتى لا يظن أنه سنة دائمة. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12163/حكم-تقبيل-ايدي-كبار-السن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_601/60110.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":13829,"question":"يقول السائل: هل يجوز لي أن أسلم على زوجة عمي أو خالي أو غيرهما من العجائز اللاتي بلغن سن اليأس؟","title":"حكم السلام على النساء","answer":"الجواب: السلام بالكلام لا بأس حتى مع غير العجائز، لك أن تسلم على النساء شبابًا أو عجائز من دون خلوة ومن دون نظر، بل مع غض البصر ومع عدم الخلوة ترد السلام أو تبدأ بالسلام على قريباتك من بنات العم أو بنات الخال أو نحوهن أو زوجة أخيك أو زوجة عمك لا بأس بهذا ولو كانت شابة، ترد السلام أو تبدأ بالسلام، أو تقول: كيف أولادك؟ كيف حال والديك؟ وما أشبه ذلك، لكن لا يجوز مع الخلوة، ولا يجوز مع وجود التكشف والتعري وعدم التستر، بل يجب إذا وجدت شيئًا من هذا أن تنصح، إذا كانت غير متسترة تنصحها وتقول تحجبي، ولا بأس أن تسلم ولا بأس أن تسأل عن حالها لكن تنصحها إذا قصرت في شيء، تأمرها بالحجاب تأمرها بعدم الخلوة بالأجنبي تبين لها الحكم الشرعي. نعم.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12195/حكم-السلام-على-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_530/53006.mp3","categories":["الحقوق الزوجية","الآداب والأخلاق المحمودة","قضايا المرأة"]},{"id":13961,"question":"رسالة وصلت إلى البرنامج من دولة الكويت بتوقيع إحدى الأخوات المستمعات تقول: أختكم في الله! تسأل في سؤال لها عن تفسير منام في الواقع، وإن كان البرنامج لا يهتم بهذا النوع، إلا أنه يتعلق بأمر دينها، فتسأل أختنا وتقول: نرجو من حضرة الشيخ الكريم الإجابة على أسئلتنا مشكورًا.السؤال الأول: حلمت في منامي أنني ألبس ذهبًا كبيرًا يغطي صدري كله، وكنت أنظر إليه، وقد أعجبني بجماله كثيرًا في الحلم، أرجو من حضرتكم تفسير هذا؛ لأني أخاف أن يكون علي شيء في النقص في أمور ديني، وهل الإنسان عندما يحلم بالذهب يكون محمود العاقبة؟ مع العلم بأني أزكي الذهب الذي أملكه كله، الذي ألبس والذي لا ألبس في كل عام، جزاكم الله خيرًا.","title":"تفسير رؤيا لبس الذهب","answer":"الجواب: نرجو أنها رؤيا خير، وأن هذا الشيء خير لك في الدنيا والآخرة إن شاء الله، لا أعلم تفسيرها عينًا، ولكن الظاهر -والله أعلم- أنها رؤية حسنة وصالحة، ولا شيء عليك فيها، بل هي بشرى خير إن شاء الله. نعم.\nالمقدم: إن شاء الله، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12382/تفسير-رويا-لبس-الذهب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_605/60506.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":14028,"question":"من سوريا هذه رسالة بعث بها مستمع من هناك يقول: أحمد محمد حبوس سوري الجنسية يسأل ويقول: لقد تركت بلدي مسقط رأسي وذهبت إلى بلد آخر يبعد عن مسقط رأسي عشرين كيلو متر، وهناك والدتي رفضت أن تأتي معي وهي غاضبة ولن ترضى إلا إذا رجعت، أي: عدت إلى بلدي، وأنا أرى إقامتي في البلد الحالي لي به صلاح لذريتي وأنا خائف من غضب السيدة الوالدة، أرجو توجيهي، جزاكم الله خيرًا.","title":"هل يلزم البقاء في البلد طاعة للأم مع تضرر الأولاد؟","answer":"الجواب: إذا كانت إقامتك في البلد الأخير أصلح لدينك وأصلح لذريتك فالزم ذلك ولا حرج عليك، إذا كانت إقامتك في بلد أمك تضرك أو تضر ذريتك لما فيها من الفساد الكثير والشر العظيم فأنت مأجور وأنت على خير، والزم المحل الذي فيه الخير والصلاح، ولا يضرك غضبها عليك، وعليك ببذل الأسباب في التماس رضاها، وشرح حالك لها وبيان الأسباب باللطف والكلام الطيب والعبارات الحسنة حتى ترضى عنك إن شاء الله، وقد قال النبي عليه الصلاة والسلام: من التمس رضا الله بسخط الناس رضي الله عنه وأرضى عنه الناس، وفي اللفظ الآخر: من التمس رضا الله بسخط الناس كفاه الله مئونة الناس. فأنت يا أخي التمس رضا الله واستقم واصبر وعليك بالكلام الطيب مع الوالدة والإحسان إليها والتماس رضاها بالأسلوب الحسن وشرح الأحوال التي أوجبت لك هذا الانتقال وهي إن شاء الله ترضى عنك، والله جل وعلا هو الموفق الهادي . نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12454/هل-يلزم-البقاء-في-البلد-طاعة-للام-مع-تضرر-الاولاد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_612/61204.mp3","categories":["الآداب والأخلاق المحمودة","نصائح وتوجيهات"]},{"id":14029,"question":"من سوريا هذه رسالة بعث بها مستمع من هناك يقول: أحمد محمد حبوس سوري الجنسية يسأل ويقول: لقد تركت بلدي مسقط رأسي وذهبت إلى بلد آخر يبعد عن مسقط رأسي عشرين كيلو متر، وهناك والدتي رفضت أن تأتي معي وهي غاضبة ولن ترضى إلا إذا رجعت، أي: عدت إلى بلدي، وأنا أرى إقامتي في البلد الحالي لي به صلاح لذريتي وأنا خائف من غضب السيدة الوالدة، أرجو توجيهي، جزاكم الله خيرًا.","title":"هل يلزم البقاء في البلد طاعة للأم مع تضرر الأولاد؟","answer":"الجواب: إذا كانت إقامتك في البلد الأخير أصلح لدينك وأصلح لذريتك فالزم ذلك ولا حرج عليك، إذا كانت إقامتك في بلد أمك تضرك أو تضر ذريتك لما فيها من الفساد الكثير والشر العظيم فأنت مأجور وأنت على خير، والزم المحل الذي فيه الخير والصلاح، ولا يضرك غضبها عليك، وعليك ببذل الأسباب في التماس رضاها، وشرح حالك لها وبيان الأسباب باللطف والكلام الطيب والعبارات الحسنة حتى ترضى عنك إن شاء الله، وقد قال النبي عليه الصلاة والسلام: من التمس رضا الله بسخط الناس رضي الله عنه وأرضى عنه الناس، وفي اللفظ الآخر: من التمس رضا الله بسخط الناس كفاه الله مئونة الناس. فأنت يا أخي التمس رضا الله واستقم واصبر وعليك بالكلام الطيب مع الوالدة والإحسان إليها والتماس رضاها بالأسلوب الحسن وشرح الأحوال التي أوجبت لك هذا الانتقال وهي إن شاء الله ترضى عنك، والله جل وعلا هو الموفق الهادي . نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12454/هل-يلزم-البقاء-في-البلد-طاعة-للام-مع-تضرر-الاولاد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_612/61204.mp3","categories":["الآداب والأخلاق المحمودة","نصائح وتوجيهات"]},{"id":14041,"question":"هل يصح قول: تقبل الله، والتسليم باليد بعد إتمام الصلاة وهذا شائع بين الناس؟","title":"حكم المصافحة بعد الصلاة","answer":"الجواب: إذا صافح أخاه بعد الصلاة بعد الذكر بعد فراغه من الذكر صافح أخاه إذا كان ما صافحه قبل ذلك؛ ما صافحه في الصف ولا عند الدخول صافحه فلا بأس، لكن من حين يسلم يبدأ بالمصافحة لا، هذا غير مشروع، إذا سلم يقول: أستغفر الله ثلاثًا، اللهم أنت السلام ومنك السلام تباركت يا ذا الجلال والإكرام، لا إله إلا الله وحده لا شريك له، له الملك وله الحمد وهو على كل شيء قدير، لا حول ولا قوة إلا بالله، لا إله إلا الله ولا نعبد إلا إياه له النعمة وله الفضل وله الثناء الحسن، لا إله إلا الله مخلصين له الدين ولو كره الكافرون، اللهم لا مانع لما أعطيت ولا معطي لما منعت ولا ينفع ذا الجد منك الجد. هكذا كان النبي يفعل عليه الصلاة والسلام إذا سلم من الصلاة فيقول: أستغفر الله ثلاثًا، اللهم أنت السلام ومنك السلام تباركت يا ذا الجلال والإكرام، ثم ينصرف إلى الناس ويعطيهم وجهه الكريم عليه الصلاة والسلام، ثم يأتي بالذكر الذي تقدم: لا إله إلا الله وحده لا شريك له، له الملك وله الحمد وهو على كل شيء قدير، لا حول ولا قوة إلا بالله، لا إله إلا الله ولا نعبد إلا إياه له النعمة وله الفضل وله الثناء الحسن، لا إله إلا الله مخلصين له الدين ولو كره الكافرون. وإذا صافح أخاه عن يمينه أو شماله إذا كان ما صافحه قبل ذلك فهذا حسن لما فيه من الإيناس والتآلف، وقد قال عليه الصلاة والسلام في الحديث الصحيح: ألا أدلكم على شيء إذا فعلتموه تحاببتم؟ أفشوا السلام بينكم، وكان النبي ﷺ يصافح أصحابه ويقول ﷺ: إذا لقي أحدكم أخاه فليسلم عليه، فإذا حال بينه وبينه جدار أو حجر أو شجرة ثم لقيه فليسلم عليه، وكان الصحابة إذا تلاقوا تصافحوا . فالمصافحة والسلام سنة مؤكدة وفي ذلك خير عظيم وتآلف وإيناس وتقارب بين المسلمين، وإذا قد كان سلم عليه في الصف قبل الصلاة كفى ذلك إن شاء الله، وإن صافحه بعد ذلك لا يضر إن شاء الله، لكن يكتفي بالمصافحة الأولى والحمد لله إذا كان صافحه عندما لقيه في الصف أو عندما فرغ من تحية المسجد أو الراتبة صافحه، كل هذا يكفي والحمد لله، ولو فرض أنه صافحه بعد ذلك بعد الفراغ من الذكر في الفريضة صافحه مرة أخرى فلا نعلم في هذا بأساً؛ لأن ذلك يزيد خيرًا وألفة ومحبة بين المسلمين والأمر في هذا واسع والحمد لله.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12468/حكم-المصافحة-بعد-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_612/61210.mp3","categories":["الأدعية والأذكار","الآداب والأخلاق المحمودة"]},{"id":14090,"question":"هل تقبيل الصديق في الخد بعد مدة من الفراق فيه شيء أم لا؟","title":"حكم تقبيل الصديق في الخد","answer":"الجواب: لا نعلم فيه شيئًا، والأفضل أن يقبله بين عينيه أو الأنف أو الرأس، وإن اكتفى بالمصافحة كفى، المصافحة كافية، وقد ورد عن النبي ﷺ التقبيل في بعض الأحيان، قد قبله بعض أصحابه في بعض الأحيان قبلوا رأسه، وقبلوا يده عليه الصلاة والسلام، لكن المصافحة كافية، وإن قبله بين عينيه، فهو أولى من الخد، أو قبل الأنف كذلك عند القدوم من السفر وطول الغيبة، وروي عن النبي ﷺ أنه لما قدم عليه جعفر بن أبي طالب من الحبشة عام خيبر، قبل بين عينيه عليه الصلاة والسلام، والصديق  لما دخل على عائشة وهي مريضة قبل خدها، فالأمر في هذا واسع، فالمحرم يقبل خد بنته أو أخته، ويقبل رأس أمه وبين عينيها، أو رأس جدته أو أخته الكبيرة، أو عمته، أو خالته، والمصافحة كافية.\nوهكذا الإنسان مع صديقه إذا لقيه يصافحه؛ كما جاء في الحديث يقول النبي ﷺ: إذا لقي أحدكم أخاه فليسلم عليه، فإن حالت بينه وبينه شجرة أو جدار أو حجر، ثم لقيه فليسلم عليه، وهذا مبالغة في الإيناس والتآلف وإزالة الوحشة، وقال عليه الصلاة والسلام: للمسلم على المسلم ست خصال: إذا لقيته فسلم عليه، وإذا دعاك فأجبه، وإذا استنصحك فانصح له، وإذا عطس فحمد الله فشمته، وإذا مرض فعده، وإذا مات فاتبعه، وقال أنس : \"كان أصحاب النبي ﷺ إذا تلاقوا تصافحوا، وإذا قدموا من سفر تعانقوا\"، وثبت عن فاطمة رضي الله عنها: \"أنها كانت إذا دخلت على أبيها عليه الصلاة والسلام قام إليها وأخذ بيدها وقبلها وأجلسها مجلسه، وكان إذا دخل عليها قامت إليه وأخذت بيده وقبلته وأجلسته في مجلسها رضي الله عنها\"، هذا كله من باب واسع والحمد لله.\nولما تاب الله على كعب بن مالك وصاحبيه، وجاء كعب إلى المسجد والنبي في المسجد عليه الصلاة والسلام وحوله الناس بعد التوبة، قام إليه طلحة بن عبيد الله التيمي -أحد العشرة المشهود لهم بالجنة- قام إليه يهرول، حتى صافحه وهنأه بتوبة الله، وكان الصحابة يصافحون النبي ﷺ، وكان يصافحهم عليه الصلاة والسلام. فالسنة المصافحة وإفشاء السلام، أما التقبيل فأمره أسهل، ولا سيما عند القدوم من السفر وعند طول الغيبة، إذا قبل فلا حرج إن شاء الله، بين عينيه، أو رأسه، أو قبل محرم محرمه في خدها أو على رأسها، كل ذلك واسع إن شاء الله. نعم.","link":"https://binbaz.org.sa/fatwas/12545/حكم-تقبيل-الصديق-في-الخد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_610/61012.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":14144,"question":"يقول في سؤاله الثاني: شخص يستخدم التورية فما حكم التورية في ذلك؟","title":"ما حكم التورية؟","answer":"الجواب: إذا دعت لها الحاجة فلا بأس، وإلا ينبغي أن يصرح في كلامه لكن إذا دعت الحاجة إليها فلا بأس بالتورية، كأن يسأل عن شخص هل هو موجود عندكم ويكره أن يخبر عنه؛ لأن في مصلحة ترك الخبر عنه فيه مصلحة له، أو فيه خوف عليه لو خبر عنه، فيقول: ليس فلان عندنا ويضرب يده، أو يضرب المجلس اللي ما هو فيه ليس عندنا هاهنا، أو ليس عندنا هاهنا ويضرب يده، ويتأول أنه ليس في اليد أو ليس في المجلس الذي هو فيه، ونحو ذلك. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12585/ما-حكم-التورية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_546/54609.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":14188,"question":"في ثاني أسئلته يقول سماحة الشيخ: رجل كثير المال وفي نفس الوقت هو جاري لا يصلي ولا يصوم ولا يدفع الزكاة لمستحقيها، ولم يحج، هل يجوز أن أرد عليه السلام وأن آكل معه وأن أخالطه في بعض الأوقات؟","title":"حكم مخالطة تارك فرائض الإسلام","answer":"الجواب: مثل هذا الرجل يجب أن ينصح ويوجه إلى الخير، ويعلم أن الصلاة فريضة والزكاة فريضة، والصوم فريضة وأنها من أركان الإسلام الخمسة، يقول النبي ﷺ: بني الإسلام على خمس: شهادة أن لا إله إلا الله، وأن محمدًا رسول الله، وإقام الصلاة وإيتاء الزكاة، وصوم رمضان وحج البيت. هذه عمد الإسلام وفرائض الإسلام، فيجب أن ينبه وينصح ويوجه إلى الخير لعله يستجيب، فإن لم يستجب وجب أن يهجر، لا تجالسه ولا تأكل طعامه ولا تزره؛ لأنه أتى جريمة عظيمة كفرية ترك الصلاة كفر أكبر -نسأل الله العافية-، فهو جدير بأن يهجر ويرفع أمره إلى ولي الأمر، إذا كان في دولة إسلامية يرفع أمره إلى ولي الأمر حتى يستتاب فإن تاب وإلا يقتل، نسأل الله العافية. نعم.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12641/حكم-مخالطة-تارك-فراىض-الاسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_547/54720.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":14227,"question":"هناك مجموعة من الأشخاص في بلدي تواطئوا على ظلمي، والآن والحمد لله وقد فرج الله همي وأريد العفو عنهم باعتبار أن ذلك مقدر من الله ، كيف هي الطريقة المثلى التي تنصحونني بها؟ جزاكم الله خيرًا.","title":"ما الطريقة في العفو عن الآخرين؟","answer":"الجواب: إذا كانوا قد ظلموك وأحببت العفو عنهم فأنت مأجور ولك خير عظيم وفضل كبير؛ لأن الله جل وعلا يقول: وَأَنْ تَعْفُوا أَقْرَبُ لِلتَّقْوَى [البقرة:237]، ويقول النبي ﷺ: ما زاد الله عبدًا بعفو إلا عزًا، ويقول جل وعلا: فَمَنْ عَفَا وَأَصْلَحَ فَأَجْرُهُ عَلَى اللَّهِ [الشورى:40]، فأنت على خير عظيم فإذا ظلموك في غيبة أو مال أو سب أو نحو ذلك وعفوت عنهم فأنت مأجور، جزاك الله خيرًا.\nالمقدم: إذًا الطريقة لو سمحتم؟\nالشيخ: الطريقة أنه يخبرهم حتى يكون ذلك أكمل، أنه قد عفا عنهم، ولا يطالبهم بشيء إذا كانوا قد ظلموه كما قال، وإن لم يخبرهم فلا بأس، المقصود العفو إذا عفا عنهم فأجره على الله، إذا ظلموه أخذوا شيئًا من ماله أو ضربوه أو سبوه أو ما أشبه ذلك من الظلم وعفا عنهم فأجره على الله .\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12681/ما-الطريقة-في-العفو-عن-الاخرين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_486/48604.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":14260,"question":"يسأل أخونا أيضًا ويقول: أنا من أسرة نشأت بينها وبين أسرة عمي خلاف قديم لا أعلم سببه، سوى أنهم يقولون بسبب الورث، وفشلت كل المحاولات للتوفيق والصلح بينهم، وحيث أن الظروف جمعت بيني وبين ابن عمي الأصغر في المدرسة وفي فصل واحد كما أننا نسكن بشارع واحد أيضًا فأصبحنا أصدقاء رغم الخلافات العائلية بين الأسرتين، ولكن سرعان ما تأثر ابن عمي بأسرته وتغير من ناحيتي خصوصًا بعد إتمام المرحلة التعليمية لدرجة أنه يقابلني كأننا لم نعرف بعض ولم يكلمني، ورغم تداخل أصدقائنا للصلح بيننا فما يلبث أن يعود مرة ثانية للمقاطعة، وقد وسطت أهل الخير ولكن دون جدوى، وعندما يئست منه تركته وحتى الآن لم أكلمه، أرجو أن تفيدوني أفادكم الله عن حكم الدين في هذا الخصام حتى لا أكون ارتكبت ذنبًا بمقاطعته، جزاكم الله خيرًا.","title":"توجيه لمن يحرص على صلة قرابته وهم يقاطعونه","answer":"الجواب: قد أحسنت فيما فعلت؛ لأنك حاولت صلة الرحم، فقد أحسنت جزاك الله خيرًا، ونوصيك بالمحاولة والحرص على صلة الرحم مع ابن عمك وبني عمك وعمك إن كان موجودًا ولو كرهوا ذلك، فأنت تفعل ما تستطيع من السلام عليهم وزيارتهم إذا مرضوا، والدعاء لهم بالخير والهداية ومواساة فقيرهم وأنت على خير، لقول النبي ﷺ في الحديث الصحيح: ليس الواصل بالمكافئ وإنما الواصل الذي إذا قطعت رحمه وصلها رواه البخاري في الصحيح، وقوله ﷺ لما سأله رجل قال: يا رسول الله! إن لي قرابة أصلهم ويقطعونني وأحسن إليهم ويسيئون إلي وأحلم عنهم ويجهلون علي، فقال له النبي ﷺ: لئن كنت كما قلت لكأنما تسفهم المل ولا يزال معك من الله ظهير عليهم ما دمت على ذلك.\nفأنت يا أخي على خير، احرص على الصلة والإحسان مهما استطعت، وإذا لم تنجح فالإثم عليهم، وأنت لك أجر، والإثم على من امتنع، وأنت لك أجر في المحاولة وتوسيط من ترى من الأخيار والمشورة على أهلك وعلى أهل عمك بترك الشحناء، فالمال أمره سهل، والدنيا أمرها كلها سهل، فينبغي للمؤمن أن يتحرى ما يرضي الله ويقرب لديه، وأن يدع الشحناء والقطيعة والمال الذي فات يخلفه الله بأفضل منه، وَمَا عِنْدَ اللَّهِ خَيْرٌ وَأَبْقَى [القصص:60]، هذا الذي ينبغي لك ولغيرك من المسلمين مع قراباتهم، والله المستعان. نعم.\nالمقدم: الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12772/توجيه-لمن-يحرص-على-صلة-قرابته-وهم-يقاطعونه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_621/62113.mp3","categories":["الآداب والأخلاق المحمودة","نصائح وتوجيهات"]},{"id":14370,"question":"هل يجوز الأنين للمريض أم هذا من الشكوى سماحة الشيخ؟","title":"حكم أنين المريض","answer":"الجواب: الأنين لا بأس به، إذا تألم لا بأس، ليس من الشكوى، إذا دعت الحاجة إلى ذلك، وصار فيه راحة له، فلا بأس، نعم.","link":"https://binbaz.org.sa/fatwas/12851/حكم-انين-المريض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_551/55112.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":14501,"question":"أضطر للكذب كي ما أصلح بين أهلي وزوجي، ما هو توجيهكم؟","title":"حكم الكذب للإصلاح بين الأقارب","answer":"الجواب: الكذب في الإصلاح لا بأس به، بل صاحب الإصلاح مأجور وإن كذب، لما ثبت عن رسول الله -عليه الصلاة والسلام- أنه قال: ليس الكذاب الذي يصلح بين الناس، فيقول خيرًا، وينمي خيرًا سماه غير كذاب، فالذي يصلح بين الناس بين رجلين مختصمين، أو بين قبيلتين أو بين الأسرة كونه يكذب كذبًا لا يضر أحدًا، وإنما ينفع الأسرة، ويسبب الصلح بينهم، لا حرج في ذلك. فإذا كذبت على أهلك، أن زوجك يدعو لهم، وأنه يثني عليهم، وأنه يحب لهم الخير، وكذبت عليه، قلت له: إن أبي يدعو لك، وأنه يثني عليك، ويحبك، وأمي كذلك وأخواتي وإخواني حتى تصلحي بينهم على وجه ليس فيه شر؛ فلا بأس، أنت مأجورة في هذا. أما إذا كان الصلح يتضمن شيئًا محرم لا، إذا كان الصلح بينهم حتى يسامحوه في ترك الصلاة، أو في ترك المسكر، أو ما أشبه، هذا لا يجوز، ليس لك التوسط في هذا، بل عليهم أن ينكروا عليه، ترك الصلاة ينكروا عليه، شرب المسكر، ينكروا عليه التدخين، ينكرون عليه حلق اللحية، ينكرون عليه إسبال الثياب، هذا مأجورون، وأنت معهم، ساعديه إذا كان زوجك يقصر في هذه الأمور فانصحيه، ولا تسكتي، وليس هذا محل الصلح، بل هذا محل الإنكار، هم ينكرون عليه وأنت معهم، لكن بالأسلوب الحسن، والكلام الطيب، يعني: تبينون له أن الإسبال محرم، وأن الواجب على الرجل أن تكون ثيابه إلى الكعب، لا تنزل عن الكعب، هكذا قال النبي ﷺ يقول -عليه الصلاة والسلام-: ما أسفل من الكعبين من الإزار فهو في النار رواه البخاري في الصحيح، ويقول ﷺ: إياك والإسبال فإنه من المخيلة ويقول -عليه الصلاة والسلام-: ثلاثة لا يكلمهم الله، ولا ينظر إليهم يوم القيامة، ولا يزكيهم، ولهم عذاب أليم: المسبل إزاره، والمنان فيما أعطى، والمنفق سلعته بالحلف الكاذب فجعله مع هؤلاء، فدل ذلك على قبح الإسبال، وهو من أسباب التكبر والخيلاء والتعاظم؛ ولهذا في الحديث الصحيح يقول ﷺ: من جر ثوبه خيلاء لم ينظر الله إليه يوم القيامة لكن ليس بشرط، لو قال: إنه ليس بخيلاء ما يطاع، يؤمر برفع ثيابه وقول النبي ﷺ لأبي بكر لما قال: يا رسول الله، إن إزاري يتفلت علي إلا أن أتعاهده، قال: لست ممن يفعله خيلاء مراد النبي ﷺ: أن الصديق ليس ممن يفعله خيلاء، وإنما يتفلت عليه ثوبه إزاره بعض الأحيان فيتلافاه. فأنت كذلك، إذا كنت ما أنت من أهل الخيلاء، وإنما قد ينحل الإزار ثم تحفظه، ثم تصونه ثم تصلحه، لا شيء عليك، لكن تسحب ثيابك عند الناس، فإذا سألوك... تقول: ما قصدت الخيلاء، من يقول لك هذا؟ من يعلم قلبك وأنت تعمل ما حرم الله عليك؟ أنت متهم بالخيلاء، ثم لو قدر أنك سليم، فقد فعلت منكرًا بإسبال الثياب، وتعريضها للأوساخ والنجاسات، ومخالفة الشرع المطهر بجعلها تحت الكعب، ثم هو إسراف لا حاجة إليه، فأنت قد فعلت منكرًا من وجوه، وهكذا إذا كان الزوج يتعاطى السكر، أو يتعاطى أشياء أخرى....... عليه، أبوك أو أخوك من ذلك وينصحوه، فالإصلاح بينهم في هذا له وجه الصلح. فالواجب أنك أنت وأهلك تستعينوا بالله عليه وتنصحونه بالأسلوب الحسن، وبالتوجيه الطيب، ولا تسامحوه يتعاطى المسكرات، أو يتهاون بالصلاة، أو ما أشبه ذلك، رزق الله الجميع التوفيق. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12990/حكم-الكذب-للاصلاح-بين-الاقارب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_632/nour_63211.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":14577,"question":"هذا سائل يقول في هذا  سماحة الشيخ، لي والد متوفى -رحمه الله- وأريد أن أتصدق عنه، وأخص ذلك بالصدقة فأيهما أفضل وصول الصدقة أو الدعاء؟ وما هو الدعاء الوارد من الكتاب والسنة بالنسبة للدعاء للوالدين؟","title":"مشروعية الدعاء والصدقة عن الوالدين","answer":"الجواب: السنة للمؤمن أن يدعو لوالديه، وأن يترحم عليهما، ويستغفر لهما، ويتصدق عنهما، كما قال الله -جل وعلا-: وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ وَبِالْوَالِدَيْنِ إِحْسَانًا إِمَّا يَبْلُغَنَّ عِنْدَكَ الْكِبَرَ أَحَدُهُمَا أَوْ كِلاهُمَا فَلا تَقُلْ لَهُمَا أُفٍّ وَلا تَنْهَرْهُمَا وَقُلْ لَهُمَا قَوْلًا كَرِيمًا ۝ وَاخْفِضْ لَهُمَا جَنَاحَ الذُّلِّ مِنَ الرَّحْمَةِ وَقُلْ رَّبِّ ارْحَمْهُمَا كَمَا رَبَّيَانِي صَغِيرًا [الإسراء:23-24] كما دعا إبراهيم: رَبَّنَا اغْفِرْ لِي وَلِوَالِدَيَّ وَلِلْمُؤْمِنِينَ يَوْمَ يَقُومُ الْحِسَابُ [إبراهيم:41] فهذا مشروع للمؤمن، وهكذا نوح دعا لمن دخل بيته وللمؤمنين والمؤمنات. المقصود: أن الدعاء مطلوب، فالمؤمن يدعو لوالديه، ويستغفر لهما، ويطلب لهما من الله الجنة والمغفرة، ويتصدق عنهما، ومن هذا قوله ﷺ لما سأله سائل، قال: «يا رسول الله، هل بقي من بر أبوي شيء أبرهما به؟ قال النبي ﷺ: نعم، الصلاة عليهما، والاستغفار لهما، وإنفاذ عهدهما من بعدهما يعني: وصية وإكرام صديقهما، وصلة الرحم التي لا توصل إلا بهما وقال آخر: «يا رسول الله، من أبر؟ -في لفظ: من أحق بحسن صحبتي؟ قال: أمك قال: ثم من؟ قال: أمك قال: ثم من؟ قال: أمك قال: ثم من؟ قال: أبوك، ثم الأقرب فالأقرب وقال رجل: «يا رسول الله، إن أمي افتلتت نفسها، ولم توصي، أفلها أجر إن تصدقت عنها؟ قال النبي ﷺ: نعم وقال -عليه الصلاة والسلام-: إذا مات ابن آدم انقطع عمله إلا من ثلاث: صدقة جارية، أو علم ينتقع به، أو ولد صالح يدعو له، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13074/مشروعية-الدعاء-والصدقة-عن-الوالدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_557/55703.mp3","categories":["إهداء القرب للميت","الآداب والأخلاق المحمودة"]},{"id":14580,"question":"أخونا السائل الحقيقة كتب رسالة مطولة أخوكم (ن. ي. م) نلخصها سماحة الشيخ بأنه يقول:بأنه يسكن في بيت أهله مع زوجته وبنته منذ خمس سنوات، يقول:أولًا: أغتنم فرصة وجودي لإرضاء والدي ووالدتي. وثانيًا: ليس عندي بيت وأنا مرتاح جدًا، ولا يوجد عقبات أمامي، والحمد لله سوى مشكلة واحدة وهي: بأنني سميت ابنتي الأولى حسب رغبة الوالدة، وهو اسم جميل، وأنا مسرور به، وأحمد الله على ذلك.أما الثانية -البنت الثانية- فقد أحرجتني والدتي كثيرًا حتى سميت اسم لا أحبه، ولا يحبه أحد، والمشكلة هي بأنني سجلت اسمها في دائرة النفوس اسم أحبه وهو جميل جدًا، وهو من أسماء الصحابيات ولا حرج فيه أمام الناس والشرع، وفي البيت أطلق عليها الاسم الذي رغبت فيه والدتي، ولا أحد يعرف بالحقيقة سوى زوجتي، سماحة الشيخ، هل أنا مذنب أو مسيئ أمام الله؟ وماذا علي أن أفعل؟علمًا بأنني أسكن مع والدي ووالدتي وهما بأمس الحاجة إلي وأنا أخشى أن تعرف بالحقيقة فتغضب مني، وجهوني سماحة الشيخ.","title":"حكم مخالفة رغبة الأم في تسمية المولود","answer":"الجواب: قد أحسنت فيما فعلت إرضاءً لوالدتك اسمها المكتوب هو المعتمد المقرر في الدوائر الرسمية هو المعتمد، وإذا أرضيت والدتك بأن سميتها بالاسم الذي رغبت فيه فلا بأس -إن شاء الله-، إذا كان الاسم الذي رغبته الوالدة غير مناسب غير طيب، ولا يناسب تسميتها به، فأنت تسعى في مصلحة طفلتك ولا تسميها باسم يضرها، ويسيئ سمعتها، ولكن إذا أرضيت والدتك بإخفاء ذلك فالأمر في هذا سهل -إن شاء الله-، إذا كان الاسم الذي سميتها به مناسب، والاسم الذي قالت أمك ليس فيه محذور شرعًا، فلا حرج.  أما إذا كان الاسم الذي قالته أمك اسم لا يناسب، ولا يليق شرعًا فتركه واجب؛ لأن الطاعة في المعروف، لا تطاع الأم في المعصية، ولا الأب في المعصية، إنما الطاعة في المعروف، لكن إذا كانت طلبت اسمًا لا حرج فيه شرعًا، فإن سميتها به فلا بأس، وإن رأيت الأصلح سميتها اسمًا آخر، وأخفيته على أمك؛ لأنك تراه أصلح للبنت فلا حرج في ذلك -إن شاء الله-، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ، أقول سماحة الشيخ: اختيار الأسماء الطيبة، واختيار بعض الناس لبعض الأسماء التي يكون قد فيها حرج، ومن ثم نجدهم يتحرجون بعد كبر هؤلاء الأطفال، ويريدون التغيير، لعل لكم كلمة أو توجيه في اختيار الأسماء سماحة الشيخ. الشيخ: المشروع للوالد والوالدة أن يتحريا الأسماء الطيبة؛ لأن الإنسان ينادى باسمه يوم القيامة باسم أبيه، فالمشروع للأب والأم أن يتحريا الأسماء الطيبة لأولادهم الذكور والإناث، وأن يتقيا الله في ذلك، هذا هو الواجب على الجميع، والمشروع للجميع أن يتحريا الأسماء المناسبة، لكن لا يجوز التعبيد لغير الله في الأسماء لا يقال: عبد الكعبة، ولا عبد النبي، ولا عبد اللات ولا عبد العزى ولا عبد زيد، ما يسمى بالتعبيد لغير الله، ولكن يتحرى الأسماء المناسبة: محمد، صالح، أحمد، زيد، فلان، إبراهيم، الأسماء ليس فيها محذور، وهكذا أسماء النساء عائشة، مريم، فاطمة، زينب، خديجة.. إلى غير هذا من الأسماء الطيبة، وإذا سماها باسم لا بأس به معتاد عند جماعته فلا بأس. المقصود: أن الأسماء لا مشاحة فيها، إلا ما عبد لغير الله لا يجوز، أو فيه تزكية كونه يسميها بشيء يعني فيه تزكية النبي غير اسم برة إلى غير هذا، قال: الله أعلم بأهل البر منكم أو اسم قبيح يغيره، اسمها عاصية فيغير اسمه عاصية إلى مطيعة، أو إلى زينب أو إلى مريم، يعني أسماء قبيحة إن غيرها لا بأس. فالمقصود: أن المؤمن من الأب والأم يتخير الاسم الطيب لابنه وبنته، الأب والأم يتخيران الأسماء الطيبة، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13077/حكم-مخالفة-رغبة-الام-في-تسمية-المولود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_557/55706.mp3","categories":["الآداب والأخلاق المحمودة","نصائح وتوجيهات"]},{"id":14591,"question":"رسالة وصلت إلى البرنامج من اليمن الشمالي -وصاب العالي- باعثها أحد الإخوة سمى نفسه الأستاذ: علي عبده حميد الوائلي، والعمر ثمان عشرة سنة، يقول: إن أبي رجل صالح، ولكن فيه عيب واحد، وهو أنه في بعض الأوقات يصيح بكلام قد لا يكون جميلًا، علينا أو على الناس، فأزجره بكلام يرده إلى الصواب، ولا يخرج كلامي معه عن سنة الأدب، ثم ألينه حتى يعود إلى الصواب، وإذا كنت ألينه برفق لا يعود، فهل هذا علي حرام؟ وقد وضحت لكم السؤال. أفتوني، جزاكم الله خيرًا.","title":"حكم رفع الصوت على الوالد لزجره","answer":"الجواب: المشروع لك الرفق، وليس لك زجره، ولا رفع الصوت عليه، ولكن تنصحه بالرفق، والأسلوب الحسن عما يحصل منه من الهفوات، أو رفع الصوت في غير محله.  وأما الزجر والشدة فهذا حرام عليك، لا يجوز لك، ولو كان قصدك حسنًا، فليس لك أن ترفع صوتك على أبيك، ولا على أمك، وليس لك زجرهما، ولا الشدة عليهما، قال الله سبحانه في كتابه العظيم: وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ وَبِالْوَالِدَيْنِ إِحْسَانًا إِمَّا يَبْلُغَنَّ عِنْدَكَ الْكِبَرَ أَحَدُهُمَا أَوْ كِلاهُمَا فَلا تَقُلْ لَهُمَا أُفٍّ وَلا تَنْهَرْهُمَا وَقُلْ لَهُمَا قَوْلًا كَرِيمًا  ۝ وَاخْفِضْ لَهُمَا جَنَاحَ الذُّلِّ مِنَ الرَّحْمَةِ وَقُلْ رَّبِّ ارْحَمْهُمَا كَمَا رَبَّيَانِي صَغِيرًا[الإسراء:23، 24].\nويقول النبي ﷺ: رضا الله في رضا الوالدين، وسخط الله في سخط الوالدين ويقول ﷺ لما سئل «أي الأعمال أفضل؟ قال: الصلاة على وقتها قيل: ثم أي؟ قال: بر الوالدين قيل: ثم أي؟ قال: الجهاد في سبيل الله فالواجب عليك الرفق بالوالدين، والإحسان إليهما، وعدم رفع الصوت عليهما، وعدم الزجر والشدة عليهما، أصلحك الله، وبارك فيك. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13088/حكم-رفع-الصوت-على-الوالد-لزجره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_635/nour_63511.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":14624,"question":"يقول في سؤاله هذا سماحة الشيخ: تارك الصلاة لو أن جاري معاندًا وقمت بدعوته أكثر من مرة ونصحته وهو يزداد سخرية، فهل هذا الشخص يقاطع؟","title":"هل يهجر قاطع الصلاة المتكبر؟","answer":"الجواب: نعم، يستحق الهجر، ما دام نصحته ولا يأبى ويتكبر يستحق الهجر، مثلما هجر النبي -عليه الصلاة والسلام- كعب بن مالك وصاحبيه خمسين ليلة حتى تاب الله عليهم، لكن إن تيسر النصح، وأنه ينفع النصح فانصح، وإذا يئست منه ولم ينفع فيه النصح فهو يستحق الهجر، نسأل الله العافية، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13117/هل-يهجر-قاطع-الصلاة-المتكبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_559/55912.mp3","categories":["حكم الصلاة وأهميتها","الآداب والأخلاق المحمودة"]},{"id":14666,"question":"تقول صاحبة الرسالة: لي والدة أتشاجر معها أحيانًا؛ لأني لا أستطيع أن أتمالك نفسي، فماذا أفعل؟أفيدوني، أفادكم الله.","title":"نصيحة لمن يتشاجر مع أمه","answer":"الجواب: الواجب عليك الرفق بالوالدة، وحسن المعاملة، وعدم المشاجرة، الوالدة حقها عظيم، وهكذا الأب حقه عظيم، الله يقول -جل وعلا- في كتابه العظيم في مواضع كثيرة: وَبِالْوَالِدَيْنِ إِحْسَانًا [الإسراء:23] ويقول سبحانه: أَنِ اشْكُرْ لِي وَلِوَالِدَيْكَ إِلَيَّ الْمَصِيرُ [لقمان:14] ويقول -جل وعلا-: وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ وَبِالْوَالِدَيْنِ إِحْسَانًا إِمَّا يَبْلُغَنَّ عِنْدَكَ الْكِبَرَ أَحَدُهُمَا أَوْ كِلاهُمَا فَلا تَقُلْ لَهُمَا أُفٍّ وَلا تَنْهَرْهُمَا وَقُلْ لَهُمَا قَوْلًا كَرِيمًا  ۝ وَاخْفِضْ لَهُمَا جَنَاحَ الذُّلِّ مِنَ الرَّحْمَةِ وَقُلْ رَّبِّ ارْحَمْهُمَا كَمَا رَبَّيَانِي صَغِيرًا([الإسراء: 23 -24].\nفالواجب على الولد أن يتقي الله، وأن يرفق بوالديه، وألا يشاجرهما، بل يسكت أو يخاطبه بالتي هي أحسن، إذا قال أبوه له كلامًا شديدًا، أو سبه، يقول له: هداك الله، رضي الله عنك، جزاك الله خيرًا، لا يقابل بالشدة، ولا بالكلام السيئ، حتى ولو سبه أبوه أو أمه، يقول: جزاك الله خيرًا، رضي الله عنك، هداك الله يا والدة، ونحو هذا من الكلام الطيب، لا يقابل بالسوء أبدًا، ولا يجوز له أن يقابل بالسوء، ولا المشاجرة، ولا رفع الصوت على أبيه، ولا أمه، نسأل الله للجميع الهداية. المقدم: آمين، آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13158/نصيحة-لمن-يتشاجر-مع-امه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_489/48915.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":14690,"question":"أحد الإخوة المستمعين بعث يسأل عن والدة له يقول: إن أقامت في الريف ارتكبتها الأمراض، وضعفت صحتها، وتأبى أن تبقى معي في المدينة إلا لمدة أربعة أشهر فقط، ويسأل هل لي أن أجبرها على الإقامة معي؟ الشيخ: أعد؟المقدم: يقول: إن له والدة إذا أقامت في الريف مرضت، وكثرت عليها الأمراض، وهو مقيم في المدينة، ولا ترضى أن تقيم معه إلا لمدة أربعة أشهر، فهل له أن يجبرها على الإقامة معه؟","title":"هل للولد أن يجبر أمه على الإقامة عنده في المدينة؟","answer":"الجواب: ليس له ذلك، ليس له إجبارها، بل يرفق بها، ويعتني بها، ويجعلها في المكان الذي يناسبها، وإذا لم يتيسر مكان يناسبها إلا بخادم، التمس لها خادمًا يخدمها إذا كانت عاجزة عن نفسها، من أقاربه، أو من غير أقاربه، ويؤدي الأجرة إذا استطاع ذلك، ويرفق بأمه لا يجبرها على شيء لا تريده، الواجب عليه برها والتماس رضاها، وجعلها في المكان الذي يناسبها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13182/هل-للولد-ان-يجبر-امه-على-الاقامة-عنده-في-المدينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_489/48919.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":14718,"question":"السائلة (م. ش) من الزبداني، تقول سماحة الشيخ: إذا طلبت من زوجي أن أذهب إلى أختي، أو إلى خالتي يقول لي: ليس لك صلة رحم، هل هذا صحيح؟ وهل للزوج أن يمنع زوجته من زيارة أقاربها؟","title":"هل للزوج منع زوجته من زيارة أقارها؟","answer":"الجواب: هذا غلط، صلة الرحم واجبة بالكلام الطيب، وبالنفقة إذا كان القريب فقيرًا، وأنت غني تساعده، وتحسن إليه، هذا واجب، صلة الرحم واجبة، وقطيعتها محرمة، ولا يجوز للزوج أن يعين على قطيعة الرحم، ولا أن يأمر بقطيعة الرحم، بل يجب عليه أن يساعد على الخير، ولكن لا تخرجي إلا بإذنه، بالكلام الطيب، والأسلوب الحسن، حتى يأذن، وليس له أن يمنعك من صلة الرحم، لا بالمال، ولا بالزيارة إلا إذا كانت الزيارة فيها شرًا، إذا كانت الرحم رحمًا فيها خبث، عندهم المعاصي، له أن يمنعك من زيارتهم، إذا كان عندهم الشر والمعاصي، ويخشى أن تضرك الزيارة.  أما إذا كانوا أهل خير واستقامة فليس له منعك على الوجه المعتاد المعروف الذي ما فيه مضرة عليه، كأن تزوري أختك أو خالتك أو عمتك أو جدتك أو ما أشبه ذلك من أرحامك أو خالك أو أخاك أو ما أشبه ذلك، لكن على الوجه الذي لا يضر الزوج، وإذا منعك فلا تخرجي إلا بإذنه بالأسلوب الحسن، والكلام الطيب، ولا تعجلي، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13198/هل-للزوج-منع-زوجته-من-زيارة-اقارها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_560/56023.mp3","categories":["الحقوق الزوجية","قضايا المرأة","الآداب والأخلاق المحمودة"]},{"id":14733,"question":"على بركة الله نبدأ هذا اللقاء برسالة من أحد الأخوات تقول: هل المصافحة على الخدين أم باليد جائز؟جزاكم الله خيرًا.","title":"حكم تقبيل الخدين عند المصافحة","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه. المصافحة تكون باليد، باليد اليمنى، مع يد أخيه اليمنى، وهكذا المرأة مع أختها، اليد اليمنى تصافح اليد اليمنى، هذه المصافحة الشرعية.  أما تقبيل الخد ما هو من السنة، السنة المصافحة، وإذا كان الرجل يصافح أمه أو جدته قبلها بين عينيها لا بأس، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13230/حكم-تقبيل-الخدين-عند-المصافحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_561/56101.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":14786,"question":"المستمع (ف. ح. ش) من الدمام، بعث برسالة يقول فيها:ما حكم تقبيل الأم أو الأخت والجدة والعمة والخالة على الخد أو الفم، فقد سمعت أن هذا لا يجوز، ويجب أن يكون التقبيل على الرأس أو اليد، فهل هذا صحيح؟","title":"حكم تقبيل المحارم","answer":"الجواب: لا حرج في تقبيل الوالدة والجدة والأخت والبنت في الخد، فقد ثبت أن الصديق  قبل عائشة مع خدها، أما الأم والجدة فالأنسب أن يكون ذلك على رأسها، أو أنفها؛ لأن ذلك أولى في إجلالها، وإكرامها، نعم. المقدم: جزاكم الله خيرًا.\nالشيخ: أما الفم فتركه أولى.\nالمقدم: للمحارم؟ الشيخ: لأن ذلك للزوج، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13289/حكم-تقبيل-المحارم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_638/nour_63810.mp3","categories":["قضايا المرأة","الآداب والأخلاق المحمودة"]},{"id":14818,"question":"يسأل ويقول: لدى كثير من الناس عادة، وهو أنه عندما يعطس أحد فيقول الشخص الذي يتكلم بعطسة: حلال، هل هذا الكلام صحيح؟","title":"حكم قول المتكلم عندما يعطس شخص: بعطسة حلال","answer":"الجواب: لا أصل لهذا، هذا كلام العامة لا أصل له، ولكن المشروع للمؤمن إذا عطس أن يقول: الحمد لله، ومن سمعه يقول له: يرحمك الله، وهو يقول: يهديكم الله ويصلح بالك، هذا السنة، إذا عطس يقول: الحمد لله، أو الحمد لله رب العالمين، أو الحمد لله على كل حال، ومن سمعه يقول: يرحمك الله، هذا السنة، وهو يقول لمن قال: يرحمك الله، يقول له: يهديكم الله، ويصلح بالكم، هكذا جاءت السنة عن النبي -عليه الصلاة والسلام-، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13329/حكم-قول-المتكلم-عندما-يعطس-شخص-بعطسة-حلال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_643/nour_64310.mp3","categories":["نواقض الإسلام","البدع والمحدثات","الآداب والأخلاق المحمودة"]},{"id":14901,"question":"السائل من جمهورية مصر العربية، يقول في سؤاله الثاني: سماحة الشيخ، والدي أخذ جميع ما أملك من مال، وزرع بها أرض على أن أعيش معه رغمًا عني، مع أنه يعلم أنني لا أرغب العيش في الريف؛ لأنني قد نشأت في المدينة، وتعلمت، وتوظفت بها، ويقول بعد مرور الوقت سوف تأخذ على هذه العيشة في الريف، فما حكم ذلك؟مأجورين.","title":"توجيه لمن أخذ والده ماله ويريد منه العيش معه","answer":"الجواب: عليك أن تستعمل الرفق مع والدك، وأن تصطلح معه على ما يسر الله، وإذا أعاد إليك المال، أو بعض المال، فالحمد لله، عليك العمل الطيب، والرفق، والكلام الحسن مع والدك والصبر؛ لأن حقه عظيم، وبره واجب، نعم.","link":"https://binbaz.org.sa/fatwas/13400/توجيه-لمن-اخذ-والده-ماله-ويريد-منه-العيش-معه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_562/56202.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":15008,"question":"بقي لـسعيد سؤال، لكن نأتي برسالة سالم محمد سالم؛ لأنها تتعلق بالسلام، سالم محمد سالم يقول: دخلت أنا وصديقي إلى المسجد، ونحن نتحدث بعضنا إلى بعض، وبعد أن أدينا تحية المسجد، سلمت عليه، على العادة التي تجري في المساجد، ومددت يدي إليه، فنظر إلي، وأبى أن يمد يده إلي، وقال: لم أفارقك، وهذه بدعة، لم يفعلها الرسول ﷺ، ولا صحابته الكرام، وقد اتخذها الناس كالواجب، اليوم عندما ينتهون من تحية المسجد، ووقفت مدهوش أمامه، فهل زميلي هذا، أو صديقي على حق، أم أنا الذي على حق؟","title":"حكم تكرار السلام والمصافحة بعد الصلاة","answer":"الجواب: لا أعلم بأسًا في أن يصافح المسلم أخاه، بعد فراغهما من تحية المسجد، أو من الراتبة، قبل الصلاة، كراتبة الظهر، أو راتبة الفجر، لا أعلم بأسًا في ذلك، ولو كانا جاءا جميعًا، ولو كانا قد سلم أحدهما على الآخر قبل الصلاة، لكن إذا كان ما جاءا جميعاً، أو ما سلم أحدهما على الآخر قبل الصلاة؛ يتأكد، تتأكد المصافحة بعد ذلك؛ لأن أصحاب النبي ﷺ كانوا إذا تلاقوا يتصافحون، وكانوا إذا قدموا من سفر تعانقوا، قال أنس ، والشعبي: \"كان أصحاب النبي ﷺ إذا تلاقوا تصافحوا، وإذا قدموا من سفر تعانقوا\" وقد ثبت عنه ﷺ أنه كان يصافح إخوانه -عليه الصلاة والسلام- عند اللقاء، فهذه سنة معروفة عن النبي ﷺ، وعن أصحابه. أما إذا كان دخل مع أخيه، أو سلم عليه في الصف قبل أن يصلي التحية لما تلاقيا في الصف؛ فإن هذا يكفي، قد حصل المقصود، والحمد لله، لكن لو سلم عليه ثانيًا بعد الفراغ من التحية، أو من الراتبة القبلية، لو صافحه مرةً أخرى، فلا أعلم بأسًا، ولا أعلم ما يوجب جعل ذلك بدعة، فإن السلام كله خير، ولا يأتي إلا بخير، وفيه إيناس من بعضهم لبعض، ودعاء من بعضهم لبعض، فلا حرج فيه -إن شاء الله-، ولا يسمى بدعة. ومما يدل على هذا: ما ثبت في الصحيحين، عن النبي ﷺ: أنه كان جالسًا في المسجد ذات يوم، فدخل بعض الناس، فصلى ولم يتم صلاته، ثم جاء فسلم على النبي ﷺ، فقال له النبي ﷺ: ارجع فصل، فإنك لم تصل فرجع فصلى، ثم جاء فسلم على النبي ﷺ، فرد عليه النبي السلام، ثم قال: ارجع فصل فإنك لم تصل فرجع فصلى، ثم جاء فسلم على النبي ﷺ، فرد عليه النبي السلام، وقال: ارجع فصل فإنك لم تصل فقال الرجل: والذي بعثك بالحق نبيًا، ما أحسن غير هذا فعلمني، فقال له النبي ﷺ: إذا قمت إلى الصلاة؛ فأسبغ الوضوء، ثم استقبل القبلة فكبر، ثم اقرأ ما تيسر معك من القرآن، ثم اركع حتى تطمئن راكعًا، ثم ارفع حتى تعتدل قائمًا، ثم اسجد حتى تطمئن ساجدًا، ثم ارفع حتى تطمئن جالسًا، ثم اسجد حتى تطمئن ساجدًا، ثم افعل ذلك في صلاتك كلها فهذا الحديث العظيم الجليل يدل على وجوب وفضيلة الطمأنينة في الصلاة، والركود فيها، وأن يعطى كل ركن حقه؛ من الاعتدال، والطمأنينة، وعدم العجلة في الركوع والسجود والاعتدال بعد الركوع، والجلوس بين السجدتين، هذا من أهم الفرائض. وكثير من الناس يعجل، ولا يكمل هذه الفروض، وهذا خطأ عظيم، لا تصح معه الصلاة، وفي هذا الحديث نفسه أنه رد على الرجل السلام، وهو يصلي بقربه، وجاء إليه ثلاث مرات، يسلم ويرد عليه النبي السلام، ولا قال: يكفي السلام الأول، مع أنه بقربه يصلي، يشاهده النبي ﷺ، ويرى حركاته، ويرى طمأنينته وعدمها، والنبي يشاهده، وكلما سلم عليه قال: وعليكم السلام، ورد عليه السلام، ثم قال له: ارجع فصل فدل ذلك على أن إعادة السلام من شخصٍ حولك، تشاهده يعمل عملًا، ثم يسلم عليك مرةً ثانية، أن هذا لا شيء فيه، وثبت عنه ﷺ أنه ربما أنه كان إذا سلم سلم ثلاثًا، والقصد من ذلك -والله أعلم- أن يفهم المستمعون، أو لعلهم لم يردوا في الأولى، أو في الثانية؛ فينتبهون للرد. فالمقصود: أن تكرار السلام للتعليم، أو لتنبيه الحاضرين حتى يردوا السلام، أو لأسبابٍ أخرى دعت إلى ذلك؛ كاشتغاله بالصلاة، فإن الصلاة فيها شغل، فلما فرغ منها، سلم على أخيه، هذا لا حرج فيه -إن شاء الله-، ولا ينبغي التشديد في هذا أبدًا، نعم.\nالمقدم: لكن في بعض العامة يعتقدون أنه مكمل للصلاة، ولا تكمل...؟ الشيخ: هذا غلط، هذا ما له تعلق بالصلاة، إنما له تعلق بإيناس أخيه، والسلام على أخيه، والدعاء لأخيه، بعد شغله بالصلاة، فيكون قد اشتغل بالصلاة، وأقبل على الله في قيامه وركوعه وسجوده، فهذا أعظم في نفس الأمر مما لو حال بينه وبين أخيه شجرة، أو جدار ثم سلم عليه، جاء في الحديث أنه إذا حال بينه وبين أخيه شجرة، فإنه يسلم عليه مرةً أخرى، إذا سلم على أخيه، ثم حال بينهما شجرة أو جدار سلم عليه مرةً أخرى، فأي هذا وأي شغله بالصلاة أعظم، إذا حال بينه وبين أخيه شجرة نخلة أو نحوها لحظة نص دقيقة، أو ربع دقيقة، أو ثانيتين، أو ثلاث. المقصود: أن هذا شيء يسير، ثم يلقاه، يسلم عليه، هذا أقل بكثير من شغله بالصلاة.","link":"https://binbaz.org.sa/fatwas/13519/حكم-تكرار-السلام-والمصافحة-بعد-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_652/nour_65206.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":15011,"question":"أيضًا شق السؤال هذا، يقول: وإذا رد السلام سرًا، ولم يسمعه المسلم، فماذا عليه أيضًا؟","title":"ما حكم من رد السلام سرًا؟","answer":"الجواب: يكون ما رد السلام، إذا رد سرًا، ولم يرفع صوته حتى يسمعه المسلم، حكمه أنه ما رد، لم يرد السلام؛ لأن المقصود أن يرد ردًا يسمعه المسلم، حتى يكون قد رد عليه تحيته، بمثلها، أو أحسن منها، وقد يكون هذا من الكبر، فإذا كان من الكبر؛ صار أقبح.  والمقصود: أنه ما رد السلام، إذا كان لم يرفع صوته؛ فإنه ما رد السلام، حتى يرفع صوته على وجه يسمعه المسلم، نعم.","link":"https://binbaz.org.sa/fatwas/13516/ما-حكم-من-رد-السلام-سرا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_652/nour_65205.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":15013,"question":"سؤاله الرابع يقول: ما حكم من يسلم عليه ولا يرد السلام؟","title":"حكم من لا يرد السلام على من يُسلم عليه","answer":"الجواب: السنة للمسلمين إذا تلاقيا أن يسلما وخيرهما الذي يبدأ بالسلام هذا هو السنة، النبي ﷺ أخبر أن المسلم له حقوق على أخيه، منها: أن يبدأه بالسلام، ومنها: أن يرد السلام، وقال في المتهاجرين: خيرهما الذي يبدأ بالسلام وقال -عليه الصلاة والسلام-: والذي نفسي بيده لا تدخلوا الجنة حتى تؤمنوا، ولا تؤمنوا حتى تحابوا، أفلا أدلكم على شيء إذا فعلتموه تحاببتم؛ أفشوا السلام بينكم. وقال -عليه الصلاة والسلام- لما أتى المدينة: أيها الناس، أطعموا الطعام، وأفشوا السلام، وصلوا الأرحام، وصلوا بالليل والناس نيام؛ تدخلوا الجنة بسلام فإفشاء السلام، والعناية بالسلام، والبدء به، من السنن العظيمة، والرد واجب، من بدئ بالسلام، فالرد عليه واجب؛ لأن الله سبحانه يقول: وَإِذَا حُيِّيتُمْ بِتَحِيَّةٍ فَحَيُّوا بِأَحْسَنَ مِنْهَا أَوْ رُدُّوهَا [النساء:86] فالرد واجب، والزيادة بالأحسن أفضل. فإذا قال: السلام عليكم، يقول: وعليكم السلام، هذا واجب، فإن زاده وقال: ورحمة الله، كان أفضل، فإن زاد قال: وبركاته، فهو أفضل، وإن قال المُسلِّم: السلام عليكم ورحمة الله، وجب على المُسلَّم عليه أن يقول: وعليكم السلام ورحمة الله، فإن زاد وبركاته، كان أفضل، فإن قال المُسلِّم: السلام عليكم ورحمة الله وبركاته، وجب على المُسلَّم عليه أن يقول: وعليكم السلام ورحمة الله وبركاته، فإن زاده بعدها فقال: كيف حالك، كيف أصبحت، كيف أمسيت، كيف أولادك؛ كان خيرًا، نعم.","link":"https://binbaz.org.sa/fatwas/13513/حكم-من-لا-يرد-السلام-على-من-يسلم-عليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_652/nour_65204.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":15099,"question":"يقول أيضًا: إذا مر عدد كبير من الرجال على رجل واحد، وسلّم واحد من هؤلاء الرجال على هذا الشخص الواحد، هل يكفي عن الباقين؟","title":"هل يجزئ عن الجماعة أن يسلم أحدهم أو يرد؟","answer":"الجواب: يجزئ عن الباقين؛ لما روي عنه ﷺ أنه قال: يجزئ عن الجماعة إذا مروا أن يسلم أحدهم، ويجزئ عن الجماعة أن يرد أحدهم فإذا سلم بعضهم على هذا الواحد أجزأ، وإن سلموا جميعًا كان أفضل وأفضل، نعم.","link":"https://binbaz.org.sa/fatwas/13601/هل-يجزى-عن-الجماعة-ان-يسلم-احدهم-او-يرد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_664/nour_66407.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":15211,"question":"السؤال السادس للمرسل محمود سيد أبو زيد، يقول فيه: ما الحكم فيمن يلقي السلام على الموجودين في المسجد؛ وذلك قبل تأدية صلاة تحية المسجد؟","title":"حكم إلقاء السلام على من في المسجد","answer":"الجواب: هذا هو السنة أنه إذا دخل على الجماعة في المسجد يسلم عليهم، ولو أنهم يصلون، يقول: السلام عليكم، وإن قال: ورحمة الله وبركاته، طيب، فالذي في الصلاة يرد بالإشارة، هكذا يشير بيده، إشارة له، والذي خارج الصلاة يرد، ويقول: وعليكم السلام ورحمة الله وبركاته، ولا بأس بهذا، ولا يكره هذا، بل مشروع، كان الصحابة يسلمون على النبي ﷺ وهو يصلي -عليه الصلاة والسلام- فيرد عليهم بالإشارة -عليه الصلاة والسلام-. وأما قول بعض العامة: إنه لا يسلم على من في المسجد أو على المصلى، هذا غلط خلاف السنة، بل يسلم عليهم ويردون عليه ولو كانوا يقرؤون، يقول: السلام عليكم، وإذا سمعوا الصوت يقولوا: وعليكم السلام، وإن كان قال: ورحمة الله يقولوا: وعليكم السلام ورحمة الله يردون مثل قوله أو أزيد؛ لأن الله قال: وَإِذَا حُيِّيتُمْ بِتَحِيَّةٍ فَحَيُّوا بِأَحْسَنَ مِنْهَا أَوْ رُدُّوهَا [النساء:86]، فإذا قال: السلام عليكم، قالوا: وعليكم السلام، وإن زادوه: ورحمة الله، كان أفضل لهم، وإن زادوه: وبركاته كان أفضل لهم. أما إذا قال: السلام عليكم ورحمة الله وبركاته، فإنه يلزمهم أن يقولوا مثل ذلك، حتى يردوا عليه تحيته، ويقفوا عن القراءة، ثم يشتغلوا بالقراءة، وإن كانوا في الصلاة ردوا بالإشارة، نعم.","link":"https://binbaz.org.sa/fatwas/13724/حكم-القاء-السلام-على-من-في-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_672/nour_67206.mp3","categories":["المساجد ومواضع السجود","الآداب والأخلاق المحمودة"]},{"id":15217,"question":"السؤال السادس للمرسل محمود سيد أبو زيد، يقول فيه: ما الحكم فيمن يلقي السلام على الموجودين في المسجد؛ وذلك قبل تأدية صلاة تحية المسجد؟","title":"حكم إلقاء السلام على من في المسجد","answer":"الجواب: هذا هو السنة أنه إذا دخل على الجماعة في المسجد يسلم عليهم، ولو أنهم يصلون، يقول: السلام عليكم، وإن قال: ورحمة الله وبركاته، طيب، فالذي في الصلاة يرد بالإشارة، هكذا يشير بيده، إشارة له، والذي خارج الصلاة يرد، ويقول: وعليكم السلام ورحمة الله وبركاته، ولا بأس بهذا، ولا يكره هذا، بل مشروع، كان الصحابة يسلمون على النبي ﷺ وهو يصلي -عليه الصلاة والسلام- فيرد عليهم بالإشارة -عليه الصلاة والسلام-. وأما قول بعض العامة: إنه لا يسلم على من في المسجد أو على المصلى، هذا غلط خلاف السنة، بل يسلم عليهم ويردون عليه ولو كانوا يقرؤون، يقول: السلام عليكم، وإذا سمعوا الصوت يقولوا: وعليكم السلام، وإن كان قال: ورحمة الله يقولوا: وعليكم السلام ورحمة الله يردون مثل قوله أو أزيد؛ لأن الله قال: وَإِذَا حُيِّيتُمْ بِتَحِيَّةٍ فَحَيُّوا بِأَحْسَنَ مِنْهَا أَوْ رُدُّوهَا [النساء:86]، فإذا قال: السلام عليكم، قالوا: وعليكم السلام، وإن زادوه: ورحمة الله، كان أفضل لهم، وإن زادوه: وبركاته كان أفضل لهم. أما إذا قال: السلام عليكم ورحمة الله وبركاته، فإنه يلزمهم أن يقولوا مثل ذلك، حتى يردوا عليه تحيته، ويقفوا عن القراءة، ثم يشتغلوا بالقراءة، وإن كانوا في الصلاة ردوا بالإشارة، نعم.","link":"https://binbaz.org.sa/fatwas/13724/حكم-القاء-السلام-على-من-في-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_672/nour_67206.mp3","categories":["المساجد ومواضع السجود","الآداب والأخلاق المحمودة"]},{"id":15247,"question":"هذه رسالة من السائل علي محمد ياسين، من اليمن، تعز، يقول: أنا شاب أقيم في المملكة العربية السعودية، بحثًا عن الرزق الحلال، ومشكلتي هو والدي فهو سيئ التعامل معنا منذ صغري، فقد تركني عند والدتي، وهجرنا من كل شيء، إلى أن كبرت وهو لا يعرفني، وأنا لا أعرفه، نتيجة هجره لنا، ثم بعد أن كبرت سافرت إلى المملكة للعمل، وكنت أبعث نقودًا بقصد التزوج بها، ولكنه كان يأخذها، ويقول لمن أريد التزوج منهم: ابني متوفى، ثم أرسلت النقود مرة أخرى إلى أهل مخطوبتي، ولكنه حينما علم بذلك رفع عليهم دعوى بقصد أخذ ما دفعته لهم من مال، بحجة أنني متوفى، وبعد ذلك رجعت إلى بلدي لأبحث معه هذا الوضع السيئ، ولكنه استقبلني أسوأ استقبال، وهددني بكل سوء إن أنا رفضت إعطاءه ما جمعته من مال، مما جعلني أفر منه ومن معاملته، وأقطع صلته. فما هي نصيحتكم لهذا الأب؟ وبماذا ترشدوني؟أفيدوني، بارك الله فيكم.","title":"نصيحة لمن يعامله أبوه معاملة قاسية ويعرقل زواجه","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فلا ريب أن حق الوالد عظيم، وبره واجب، وننصحك بأن تعامله بالتي هي أحسن، وتلتمس الزواج في جهة أخرى من بنات اليمن الموجودات في المملكة، أو في اليمن الشمالي، وتحسن إليه إذا كان فقيرًا بما يتيسر، إذا كان فقيرًا تحسن إليه بما يسر الله لك، وتخاطبه بالتي هي أحسن؛ لأن البر بالوالدين أمره عظيم، والله سبحانه يقول: وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ وَبِالْوَالِدَيْنِ إِحْسَانًا[الإسراء:23] والنبي ﷺ لما سئل: أي العمل أفضل؟ قال: الصلاة على وقتها قيل: ثم أي يا رسول الله؟ قال: بر الوالدين قيل: ثم أي؟ قال: الجهاد في سبيل الله فجعل بر الوالدين مقدم على الجهاد في سبيل الله، فبرهما عظيم، وأمر لازم. فنوصيك بالإحسان إليه، ومخاطبته بالتي هي أحسن، والدعاء له بالهداية والتوفيق، وحسن الخاتمة، وتترك الخطبة من الناس الذين حوله، لعلك تجد امرأة أخرى في جهة أخرى، والنساء كثير، في اليمن الشمالي في المملكة العربية السعودية حتى لا يحصل بينك وبين أبيك ما لا تحمد عقباه، وإن تيسر أن الذين خطبت منهم يتوجهون بها إلى المملكة، وتزوج هنا في المملكة بها فهذا خير كبير، وفيه مصلحة لك وراحة من المشاقة لأبيك، نسأل الله لنا ولك الهداية والتوفيق. وبكل حال نوصيك بالرفق بوالدك، والإحسان إليه، والتماس الطريق الصالحة التي تمكنك من الزواج من دون مشقة بينك وبين أبيك، سواء بالبنت التي خطبتها أو بغيرها، نسأل الله لك التيسير والتسهيل.\nالمقدم: لكن فعل والده بأن ادعى وفاة ابنه طمعًا في الحصول على المال؟ الشيخ: هذا منكر، كلام والده غلط، كونه كذب عليه، وكونه يمنعه من الزواج، هذا ظلم من والده غلط، لكن الوالد يُتحمل، يُتحمل ولو جرى منه هذا الغلط وهذا المنكر، لا بد من التحمل.\nالمقدم: إنما هو مخطئ في عمله هذا. الشيخ: مخطئ لا شك، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/13772/نصيحة-لمن-يعامله-ابوه-معاملة-قاسية-ويعرقل-زواجه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_681/nour_68101.mp3","categories":["الآداب والأخلاق المحمودة","نصائح وتوجيهات"]},{"id":15261,"question":"هذه سائلة للبرنامج تقول، تذكر بأن أهل زوجها من أقاربها يسيؤون لها -تقول- بالظن والظلم والحقد علي من عدة سنوات، ويتكلمون عني عند القريب والبعيد، مما يؤلمني كثيرًا، وتذكر هذه السائلة وتقول: والذي أريد أن أستفسر عنه، هل علي إثم في مقاطعتهم، والبعد عنهم قدر المستطاع؛ وذلك في مجتمعهم، مع أنني إذا اجتمعت بهم أبش في وجوههم، وأرحب بهم، وهم عكس ذلك، ولا أدري ما السبب في هذا البغض لي؟ مع أن زوجي طيب، ويكرمهم أحسن كرامة، ولا يقدرون هذا، جزاكم الله خيرًا.","title":"توجيه لمن يسيؤون لها قرابة زوجها","answer":"الجواب: نوصيك بالصبر، وأنت مشكورة، نوصيك بالصبر على أذاهم، وأبشري بالخير، يقول النبي ﷺ: ليس الواصل بالمكافي، ولكن الواصل الذي إذا قطعت رحمه وصلها فنوصيك بالصبر، والدعاء لهم بالهداية، وتقولين: اللهم اكفني شرهم، اللهم اكفني شرهم، اللهم اهدهم، اللهم اكفني شرهم، وتخاطبينهم بالتي هي أحسن بالبشاشة، والكلام الطيب، والدعاء لهم بالتوفيق والهداية، وأنت على خير، وأبشري بالخير؛ لأن الواصل هو الذي يصل رحمه وإن قطعت، هذا الواصل الكامل؛ لما روى البخاري في الصحيح، يقول ﷺ: ليس الواصل بالمكافي، ولكن الواصل الذي إذا قطعت رحمه وصلها وجاءه رجل فقال: «يا رسول الله، إن لي قرابة أصلهم ويقطعونني، وأحسن إليهم ويسيؤون إلي، وأحلم عليهم ويجهلون علي، فقال له ﷺ: لئن كنت كما قلت لكأنما تسفهم المل يعني: الرماد المحمى ولا يزال معك من الله ظهير عليهم ما دمت على ذلك فأبشري بالخير واصبري، نعم. المقدم: أحسن الله إليكم سماحة الشيخ على هذا التوجيه المبارك.","link":"https://binbaz.org.sa/fatwas/13751/توجيه-لمن-يسيوون-لها-قرابة-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_565/56509.mp3","categories":["قضايا المرأة","الآداب والأخلاق المحمودة"]},{"id":15264,"question":"المستمع عبدالله محمد علي العمر، من الرياض، بعث يسأل ويقول: ما حكم من أتى إليه أناس وقال لهم: بالسنة عيدين وهذا الثالث؟","title":"حكم قول المضيف لضيفه: في السنة عيدان وهذا الثالث","answer":"الجواب: ما نعلم في هذا شيئًا، معناه: يعني: أن هذا عيد لنا، يعني: نفرح بكم، هذا.......، أن يتساهلوا فيها، ما هو معناه: أنه يقيم عيد يحط عيد ثالث.  المقصود: أنا نفرح بكم كأنه عيد عندنا ما فيه شيء، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13757/حكم-قول-المضيف-لضيفه-في-السنة-عيدان-وهذا-الثالث","audio":"","categories":["الآداب والأخلاق المحمودة"]},{"id":15309,"question":"ما هي الجلسات المخالفة للسنة لغير الصلاة أو بغير الصلاة؟","title":"ما هي الجلسات المخالفة للسنة؟","answer":"الجواب: ما أعلم في هذا شيئًا، إلا أن السنة أن يجلس المؤمن مثلما يجلس الناس، لا يأتي بشيء يخالف عادة الناس؛ حتى لا يقال: فلان كذا، وفلان كذا، يجلس سواء كان مفترشًا رجله اليسرى، ناصبًا اليمنى، أو متوركًا، أو مستوفزًا ناصبًا ساقيه وفخذيه، كل ذلك لا حرج فيه، الأمر فيه واسع، لا أعلم في هذا شيء يتعين، ولا أعلم عن النبي ﷺ شيئًا يوجب تعيين جلسة خاصة، فالأمر في هذا واسع، جلس على رجله اليسرى مفترشًا، أو جلس متوركًا أو متربعًا، أو مستوفزًا، كل ذلك لا حرج فيه -إن شاء الله-، نعم.","link":"https://binbaz.org.sa/fatwas/13806/ما-هي-الجلسات-المخالفة-للسنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_566/56604.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":15407,"question":"السائل (أ. أ) يقول: ما هي شروط الولد الصالح الذي تقبل دعوته؟","title":"من الولد الصالح الذي تقبل دعوته؟","answer":"الجواب: الولد الصالح: المستقيم على دين الله هو الصالح، المستقيم على أداء الفرائض، وترك المحارم، وهو المؤمن، وهو التقي، هذا هو الصالح، فهذا ترجى إجابته إذا دعا لوالديه أو لغيرهما، بخلاف الفاسق فإن فسقه قد يمنع إجابة الدعاء، الفاسق المصر على المعاصي كالزنا، أو شرب الخمر، أو العقوق للوالدين، أو أكل الربا، أو ما أشبه ذلك. فالولد الصالح هو المؤمن المتقي لله الذي يؤدي فرائض الله، ويحذر محارم الله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13930/من-الولد-الصالح-الذي-تقبل-دعوته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_500/50004.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":15436,"question":"هذا سؤال من المستمع طالب مبارك قربان من اليمن لواء مأرب، يقول: لي ولد، وقد أسميته عزيز، وقد أفتاني بعض الناس بأن هذا الاسم لا يجوز، فما هو القول الصحيح في هذا؟","title":"حكم التسمي بـ (عزيز)","answer":"الجواب: لا حرج الصحيح أنه لا حرج عزيز، عزيز لا حرج فيه، وقد قال الله -جل وعلا-: قَالَتِ امْرَأَةُ الْعَزِيزِ[يوسف:51] وأقره . المقصود: أن هذا لا حرج فيه، وإذا جعله عبدالعزيز يكون أفضل، يزيد في عبد بدل عزيز عبدالعزيز يكون أفضل وأحسن حتى ينسبه لله، ويجعله عبدًا لله، ولكن عزيز وحده، عزيز، لا حرج فيها -إن شاء الله-، لكن تركها وجعلها عبدالعزيز أفضل وأحسن.","link":"https://binbaz.org.sa/fatwas/13969/حكم-التسمي-بـ-عزيز","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_686/nour_68605.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":15447,"question":"هذا محمد عبداللَه من القصيم، يقول: لي مجموعة من الأسئلة عن الاستئذان، يقول في سؤاله الأول: سماحة الشيخ، قال ﷺ: الاستئذان ثلاثًا، فإن أذن لك وإلا فارجع هل من وقفة مع هذا الحديث الشريف؟","title":"وقفة مع حديث: الاستئذان ثلاثًا","answer":"الجواب: نعم؛ لأن المستأذن عليهم قد يكونوا مشغولين، قد يكونون مشغولين، فإذا استأذنت ثلاث، ولم يُرد عليك، فانصرف، حتى لا تعطل نفسك، ولا تؤذي أهل البيت، تقول: السلام عليكم، ثم يعيدها مرة ثانية، ثم ثالثة، فإن لم يرد عليها ترك؛ لئلا يكلفهم، أو يؤذيهم، قد يكونون مشغولين، والحديث صحيح عن النبي ﷺ، وفي ذلك خير للمسلمين، ومنفعة كبيرة؛ لأن الإلحاح قد يضر أهل البيت، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13960/وقفة-مع-حديث-الاستىذان-ثلاثا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_568/56807.mp3","categories":["الآداب والأخلاق المحمودة","شروح الحديث"]},{"id":15450,"question":"في آخر أسئلته يقول يا سماحة الشيخ: سؤالي أيضًا عن الاستئذان: متى يبدأ الأطفال بالاستئذان على والديهم؟","title":"متى يبدأ أوقات استئذان الأطفال؟","answer":"الجواب: هذا بينه الله في سورة النور، في قوله -جل وعلا-: يَا أَيُّهَا الَّذِينَ آمَنُوا لِيَسْتَأْذِنْكُمُ الَّذِينَ مَلَكَتْ أَيْمَانُكُمْ وَالَّذِينَ لَمْ يَبْلُغُوا الْحُلُمَ مِنْكُمْ ثَلاثَ مَرَّاتٍ مِنْ قَبْلِ صَلاةِ الْفَجْرِ وَحِينَ تَضَعُونَ ثِيَابَكُمْ مِنَ الظَّهِيرَةِ وَمِنْ بَعْدِ صَلاةِ الْعِشَاءِ ثَلاثُ عَوْرَاتٍ لَكُمْ لَيْسَ عَلَيْكُمْ وَلا عَلَيْهِمْ جُنَاحٌ بَعْدَهُنَّ طَوَّافُونَ عَلَيْكُمْ بَعْضُكُمْ عَلَى بَعْضٍ [النور:58] ثم قال بعده: وَإِذَا بَلَغَ الأَطْفَالُ مِنْكُمُ الْحُلُمَ فَلْيَسْتَأْذِنُوا [النور:59] فهم في قبل بلوغ الحلم يستأذنوا في الأوقات الثلاثة، أما بعد بلوغ الحلم يستأذنوا كلما أرادوا الدخول، إذا بلغ الحلم بخمسة عشر سنة، أو أنبت الشعر الخشن حول فرجه، أو أمنى خرج منه المني مع الشهوة، قد بلغ الحلم، حينئذٍ يستأذن، كلما أراد الدخول؛ لأنه قد تكون أمه على غير حالة حسنة، قد تكون زوجته، قد تكون أختك.  المقصود: يستأذن عليهم، حتى لا يفاجئهم على حالة لا يرضونها، أما إذا كان دون ذلك يستأذن في العورات الثلاث، نعم. المقدم: أحسن الله إليكم يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13967/متى-يبدا-اوقات-استىذان-الاطفال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_568/56809.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":15521,"question":"السائلة تقول -يا سماحة الشيخ-: بأنها دائمًا تكذب على أمها في بعض الأحيان، حيث تشتري مثلًا فستان بمائتين ريال، وتقول لأمها: اشتريت ذلك بمائة ريال؛ منعًا للمشاكل، علمًا بأن هذا المال من مالي الخاص، ما حكم هذا العمل يا شيخ؟","title":"حكم الكذب لدرء المشاكل","answer":"الجواب: الأقرب -والله أعلم- أنه لا حرج؛ لأنها لا تضر أحدًا بذلك، وفي ذلك ترك لما قد يسبب غضب والدتها عليها، فلا حرج -إن شاء الله- إذا كان الواقع مثلما ذكرت السائلة، وأنها إذا أخبرت والدتها بالحقيقة غضبت عليها، فالأحوط لها أن تخفض في الثمن حتى لا تغضب عليها والدتها، وهذا الكذب لا يضر أحدًا، نعم، هو داخل في الإصلاح في الحديث الصحيح من حديث أم كلثوم -رضي الله عنها- بنت عقبة قالت: «لم أسمع النبي ﷺ يرخص في شيء من الكذب إلا في ثلاث: في الحرب، وحديث الرجل امرأته، والمرأة زوجها، وفي الإصلاح» وهذا -إن شاء الله- يدخل في الإصلاح؛ لأن صدقها قد يسبب مشاكل عليها مع أمها، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/14058/حكم-الكذب-لدرء-المشاكل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_569/56919.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":15686,"question":"أخيرًا يسأل أخونا ويقول: الصفة الصحيحة للتسليم على النساء الأجنبيات ما هي؟","title":"صفة إلقاء التحية على المرأة الأجنبية","answer":"الجواب: مثل السلام على غيرهم: السلام عليكم ورحمة الله وبركاته للرجال والنساء، وإن قال: عليكن بالنون فلا بأس، المقصود: هذا هو السلام الشرعي، وهن يقلن: وعليكم السلام ورحمة الله وبركاته، مثل ما قال لهن.\nوإن قال: السلام عليكم، وجب أن يقولوا: وعليكم السلام، وإن قال: ورحمة الله وجب أن يقول: وعليكم السلام ورحمة الله، وإذا قال: السلام عليكم ورحمة وبركاته، وجب الرد بأن يقول: وعليكم السلام ورحمة الله وبركاته؛ لأن الله سبحانه يقول: وَإِذَا حُيِّيتُمْ بِتَحِيَّةٍ فَحَيُّوا بِأَحْسَنَ مِنْهَا أَوْ رُدُّوهَا [النساء:86] فالرد واجب، والزيادة مستحبة، زيادة: ورحمة الله وبركاته مستحبة، فإذا قالها المسلم وجب ردها من الرجال والنساء جميعًا، فإذا مر على النساء أو دخل عليهن في البيت سلم عليهن، لكن على وجه ليس فيه فتنة، بل يكون مع التحجب، ومع الصيانة، وعدم الخلوة بالمرأة، يكون على طريقة شرعية ليس فيها فتنة ولا تهمة، نعم. المقدم: جزاكم الله خيرًا، إنما المصافحة كيف يكون وضعها لو سمحتم؟\nالشيخ: ليس للرجل أن يصافح المرأة الأجنبية؛ لقول النبي ﷺ: إني لا أصافح النساء وتقول عائشة -رضي الله عنها-: «والله ما مست يد رسول الله ﷺ يد امرأة قط، ما كان يبايعهن إلا بالكلام ».\nفالرجل لا يصافح المرأة الأجنبية، ويجب عليها التحجب عنه، ولا يخلو بها أيضًا، ولكن يسلم من دون خلوة، ومن دون مصافحة، أما مع المحارم لا بأس يصافح: أخته، عمته، أمه، لا بأس، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14239/صفة-القاء-التحية-على-المراة-الاجنبية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_572/57207.mp3","categories":["قضايا المرأة","الآداب والأخلاق المحمودة"]},{"id":15720,"question":"هل يجوز تقبيل اليدين للوالدين وغيرهم؟","title":"حكم تقبيل اليدين للوالدين وغيرهم","answer":"الجواب: تركه أحسن، التقبيل بين عينيه أحسن، وإن قبل يدي والديه فلا حرج، لكن كونه يقبل بين عينيه، وهكذا الشيخ الكبير بين عينيه، أو على رأسه، لا بأس، وإن اكتفى بالمصافحة فلا بأس، النبي ﷺ ربما قبلوا يده، وربما قبلوا رأسه، ربما قبلوا رجله -عليه الصلاة والسلام-؛ لأنه لا يقاس بغيره -عليه الصلاة والسلام-، لكن الغالب مع الصحابة المصافحة، الغالب مع الصحابة كانوا يصافحونه -عليه الصلاة والسلام-. وثبت عنه ﷺ أنه «كان إذا دخلت عليه ابنته فاطمة قام إليها وقبلها، وأخذ بيدها، وكانت إذا دخل عليها أبوها هي قامت إليه وقبلته، وأخذت بيده وأجلسته مكانها -رضي الله عنها-» فالأمر في هذا واسع، لكن الأفضل عند اللقاء المصافحة، يقول أنس : «كان أصحاب النبي ﷺ إذا تلاقوا تصافحوا، وإذا قدموا من سفر تعانقوا». المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14280/حكم-تقبيل-اليدين-للوالدين-وغيرهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_574/57409.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":15766,"question":"من دولة البحرين، رسالة بعث بها المستمع زاكي الدين زاكي، يسأل جمعًا من الأسئلة في أحدها يقول: هل النوم بعد صلاة الصبح عمل من أعمال الجاهلية؟","title":"حكم النوم بعد صلاة الفجر","answer":"الجواب: لا أعلم فيه بأسًا، النوم بعد الصلاة لا أعلم فيه بأسًا، ولا حرجًا، لكن الجلوس بعد الصلاة للذكر والاستغفار والقراءة حتى ارتفاع الشمس، هذا أفضل، كان النبي يفعله -عليه الصلاة والسلام-، فهذا أفضل، ولو نام لا حرج عليه، لا أعلم فيه حرجًا؛ لأن الأصل أنه لا ينهى عن شيء إلا ما نهى الله عنه ورسوله، فإذا جلس الإنسان في مصلاه يذكر الله، أو يقرأ حتى ترتفع الشمس هذا أفضل؛ تأسيًا بالنبي -عليه الصلاة والسلام-، وإذا خرج إلى بيته أو إلى أعماله أو نام؛ فلا حرج في ذلك، والحمد لله، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14354/حكم-النوم-بعد-صلاة-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_707/nour_70713.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":15795,"question":"تقول عن نفسها: تزوجت وأنا صغيرة في السن، ولم أستطع أن أقول لأم زوجي: عمة أو خالة، وعندما كبرت لم أستطع أن أقولها أيضًا؛ لعدم تعودي على ذلك من البداية، وسؤالي يا سماحة الشيخ: هل تلقيب أم الزوج بذلك يعتبر حقًا من حقوقها، وبذلك أكون آثمة بعدم قولي ذلك مع احترامي الشديد لها، وحسن المعاملة؟","title":"حكم ترك مناداة أم الزوج بالعمة أو بالخالة","answer":"الجواب: ليس هذا بواجب، إنما هو عرف، عادة، كون أم الزوج خالة أو عمة هذه عادة، ولأبي الزوج عم وخال عادة، ليس بلازم، فإذا خاطبتيها بأم فلان، وخاطب الإنسان أبا الزوجة: بأبي فلان أو فلان، لا بأس، لا حرج في ذلك، وإذا خاطبتيها بالمعروف: يا عمة، أو يا خالة كان حسنًا -إن شاء الله- من باب اعتياد الشيء المعروف، ومن باب مراعاة الخواطر، وعدم وجود شيء في النفوس، وهكذا الإنسان إذا قال لأبي زوجته: يا عم أو يا خال من باب التلطف ومن باب درء المفاسد فلا بأس، وإلا فلا حرج؛ لأن هذه أعراف ليست بلازمة، وإذا قال الرجل لأبي زوجته: يا أبا فلان، أو قال لأم زوجته: يا أم فلان، ولم يقل: يا خالة كله لا بأس، وهكذا الزوجة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14384/حكم-ترك-مناداة-ام-الزوج-بالعمة-او-بالخالة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_742/nour_74221.mp3","categories":["قضايا المرأة","الآداب والأخلاق المحمودة"]},{"id":15806,"question":"قضية طويلة بعض الشيء يقول صاحبها: رجل من أهل البادية في يوم من الأيام ذهب في دورة بعض المواشي، فابتعد عن أماكن الماء والأكل والناس، واشتد عليه العطش نتيجة لشدة البحث عن المواشي في صحراء جرداء، وقيض شديد، وحاول البحث عن ماء فلم يجد شيئًا مما اضطره إلى تسليم أمره لله، واستعد للموت، فسقط على الأرض مغشيًا عليه، وبينما هو على هذه الحال في وسط الصحراء تلفحه حرارة الشمس الشديدة، ومتجردًا من ملابسه، ومغمًا عليه، لا يحس بمن حوله، بينما هو كذلك؛ إذ قدم رجل بفضل الله، فأنقذه من هذه الحالة، وأعطاه الماء والملابس، وأطعمه، وأخذه معه حتى وعى من غيبوبته تلك. و إنه نتيجة لهذه المعاملة الحسنة التي لقيها من هذا الرجل الذي مر عليه، فإنه قد تأثر نفسيًا تأثيرًا بالغًا حتى قال: إنك أخ لأولادي ولزوجتي، وأنت كالمحرم لهن، هل ما فعل صحيح؟جزاكم الله خيرًا.","title":"حكم جعل الرجل غيره محرمًا لأهله","answer":"الجواب: هذا الذي أنقذه قد فعل معروفًا، قد أحسن، وله أجره عند الله  حيث أنقذ نفسًا أشرفت على الهلاك، فهو مأجور بهذا العمل، وله ثواب جزيل، لكن لا يكون بذلك محرمًا لزوجة المنقذ ولا لبناته، ولكنه أخوهن في الله، وقد أحسن إلى أب البنات وإلى زوج المرأة إحسانًا كبيرًا، ولكنه لا يكون بهذا محرمًا، ولا يكون أخًا للمنقذ ولا أبًا له، ولا ابنًا له، وإنما هو أخوهم في الله إذا كانا مسلمين جميعًا، فكلهم إخوة في الله، ولكن المحرمية لا تثبت بهذا، فكونه أنقذ إنسانًا لا يكون بذلك محرمًا لبناته أو زوجته أو غيرهن، والله ولي التوفيق، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14394/حكم-جعل-الرجل-غيره-محرما-لاهله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_743/nour_74309.mp3","categories":["الآداب والأخلاق المحمودة","فتاوى متنوعة"]},{"id":15817,"question":"بعد هذا ننتقل إلى الباحة، عبر رسالة بعثت بها إحدى الأخوات المستمعات تقول المرسلة (ع. ق) أختنا لها عدة أسئلة في أحدها تقول: حدثونا سماحة الشيخ لو تكرمتم عن تقبيل يد من نحب ونقدر؛ لكبر السن، أو للعلم والفضل والتقوى؟","title":"الأفضل ترك تقبيل الأيدي","answer":"الجواب: ترك التقبيل أفضل، ليس من عادة السلف التقبيل، ترك التقبيل أفضل، السلام والتحية والمصافحة، والمرأة مع المرأة، أو مع محارمها، والرجل مع الرجل، أو مع محارمه من النساء المصافحة كافية، وإن قبلت المرأة رأس أبيها فلا بأس، طيب، كانت فاطمة إذا دخلت على النبي ﷺ قبلته، وأخذت بيده -عليه الصلاة والسلام-، وهو كذلك، أما اعتياد تقبيل أيدي الناس للتعظيم، أو لأنه كبير في السن، أو لأنه عالم، ترك هذا أفضل. المقدم: بارك الله فيكم، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14404/الافضل-ترك-تقبيل-الايدي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_744/nour_74403.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":15910,"question":"في ثاني أسئلته يقول: هل تجوز صلة الرحم عبر التلفون؟","title":"صلة الرحم عبر الهاتف","answer":"الجواب: نعم، هذا من صلة الرحم، المكالمة الهاتفية، والمكاتبة بالقلم كلها من الصلة، كونه يكتب إليه إلى أخيه أو عمه أو قريبه يسأله عن صحته وعن حاله، أو يكلمه بالهاتف كله طيب، كله من الصلة. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14502/صلة-الرحم-عبر-الهاتف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_577/57709.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":15961,"question":"أختنا السائلة أم عبدالله تقول في هذا  لدي أخوات وعمات وخالات متفرقات: واحدة في الشمال، والأخرى في الجنوب، وأخرى في الغرب، وفيهم كبار السن، والصغار، والبعض منهم يملك هاتف، والبعض الآخر لا يملك هاتف، ولا أستطيع أن أقوم بزيارتهم؛ لأن الزيارة مكلفة، فالواحد منهم إذا أراد أن يزور هذا القريب يجب أن يعطيه مبلغ من المال، وفوق هذا تكاليف السفر باهظة جدًا. السؤال يبقى -يا سماحة الشيخ-: هل المكالمات الهاتفية تكفي عن صلة الرحم، أم يجب الذهاب إليهم في ذلك؟ مأجورين.","title":"وسائل صلة الأرحام","answer":"الجواب: الصلة من جهة مواصلتهم بالمكاتبة أو بالهاتف طيبة، ويحسن بها وصل الرحم، بالهاتف بالتلفون، بالمكاتبة بالسلام الذي يحمله فلان: سلم لنا على فلان، على أخي فلان، على عمي، على خالي، كل هذا من صلة الرحم، وإذا تيسرت الزيارة بلا تكلفة فهي من كمال الصلة: الزيارة، وبذل المال إذا كانوا محاويج، أو يسرهم بذل المال؛ هذا من الصلة، الهدية الطيبة، مواساة الفقير؛ هذا من الصلة الواجبة -صلة الرحم­-، وإذا كانوا أغنياء فالكلام الطيب والمكاتبة الطيبة والمكالمة الهاتفية، ولو ما تسافر إليهم يكفي بالمكالمة الهاتفية والمكاتبة تكفي، وإذا كانوا فقراء أو يمكن يعني: يحتاجون إلى هدية يهدي إليهم، والفقير يواسى إذا كان يستطيع يواسيهم من الزكاة أو من غيرها، كل هذا من صلة الرحم، نسأل الله للجميع الهداية والتوفيق، نعم. المقدم: اللهم آمين، أحسن الله إليكم، وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/14567/وساىل-صلة-الارحام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_578/57813.mp3","categories":["الآداب والأخلاق المحمودة","فتاوى متنوعة"]},{"id":15962,"question":"إذا سلم الكافر على المؤمن، فهل يرد عليه السلام؟","title":"حكم رد السلام على الكافر","answer":"الجواب: نعم، إذا سلم الكافر على المؤمن يرد عليه، يقول النبي ﷺ: إذا سلم علينا أهل الكتاب فقولوا: وعليكم وقال ﷺ: لا تبدؤوا اليهود والنصارى بالسلام فدل على أنهم إذا بدؤوا نرد عليهم؛ لأن المنهي عنه البداءة، أما الرد عليهم فواجب، نعم.","link":"https://binbaz.org.sa/fatwas/14569/حكم-رد-السلام-على-الكافر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_710/nour_71012.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":16060,"question":"يقول: بعض الناس يسمون أبناءهم على تسمية أسماء السور القرآنية، فبعضهم يسمي فلانًا (مدثر) وفلانًا (مزمل) وفلانًا (طارق) وغير ذلك، ما هو توجيهكم؟","title":"حكم تسمية الأبناء بأسماء بعض سور القرآن","answer":"الجواب: لا حرج في ذلك، ليس فيه حرج، والحمد لله، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14692/حكم-تسمية-الابناء-باسماء-بعض-سور-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_748/nour_74819.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":16070,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين ضمنها عددًا من الأسئلة، وقال عن نفسه: أنا المستمع إدريس آدم دهران، يسأل مجموعةً من الأسئلة فيقول في أحدها: ما حكم السلام على المرأة الأجنبية، ولاسيما إذا كانت من الجيران، وهي متحجبة، وبدون خلوة؟","title":"حكم السلام على الأجنبية","answer":"الجواب: لا حرج في السلام عليها، السلام مشروع في حق الجميع؛ الرجال والنساء، فإذا سلم عليها، أو رد عليها السلام من دون تهمة، ولا فتنة؛ فلا حرج، فإن كانت كاشفة؛ نصحها، وأمرها بالستر والتستر، وإذا كانت وحدها لا يخلو بها، يمر ويسلم من دون جلوس معها، ولا وقوف معها في محل خلوة، فإذا مر بها عند بابها، أو في الطريق، أو في أي مكان ليس له الجلوس معها خلوة، أما مروره بها من دون خلوة؛ فلا يسمى خلوة، ولا يضره كونه سلم عليها، أو رد عليها السلام، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14706/حكم-السلام-على-الاجنبية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_749/nour_74905.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":16075,"question":"يقول: كيف هي زيارة بنات العم والعمة، والخال والخالة؛ لأنهن من القرابة؟ أفيدونا، جزاكم الله خيرًا.","title":"كيفية صلة بنات العم والعمة والخال والخالة","answer":"الجواب: تشرع زيارة الأقارب ولاسيما المحارم كالأخوال والأعمام أو العمات، ونحو ذلك بحسب الترتيب، أو بالمكاتبة، أو بالهاتف، بالتلفون، كله طيب، المهم أن تكون الصلة بينهم طيبة، ليست قطيعة، بل صلة طيبة بالكلام الطيب، والزيارة، والمكالمة الهاتفية، ونحو ذلك. وإذا كانت المزورة غير محرم؛ فلا بأس إلا إذا كانت الزيارة ليس فيها خلوة، ولا فتنة، ولا شبهة، فلا بأس إذا زارها مع زوجها، أو عند أخيها، أو عند أبيها، زيارة المحبة، والقرابة، السلام عليكم السلام، كيف حالكم؟ كيف..؟ فلا بأس بهذا في صلة الرحم على وجه ليس فيه تهمة بالشر، وليس فيه محرم، لا خلوة، ولا تبرج، ولا كشف شيء من الزينة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14713/كيفية-صلة-بنات-العم-والعمة-والخال-والخالة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_749/nour_74910.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":16257,"question":"تسأل وتقول: هل تجوز تسمية الولد بخالد؟ جزاكم الله خيرًا.","title":"حكم التسمية بـ (خالد)","answer":"الجواب: لا بأس، في الصحابة خالد بن الوليد  هذا الاسم مشهور من قديم الزمان، ولم ينكره النبي، عليه الصلاة والسلام، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14951/حكم-التسمية-بـ-خالد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_808/nour_80805.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":16265,"question":"تسأل وتقول: هل تجوز تسمية الولد بخالد؟ جزاكم الله خيرًا.","title":"حكم التسمية بـ (خالد)","answer":"الجواب: لا بأس، في الصحابة خالد بن الوليد  هذا الاسم مشهور من قديم الزمان، ولم ينكره النبي، عليه الصلاة والسلام، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14951/حكم-التسمية-بـ-خالد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_808/nour_80805.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":16272,"question":"من بيشة رسالة بعث بها إحدى الأخوات المستمعات تقول: (ع. ع. س) من سد وادي بيشة تقول: إنه يوجد في منطقتنا نساء، ونحن بادية، ويفد إلى هؤلاء النساء ضيوف؛ فتقوم المرأة بتكريم الضيوف إذا كان زوجها غائبًا، أو متوفيًا، وإذا كانت مطلقة، وليس هناك -بحمد الله- شك ولا ريبة، فهل في هذا شيء؟ وبم توجهون الناس؟ جزاكم الله خيرًا.","title":"حكم استقبال المرأة الضيوف وإكرامهم","answer":"الجواب: إذا كان الموضوع ليس فيه ريبة، ولا خلوة؛ فلا مانع أن تقدم لهم الضيافة، وهي متسترة، متحفظة في وجهها، ويديها، وبدنها، تقدم لهم، وتقول لهم: خذوا عندكم القهوة ،عندكم كذا، تقهووا، وافعلوا كذا.. وكلوا.. تقدم لهم الطعام، وهم يأخذونه، والحمد لله. أما إذا كان واحدًا؛ لا تخلو به، تعذر تقول: ليس عندي أحد، واعذرني يا أخي! وكذلك إذا كان هناك ريبة، تخشى ريبة؛ تعتذر إليهم، ولو كانوا أكثر من واحد، إذا كانت تخشى أن تتهم بالشر؛ فتعتذر إليهم، وتقول: اعذروني؛ صاحب البيت ليس بحاضر، إن شاء الله تراجعونه في وقت كذا، وفي وقت كذا، أما إذا كان طوفًا معروفًا عندهم، وليس فيه تهمة، ولا شر، تقدم لهم ما ينبغي من الضيافة، مع التستر، والتحفظ، والكلام الطيب، والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14973/حكم-استقبال-المراة-الضيوف-واكرامهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_752/nour_75210.mp3","categories":["الخِطْبَة والاختيار ","النظر والخلوة والاختلاط","قضايا المرأة","الآداب والأخلاق المحمودة"]},{"id":16286,"question":"من بيشة رسالة بعث بها إحدى الأخوات المستمعات تقول: (ع. ع. س) من سد وادي بيشة تقول: إنه يوجد في منطقتنا نساء، ونحن بادية، ويفد إلى هؤلاء النساء ضيوف؛ فتقوم المرأة بتكريم الضيوف إذا كان زوجها غائبًا، أو متوفيًا، وإذا كانت مطلقة، وليس هناك -بحمد الله- شك ولا ريبة، فهل في هذا شيء؟ وبم توجهون الناس؟ جزاكم الله خيرًا.","title":"حكم استقبال المرأة الضيوف وإكرامهم","answer":"الجواب: إذا كان الموضوع ليس فيه ريبة، ولا خلوة؛ فلا مانع أن تقدم لهم الضيافة، وهي متسترة، متحفظة في وجهها، ويديها، وبدنها، تقدم لهم، وتقول لهم: خذوا عندكم القهوة ،عندكم كذا، تقهووا، وافعلوا كذا.. وكلوا.. تقدم لهم الطعام، وهم يأخذونه، والحمد لله. أما إذا كان واحدًا؛ لا تخلو به، تعذر تقول: ليس عندي أحد، واعذرني يا أخي! وكذلك إذا كان هناك ريبة، تخشى ريبة؛ تعتذر إليهم، ولو كانوا أكثر من واحد، إذا كانت تخشى أن تتهم بالشر؛ فتعتذر إليهم، وتقول: اعذروني؛ صاحب البيت ليس بحاضر، إن شاء الله تراجعونه في وقت كذا، وفي وقت كذا، أما إذا كان طوفًا معروفًا عندهم، وليس فيه تهمة، ولا شر، تقدم لهم ما ينبغي من الضيافة، مع التستر، والتحفظ، والكلام الطيب، والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14973/حكم-استقبال-المراة-الضيوف-واكرامهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_752/nour_75210.mp3","categories":["الخِطْبَة والاختيار ","النظر والخلوة والاختلاط","قضايا المرأة","الآداب والأخلاق المحمودة"]},{"id":16289,"question":"سؤال طويل تقول فيه: لوالدتي عمة لا تقبل صلة والدتي لها، فبم توجهون الوالدة - جزاكم الله خيرًا - هل تستمر في صلتها أو تقاطعها؟الشيخ: أعد.المقدم: تقول لوالدتي عمة لا تقبل صلة والدتي لها، فبم توجهون والدتي؟ هل تواصلها أم تقاطعها؟","title":"الحث على صلة الرحم وإن قطعت","answer":"الجواب: نوجهها بأن تصبر، وتواصل الصلة بالكلام الطيب، والفعل الطيب، والمال إذا تيسر ذلك، ولا تقطع، إذا قطعت لا تقطعها هي بنت أخيها، فعليها أن تجتهد في صلتها، والدعاء لها بالتوفيق والهداية، واستعمال الكلام الطيب، وتستعين بمن تشاء من قريباتها حتى ترضى عنها عمتها يقول النبي ﷺ في الحديث الصحيح: ليس الواصل بالمكافي، ولكن الواصل الذي إذا قطعت رحمه؛ وصلها هذا الواصل، ومن عقيدة أهل السنة والجماعة أن تصل من قطعك، هذا هو السنة، فإذا قطعت وقطع؛ استمرت القطيعة، لكن أنت إذا قطعك أخوك، أو عمك، أو عمتك، أو غيرهما من أقاربك؛ لا تقطع أنت، افعل المعروف بالكلام الطيب، والفعل الطيب حسب طاقتك، واستعن على ذلك بمن تشاء من الأخيار والطيبين؛ حتى تعود الصلة، وتعود المحبة، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14975/الحث-على-صلة-الرحم-وان-قطعت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_752/nour_75211.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":16382,"question":"رجل أمر زوجته بارتداء الحجاب الشرعي فأبت، ماذا يفعل؟","title":"توجيه للزوج الذي ترفض زوجته الحجاب","answer":"الجواب: يستمر في نصيحتها، ويتعاون مع أهلها في ذلك؛ لعل الله يهديها بأسبابه؛ لأن هذه معصية، فعليه أن يستمر في النصيحة، ولا مانع من تأديبه لها على ذلك تأديبًا لا يضرها، بضرب غير مبرح من باب إنكار المنكر، إذا كانت لا تبالي بذلك عند الأجناب، عند الرجل الأجنبي، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15089/توجيه-للزوج-الذي-ترفض-زوجته-الحجاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_754/nour_75412.mp3","categories":["الدعوة والدعاة","الآداب والأخلاق المحمودة","اللباس والزينة"]},{"id":16525,"question":"هذه الأخت السائلة أم محمد من الدمام تقول: سماحة الشيخ ما حكم الشرع في نظركم في كذب أحد الزوجين على الآخر إذا كان فيه مصلحة لهذه الأسرة؟","title":"حكم كذب أحد الزوجين على الآخر","answer":"الجواب: تقول أم كلثوم بنت عقبة بن أبي معيط -رضي الله عنها- تقول أم كلثوم -رضي الله عنها-: «لم أسمع النبي ﷺ يرخص في شيء من الكذب إلا في ثلاث: الحرب، والإصلاح بين الناس، وحديث الرجل امرأته، والمرأة زوحها» رواه مسلم في الصحيح. فالنبي ﷺ رخص في كذب الرجل على امرأته، والمرأة على زوجها إذا كان فيه إصلاح، إذا كان لا يضر أحدًا، بل ينفع ولا يضر، إذا كذب عليها لمصلحة تتعلق بها، وبأهلها، أو كذبت عليه لمصلحة تتعلق به، أو بأهله، لا تضر أحدًا؛ هذا طيب، لا بأس به. تقول: أهلك يحبونك، ويثنون عليك، ويحبون لك أن تكون صدوقًا في كلامك، ويحبون أنك تحافظ على الصلوات في الجماعة، ويحبون أنك تكون طيب الكلام معهم، طيب البشر، ويثنون على خدماتك لهم، حتى تشجعه، طيب. وهو يقول لها كذلك: أني سوف لا أتزوج عليك، وسوف أجتهد فيما ينفعك، وسوف أوصي أهلك بك خيرًا، والكلمات التي تنفعها، وتسرها، نعم. المقدم: جزاكم الله خيرًا، وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/15250/حكم-كذب-احد-الزوجين-على-الاخر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_583/58306.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":16629,"question":"تسأل أختنا عن الأسماء التالية، وجوازها سماحة الشيخ: هدى، ونور، وإيمان، ودعاء، وأفنان للبنات، ما هو رأيكم؟ الشيخ: أعد.المقدم: تسأل عن صحة التسمية بهذه الأسماء: هدى، ونور، وإيمان، ودعاء، وأفنان؟","title":"حكم التسمية بـ (هدى وإيمان ودعاء وأفنان) للبنات","answer":"الجواب: ما أعلم فيها بأسًا، لا أعلم فيها بأسًا. المقدم: الحمد لله.  الشيخ: نعم.  المقدم: الحمد لله، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15362/حكم-التسمية-بـ-هدى-وايمان-ودعاء-وافنان-للبنات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_759/nour_75906.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":16652,"question":"إحدى الأخوات المستمعات رمزت إلى اسمها بالحروف (ف. أ) تسأل سماحتكم وتقول: ما هو الحكم في النوم بعد صلاة الفجر؟ وهل يقسى القلب؟ وهل يعتبر من المنكرات؟ جزاكم الله خيرًا.","title":"حكم النوم بعد صلاتي الفجر والعصر","answer":"الجواب: ليس في النوم بعد الفجر حرج، ولا نعلم فيه بأسًا، وما اشتهر بين الناس أنه غير طيب، وأنه كذا وأنه.. ليس عليه دليل معتمد، فالنوم بعد الفجر لا حرج فيه، وبعد العصر لا حرج فيه.  لكن من جلس بعد الفجر في مصلاه يقرأ، ويستغفر الله، ويسبح، ويهلل، ونحو ذلك حتى ترتفع الشمس؛ يكون هذا أفضل، كفعل النبي -عليه الصلاة والسلام- ومن ترك؛ فلا حرج عليه، من ترك فقام إلى حاجاته، أو نام، أو اشتغل بأشياء أخرى؛ فلا بأس عليه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15385/حكم-النوم-بعد-صلاتي-الفجر-والعصر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_717/nour_71715.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":16685,"question":"حكيت لزوجتي في البيت عن رجل كذب علي في أمور، ولم يوف بوعوده معي، هل يعتبر هذا غيبة ونميمة في حق هذا الرجل، بالرغم من أن هذه الصفات السيئة حصلت منه؟","title":"حكم إخبار الرجل زوجته بما يحصل له مع الآخرين","answer":"الجواب: لا أعلم حرجًا في ذلك إذا كان في إخبارها مصلحة إذا كان في إخبارها مصلحة؛ لأنها واقعة منه عليك أنت، فلا أعلم في ذلك بأسًا، ولا يكون من الغيبة؛ لأنك أخبرت عنه بشيء فعله معك، وتعدى به عليك، فإذا كانت هناك حاجة لإخبارها، وتدعو الحاجة إلى إخبارها، وإلا فالترك أولى، لأني أخشى أن تكون غيبة، إذا كان ليس هناك مصلحة في إخبارها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15458/حكم-اخبار-الرجل-زوجته-بما-يحصل-له-مع-الاخرين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_820/nour_82009.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":16710,"question":"يسأل سؤالًا آخر فيقول: هل يجوز للمصلي أن يضع يده على فمه إذا تثاءب أثناء الصلاة؟","title":"وضع المصلي يده على فيه عند التثاؤب","answer":"الجواب:  هذا السنة، نعم يضع يده على فمه أثناء الصلاة، وخارج الصلاة أيضًا، ولا يقل: هاه، يكتم صوته، ويكظم فمه، يحط يده على فمه، نعم.  المقدم: جزاكم الله خيرًا، هل تتفضلون بذكر ما ورد عن الرسول ﷺ حول هذا الموضوع؟ جزاكم الله خيرًا. الشيخ: نعم يقول النبي ﷺ: إذا تثاءب أحدكم؛ فليكظم ما استطاع، ولا يقول: هاه، فإن الشيطان يدخل في فيه ويقول في الحديث الآخر: إذا تثاءب أحدكم؛ فليضع يده على فيه، ولا يقل: هاه، فإن الشيطان يدخل هذا هو السنة، يكظم ما استطاع، ويضع يده على فيه، نعم، ولا يقول: هاه، لا يتكلم، يسكت، نعم. المقدم: بارك الله فيكم، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15450/وضع-المصلي-يده-على-فيه-عند-التثاوب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_761/nour_76103.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":16718,"question":"إذًا ننتقل إلى موضوع آخر عبر رسالة أخرى وصلت إلى البرنامج من أحد الإخوة المستمعين وصف نفسه بأنه من أسرة مفككة، أي: أن الوالد لا يحس بالمسؤولية نحو الأسرة، ووالدتي تشاجره في كثير من الأمور، والشجار يكون بسبب، أو بدون سبب، حتى كانت تتطاول عليه، فكنت أقوم بسبها أحيانًا، أو الاعتداء عليها بالدفع؛ مخافة أن يزيد الشجار بينهما، وتشتت الأسرة، وفي نفس الوقت أندم على ما فعلت، وأحاول أن أقنعها بالكلام، أو هجرة المنزل، فلا تبالي بعتابي، ولا هجرتي للمنزل، وتستهزئ بي في كثير من الأحيان، وكان يحدث في كثير من الأحيان الشجار مع زوجات أعمامي بسبب، أو بدون سبب، وأفعل معها الدفع، أو الإقناع فلا تطعني، رغم أنني أعلم من كتاب الله تعالى قوله تعالى: فَلا تَقُلْ لَهُمَا أُفٍّ وَلا تَنْهَرْهُمَا [الإسراء:23] وجهوني كيف أتصرف؟ جزاكم الله خيرًا.","title":"توجيه لمن يسيء لأمه لسوء معاملتها لوالده","answer":"الجواب: قد أسأت في عملك، ولم تحسن، والواجب عليك احترامها، وكف الأذى عنها، والنصيحة فقط، أما سبها، ودفعها هذا لا يجوز، هذا من العقوق، ولكن عليك بالكلام الطيب، والنصيحة، فإن قبلت منك، وإلا فقد أديت ما عليك، ولا يجوز لك أن تدفعها بالقوة، ولا أن تسبها وتلعنها، كل هذا منكر، ولكن عليك التلطف، والكلام الطيب، والأسلوب الحسن، والنصيحة، وإلا فالتمس من يقوم مقامك في هذا، وينصحها، ويتولى منعها من الأذى، أما أنت لا، أبوك يقوم بالواجب، أخوها، أبوها؛ يعالجون الموضوع، أما أنت لا تعالجها بسبها وإيذائها، نسأل الله السلامة، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15469/توجيه-لمن-يسيء-لامه-لسوء-معاملتها-لوالده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_761/nour_76108.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":16740,"question":"من المستمع (ض. ع. ض) من الدمام يسأل ويقول: رأيت في المنام أنني أرمي قريبة لي بالتراب، والحجارة في وجهها، وقد أزعجتني هذه الرؤيا، فهل لها من تفسير؟ جزاكم الله خيرًا.","title":"الآداب التي يفعلها من رأى رؤيا تسوؤه","answer":"الجواب: إذا رأيت مثل هذه الرؤيا، فاعلم أنها من الشيطان، ولا تحزن، وانفث عن يسارك ثلاث مرات، بريقك تتفل عن اليسار، تقول: أعوذ بالله من الشيطان، ومن شر ما رأيت ثلاث مرات، ثم تنقلب على الجنب الآخر، فإنها لا تضرك، ولا تخبر بها أحدًا، ولا تضرك. هكذا أمر النبي ﷺ لما سئل، قال -عليه الصلاة والسلام-: الرؤيا الصالحة من الله، والحلم من الشيطان، فإذا رأى أحدكم ما يكره؛ فلينفث عن يساره ثلاث مرات، وليتعوذ بالله من الشيطان، ومن شر ما رأى ثلاث مرات، ثم لينقلب على جنبه الآخر؛ فإنها لا تضره، ولا يخبر بها أحدًا هذا هو المشروع يا أخي، كل رؤيا مكروهة هذا شأنها، نعم. المقدم: جزكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15496/الاداب-التي-يفعلها-من-راى-رويا-تسووه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_821/nour_82107.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":16838,"question":"بعد هذا رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات تقول المرسلة: (ب. ع) من الرياض، تقول عن نفسها: من عاداتي كتابة بسم الله الرحمن الرحيم، والثناء على رسول الله ﷺ في رسائلي إلى أهلي، وصديقاتي، ويتخلل الرسالة بعض الآيات، أو كلمات دعاء، وفي الأيام الأخيرة اعتراني شعور بألا أكتب لفظ الجلالة أبدًا، مع العلم أنني منذ كتابة رسائلي بتلكم الطريقة الأخيرة أشعر أن الرسالة ناقصة، وفيها عيب واضح، وسبب هذا الشعور أنني أخاف أن يكون علي إثم إذا الرسالة وضعت في مكان غير لائق، أو ضاعت، فماذا عساي أن أفعل؟ جزاكم الله خيرًا.","title":"حكم كتابة البسملة وبعض الآيات في الرسائل","answer":"الجواب: عملك الأول، العمل الأول أطيب، وأحسن، اكتبي بسم الله الرحمن الرحيم، واكتبي بعض الآيات، أو الصلاة على النبي ﷺ وبعض النصائح، ولا يضرك لو أن الذين قرؤوها طرحوها في محل غير مناسب، الإثم عليهم، ليس عليك أنت، الإثم على من طرح الرسالة، أو الكتاب، أو الفائدة في محل غير لائق، الإثم عليه. أما أنت فأنت مأجورة إذا سميت الله في أولها، وصليت على النبي ﷺ أو حمدت الله، أو ذكرت بعض الآيات المفيدة، أو بعض الأحاديث، كله طيب، وأنت مأجورة، ومن طرحها في محل غير مناسب؛ فالإثم عليه، ليس عليك أنت، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15590/حكم-كتابة-البسملة-وبعض-الايات-في-الرساىل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_718/nour_71802.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":16907,"question":"المستمع ياسين الحربي من السويدرة أيضًا يقول: سماحة الشيخ! كنت طالبًا في الصف الثاني المتوسط، وعندما قمت باختبار القواعد ظننت أنني قد رسبت، فقال لي بعض الزملاء: إذا نجحت لنا عليك تيس.الشيخ: أعد أعد.المقدم: يقول: سماحة الشيخ! كنت طالبًا في الصف الثاني المتوسط، وعندما قمت باختبار القواعد ظننت أنني قد رسبت، فقال لي بعض الزملاء: إذا نجحت لنا عليك تيس، فقلت: لكم تيسان، وبعد نهاية الاختبار ظهرت النتيجة، كنت ولله الحمد من الناجحين، فلما عزمت على الذبح مرت بي عدة ظروف أولها عندما رجعت لكي أوفي بوعدي، وجدت أحد جماعتي متوفيًا، ولكون الناس في حزنهم لم أذبحها، وقلت: أذبحها في المرة القادمة، فرجعت إلى عملي، فلما عزمت على الذهاب إلى أهلي لأقوم بذبحها؛ صار علي حادث، وتوفي..... فتوقفت لمدة ستة أشهر، ولم أقم بذبحها حتى الآن، فهل علي إثم في التأخير؟ وجهوني جزاكم الله خيرًا.","title":"حكم من وعد أصحابه بذبيحة ثم تأخر وفاؤه لعذر","answer":"الجواب: المشروع لك الوفاء بما وعدت؛ لأنه ليس بنذر، ما قلت: لله علي، ولا نذر لله، قلت: لكم تيسان، هذا وعد منك، والسنة الوفاء بالوعد، الرسول ﷺ ذم المنافقين لإخلاف الوعد، قال عنهم: إن المنافق إذا وعد أخلف فلا يليق بك أن تشابه المنافقين، بل توفي بالوعد، وتذبح التيسين، وتدعو الزملاء الذين قالوا لك، وهذا هو الأفضل لك، وهو الأحوط، يسر الله أمرك. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15665/حكم-من-وعد-اصحابه-بذبيحة-ثم-تاخر-وفاوه-لعذر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_719/nour_71914.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":16923,"question":"أحسن الله إليك يا سماحة الشيخ، أخونا (ع. أبو عمرو الزعبي) من الرمثا الأردن في آخر أسئلته يقول: يا سماحة الشيخ هل ورد في السنة النبوية أحاديث عن الرسول ﷺ بالنهي عن النوم بعد صلاة العصر، أو قبل المغرب؟","title":"حكم النوم بعد صلاة العصر والمغرب","answer":"الجواب: ليس في هذا شيء، لا بأس بالنوم بعد العصر، ولم يرد في هذا شيء يمنع، فالنوم بعد العصر لا حرج فيه، وليس فيه شيء من الأحاديث تمنع من ذلك، نعم.","link":"https://binbaz.org.sa/fatwas/15690/حكم-النوم-بعد-صلاة-العصر-والمغرب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_586/58608.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":16950,"question":"ما حكم تقبيل يدي أهل الفضل، والجاه، والصلاح، والوالدين؟","title":"حكم تقبيل يدي الوالدين وأهل الفضل","answer":"الجواب: إذا كان بعض الأحيان قد اعتيد؛ فالأمر سهل، لكن لا يتخذه عادةً، ينبغي تركه، أما إذا كان اعتاده في بلاده الناس، ويرى أنه لو ترك ذلك عده هضمًا له، وتنقصًا له؛ فلا مانع أن يفعله عند الحاجة إلى ذلك، من باب سد الذرائع المفضية إلى الشحناء، والعداوة، أو ظن الانتقاص. وهكذا مع الوالد؛ لا بأس، \"كانت فاطمة -رضي الله عنها- إذا دخلت على النبي ﷺ قام إليها، وأخذ بيدها وقبلها، وكان إذا دخل عليها قامت إليه، وأخذت بيده وقبلته\" -رضي الله عنها- وﷺ. فلا حرج، الوالد له حق عظيم، فإذا قبل يده، أو قبل رأسه؛ فلا بأس، لكن كونه يتخذ هذا عادة، كل ساعة، كل ساعة، قد يكون تركه أفضل، إلا مع الوالد خاصة، أما مع الناس إذا فعله بعض الأحيان؛ لتفادي بعض الشر، أو بعض الشحناء، فلا بأس، أما مع الوالد فلا حرج، لفعل فاطمة مع النبي ﷺ نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15758/حكم-تقبيل-يدي-الوالدين-واهل-الفضل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_828/nour_82816.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":16955,"question":"ما حكم تقبيل يدي أهل الفضل، والجاه، والصلاح، والوالدين؟","title":"حكم تقبيل يدي الوالدين وأهل الفضل","answer":"الجواب: إذا كان بعض الأحيان قد اعتيد؛ فالأمر سهل، لكن لا يتخذه عادةً، ينبغي تركه، أما إذا كان اعتاده في بلاده الناس، ويرى أنه لو ترك ذلك عده هضمًا له، وتنقصًا له؛ فلا مانع أن يفعله عند الحاجة إلى ذلك، من باب سد الذرائع المفضية إلى الشحناء، والعداوة، أو ظن الانتقاص. وهكذا مع الوالد؛ لا بأس، \"كانت فاطمة -رضي الله عنها- إذا دخلت على النبي ﷺ قام إليها، وأخذ بيدها وقبلها، وكان إذا دخل عليها قامت إليه، وأخذت بيده وقبلته\" -رضي الله عنها- وﷺ. فلا حرج، الوالد له حق عظيم، فإذا قبل يده، أو قبل رأسه؛ فلا بأس، لكن كونه يتخذ هذا عادة، كل ساعة، كل ساعة، قد يكون تركه أفضل، إلا مع الوالد خاصة، أما مع الناس إذا فعله بعض الأحيان؛ لتفادي بعض الشر، أو بعض الشحناء، فلا بأس، أما مع الوالد فلا حرج، لفعل فاطمة مع النبي ﷺ نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15758/حكم-تقبيل-يدي-الوالدين-واهل-الفضل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_828/nour_82816.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":17050,"question":"تقول السائلة: لقد ظلمني عدد من الناس، وحينما يبلغ بي الألم النفسي مبلغه أدعو عليهم، وعندما تهدأ نفسي أستغفر الله، وأحاول أن أسامحهم، ولكنني أعود، وأدعو عليهم عندما أفكر بما سببوه لي من آلام، هل لكم من توجيه سماحة الشيخ؟","title":"حكم الدعاء على الظالم","answer":"الجواب: لا حرج في الدعاء على من ظلم بقدر ظلمه، قال الله تعالى: لا يُحِبُّ اللَّهُ الْجَهْرَ بِالسُّوءِ مِنَ الْقَوْلِ إِلَّا مَنْ ظُلِمَ [النساء:148] فمن ظلم استحق أن يدعى عليه، وإذا سمحت وعفوت فلك أجر عظيم، وإذا دعوت على من ظلمك بقدر ظلمه، وأن الله يجازيه عن ظلمه بما يستحق فلا حرج، وإذا تركت، وعفوت فالأجر أكبر، ولك أجر عظيم إذا عفوت، وصبرت، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15839/حكم-الدعاء-على-الظالم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_587/58725.mp3","categories":["مسائل فقهية متفرقة","الآداب والأخلاق المحمودة"]},{"id":17146,"question":"يقول: -يستفسر عن هذا الحديث- قال رسول الله ﷺ: لا يشربن أحدٌ منكم قائمًا، فمن نسي وشرب قائمًا فليستقيء فيه نوع -يقول- من التشديد على عدم الشرب قائمًا، ولكن في الحديث الآخر عن ابن عباس -رضي الله عنهما- قال: «سقيت النبي ﷺ من زمزم، فشرب وهو قائم». متفقٌ عليه، ما الجمع بين هذا وهذا يا سماحة الشيخ؟","title":"حكم الشرب قائمًا","answer":"الجواب: الشرب قاعدًا أفضل، والشرب قائمًا لا بأس به، والحديث الذي فيه الاستقاء منسوخ؛ لأن الأحاديث الصحيحة دلت على أنه ﷺ كان يشرب قائمًا وقاعدًا، من حديث ابن عباس، ومن حديث علي  فلا بأس أن يشرب قاعدًا وقائمًا، والقعود أفضل، أما: فليستقيء قد نسخ. نعم.","link":"https://binbaz.org.sa/fatwas/15965/حكم-الشرب-قاىما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_589/58927.mp3","categories":["الأطعمة والأشربة","الآداب والأخلاق المحمودة"]},{"id":17156,"question":"ما حكم عيادة المرأة للرجل الأجنبي المنوم في المستشفى، مع الدليل أيضًا؟ جزاكم الله خيرًا.","title":"حكم عيادة المرأة للرجل الأجنبي","answer":"الجواب: العيادة للمرضى سنة للرجال، والنساء للأحاديث العامة الدالة على ذلك لقوله ﷺ: عودوا المريض وهذا يعم الجميع، عودوا المريض، وأطعموا الجائع، وفكوا العاني؛ لأن حق المسلم على أخيه مطلوب في حق الجميع، وهو من أسباب الألفة، والتحاب، والتعاون على البر والتقوى، فتسلم، وترد السلام، وتعود المريض، وتجيب الداعي، وتشمت العاطس، لكن لا تتبع الجنازة. جاء في أحاديث خاصة، اتباع الجنائز تنهى النساء عن اتباع الجنائز إلى المقابر، هذا خاص مستثنى من هذا؛ لأن رسولنا ﷺ نهى عن اتباع الجنائز للنساء خاصة؛ لأنهن فتنة، وقد يحصل باتباعهن إلى المقابر فتنة، لكن تصلي على الميت. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15978/حكم-عيادة-المراة-للرجل-الاجنبي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_767/nour_76712.mp3","categories":["قضايا المرأة","الآداب والأخلاق المحمودة"]},{"id":17202,"question":"هذه سائلة للبرنامج تقول: سماحة الشيخ! حفظكم الله، في الجلسة العائلية في البيت، وأثناء تقديمنا للقهوة والشاي، وعلى يميني نساء، وعن شمالي رجال، فمن أين أبدأ؟","title":"من آداب الشرب البدأ بالأيمن","answer":"الجواب: باليمين، الفنجال والبيالة يعطاها اليمين، كان النبي ﷺ إذا شرب أعطى من كان عن يمينه، فالذي يصب القهوة يبدأ برئيس المجلس، أو رئيسة المجلس إذا كان نساء، مقدمة المجلس، ثم من عن يمينها، والرجال كذلك يبدأ برئيس المجلس، ثم من عن يمينه، إلا إذا سمح من كان على يمينه أن يعطى من على شماله فلا بأس. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16024/من-اداب-الشرب-البدا-بالايمن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_590/59030.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":17221,"question":"يزعم بعض الناس عندنا أن الشيء المكشوف كالطعام مثلًا إذا وضع عليه عود، أو نحوه، وسمي الله  فإنه لا يضر ذلك الطعام شيئًا، وإن مسه ثعبان، أو شيء ضار، فهل هذا صحيح؟","title":"مشروعية تغطية الأواني","answer":"الجواب:  هكذا جاء الحديث تغطية الأواني، يغطي الإناء، ويسمي الله، ... أن يعرض عليها عودًا، فإذا سمى الله فإنه ترجى له السلامة من كل شر. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16047/مشروعية-تغطية-الاواني","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_723/nour_72317.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":17255,"question":"السائل يقول يا سماحة الشيخ: لي مجموعة من الأصدقاء، لا أحد منهم يصلي، وهم يقطنون معي في نفس القرية، وأنا ملازم لهم؛ لغياب الإخوان في الله في هذه القرية، ولأن لي فيهم مصالح دنيوية، ولأنهم جيراني، وأصدقاء الطفولة، حاولت مرارًا أن أدعوهم، فيكون الرد منهم نخاف أن نتوب، وبعد مدة نفسق، نخاف ألا نحافظ على الصلاة فنتركها، ونحن أحسن من فلان؛ لأنه يصلي، ويفعل كذا وكذا، ونحن لا نصلي إطلاقًا؛ فعجزت عن جوابهم، ولا أجد ما أقوله لهم إلا هدانا الله وإياهم، كيف توجهون لهم النصيحة مأجورين سماحة الشيخ؟","title":"حكم مجالسة تاركي الصلاة","answer":"الجواب: نصيحتي لهؤلاء وأشباههم أن يخافوا الله، وأن يراقبوه، وأن يصلوا مع المسلمين جميع الصلوات الخمس؛ لقول الله : حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلاةِ الْوُسْطَى [البقرة:238] ولقوله سبحانه: وَأَقِمِ الصَّلاةَ إِنَّ الصَّلاةَ تَنْهَى عَنِ الْفَحْشَاءِ وَالْمُنْكَرِ [العنكبوت:45] ولقوله : وَأَقِيمُوا الصَّلاةَ وَآتُوا الزَّكَاةَ وَارْكَعُوا مَعَ الرَّاكِعِينَ [البقرة:43] والآيات في هذا المعنى كثيرة، ولقول النبي ﷺ: من سمع النداء فلم يأت، فلا صلاة له إلا من عذر قيل لابن عباس: ما هو العذر قال: «خوف أو مرض» ولقوله ﷺ: بين الرجل، وبين الكفر والشرك ترك الصلاة رواه مسلم في الصحيح، وقوله ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر.. أخرجه الإمام أحمد، وأهل السنن الأربع بإسناد صحيح عن بريدة  ولقوله ﷺ: رأس الأمر الإسلام، وعموده الصلاة. فالواجب على هؤلاء الذين سألت عنهم أن يتقوا الله، وأن يراقبوا الله، وأن يصلوا، وأن لا يتعذروا بأنهم يخافون أن يتركوا الصلاة، فالواجب عليهم ألا يتركوها، أن يحافظوا عليها، وإن تركوها فالواجب التوبة، ومن تاب تاب الله عليه، لا ييأسوا، الله يقول -جل وعلا-: قُلْ يَا عِبَادِيَ الَّذِينَ أَسْرَفُوا عَلَى أَنْفُسِهِمْ لا تَقْنَطُوا مِنْ رَحْمَةِ اللَّهِ [الزمر:53] فالواجب عليهم التوبة إلى الله، والإنابة إليه، والصلوات الخمس مع المسلمين في مساجدهم. وعليك أنت أن تحذرهم، وألا تجتمع بهم، وأن لا تصاحبهم، وعليك أن تهجرهم حتى يتوبوا إلى الله -جل وعلا- لئلا يصيبك ما أصابهم، الواجب عليك التوبة إلى الله من مصاحبتهم، والحذر منهم، ما داموا لم يستجيبوا فالواجب الحذر منهم، أما إذا استجابوا، ورجعوا إلى الله، وتابوا، فالحمد لله، نسأل الله لنا ولهم الهداية. نعم. المقدم: اللهم آمين، شكر الله لكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16094/حكم-مجالسة-تاركي-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_592/59209.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":17367,"question":"من أسئلته يا سماحة الشيخ هذا السائل من جمهورية مصر العربية يقول: رؤية الإنسان لنفسه وهو يقرأ القرآن العظيم في الرؤية المنامية، ماذا تعني مأجورين؟","title":"تأويل من رأى في المنام أنه يقرأ القرآن","answer":"الجواب: خيرًا -إن شاء الله- من يرى في النوم أنه يقرأ القرآن إن شاء الله خيرًا، ما أعلم فيها إلا خيرًا. نعم. المقدم: جزاكم الله عنا، وعن المسلمين خير الجزاء.","link":"https://binbaz.org.sa/fatwas/16203/تاويل-من-راى-في-المنام-انه-يقرا-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_593/59327.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":17454,"question":"سماحة الشيخ! هذا سائل يقول: طلقت زوجتي، وبيني وبينها بنت، ويوجد في بيت أهل زوجتي بعض المنكرات، ماذا أفعل تجاه ذلك مأجورين؟","title":"حكم زيارة الرجل لابنته في بيت به منكرات","answer":"الجواب: إذا كانت منكرات ظاهرة لا تزرهم، واطلب بنتك تأتي إليك، اطلب منهم أن يرسلوها إليك فتشوفها، أما إذا كانت منكرات مستورة؛ تزورهم ترى بنتك، وتسلم عليهم، والمستور لا حكم له. أما إذا كنت تعلم أنها منكرات ظاهرة، إذا جئتهم؛ ترى منكرات ظاهرة، نساءهم يكشفون عندك، مزامير وآلات الملاهي عندك، أو شرب الخمر، لا، لا تذهب إليهم، لكن تطلب البنت، ترسل لهم، تقول: أرسلوا لي بنتي، أو ترسل ولدك، أو أخاك، أو غيرهم من يأتي بها لك، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16318/حكم-زيارة-الرجل-لابنته-في-بيت-به-منكرات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_772/nour_77206.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":17457,"question":"السائلة التي رمزت لاسمها بـ (أ. أ) أرسلت بمجموعة من الأسئلة، السائلة الأخت سامية عبدالله تقول في هذا  قالت لي إحدى الأخوات: بأن قول أعوذ بالله من الشيطان الرجيم بعد التثاؤب بدعة؛ لأنها لم ترد عن النبي ﷺ، وإذا قالها الإنسان هل يأثم.","title":"حكم التعوذ بعد التثاؤب","answer":"الجواب: لا حرج في ذلك؛ لأن هذا مأخوذ من قوله -جل وعلا-: وَإِمَّا يَنزَغَنَّكَ مِنَ الشَّيْطَانِ نَزْغٌ فَاسْتَعِذْ بِاللَّهِ [الأعراف:200] والرسول يقول ﷺ: التثاؤب من الشيطان، فإذا تثاءب أحدكم فليكظم ما استطاع والناس إذا قالوا: أعوذ بالله من الشيطان الرجيم؛ لا بأس؛ لأنه من الشيطان، لكن لا يقال: إنها مستحبة، من فعلها؛ فلا بأس؛ لأن الرسول ﷺ أخبر أن التثاؤب من الشيطان، والله يقول سبحانه: وَإِمَّا يَنزَغَنَّكَ مِنَ الشَّيْطَانِ نَزْغٌ فَاسْتَعِذْ بِاللَّهِ[الأعراف:200] فالتعوذ بالله من الشيطان عند التثاؤب لا حرج فيه، لا يقال: إنه سُنة؛ لعدم وروده، ولكن لا حرج فيه، مثلما يقول: \"أعوذ بالله من الشيطان الرجيم\" دائمًا عند قيامه، أو قعوده، أو عثرته.. أو ما أشبه ذلك، نعم.  المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16326/حكم-التعوذ-بعد-التثاوب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_772/nour_77214.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":17806,"question":"هذا سائل للبرنامج يقول: ما الفرق بين الحلم والرؤيا؟","title":"الفرق بين الحلم والرؤيا","answer":"الجواب: الحلم هو الرؤيا لكن يطلق الحلم على ما كان من لعب الشيطان وإلا فيقال: حلم، ويقال: رأى، فالرؤيا الصالحة من الله والحلم من الشيطان، يعني: ما يكرهه الإنسان هذا من الشيطان، وما ليس بمكروه فهو من الله، ولهذا في الحديث الصحيح: الرؤيا الصالحة من الله، والحلم من الشيطان فإذا رأى ما يكره فهذا من الشيطان، وإذا رأى ما يسره فهذا من الله .\nوالسنة له إذا رأى ما يكره أن يتعوذ بالله من الشيطان ومن شر ما رأى ثلاث مرات ويتفل مع هذا ثلاث مرات، ينفث ثلاث مرات ويقول: أعوذ بالله من الشيطان ومن شر ما رأيت ثلاث مرات، ثم ينقلب على جنبه الآخر فإنها لا تضره ولا يخبر بها أحدًا، أما إذا رأى ما يسره فإنه يحمد الله، ويخبر به من شاء. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16796/الفرق-بين-الحلم-والرويا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_778/nour_77817.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":17818,"question":"من السودان هذه السائلة تقول: قال ﷺ: دعاء المسلم لأخيه مستجاب بظهر الغيب ولأول مرة أقول لأحد: ادع لي معك بالشفاء، هل يعتبر هذا واسطة بيني وبين ربي؟","title":"حكم طلب الدعاء من الأخ لأخيه","answer":"الجواب: لا بأس بهذا، إذا قال الإنسان لأخيه ادع لي بالشفاء أو ادع الله لي أن يرزقني كذا، أو يرزقني الزوجة الصالحة ...... لا بأس بهذا ولا حرج إن شاء الله، نعم. وإذا دعا فله بمثله، قال الملك الموكل: آمين ولك بمثله، إذا دعا لأخيه كما جاء به الحديث الشريف. نعم.\nالمقدم: شكر الله لكم يا سماحة الشيخ وبارك الله فيكم وفي علمكم ونفع بكم المسلمين.","link":"https://binbaz.org.sa/fatwas/16812/حكم-طلب-الدعاء-من-الاخ-لاخيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_778/nour_77824.mp3","categories":["الأدعية والأذكار","الآداب والأخلاق المحمودة"]},{"id":17846,"question":"يقول السائل في سؤال من أسئلته: هل إذا قال المسلم: ما شاء الله! على شيء معين، ولكن ما شاء الله هذه كانت من خارج نفسه فهل تذهب هذه الكلمة عين هذا الشخص بالرغم بأنها كانت من خارج نفسه؟","title":"ما المشروع عند رؤية ما يعجب الإنسان؟","answer":"الجواب: المشروع للمؤمن إذا رأى شيئًا يعجبه أن يقول: ما شاء الله، أو بارك الله كذا، اللهم بارك فيه كما قال الله تعالى: وَلَوْلا إِذْ دَخَلْتَ جَنَّتَكَ قُلْتَ مَا شَاءَ اللَّهُ لا قُوَّةَ إِلَّا بِاللَّهِ[الكهف:39]، والحديث: إذا رأى الإنسان شيئًا يعجبه فليبرك يقول: بارك الله فيه، اللهم بارك فيه. هذا من أسباب السلامة من العين، الإنسان إذا خشي من نفسه شيئًا، ورأى ما يعجبه يقول: ما شاء الله، لا قوة إلا بالله، بارك الله في هذا، اللهم بارك فيه، هذه من أسباب السلامة. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16839/ما-المشروع-عند-روية-ما-يعجب-الانسان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_780/nour_78005.mp3","categories":["الأدعية والأذكار","الآداب والأخلاق المحمودة"]},{"id":17939,"question":"إحدى الأخوات المستمعات من الأردن رمزت إلى اسمها بالحروف (أ. ث) تقول: إنني في السادسة عشرة من عمري وإني والحمد لله أقوم بالفرائض وبعض السنن ولي أم عصبية جدًا إنها تقول لي كلامًا سيئًا وتقول كلامًا فاحشًا، وطبعًا تقول: إن ذلك من غير قلبها وهي كثيرًا ما تتدخل في شئوني وتمنعني من زيارة الأخوات في الله، فما هو توجيهكم تجاه ما ذكرت؟ جزاكم الله خيرًا.الشيخ: تعيده أحسن. نعم.المقدم: تقول: إنني في السادسة عشرة من عمري وإني والحمد لله أقوم بالفرائض وبعض السنن ولي أم عصبية جدًا إنها تقول لي كلامًا سيئًا وتقول كلامًا فاحشًا، وتمنعني من زيارة الأخوات في الله وتقول: إن كلامها ذلك ليس من قلبها، فما هو توجيهكم؟","title":"توجيه لمن تقسو عليها أمها","answer":"الجواب: عليك الصبر والحلم والدعاء لها بالهداية والتوفيق والكلام الطيب حتى يهديها الله وتكف لسانها عن أذاك، وإذا كان أبوك موجودًا ينصحها أيضًا، وهكذا إخوتك الكبار ينصحونها حتى لا تخاطبك بالشيء الذي يؤذيك والحمد لله. أما الزيارة فالزيارة فيها تفصيل، إذا كانت الزيارة لأخواتك ما يترتب عليها مفاسد ولا فجور ولا خلوة بالأجانب فلا بأس بها إذا رضيت الوالدة وإلا فلا تخرجي إلا برضاها؛ لأن برها واجب، بر الوالدة مهم جدًا فلا تخرجي إلى الأخوات إلا برضاها حتى ترضى عنك، ولكن عليك بالكلام الطيب مع الوالدة والأسلوب الحسن وطلب رضاها بالطرق الشرعية، والاستعانة في ذلك بأبيك أو بإخوتك حتى تسمح عنك ولا تسبك ولا تؤذيك بالكلام الفارغ الرديء، الله يهديها، نسأل الله لنا ولها الهداية.\nالمقدم: اللهم آمين، جزاكم الله خيرًا. عبارة وقفت عندها سماحة الشيخ وهي قولها: إن والدتي تتدخل في شئوني، هل يليق هذا الكلام من الأبناء للآباء؟\nالشيخ: هذا لا يليق ولا ينبغي، للوالد أن يتدخل والأم تتدخل فيما يتعلق بإصلاح الولد والبنت، هما ملزومان بأن يربيا أولادهما التربية الشرعية، فالوالد يتدخل والوالدة تتدخل في الشيء الذي يصلح الأولاد وينفعهم في دينهم ودنياهم، أما شيء يمنعهم من الخير أو يثبطهم عن الحق فلا ينبغي للوالدين إنما الطاعة في المعروف، فلو قال الوالد للولد: أريدك تسرق، أو تخون الأمانة، أو تغش في المعاملة ما يطيع ما يجوز له طاعته ولا طاعة الوالدة أيضًا؛ لأن هذه معاصي، والرسول يقول ﷺ: إنما الطاعة في المعروف، لا طاعة لمخلوق في معصية الخالق. وهكذا لو قالا له: إنك ما تصلي في الجماعة، أو إنك تعق إخوتك، تقطع إخوتك القطيعة التي حرمها الله، أو قالا له: إنك عليك أن تعامل بالربا، أو تتجر في الخمور أو في المخدرات ما يطيعهم في هذه المسائل، إنما الطاعة في المعروف، لا طاعة لمخلوق في معصية الخالق. نعم.\nالمقدم: جزاكم الله خيرًا، إذًا من حق الوالدين أن يتدخلا في حقوق الأبناء؟\nالشيخ: نعم، التدخل الذي يحصل به المطلوب من دون أذى ولا ظلم، مشورة ونصيحة ومنع مما يضر. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16974/توجيه-لمن-تقسو-عليها-امها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_847/nour_84714.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":17947,"question":"إحدى الأخوات المستمعات من الأردن رمزت إلى اسمها بالحروف (أ. ث) تقول: إنني في السادسة عشرة من عمري وإني والحمد لله أقوم بالفرائض وبعض السنن ولي أم عصبية جدًا إنها تقول لي كلامًا سيئًا وتقول كلامًا فاحشًا، وطبعًا تقول: إن ذلك من غير قلبها وهي كثيرًا ما تتدخل في شئوني وتمنعني من زيارة الأخوات في الله، فما هو توجيهكم تجاه ما ذكرت؟ جزاكم الله خيرًا.الشيخ: تعيده أحسن. نعم.المقدم: تقول: إنني في السادسة عشرة من عمري وإني والحمد لله أقوم بالفرائض وبعض السنن ولي أم عصبية جدًا إنها تقول لي كلامًا سيئًا وتقول كلامًا فاحشًا، وتمنعني من زيارة الأخوات في الله وتقول: إن كلامها ذلك ليس من قلبها، فما هو توجيهكم؟","title":"توجيه لمن تقسو عليها أمها","answer":"الجواب: عليك الصبر والحلم والدعاء لها بالهداية والتوفيق والكلام الطيب حتى يهديها الله وتكف لسانها عن أذاك، وإذا كان أبوك موجودًا ينصحها أيضًا، وهكذا إخوتك الكبار ينصحونها حتى لا تخاطبك بالشيء الذي يؤذيك والحمد لله. أما الزيارة فالزيارة فيها تفصيل، إذا كانت الزيارة لأخواتك ما يترتب عليها مفاسد ولا فجور ولا خلوة بالأجانب فلا بأس بها إذا رضيت الوالدة وإلا فلا تخرجي إلا برضاها؛ لأن برها واجب، بر الوالدة مهم جدًا فلا تخرجي إلى الأخوات إلا برضاها حتى ترضى عنك، ولكن عليك بالكلام الطيب مع الوالدة والأسلوب الحسن وطلب رضاها بالطرق الشرعية، والاستعانة في ذلك بأبيك أو بإخوتك حتى تسمح عنك ولا تسبك ولا تؤذيك بالكلام الفارغ الرديء، الله يهديها، نسأل الله لنا ولها الهداية.\nالمقدم: اللهم آمين، جزاكم الله خيرًا. عبارة وقفت عندها سماحة الشيخ وهي قولها: إن والدتي تتدخل في شئوني، هل يليق هذا الكلام من الأبناء للآباء؟\nالشيخ: هذا لا يليق ولا ينبغي، للوالد أن يتدخل والأم تتدخل فيما يتعلق بإصلاح الولد والبنت، هما ملزومان بأن يربيا أولادهما التربية الشرعية، فالوالد يتدخل والوالدة تتدخل في الشيء الذي يصلح الأولاد وينفعهم في دينهم ودنياهم، أما شيء يمنعهم من الخير أو يثبطهم عن الحق فلا ينبغي للوالدين إنما الطاعة في المعروف، فلو قال الوالد للولد: أريدك تسرق، أو تخون الأمانة، أو تغش في المعاملة ما يطيع ما يجوز له طاعته ولا طاعة الوالدة أيضًا؛ لأن هذه معاصي، والرسول يقول ﷺ: إنما الطاعة في المعروف، لا طاعة لمخلوق في معصية الخالق. وهكذا لو قالا له: إنك ما تصلي في الجماعة، أو إنك تعق إخوتك، تقطع إخوتك القطيعة التي حرمها الله، أو قالا له: إنك عليك أن تعامل بالربا، أو تتجر في الخمور أو في المخدرات ما يطيعهم في هذه المسائل، إنما الطاعة في المعروف، لا طاعة لمخلوق في معصية الخالق. نعم.\nالمقدم: جزاكم الله خيرًا، إذًا من حق الوالدين أن يتدخلا في حقوق الأبناء؟\nالشيخ: نعم، التدخل الذي يحصل به المطلوب من دون أذى ولا ظلم، مشورة ونصيحة ومنع مما يضر. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16974/توجيه-لمن-تقسو-عليها-امها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_847/nour_84714.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":17948,"question":"كيف يكون الإصلاح بين الناس فيما ورد من الأحاديث؟","title":"كيفية الإصلاح بين الناس","answer":"الجواب: إذا تنازعا عندك أو ناس تعرفهم؛ تصلح بينهم، من أهلك أو من جيرانك، إذا علمت ذلك واستطعت، تسعى في الصلح بينهم: فَاتَّقُوا اللَّهَ وَأَصْلِحُوا ذَاتَ بَيْنِكُمْ [الأنفال:1].. وَالصُّلْحُ خَيْرٌ [النساء:128]، وفي الحديث الصحيح: \"أن الرسول ﷺ نهى عن الكذب إلا في ثلاث -من جملة الثلاث:- الإصلاح بين الناس\"، فالإصلاح بينهم توسط بينهم؛ حتى تعود الحالة الطيبة بينهم، ويزول ما بينهم من الهجر والكراهة، تكون أنت مأجور بذلك، فإصلاح ذات البين من أفضل القربات، من جيرانك أو من أقاربك أو من غيرهم.\nالمقدم: جزاكم الله خيرًا، وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/16950/كيفية-الاصلاح-بين-الناس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_598/59827.mp3","categories":["الآداب والأخلاق المحمودة","نصائح وتوجيهات"]},{"id":17964,"question":"من المستمعة (م. ع. ز) رسالة وفيها سؤال طويل تقول عن نفسها: أنا امرأة اغتبت كثيرًا جدًا ولم يسلم أحد من لساني حتى المارة في الطريق أغتابهم سواءً عرفت أحدًا منهم أم لم أعرفهم، اغتبت إخواني وأخواتي ووالدي وزوجي وجيراني وأقاربي فردًا فردًا، وإذا ذهبت إلى حفلة لم أترك أحدًا إلا وأتيت بذكره بعيب فيه على مدار عشر سنين أو أكثر، وقد ندمت أشد الندم وتحسرت على ما كنت عليه من الغفلة وتبت إلى الله  وعسى الله أن يقبل، ولكني علمت أن التوبة من الغيبة يلزمها شرط هو: أن أتحلل ممن اغتبت، كيف أتحلل من أبي وأمي وإخواني مما قد يورث الكره؟ وكيف أتحلل ممن لا أعرفه وهذا صعب وشاق وقد لا أجد سبيلًا للتعرف عليهم؟ وهل من مخرج؟ وكيف يكون؟ هل تنصحونني بالاستغفار لهذا الجمع الهائل من الناس؟ أم ماذا أفعل؟ أفيدوني، جزاكم الله خيرًا، وهل يكفي أن أقول: اللهم اغفر لكل من اغتبت، دبر كل صلاة؟ وجزاكم الله خيرًا.","title":"كيفية التحلل من الغيبة","answer":"الجواب: التوبة والحمد لله كافية، التوبة كافية والحمد لله، ونسأل الله أن يتقبلها منك، وعليك أن تسألي الله لهم العفو والمغفرة، وأن تذكريهم بالخير الذي تعرفين عنهم من تعرفين منهم تذكريه بالخير الذي تعرفيه منه بدلًا من السوء الذي ذكرته. وأما تحللهم فلا يلزم للصعوبة التي ذكرت، لكن من عرفت منهم وتيسر استحلاله فلا بأس، قولي له: إني فعلت كذا أبحني وسامحني، إذا تيسر ولم تخشي شرًا، أما إذا كان تخشي شرًا أن يترتب على طلبك التحلل فتنة وعداوة وشحناء فيكفي التوبة والحمد لله ولا يلزم استحلالهم.\nأما من لا تعرفين فيكفي التوبة والحمد لله والدعاء لهم بالخير والاستغفار لهم والحمد لله. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17006/كيفية-التحلل-من-الغيبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_848/nour_84813.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":18132,"question":"من الكويت الذي رمز لاسمه بـ (م. م) يقول: ما هي السنن التي كان يعملها المصطفى ﷺ قبل النوم؟","title":"السنن العملية قبل النوم","answer":"الجواب: كان عليه الصلاة والسلام يأتي بالأذكار الشرعية قبل النوم، فالسنة للمؤمن أن يأتي بالأذكار الشرعية التي ذكرها العلماء في كتب الحديث عند النوم، يقول: اللهم باسمك أحيا وأموت عندما يضع يده تحت خده الأيمن مضطجعًا ويكون على طهارة، ويقول: اللهم باسمك أحيا وأموت، اللهم باسمك ربي وضعت جنبي وبك أرفعه، إن أمسكت نفسي فارحمها، وإن أرسلتها فاحفظها وأشباه ذلك مما ثبت عنه عليه الصلاة والسلام، يتحرى الإنسان ما ذكره العلماء في كتب الحديث حتى يفعل ذلك. كذلك يقرأ آية الكرسي عند النوم، و قل هو الله أحد والمعوذتين ثلاث مرات عند النوم، كل هذا مما كان يفعله النبي ﷺ، فهذا من أسباب الحفظ والوقاية، نعم. المقدم: أحسن الله إليكم، وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17178/السنن-العملية-قبل-النوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_781/nour_78114.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":18136,"question":"سائلة تذكر في سؤال لها سماحة الشيخ بأن عندها خادمات في البيت، وتذكر بأنها تقسو عليهن في المعاملة، وبالكلام، وبالعمل تقول: مع أنني كنت أساعدهن في بعض الأعمال فكيف أكفر عن ذلك؟ وهل يلحقني إثم؟","title":"الواجب الرفق والحكمة في التعامل مع الخادمات","answer":"الجواب: الواجب الرفق والحكمة، وعدم التشديد يقول النبي ﷺ: إن الرفق لا يكون في شيء إلا زانه، ولا ينزع من شيء إلا شأنه، فالواجب على من عنده عمال أو خدم أو أولاد أن يرفق في تعليمهم وتوجيههم إلى الخير، وأن يتباعد عن القسوة، لكن إذا فعلوا منكر ينكر عليهم المنكر، ويجتهد في تركهم له، لكن في الخدمة المعتادة، والقيام بحاجات البيت؛ يكون بالرفق، والحكمة، والوصايا الطيبة، وطلاقة الوجه، وطيب الكلام، نسأل الله للجميع الهداية. نعم. المقدم: اللهم آمين، أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17175/الواجب-الرفق-والحكمة-في-التعامل-مع-الخادمات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_781/nour_78113.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":18138,"question":"تقول أختنا: إن يدي أصيبت بحرقٍ منذ صغري، وهي يدي اليمنى، مما سبب فقدي لإصبع الخنصر، والبنصر، فما حكمي للأكل بيدي اليسرى؟ جزاكم الله خيرًا.","title":"حكم الأكل باليد اليسرى لمن فقد بعض أصابع اليمنى","answer":"الجواب: تأكلين بالثلاثة: الإبهام، والوسطى، والسبابة، والحمد لله، تأكلين بها، أو بملعقة، ولا تأكلي باليسرى، الرسول ﷺ قال: إذا أكل أحدكم فليأكل بيمينه، وإذا شرب فليشرب بيمينه؛ فإن الشيطان يأكل بشماله ويشرب بشماله وزوال الخنصر والبنصر لا يمنع الأكل، كان النبي يأكل بثلاثة أصابع عليه الصلاة والسلام، كان النبي ﷺ يأكل بثلاثة أصابع، فأنت كلي بالثلاث، فإن لم تنفع فبالملعقة. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17171/حكم-الاكل-باليد-اليسرى-لمن-فقد-بعض-اصابع-اليمنى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_731/nour_73102.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":18201,"question":"يدور على ألسنة الناس الكلمة التالية: لا حياء في الدين؟","title":"مدى صحة المقولة (لا حياء في الدين)","answer":"الجواب: هذا صحيح في المعنى، صحيح في الجملة مثلما قال ﷺ.. مثلما قالت المرأة للنبي ﷺ: \"إن الله لا يستحي من الحق، فهل على المرأة من غسل إذا هي احتلمت؟\"، فمعنى لا حياء في الدين، يعني: لا حياء يمنع السؤال، والتعلم، والتفقه في الدين، الحياء لا يمنع. أما إن كان المراد لا حياء في الدين، بالكلية، لا ما هو بصحيح، الرسول عليه السلام قال: الحياء من الإيمان فالحياء الذي يردعه عن المعاصي؛ من الإيمان الحياء من الإيمان، قال النبي ﷺ: إذا لم تستح فاصنع ما شئت. لكن إذا كان المراد: لا حياء في الدين: لا حياء يمنع من التعلم والسؤال؛ فهذا صحيح، الحياء لا يمنع بسؤالك عن دينك، والتفقه في الدين، فالحياء حياءان: حياء يمنع من التفقه في الدين، هذا ممنوع، ليس بحياء، والحياء الثاني: يمنعك من سيئ الأخلاق من المعاصي، فهذا حياء مطلوب، جاء به الدين، كما في الحديث الصحيح: الإيمان بضع وسبعون شعبة، فأفضلها قول: لا إله إلا الله، وأدناها: إماطة الأذى عن الطريق، والحياء شعبة من الإيمان فالحياء الذي يمنع من الشر شعبة من الإيمان؛ فإن الحياء خلق عظيم كريم، يمنع من أعمال الشر، ويحمل على الأفعال الطيبة. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17243/مدى-صحة-المقولة-لا-حياء-في-الدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_731/nour_73116.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":18317,"question":"هذه السائلة: (م. الشهراني) تقول في سؤالها: سماحة الشيخ! هناك معلمة سليطة اللسان دائمًا تتعدى علي وتشتمني دون سبب واضح، وهي الآن لا تكلمني، ولا أكلمها ودائمًا تقعد لي بالمرصاد وتثير مني الشكوك، تقول: ما الواجب علي وما الواجب عليها في هذا الأمر؟","title":"الواجب على من كانت بينهما عداوة وشحناء","answer":"الجواب: الواجب عليكم تقوى الله جل وعلا، لا تظلمك ولا تظلمينها، عليك ألا تظلميها ولا تظلمك وارفعي أمرها إلى المديرة والعميدة حتى تصلح بينكما، الواجب الصلح بينكم والحذر من الشحناء، وعليك أن ترفعي الأمر إلى العميدة أو المديرة لعلها تصلح بينكما. نعم.","link":"https://binbaz.org.sa/fatwas/17367/الواجب-على-من-كانت-بينهما-عداوة-وشحناء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_913/nour_91308.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":18433,"question":"أنا ساكن في القرية، وعندما أذهب إلى المسجد للصلاة أرى في الطريق بعض الشباب لا يصلون، وأسلم عليهم، هل علي إثم في هذا الفعل؟","title":"حكم إلقاء السلام على من لا يصلي","answer":"الجواب: ليس عليك إثم، يشرع لك السلام عليهم، وأمرهم بالمعروف، ونهيهم عن المنكر، تقول لهم: يا عباد الله! الصلاة.. الصلاة.. توكلوا على الله.. الحقوا الصلاة.. أذن المؤذن، تنصحهم وتأمرهم بالمعروف وتسلم، تبدأ بالسلام، ثم تأمرهم بالمعروف وتنصحهم تقول: استعينوا بالله.. توجهوا إلى المسجد.. بارك الله فيكم.. هداكم الله.. أصلحكم الله ونحو هذا من الكلام الطيب. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17514/حكم-القاء-السلام-على-من-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_914/nour_91408.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":18469,"question":"أرجو إفادتي عن بعض الكلمات التي أرددها عند رؤيتي حلم مزعج؟","title":"السنة عند رؤية ما يكره في المنام","answer":"الجواب: ثبت عن رسول الله عليه الصلاة والسلام أنه قال: الرؤيا الصالحة من الله والحلم من الشيطان؛ فإذا رأى أحدكم ما يكره فلينفث عن يساره ثلاثًا، وليستعذ بالله من الشيطان ومن شر ما رأى ثلاثًا ثم لينقلب على جنبه الآخر فإنها لا تضره ولا يخبر بها أحدًا هكذا السنة. وفي لفظ آخر يقول ﷺ: إذا رأى أحدكم ما يحب فليحمد الله وليحدث بذلك من يحب، وإذا رأى ما يكره فلينفث عن يساره ثلاث مرات، وليتعوذ بالله من الشيطان ومن شر ما رأى ثلاث مرات، ثم لينقلب على جنبه الآخر؛ فإنها لا تضره ولا يخبر بها أحدًا فهذا يا أخي هو السنة. نعم.","link":"https://binbaz.org.sa/fatwas/17578/السنة-عند-روية-ما-يكره-في-المنام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_866/nour_86613.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":18493,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من الأخ حامد محمد عيسى من رابغ، أخونا يسأل ويقول: حيث أنني عامل في بقالة لبيع المواد الغذائية، وقد لاحظت العديد من المظاهر التي اشمأزيت منها، وإنني أسأل هل يجوز الكذب على من أعرفه أنه لا يصلي ولا يصوم ويدعي أنه مسلم؟ وكذلك هل يجوز غشهم؟ أرجو أن ترشدوني جزاكم الله خيرًا.","title":"النهي عن غش الكافر وخيانته","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد فإن الله  حرم على عباده الخيانة والغش؛ حيث قال : إِنَّ اللَّهَ يَأْمُرُكُمْ أَنْ تُؤَدُّوا الأَمَانَاتِ إِلَى أَهْلِهَا [النساء:58]، وقال : يَا أَيُّهَا الَّذِينَ آمَنُوا لا تَخُونُوا اللَّهَ وَالرَّسُولَ وَتَخُونُوا أَمَانَاتِكُمْ وَأَنْتُمْ تَعْلَمُونَ [الأنفال:27]، وقال : وَالَّذِينَ هُمْ لِأَمَانَاتِهِمْ وَعَهْدِهِمْ رَاعُونَ [المؤمنون:8]. هذه من صفات أهل الإيمان، وقال النبي ﷺ: من غشنا فليس منا. فليس لك -أيها السائل- أن تغش من يشتري منك ويعاملك، سواء كان كافرًا أو مسلمًا، سواء كان يصلي أو لا يصلي، الواجب عليك أن تؤدي الأمانة وأن تبيع بأمانة ونظافة وعدم غش وعدم خيانة. وإذا علمت أن أحدًا لا يصلي أو أنه يفعل شيئًا من المنكر فعليك أن تنصحه إذا استطعت ذلك، وأن تعلمه ما ينفعه، وأن ترشده إلى الخير، وأن تنكر عليه المنكر، كما قال الله : وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ [التوبة:71]، وقال النبي ﷺ: الدين النصيحة، قيل: لمن يا رسول الله؟ قال: لله ولكتابه ولرسوله ولأئمة المسلمين وعامتهم فانصح من ترى منه ما يخالف الشرع حسب طاقتك، أما الغش والخيانة فلا. نعم.","link":"https://binbaz.org.sa/fatwas/17581/النهي-عن-غش-الكافر-وخيانته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_867/nour_86701.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":18599,"question":"إذا زارني زائر، أو دعوت أحدًا لمنزلي، فإنني أقول: هذه الذبيحة لفلان، وأقول أيضًا: إذا أتى فلان سأذبح له ذبيحة، فهل هذا جائز، أم أنه من الشرك؟","title":"حكم الذبح للضيافة والإكرام","answer":"الجواب: لا، لا حرج في ذلك، من باب الإكرام والضيافة، هذا: أذبح له ذبيحة، يعني: أكرمه بهذه الشيء، ثم أذبح .... فالمقصود: أن هذا لا بأس به، هذا من باب الإكرام، من باب الضيافة، ليس من باب التقرب إلى شخص معين، بخلاف الذي يذبح للقبور أو للأصنام، ويتقرب إليهم أو للجن هذا الشرك الأكبر، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17707/حكم-الذبح-للضيافة-والاكرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_734/nour_73407.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":19033,"question":"الرسالة التالية وصلت إلى البرنامج من أحد الإخوة المستمعين، بل من إحدى الأخوات المستمعات تقول: أختكم في الله (أ. ع. أ) من الرياض تسأل جمعًا من الأسئلة في أحدها تقول: جيراني يدعونني لكي أزورهم، لكن بعض الأحيان أقول: عندي شغل؛ لعدم رغبتي في الذهاب إليهم، هل يعتبر هذا من الكذب؟ ومرات أقول: لهم إن شاء الله، ولا أذهب إليهم، هل هذا أيضًا يعتبر من عدم الوفاء بالوعد؟ أفيدونا بارك الله فيكم.","title":"حكم التعذر بالانشغال عند عدم الرغبة في الزيارة","answer":"الجواب: يقول النبي ﷺ في الحديث الصحيح: من كان يؤمن بالله واليوم الآخر فليكرم جاره ويقول ﷺ: ما زال جبريل يوصيني بالجار حتى ظننت أنه سيورثه. فزيارة الجار، والأنس به، والإحسان إليه إذا كان فقيرًا بالمال، وبالكلام الطيب، وبكف الأذى؛ أمر مطلوب ومشروع. وإذا كانت الزيارة فيها مضرة فالأولى تركها، والاعتذار بالعذر المناسب، إذا كان الجيران عندهم معاص ظاهرة، أو أشياء أخرى تمنع من الزيارة؛ فلا بأس في الاعتذار، وإذا قال الزائر: إن شاء الله وهو قصده أنه لا يزور إلا بمشيئة الله فلا بأس. أما أن يقول: لي شغل وهو ليس له شغل؛ لا بد من التأويل يقول: لي شغل يعني: شغل يمنع من الزيارة، ينوي في قلبه أنه أراد بالشغل يعني: شغل يمنع من الزيارة مثل: ظهور المنكرات عندهم، مثل كونهم إذا حصلت الزيارة يحصل غيبة، ولا يسكتون عن الغيبة، أو مشاهدة المنكرات عندهم، فالمعتذر يقول: لي شغل بالنية، لي شغل وهو ما عندكم من الشر، هو اللي يمنعني من المجيء، فالحاصل أنه إذا اعتذر بشيء يتأول حتى لا يكون كاذبًا. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18218/حكم-التعذر-بالانشغال-عند-عدم-الرغبة-في-الزيارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_796/nour_79606.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":19080,"question":"أولى أسئلة هذه الحلقة سماحة الشيخ: سؤال من المواطن (ع.ف.غ) يقول: صدر من سماحتكم بيان منذ أسبوعين تقريبًا حول ما ينبغي للدعاة والعلماء من النقد البناء، وعدم تجريح الأشخاص، فتأوله بعض الناس على أناس معينين، فماذا ترون في هذا التأويل؟ جزاكم الله خيرًا، وأحسن إليكم.","title":"النقد البناء ليس فيه تجريح","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله، وأصحابه ومن اهتدى بهداه، أما بعد: فهذا البيان الذي أشار إليه السائل أردنا منه نصيحة إخواني العلماء والدعاة بأن يكون نقدهم لإخوانهم فيما يصدر من مقالات، أو نصيحة، أو محاضرة، أو ندوة، أن يكون نقدًا بناءً بعيدًا عن التجريح، وتسمية الأشخاص؛ لأن هذا قد يسبب شحناء وعداوة بين الجميع، وكان من عادة النبي ﷺ وطريقته إذا بلغه عن بعض أصحابه شيء لا يوافق الشرع نبه على ذلك بقوله ﷺ: ما بال أقوام قالوا كذا وكذا، ثم يبين الأمر الشرعي عليه الصلاة والسلام. ومن ذلك أنه بلغه أن بعض الناس قال: أما أنا فأصلي ولا أنام، وقال الآخر: أما أنا فأصوم ولا أفطر، وقال آخر: أما أنا فلا أتزوج النساء؛ فخطب الناس عليه الصلاة والسلام، وحمد الله، وأثنى عليه ثم قال: ما بال أقوام قالوا كذا وكذا، لكني أصلي وأنام، وأصوم وأفطر، وأتزوج النساء؛ فمن رغب عن سنتي فليس مني، فمقصودي هو ما قاله النبي ﷺ. مقصودي أن التنبيه يكون بمثل هذا الكلام، بعض الناس يقول كذا، وبعض الناس قال كذا، والواجب كذا، والمشروع كذا. يكون الانتقاد بغير تجريح لأحد معين، ولكن من باب بيان الأمر الشرعي، أن الواجب كذا، وأن المشروع كذا، وينبغي كذا، من دون أن يقال فعل فلان، وقال فلان؛ حتى تبقى المودة والمحبة بين الإخوان، وبين الدعاة، وبين العلماء. ولست أقصد بذلك أناسًا معينين، وإنما قصدت العموم، قصدت جميع الدعاة، وجميع العلماء في الداخل والخارج. نصيحتي للجميع أن يكون التخاطب فيما يتعلق بالنصيحة والنقد من طريق الإبهام لا من طريق التعيين، إذ المقصود التنبيه على الخطأ والغلط، والتنبيه على ما ينبغي في هذا المقام من بيان الصواب والحق من دون حاجة إلى تجريح فلان أو فلان. هذا هو المقصود، وليس المقصود أحدًا معينًا بذلك دون غيره، وفق الله الجميع. نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18251/النقد-البناء-ليس-فيه-تجريح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_797/nour_79701.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":19083,"question":"من أسئلته يقول: يوجد بعض الناس الذين يقومون بأداء الصلاة ويكونون تاركين للصلاة في نفس الوقت وأضطر أن آكل معهم، هل يجوز أن نأكل مع الذين لا يؤدون الصلاة؟ أو يتركون الصلاة؟","title":"حكم الأكل مع من لا يصلي","answer":"الجواب: إذا دعت الحاجة إلى ذلك مع النصيحة مع نصيحتهم؛ فإن لم يقبلوا فاهجرهم ولا تأكل معهم، لكن إذا دعت الضرورة إلى الأكل معهم فكن ناصحًا لهم موجهًا لهم إلى الخير، محذرًا لهم من ترك الصلاة ومبينًا لهم أن من تركها كفر لعل الله يهديهم بأسبابك، فإن لم يستجيبوا فاهجرهم، ولا تجالسهم، ولا تأكل معهم، نسأل الله العافية. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/18241/حكم-الاكل-مع-من-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_883/nour_88318.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":19102,"question":"رسالة وصلت خطها شبيه بالرسالة الأولى، والقضية قريبة منها إلا أنها من مكة، والتوقيع هو نفس التوقيع فيما يبدو لي المرسلة (س. م. ج) صاحبة هذه الرسالة تقول: بسم الله الرحمن الرحيم، والحمد لله رب العالمين، والصلاة والسلام على أشرف المرسلين، سيدنا محمد وعلى آله وصحبه أجمعين.سماحة الشيخ عبد العزيز بن عبد الله بن باز حفظه الله، السلام عليكم ورحمة الله وبركاته وبعد:أريد من سماحتكم تفسيرًا لهذه الرؤيا حيث أنني ما رأيت رؤيا أو حلمت حلمًا إلا ووقع بإذن الله تعالى في حياتي، هذه الرؤيا رأيتها بعد طلاقي من زوجي بيومين، ذلك الزواج الذي دام أقل من سنتين، وانفصلنا عن بعض لوجود عيب في زوجي، قمت من نومي حوالي الساعة الثامنة صباحًا، كنت وقتها للتو مستيقظة من الرؤيا وهي كالتالي:رأيت هلالًا في السماء كالهلال الذي يكون في الخمسة الأيام الأولى من بداية الشهر، وكنت أحدث نفسي وأنا أنظر إليه وأقول: سبحان الله هلال في وضح النهار! ثم جاء بجانبه هلال آخر، ثم آخر، حتى أصبحت سبعة أهلة كما هي موضحة في الرسم -رسمت أربعة أهلة من أعلى وثلاثة من أسفل سماحة الشيخ-.ثم استيقظت من نومي مستبشرة، وفسرتها لنفسي على أن الله سيعوضني خيرًا مما سلف، وأتزوج وأنجب سبعة أولاد، يأتي الأول ثم أتأخر في الحمل قليلاً ثم يأتي الأولاد الباقون وراء بعضهم بعضًا.ثم حدثت أخًا لي بالرؤيا فقال لي: قد يكونوا أخوتك مثل رؤيا سيدنا يوسف عليه السلام، وفعلًا عدد إخوتي سبعة، ولكن واحدًا منهم غائب حيث أنه محكوم عليه في سجون الاحتلال الصهيوني أربعة عشر عامًا، فما هو الصحيح سماحة الشيخ في تفسير هذه الرؤيا حيث أنني رأيتها وأنا علي الدورة الشهرية؟ والسلام عليكم ورحمة الله وبركاته.","title":"تفسير رؤية الأهلة في المنام","answer":"الجواب: الله أعلم بتفسيرها  لأنه لا يجوز للمسلم أن يعبر رؤيا على غير هدى، وعلى غير بصيرة، ولكن نرجو أن يكون تأويلك لها خيرًا، وواقعًا، وأن الله يرزقك خيرًا من الزوج السابق، وأن يهبك أولادًا سبعة، أو أكثر من ذلك، ويجعل فيهم الصلاح والخير، فتأويلك ليس ببعيد، ولعلهم يكونون أخيارًا، دعاة للخير، ويكون لهم شهرة كالأهلة، يكون لهم خير إن شاء الله، هذا ليس ببعيد، أما كون هذا هو التأويل. فالله أعلم لكن نرجو لك الخير، والعاقبة الحميدة، وأن يكون تأويلك تأويلًا واقعًا في مصلحتك وخيرك إن شاء الله. نعم. المقدم: جزاكم الله خيرًا، الواقع يبدو لي أن المرسلة واحدة؟ الشيخ: هي هي. المقدم: هي هي. الشيخ: نعم.","link":"https://binbaz.org.sa/fatwas/18296/تفسير-روية-الاهلة-في-المنام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_884/nour_88405.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":19150,"question":"في سؤالها الثاني تقول: هل يعتبر إنفاقي على ولدي ثوابًا يغنيني عن إخراج زكاة أموالي؟","title":"حكم إنفاق المرأة على ولدها واحتساب ذلك من الزكاة","answer":"الجواب: لا، الإنفاق على الولد أمر لازم، إذا كان الولد فقيرًا وليس له أب ينفق عليه، إما ميت وإما عاجز، فالنفقة منك عليه واجبة على الصحيح، إذا كنت قادرة، والزكاة لا تصلح للولد، ولا للأب ولا للأم، وإنما تصلح للفقراء من الإخوة والأخوات والأعمام والعمات ونحو ذلك، أما ولدك فالواجب عليك الإنفاق عليه من مالك، أما الزكاة فتنفق في جهات أخرى، الزكاة تنفق في أهلها من الفقراء والمساكين غير أولادك. نعم.","link":"https://binbaz.org.sa/fatwas/18326/حكم-انفاق-المراة-على-ولدها-واحتساب-ذلك-من-الزكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_886/nour_88602.mp3","categories":["النفقات","الآداب والأخلاق المحمودة"]},{"id":19170,"question":"نعود في هذه الحلقة إلى رسالة المستمع محسن عبد العزيز عبد الواحد من جمهورية مصر العربية، وهو مقيم في العراق، أخونا عرضنا بعض أسئلته في حلقة مضت، وفي هذه الحلقة يقول: أنا اسمي محسن، وأحد طلبة العلم قال: إن هذا الاسم غير جائز، ونصحني بتغيير اسمي، فما هو رأيكم جزاكم الله خيرًا؟","title":"حكم التسمي باسم محسن","answer":"الجواب: نعم قد جاء في بعض الأحاديث ما يدل على تسمية الله سبحانه بأنه محسن، فلا حرج في ذلك إن شاء الله، قد جاء في حديث جيد لا بأس به، إطلاق اسم المحسن على الله جل وعلا، فهو المحسن  هو المحسن إلى جميع العباد جل وعلا، فـعبد المحسن لا بأس به، هذا هو الصواب. نعم. المقدم: هو اسمه محسن وليس عبد المحسن ؟ الشيخ: اسمه محسن ؟ المقدم: نعم. الشيخ: فلا بأس أيضًا، لا بأس بمحسن؛ لأن هذا من الأسماء التي يسمى بها، مثل: عزيز، مثل: سميع، مثل اسم: حليم، ومثل أشباهها؛ لأن أسماء الله ليست تمنع بالنسبة إلى المخلوقين إلا ما يختص به سبحانه، كالخلاق، والرزاق، ومالك الملك، والرحمن الرحيم، والرحمن كذا، وما أشبه ذلك، أما ما يشترك فيه غيره فللعبد ما يناسبه ولله ما يناسبه، فيقال في الشخص: حليم، ويقال: رءوف، ويقال: رحيم، كما قال الله في نبيه محمد ﷺ: بِالْمُؤْمِنِينَ رَءُوفٌ رَحِيمٌ [التوبة:128]، عليه الصلاة والسلام، وهكذا في السميع والبصير، في قوله جل وعلا: هَلْ أَتَى عَلَى الإِنسَانِ حِينٌ مِنَ الدَّهْرِ لَمْ يَكُنْ شَيْئًا مَذْكُورًا ۝ إِنَّا خَلَقْنَا الإِنسَانَ مِنْ نُطْفَةٍ أَمْشَاجٍ نَبْتَلِيهِ فَجَعَلْنَاهُ سَمِيعًا بَصِيرًا [الإنسان:1-2]، سماه سميعًا بصيرًا. فالحاصل أن المخلوق يسمى ببعض أسماء الله التي لا تختص به سبحانه، كالسميع والبصير والقدير والحليم والرءوف والرحيم، ونحو ذلك، فالمحسن من ذلك. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18376/حكم-التسمي-باسم-محسن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_887/nour_88705.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":19218,"question":"أختنا تسأل وتقول: هل الأسماء: هدى، ورحمة، وبركة، وإيمان، هل هذه الأسماء من الأسماء المكروهة في الدين؟","title":"حكم التسمي بهدى ورحمة وبركة وإيمان","answer":"الجواب: لا حرج فيها مثل: صالح وعامر وسعيد كلها أسماء جامدة ما تقصد معانيها، فلا حرج في ذلك إن شاء الله، نعم.\nوقد هم النبي ﷺ أن ينهى عن مثل هذا ثم تركه عليه الصلاة والسلام. المقدم: اللهم صل عليه.","link":"https://binbaz.org.sa/fatwas/18392/حكم-التسمي-بهدى-ورحمة-وبركة-وايمان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_933/nour_93312.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":19356,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول: المرسل أخوكم (ن. ك. ر) باكستاني يسأل ويقول: أنا رجل باكستاني مسلم أبًا عن جد، واسمي ليس بالسهل النطق به، والكثير من الناس ينادونني باسم محمد، ويومًا ذهبت إلى المسجد للصلاة فسألني أحد الإخوة عن اسمي فقلت له بأن اسمي محمد، هل هذا جائز أو لا؟ وقد استغفرت الله؛ لأن ذلك أثر في نفسي.","title":"حكم تغيير الأسماء","answer":"الجواب: إذا كنت لا تسميت بمحمد من جهة الرسميات، ليس في جوازك اسمك محمد ولا في حافظة ... وإنما بعض الناس يسميك محمد فليس لك أن تقول للناس: إن اسمك محمد إلا إذا صممت على تغيير اسمك وجعلته محمدًا بدل اسمك الذي سماك به أهلك فلا بأس، وأما أن تكذب على بعض الناس لا، فالتوبة من هذا كافية والاستغفار. أما إذا عزمت على أن تجعله اسمًا لك أو دائمًا بدلًا من اسمك الذي سماك به أهلك فلا حرج في ذلك يجوز تغيير الاسم والحمد لله. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/18565/حكم-تغيير-الاسماء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_900/nour_90003.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":19436,"question":"تسأل أختنا وتقول: هل يجوز الكذب من أجل الإصلاح لغير الزوجين، فمثلًا: عندما أقوم بالدعوة إلى طريق الله والأمر بالمعروف والنهي عن المنكر، هل يجوز لي أن أستحدث قصة من خيالي، أي: غير حقيقية، إما للترهيب وإما للترغيب؟ وما هي المواضع التي يجوز فيها الكذب؟","title":"الأحوال التي يجوز فيها الكذب","answer":"الجواب: ثبت عن النبي ﷺ أنه قال: ليس الكذاب الذي يصلح بين الناس فيقول خيرًا وينمي خيرًا وقالت أم كلثوم بنت عقبة بن أبي معيط رضي الله عنها: «لم أسمع النبي ﷺ يرخص في شيء من الكذب إلا في ثلاث: الإصلاح بين الناس، والحرب، وحديث الرجل امرأته والمرأة زوجها». ففي الحرب لا مانع من الكذب الذي ينفع المسلمين، ولا يكون فيه خداع، ولا يكون فيه غدر للكفار، لكن يكون فيه مصلحة للمسلمين، كأن يقول أحدهم في للجيش: نحن راحلون غدًا إن شاء الله إلى كذا وكذا، أو يقول: نحن سنتوجه إلى الجهة الفلانية؛ ليعمي الخبر على العدو حتى يفجأهم على غرة إذا كانوا قد بلغوا وأنذروا ودعوا قبل ذلك فلم يستجيبوا وعاندوا، قد ثبت عنه ﷺ أنه كان إذا أراد غزوة ورى بغيرها. فالمقصود: أن الكذب الذي ليس فيه غدر ولا خداع، ولكن فيه مصلحة للمسلمين لا بأس به في الحرب . وهكذا في الإصلاح بين الناس، بين قريتين، أو جماعتين، أو قبيلتين، أو شخصين يصلح بينهم بكذب لا يضر أحدًا من الناس ولكن ينفع هؤلاء، كأن يأتي إحدى القبيلتين فيقول: إن إخوانكم يعني: القبيلة الأخرى يدعون لكم ويثنون عليكم ويرغبون في الإصلاح معكم، ثم يذهب للأخرى فيقول مثل ذلك، ولو ما سمع منهم هذا؛ حتى يجمع بينهما، وحتى يصلح بينهما، وحتى يزيل الشحناء التي بينهما، وهكذا بين جماعتين، أو أسرتين، أو شخصين يكذب كذبًا لا يضر أحدًا من الناس، ولكنه ينفع هؤلاء، ويسبب زوال الشحناء، هذا هو الإصلاح بين الناس . وأما الرجل مع زوجته فالأمر فيه واسع، إذا كان الكذب لا يضر أحدًا غيرهما إنما فيما بينهما فلا بأس بذلك، أن تقول: أنا سوف أفعل كذا، وسوف لا أعصيك أبدًا، وسوف أشتري هذا الشيء، وسوف أعمل في البيت هذا الشيء، وهو يقول كذلك فيما سيتعلق بهما لإرضائها: سوف أشتري لك كذا وكذا، سوف أفعل كذا وكذا، يتقرب إليها بأشياء ترضيها وتنفعها وتجمع بينهما، وهي كذلك في أشياء تتعلق بهما خاصة ليس في ذلك كذب على أحد من الناس، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18663/الاحوال-التي-يجوز-فيها-الكذب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_937/nour_93707.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":19565,"question":"يقول يا سماحة الشيخ هذا السائل: ظلمني البعض من الناس، وأنا لا أقدر عليهم، ومع ذلك سامحتهم لله : هل شرط المسامحة أن أكون قادرًا عليهم؟","title":"حكم المسامحة للظالم عند عدم المقدرة على رد ظلمه","answer":"الجواب: ليس من شرط ذلك إذا سمح عنهم جزاه الله خيرًا، يؤجر ولو كان غير قادر، وإن لم يسمح فالموعد الله بينه وبينهم، وإن سامحهم وعفا فله أجر ذلك.","link":"https://binbaz.org.sa/fatwas/18820/حكم-المسامحة-للظالم-عند-عدم-المقدرة-على-رد-ظلمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_947/nour_94712.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":19568,"question":"يقول يا سماحة الشيخ! حدثونا عن فضل السلام، فمثلًا لو كان هناك مجموعة من الناس في مجلس، ودخل عليهم شخص وسلم عليهم، هل يلزمهم رد السلام كلهم أم يكتفي البعض؟","title":"كيفية رد الجماعة إذا سلم عليهم شخص واحد","answer":"الجواب: إذا سلموا كلهم أفضل، وإن رد البعض أجزأ عن الباقين لحديث: يجزئ عن الجماعة أن يسلم أحدهم، ويجزئ عن الجماعة أن يرد أحدهم لكن إذا سلموا جميعًا كان أفضل. نعم.","link":"https://binbaz.org.sa/fatwas/18828/كيفية-رد-الجماعة-اذا-سلم-عليهم-شخص-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_947/nour_94718.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":19595,"question":"الأخت المستمعة أم زيدون تسأل وتقول: عندما أذهب إلى أقارب زوجي أحس ببعض المضايقات، فهل عدم ذهابي إليهم يعتبر من قطيعة الرحم؟ وجهونا يا سماحة الشيخ.","title":"حكم صلة المرأة أقارب زوجها غير الراغبين","answer":"الجواب: اعملي الأصلح، اعملي الأصلح مع أقارب زوجك، إن رأيت أنهم لا يرغبون بمجيئك لا تجيئي، وإن رأيت أنهم يرغبون بمجيئك فزوريهم، من باب التأليف، ومن باب التعاون على الخير، وإذا رأيت أنهم لا يرغبون بمجيئك فلا مانع من ترك المجيء، وإذا زرتيهم استعملي الكلام الطيب، والأسلوب الحسن، ولا تكوني ثقيلة اجلسي خفيفًا، ثم ارجعي إلى بيتك. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/18865/حكم-صلة-المراة-اقارب-زوجها-غير-الراغبين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_948/nour_94803.mp3","categories":["قضايا المرأة","الآداب والأخلاق المحمودة"]},{"id":19640,"question":"السائل (ر. ع. م) يقول: يا سماحة الشيخ إذا دخل المسلم على منزله من غير وجود أحد داخل المنزل، فهل التحية تكون السلام علينا وعلى عباد الله الصالحين، أم السلام عليكم؟","title":"حكم إلقاء السلام عند دخول المنزل الذي ليس فيه أحد","answer":"الجواب: إنما يسلم إذا كان فيه أحد، إذا كان فيه أحد سلم عليهم. نعم.","link":"https://binbaz.org.sa/fatwas/18917/حكم-القاء-السلام-عند-دخول-المنزل-الذي-ليس-فيه-احد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_949/nour_94928.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":19644,"question":"يقول أخيرًا السائل: ما حكم إلقاء السلام على غير المسلمين، أي: القول: السلام عليكم؟","title":"حكم إلقاء السلام على غير المسلمين","answer":"الجواب: الكفار لا يبدؤون، الرسول ﷺ قال: لا تبدؤوا اليهود والنصارى بالسلام لا يبدؤون لكن إذا سلموا يرد عليهم، إذا بدؤوا يرد عليهم. نعم. المقدم: جزاكم الله عنا وعن المسلمين خير الجزاء.","link":"https://binbaz.org.sa/fatwas/18922/حكم-القاء-السلام-على-غير-المسلمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_949/nour_94931.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":19662,"question":"يقول هذا السائل: بأنه يعمل في داخل مزرعة، هل يجوز له أن يأكل منها أي شيء بدون علم صاحبها، وإن علم وأنا له هل أستأذن؟","title":"حكم أكل العامل من مزرعة من يعمل معه بغير إذنه","answer":"الجواب: لا بأس أن يأكل منها غير متخذ خبنة، لا يذهب إلى بيته بشيء، له أن يأخذ من الفاكهة ما يأكل في بطنه فقط لا بأس، لكن لا يتخذ خبنة ، لا يذهب إلى بيته بشيء إلا بإذن.","link":"https://binbaz.org.sa/fatwas/18950/حكم-اكل-العامل-من-مزرعة-من-يعمل-معه-بغير-اذنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_950/nour_95015.mp3","categories":["الآداب والأخلاق المحمودة"]},{"id":19727,"question":"إذا كان الرحمُ غير مسلمين؟","title":"حكم صلة الرحم الكافر","answer":"الجواب: ولو لم يكونوا مسلمين، يقول النبيُّ ﷺ لأسماء لما جاءت أمّها تطلب الرّفد وهي كافرة: صليها وكان عمر يصل أقاربَه في مكة بعد الصلح وهو في المدينة، والله جلَّ وعلا يقول في كتابه الكريم: لَا يَنْهَاكُمُ اللَّهُ عَنِ الَّذِينَ لَمْ يُقَاتِلُوكُمْ فِي الدِّينِ وَلَمْ يُخْرِجُوكُمْ مِنْ دِيَارِكُمْ أَنْ تَبَرُّوهُمْ وَتُقْسِطُوا إِلَيْهِمْ..[الممتحنة:8]. فإذا لم يكن بيننا وبينهم حربٌ فلا بأس أن نصلهم؛ لأنَّ فيه تأليفًا ودعوةً إلى الخير، إذا وصلهم وأحسن إليهم بالمال أو بالمكاتبة يدعوهم إلى الله؛ فهذا فيه تأليف ودعوة إلى الخير.","link":"https://binbaz.org.sa/fatwas/29294/حكم-صلة-الرحم الكافر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/%D9%85%D8%A7%20%D9%83%D9%8A%D9%81%D9%8A%D8%A9%20%D8%B5%D9%84%D8%A9%20%D8%A7%D9%84%D8%B1%D8%AD%D9%85%20%D8%BA%D9%8A%D8%B1%20%D8%A7%D9%84%D9%85%D8%B3%D9%84%D9%85%D9%8A%D9%86%D8%9F.mp3","categories":["الآداب والأخلاق المحمودة"]}]
